export const PACK = {"id":"kobold-spells","name":"Deep Magic & Kobold Press Spells","description":"Over 650 spells from Deep Magic, Deep Magic Extended, Warlock zine and other Kobold Press releases.","license":"OGL-1.0a","sources":["Deep Magic for 5th Edition","Deep Magic Extended","Kobold Press Compilation","Warlock Zine"],"notices":["Deep Magic for 5th Edition. Copyright 2020 Open Design LLC d/b/a Kobold Press; Authors: Dan Dillon, Chris Harris, and Jeff Lee.","Deep Magic Extended. Copyright 2024 Open Design LLC d/b/a Kobold Press; Authors: Not sure..","Kobold Press Compilation. Copyright 2024 Open Design LLC d/b/a Kobold Press; Authors: Various.","Warlock Zine. Copyright 2017 Open Design LLC d/b/a Kobold Press; Authors: Woflgang Baur, others.."],"content":{"spells":[{"id":"deepm_abhorrent-apparition","name":"Abhorrent Apparition","level":4,"school":"Illusion","time":"Action","range":"60 feet","components":"M (a gourd with a face carved on it)","duration":"Instantaneous","classes":["bard","sorcerer","wizard"],"desc":"You imbue a terrifying visage onto a gourd and toss it ahead of you to a spot of your choosing within range. Each creature within 15 feet of that spot takes 6d8 psychic damage and becomes frightened of you for 1 minute; a successful Wisdom saving throw halves the damage and negates the fright. A creature frightened in this way repeats the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"If you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th.","damage":"6d8 psychic","save":"wis"},{"id":"deepm_accelerate","name":"Accelerate","level":3,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a toy top)","duration":"1 minute","classes":["bard","cleric","druid","sorcerer","wizard"],"desc":"Choose up to three willing creatures within range, which can include you. For the duration of the spell, each target's walking speed is doubled. Each target can also use a bonus action on each of its turns to take the Dash action, and it has advantage on Dexterity saving throws.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can affect one additional creature for each slot level above 3rd.","save":"dex"},{"id":"deepm_acid-gate","name":"Acid Gate","level":7,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a vial of acid and a polished silver mirror worth 125 gp)","duration":"1 minute","classes":[],"desc":"You create a portal of swirling, acidic green vapor in an unoccupied space you can see. This portal connects with a target destination within 100 miles that you are personally familiar with and have seen with your own eyes, such as your wizard's tower or an inn you have stayed at. You and up to three creatures of your choice can enter the portal and pass through it, arriving at the target destination (or within 10 feet of it, if it is currently occupied). If the target destination doesn't exist or is inaccessible, the spell automatically fails and the gate doesn't form.\n\nAny creature that tries to move through the gate, other than those selected by you when the spell was cast, takes 10d6 acid damage and is teleported 1d100 × 10 feet in a random, horizontal direction. If the creature makes a successful Intelligence saving throw, it can't be teleported by this portal, but it still takes acid damage when it enters the acid-filled portal and every time it ends its turn in contact with it.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, you can allow one additional creature to use the gate for each slot level above 7th.","damage":"10d6 acid","save":"int"},{"id":"deepm_acid-rain","name":"Acid Rain","level":5,"school":"Conjuration","time":"Action","range":"150 feet","components":"V, S, M (a drop of acid)","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"You unleash a storm of swirling acid in a cylinder 20 feet wide and 30 feet high, centered on a point you can see. The area is heavily obscured by the driving acidfall. A creature that starts its turn in the area or that enters the area for the first time on its turn takes 6d6 acid damage, or half as much damage if it makes a successful Dexterity saving throw. A creature takes half as much damage from the acid (as if it had made a successful saving throw) at the start of its first turn after leaving the affected area.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d6 for each slot level above 5th.","damage":"6d6 acid","save":"dex"},{"id":"deepm_adjust-position","name":"Adjust Position","level":1,"school":"Transmutation","time":"Action","range":"30 feet","components":"V","duration":"Instantaneous","classes":["bard","cleric","warlock","wizard"],"desc":"You adjust the location of an ally to a better tactical position. You move one willing creature within range 5 feet. This movement does not provoke opportunity attacks. The creature moves bodily through the intervening space (as opposed to teleporting), so there can be no physical obstacle (such as a wall or a door) in the path.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can target an additional willing creature for each slot level above 1st."},{"id":"deepm_afflict-line","name":"Afflict Line","level":9,"school":"Necromancy","time":"1 hour","range":"1 mile","components":"V, S, M (a statuette carved in the likeness of the victim worth 1,250 gp)","duration":"Permanent; one generation","classes":["cleric","warlock","wizard"],"desc":"You invoke the darkest curses upon your victim and his or her descendants. This spell does not require that you have a clear path to your target, only that your target is within range. The target must make a successful Wisdom saving throw or be cursed until the magic is dispelled. While cursed, the victim has disadvantage on ability checks and saving throws made with the ability score that you used when you cast the spell. In addition, the target's firstborn offspring is also targeted by the curse. That individual is allowed a saving throw of its own if it is currently alive, or it makes one upon its birth if it is not yet born when the spell is cast. If the target's firstborn has already died, the curse passes to the target's next oldest offspring.\n\n**Ritual Focus.** If you expend your ritual focus, the curse becomes hereditary, passing from firstborn to firstborn for the entire length of the family's lineage until one of them successfully saves against the curse and throws off your dark magic.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_agonizing-mark","name":"Agonizing Mark","level":1,"school":"Evocation","time":"Action","range":"90 feet","components":"S","duration":"1 minute","classes":["bard","cleric","druid","ranger","sorcerer","wizard"],"desc":"You choose a creature you can see within range to mark as your prey, and a ray of black energy issues forth from you. Until the spell ends, each time you deal damage to the target it must make a Charisma saving throw. On a failed save, it falls prone as its body is filled with torturous agony.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_alchemical-form","name":"Alchemical Form","level":6,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a vial of acid, poison, or alchemist's fire)","duration":"1 minute","classes":[],"desc":"You transform into an amoebic form composed of highly acidic and poisonous alchemical jelly. While in this form:\n- you are immune to acid and poison damage and to the poisoned and stunned conditions;\n- you have resistance to nonmagical fire, piercing, and slashing damage;\n- you can't speak, cast spells, use items or weapons, or manipulate objects;\n- your gear melds into your body and reappears when the spell ends;\n- you don't need to breathe;\n- your speed is 20 feet;\n- your size doesn't change, but you can move through and between obstructions as if you were two size categories smaller; and\n- you gain the following action: **Melee Weapon Attack:** spellcasting ability modifier + proficiency bonus to hit, range 5 ft., one target; **Hit:** 4d6 acid or poison damage (your choice), and the target must make a successful Constitution saving throw or be poisoned until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_ale-dritch-blast","name":"Ale-dritch Blast","level":0,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":["bard","druid","wizard"],"desc":"A stream of ice-cold ale blasts from your outstretched hands toward a creature or object within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage and it must make a successful Constitution saving throw or be poisoned until the end of its next turn. A targeted creature has disadvantage on the saving throw if it has drunk any alcohol within the last hour.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The damage increases when you reach higher levels: 2d8 at 5th level, 3d8 at 11th level, and 4d8 at 17th level.","damage":"1d8 cold","save":"con","attack":true},{"id":"deepm_ally-aegis","name":"Ally Aegis","level":6,"school":"Abjuration","time":"Reaction","range":"60 feet","components":"V, S","duration":"1 round","classes":["bard","cleric","sorcerer","wizard"],"desc":"When you see an ally within range in imminent danger, you can use your reaction to protect that creature with a shield of magical force. Until the start of your next turn, your ally has a +5 bonus to AC and is immune to force damage. In addition, if your ally must make a saving throw against an enemy's spell that deals damage, the ally takes half as much damage on a failed saving throw and no damage on a successful save. Ally aegis offers no protection, however, against psychic damage from any source.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, you can target one additional ally for each slot level above 6th."},{"id":"deepm_alone","name":"Alone","level":3,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":["cleric","sorcerer","warlock","wizard"],"desc":"You cause a creature within range to believe its allies have been banished to a different realm. The target must succeed on a Wisdom saving throw, or it treats its allies as if they were invisible and silenced. The affected creature cannot target, perceive, or otherwise interact with its allies for the duration of the spell. If one of its allies hits it with a melee attack, the affected creature can make another Wisdom saving throw. On a successful save, the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_alter-arrows-fortune","name":"Alter Arrow’s Fortune","level":1,"school":"Divination","time":"Reaction","range":"100 feet","components":"S","duration":"Instantaneous","classes":["bard","cleric","druid","ranger","sorcerer","wizard"],"desc":"You clap your hands, setting off a chain of tiny events that culminate in throwing off an enemy's aim. When an enemy makes a ranged attack with a weapon or a spell that hits one of your allies, this spell causes the enemy to reroll the attack roll unless the enemy makes a successful Charisma saving throw. The attack is resolved using the lower of the two rolls (effectively giving the enemy disadvantage on the attack).","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_altheas-travel-tent","name":"Althea’s Travel Tent","level":2,"school":"Conjuration","time":"5 minutes","range":"Touch","components":"V, S, M (a canvas tent)","duration":"8 hours","classes":["sorcerer","wizard"],"desc":"You touch an ordinary, properly pitched canvas tent to create a space where you and a companion can sleep in comfort. From the outside, the tent appears normal, but inside it has a small foyer and a larger bedchamber. The foyer contains a writing desk with a chair; the bedchamber holds a soft bed large enough to sleep two, a small nightstand with a candle, and a small clothes rack. The floor of both rooms is a clean, dry, hard-packed version of the local ground. When the spell ends, the tent and the ground return to normal, and any creatures inside the tent are expelled to the nearest unoccupied spaces.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When the spell is cast using a 3rd-level slot, the foyer becomes a dining area with seats for six and enough floor space for six people to sleep, if they bring their own bedding. The sleeping room is unchanged. With a 4th-level slot, the temperature inside the tent is comfortable regardless of the outside temperature, and the dining area includes a small kitchen. With a 5th-level slot, an unseen servant is conjured to prepare and serve food (from your supplies). With a 6th-level slot, a third room is added that has three two-person beds. With a slot of 7th level or higher, the dining area and second sleeping area can each accommodate eight persons."},{"id":"deepm_amplify-gravity","name":"Amplify Gravity","level":7,"school":"Transmutation","time":"Action","range":"100 feet","components":"V, S, M (a piece of lead)","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"This spell intensifies gravity in a 50-foot-radius area within range. Inside the area, damage from falling is quadrupled (2d6 per 5 feet fallen) and maximum damage from falling is 40d6. Any creature on the ground in the area when the spell is cast must make a successful Strength saving throw or be knocked prone; the same applies to a creature that enters the area or ends its turn in the area. A prone creature in the area must make a successful Strength saving throw to stand up. A creature on the ground in the area moves at half speed and has disadvantage on Dexterity checks and ranged attack rolls.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_analyze-device","name":"Analyze Device","level":1,"school":"Divination","time":"1 hour","range":"Touch","components":"V, S, M (a set of clockworker’s tools)","duration":"Instantaneous","classes":["bard","sorcerer","wizard"],"desc":"You discover all mechanical properties, mechanisms, and functions of a single construct or clockwork device, including how to activate or deactivate those functions, if appropriate.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_ancestors-strength","name":"Ancestor’s Strength","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"8 hours","classes":["cleric","druid"],"desc":"Choose a willing creature you can see and touch. Its muscles bulge and become invigorated. For the duration, the target is considered one size category larger for determining its carrying capacity, the maximum weight it can lift, push, or pull, and its ability to break objects. It also has advantage on Strength checks.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_anchoring-rope","name":"Anchoring Rope","level":1,"school":"Evocation","time":"Action","range":"30 feet","components":"V, S","duration":"5 minutes","classes":["bard","druid","ranger"],"desc":"You create a spectral lanyard. One end is tied around your waist, and the other end is magically anchored in the air at a point you select within range. You can choose to make the rope from 5 to 30 feet long, and it can support up to 800 pounds. The point where the end of the rope is anchored in midair can't be moved after the spell is cast. If this spell is cast as a reaction while you are falling, you stop at a point of your choosing in midair and take no falling damage. You can dismiss the rope as a bonus action.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can create one additional rope for every two slot levels above 1st. Each rope must be attached to a different creature."},{"id":"deepm_anchoring-rope-reaction","name":"Anchoring Rope (Reaction)","level":1,"school":"Evocation","time":"Reaction","range":"30 feet","components":"V, S","duration":"5 minutes","classes":["bard","druid","ranger"],"desc":"You create a spectral lanyard. One end is tied around your waist, and the other end is magically anchored in the air at a point you select within range. You can choose to make the rope from 5 to 30 feet long, and it can support up to 800 pounds. The point where the end of the rope is anchored in midair can't be moved after the spell is cast. If this spell is cast as a reaction while you are falling, you stop at a point of your choosing in midair and take no falling damage. You can dismiss the rope as a bonus action.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can create one additional rope for every two slot levels above 1st. Each rope must be attached to a different creature."},{"id":"deepm_ancient-shade","name":"Ancient Shade","level":5,"school":"Necromancy","time":"Action","range":"10 feet","components":"V, S, M (burning candles of planar origin worth 500 gp)","duration":"10 minutes","classes":["cleric","wizard"],"desc":"You grant the semblance of life and intelligence to a pile of bones (or even bone dust) of your choice within range, allowing the ancient spirit to answer the questions you pose. These remains can be the remnants of undead, including animated but unintelligent undead, such as skeletons and zombies. (Intelligent undead are not affected.) Though it can have died centuries ago, the older the spirit called, the less it remembers of its mortal life.\n\nUntil the spell ends, you can ask the ancient spirit up to five questions if it died within the past year, four questions if it died within ten years, three within one hundred years, two within one thousand years, and but a single question for spirits more than one thousand years dead. The ancient shade knows only what it knew in life, including languages. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn't return the creature's soul to its body, only its animating spirit. Thus, the corpse can't learn new information, doesn't comprehend anything that has happened since it died, and can't speculate about future events.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_angelic-guardian","name":"Angelic Guardian","level":1,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":["cleric","warlock","wizard"],"desc":"You conjure a minor celestial manifestation to protect a creature you can see within range. A faintly glowing image resembling a human head and shoulders hovers within 5 feet of the target for the duration. The manifestation moves to interpose itself between the target and any incoming attacks, granting the target a +2 bonus to AC.\n\nAlso, the first time the target gets a failure on a Dexterity saving throw while the spell is active, it can use its reaction to reroll the save. The spell then ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_animate-ghoul","name":"Animate Ghoul","level":2,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M (piece of rotting flesh and an onyx gemstone worth 100 gp)","duration":"Instantaneous","classes":["cleric","sorcerer","wizard"],"desc":"You raise one Medium or Small humanoid corpse as a ghoul under your control. Any class levels or abilities the creature had in life are gone, replaced by the standard ghoul stat block.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 3rd-level spell slot, it can be used on the corpse of a Large humanoid to create a Large ghoul. When you cast this spell using a spell slot of 4th level or higher, this spell creates a ghast, but the material component changes to an onyx gemstone worth at least 200 gp."},{"id":"deepm_animate-greater-undead","name":"Animate Greater Undead","level":6,"school":"Necromancy","time":"1 hour","range":"15 feet","components":"V, S, M (a pint of blood, a pound of flesh, and an ounce of bone dust, all of which the spell consumes)","duration":"Instantaneous","classes":["cleric","wizard"],"desc":"**Animate greater undead** creates an undead servant from a pile of bones or from the corpse of a Large or Huge humanoid within range. The spell imbues the target with a foul mimicry of life, raising it as an undead skeleton or zombie. A skeleton uses the stat block of a minotaur skeleton, or a zombie uses the stat block of an ogre zombie, unless a more appropriate stat block is available.\n\nThe creature is under your control for 24 hours, after which it stops obeying your commands. To maintain control of the creature for another 24 hours, you must cast this spell on it again while you have it controlled. Casting the spell for this purpose reasserts your control over up to four creatures you have previously animated rather than animating a new one.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, you can reanimate one additional creature for each slot level above 6th."},{"id":"deepm_animated-scroll","name":"Animated Scroll","level":0,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (intricately folded paper or parchment)","duration":"24 hours","classes":["druid","sorcerer","wizard"],"desc":"The paper or parchment must be folded into the shape of an animal before casting the spell. It then becomes an animated paper animal of the kind the folded paper most closely resembles. The creature uses the stat block of any beast that has a challenge rating of 0. It is made of paper, not flesh and bone, but it can do anything the real creature can do: a paper owl can fly and attack with its talons, a paper frog can swim without disintegrating in water, and so forth. It follows your commands to the best of its ability, including carrying messages to a recipient whose location you know.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The duration increases by 24 hours at 5th level (48 hours), 11th level (72 hours), and 17th level (96 hours)."},{"id":"deepm_anticipate-arcana","name":"Anticipate Arcana","level":3,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":["cleric","sorcerer","warlock","wizard"],"desc":"Your foresight gives you an instant to ready your defenses against a magical attack. When you cast **anticipate arcana**, you have advantage on saving throws against spells and other magical effects until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_anticipate-attack","name":"Anticipate Attack","level":2,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":["bard","cleric","druid","ranger","sorcerer","wizard"],"desc":"In a flash of foreknowledge, you spot an oncoming attack with enough time to avoid it. Upon casting this spell, you can move up to half your speed without provoking opportunity attacks. The oncoming attack still occurs but misses automatically if you are no longer within the attack's range, are in a space that's impossible for the attack to hit, or can't be targeted by that attack in your new position. If none of those circumstances apply but the situation has changed—you have moved into a position where you have cover, for example—then the attack is made after taking the new situation into account.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_anticipate-weakness","name":"Anticipate Weakness","level":1,"school":"Divination","time":"Bonus Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":["bard","cleric","druid","ranger","sorcerer","warlock","wizard"],"desc":"With a quick glance into the future, you pinpoint where a gap is about to open in your foe's defense, and then you strike. After casting **anticipate weakness**, you have advantage on attack rolls until the end of your turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_arcane-sight","name":"Arcane Sight","level":8,"school":"Divination","time":"Action","range":"Touch","components":"V, S, M (a piece of clear quartz)","duration":"1 hour","classes":["sorcerer","warlock","wizard"],"desc":"The recipient of this spell gains the benefits of both [true seeing](https://api.open5e.com/spells/true-seeing) and [detect magic](https://api.open5e.com/spells/detect-magic) until the spell ends, and also knows the name and effect of every spell he or she witnesses during the spell's duration.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_as-you-were","name":"As You Were","level":2,"school":"Necromancy","time":"1 minute","range":"Touch","components":"V, S, M (a piece of flesh from a creature of the target’s race)","duration":"Instantaneous","classes":["cleric","wizard"],"desc":"When cast on a dead or undead body, **as you were** returns that creature to the appearance it had in life while it was healthy and uninjured. The target must have a physical body; the spell fails if the target is normally noncorporeal.\n\nIf as you were is cast on a corpse, its effect is identical to that of [gentle repose](https://api.open5e.com/spells/gentle-repose), except that the corpse's appearance is restored to that of a healthy, uninjured (albeit dead) person.\n\nIf the target is an undead creature, it also is restored to the appearance it had in life, even if it died from disease or from severe wounds, or centuries ago. The target looks, smells, and sounds (if it can speak) as it did in life. Friends and family can tell something is wrong only with a successful Wisdom (Insight) check against your spell save DC, and only if they have reason to be suspicious. (Knowing that the person should be dead is sufficient reason.) Spells and abilities that detect undead are also fooled, but the creature remains susceptible to Turn Undead as normal.\n\nThis spell doesn't confer the ability to speak on undead that normally can't speak. The creature eats, drinks, and breathes as a living creature does; it can mimic sleep, but it has no more need for it than it had before.\n\nThe effect lasts for a number of hours equal to your caster level. You can use an action to end the spell early. Any amount of radiant or necrotic damage dealt to the creature, or any effect that reduces its Constitution, also ends the spell.\n\nIf this spell is cast on an undead creature that isn't your ally or under your control, it makes a Charisma saving throw to resist the effect.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_ashen-memories","name":"Ashen Memories","level":2,"school":"Divination","time":"1 minute","range":"Touch","components":"V, S","duration":"Instantaneous","classes":["bard","cleric","wizard"],"desc":"You touch the ashes, embers, or soot left behind by a fire and receive a vision of one significant event that occurred in the area while the fire was burning. For example, if you were to touch the cold embers of a campfire, you might witness a snippet of a conversation that occurred around the fire. Similarly, touching the ashes of a burned letter might grant you a vision of the person who destroyed the letter or the contents of the letter. You have no control over what information the spell reveals, but your vision usually is tied to the most meaningful event related to the fire. The GM determines the details of what is revealed.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_aspect-of-the-dragon","name":"Aspect of the Dragon","level":7,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a dragon scale)","duration":"1 minute","classes":[],"desc":"This spell draws out the ancient nature within your blood, allowing you to assume the form of any dragon-type creature of challenge 10 or less.\n\nYou assume the hit points and Hit Dice of the new form. When you revert to your normal form, you return to the number of hit points you had before you transformed. If you revert as a result of dropping to 0 hit points, any excess damage carries over to your normal form. As long as the excess damage doesn't reduce your normal form to 0 hit points, you aren't knocked unconscious.\n\nYou retain the benefits of any features from your class, race, or other source and can use them, provided that your new form is physically capable of doing so. You can speak only if the dragon can normally speak.\n\nWhen you transform, you choose whether your equipment falls to the ground, merges into the new form, or is worn by it. Worn equipment functions normally, but equipment doesn't change shape or size to match the new form. Any equipment that the new form can't wear must either fall to the ground or merge into the new form. The GM has final say on whether the new form can wear or use a particular piece of equipment. Equipment that merges has no effect in that state.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_aspect-of-the-serpent","name":"Aspect of the Serpent","level":3,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a dried snakeskin)","duration":"1 minute","classes":["druid","sorcerer","wizard"],"desc":"A creature you touch takes on snakelike aspects for the duration of the spell. Its tongue becomes long and forked, its canine teeth become fangs with venom sacs, and its pupils become sharply vertical. The target gains darkvision with a range of 60 feet and blindsight with a range of 30 feet. As a bonus action when you cast the spell, the target can make a ranged weapon attack with a normal range of 60 feet that deals 2d6 poison damage on a hit.\n\nAs an action, the target can make a bite attack using either Strength or Dexterity (Melee Weapon Attack: range 5 ft., one creature; Hit: 2d6 piercing damage), and the creature must make a successful DC 14 Constitution saving throw or be paralyzed for 1 minute. A creature paralyzed in this way repeats the saving throw at the end of each of its turns, ending the effect on itself on a success).","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, both the ranged attack and bite attack damage increase by 1d6 for each slot level above 3rd.","save":"str"},{"id":"deepm_aura-of-protection-or-destruction","name":"Aura of Protection or Destruction","level":3,"school":"Abjuration","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":["cleric"],"desc":"When you cast this spell, you radiate an otherworldly energy that warps the fate of all creatures within 30 feet of you. Decide whether to call upon either a celestial or a fiend for aid. Choosing a celestial charges a 30-foot-radius around you with an aura of nonviolence; until the start of your next turn, every attack roll made by or against a creature inside the aura is treated as a natural 1. Choosing a fiend charges the area with an aura of violence; until the start of your next turn, every attack roll made by or against a creature inside the aura, including you, is treated as a natural 20.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can extend the duration by 1 round for each slot level above 3rd."},{"id":"deepm_auspicious-warning","name":"Auspicious Warning","level":1,"school":"Enchantment","time":"Reaction","range":"30 feet","components":"V","duration":"Instantaneous","classes":["bard","sorcerer","wizard"],"desc":"Just in time, you call out a fortunate warning to a creature within range. The target rolls a d4 and adds the number rolled to an attack roll, ability check, or saving throw that it has just made and uses the new result for determining success or failure.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_avoid-grievous-injury","name":"Avoid Grievous Injury","level":1,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":["bard","cleric","druid","sorcerer","warlock","wizard"],"desc":"You cast this spell when a foe strikes you with a critical hit but before damage dice are rolled. The critical hit against you becomes a normal hit.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_avronins-astral-assembly","name":"Avronin’s Astral Assembly","level":6,"school":"Necromancy","time":"10 minutes","range":"Unlimited","components":"V, M (a spool of fine copper wire and a gem worth at least 100 gp for each target)","duration":"1 hour","classes":["warlock","wizard"],"desc":"You alert a number of creatures that you are familiar with, up to your spellcasting ability modifier (minimum of 1), of your intent to communicate with them through spiritual projection. The invitation can extend any distance and even cross to other planes of existence. Once notified, the creatures can choose to accept this communication at any time during the duration of the spell.\n\nWhen a creature accepts, its spirit is projected into one of the gems used in casting the spell. The material body it leaves behind falls unconscious and doesn't need food or air. The creature's consciousness is present in the room with you, and its normal form appears as an astral projection within 5 feet of the gem its spirit occupies. You can see and hear all the creatures who have joined in the assembly, and they can see and hear you and each other as if they were present (which they are, astrally). They can't interact with anything physically.\n\nA creature can end the spell's effect on itself voluntarily at any time, as can you. When the effect ends or the duration expires, a creature's spirit returns to its body and it regains consciousness. A creature that withdraws voluntarily from the assembly can't rejoin it even if the spell is still active. If a gem is broken while occupied by a creature's astral self, the spirit in the gem returns to its body and the creature suffers two levels of exhaustion.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_awaken-object","name":"Awaken Object","level":8,"school":"Transmutation","time":"8 hours","range":"Touch","components":"V, S, M (a ruby worth at least 1,000 gp, which the spell consumes)","duration":"Permanent","classes":[],"desc":"After spending the casting time enchanting a ruby along with a Large or smaller nonmagical object in humanoid form, you touch the ruby to the object. The ruby dissolves into the object, which becomes a living construct imbued with sentience. If the object has no face, a humanoid face appears on it in an appropriate location. The awakened object's statistics are determined by its size, as shown on the table below. An awakened object can use an action to make a melee weapon attack against a target within 5 feet of it. It has free will, acts independently, and speaks one language you know. It is initially friendly to anyone who assisted in its creation.\n\nAn awakened object's speed is 30 feet. If it has no apparent legs or other means of moving, it gains a flying speed of 30 feet and it can hover. Its sight and hearing are equivalent to a typical human's senses. Intelligence, Wisdom, and Charisma can be adjusted up or down by the GM to fit unusual circumstances. A beautiful statue might awaken with increased Charisma, for example, or the bust of a great philosopher could have surprisingly high Wisdom.\n\nAn awakened object needs no air, food, water, or sleep. Damage to an awakened object can be healed or mechanically repaired.\n\nSize | HP | AC | Attack | Str | Dex | Con | Int | Wis | Cha\nT | 20 | 18 | +8 to hit, 1d4 + 4 damage | 4 | 18 | 10 | 2d6 | 2d6 | 2d6\nS | 25 | 16 | +6 to hit, 1d8 + 2 damage | 6 | 14 | 10 | 3d6 | 2d6 | 2d6\nM | 40 | 13 | +5 to hit, 2d6 + 1 damage | 10 | 12 | 10 | 3d6 | 3d6 | 2d6\nL | 50 | 10 | +6 to hit, 2d10 + 2 damage | 14 | 10 | 10 | 3d6 | 3d6 | 2d6 + 2","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_bad-timing","name":"Bad Timing","level":2,"school":"Divination","time":"Action","range":"60 feet","components":"V","duration":"Instantaneous","classes":["bard","sorcerer","wizard"],"desc":"You point toward a creature that you can see and twist strands of chaotic energy around its fate. If the target gets a failure on a Charisma saving throw, the next attack roll or ability check the creature attempts within 10 minutes is made with disadvantage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_batsense","name":"Batsense","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a bit of fur from a bat’s ear)","duration":"1 hour","classes":["bard","druid","ranger","sorcerer"],"desc":"For the duration of the spell, a creature you touch can produce and interpret squeaking sounds used for echolocation, giving it blindsight out to a range of 60 feet. The target cannot use its blindsight while deafened, and its blindsight doesn't penetrate areas of magical silence. While using blindsight, the target has disadvantage on Dexterity (Stealth) checks that rely on being silent. Additionally, the target has advantage on Wisdom (Perception) checks that rely on hearing.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_become-nightwing","name":"Become Nightwing","level":6,"school":"Enchantment","time":"Action","range":"Self","components":"V, S, M (a crow’s eye)","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"This spell imbues you with wings of shadow. For the duration of the spell, you gain a flying speed of 60 feet and a new attack action: Nightwing Breath.\n\n**Nightwing Breath (Recharge 4–6).** You exhale shadow‐substance in a 30-foot cone. Each creature in the area takes 5d6 necrotic damage, or half the damage with a successful Dexterity saving throw.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"5d6 necrotic","save":"dex"},{"id":"deepm_beguiling-bet","name":"Beguiling Bet","level":2,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You issue a challenge against one creature you can see within range, which must make a successful Wisdom saving throw or become charmed. On a failed save, you can make an ability check as a bonus action. For example, you could make a Strength (Athletics) check to climb a difficult surface or to jump as high as possible; you could make a Dexterity (Acrobatics) check to perform a backflip; or you could make a Charisma (Performance) check to sing a high note or to extemporize a clever rhyme. You can choose to use your spellcasting ability modifier in place of the usual ability modifier for this check, and you add your proficiency bonus if you're proficient in the skill being used.\n\nThe charmed creature must use its next action (which can be a legendary action) to make the same ability check in a contest against your check. Even if the creature can't perform the action—it may not be close enough to a wall to climb it, or it might not have appendages suitable for strumming a lute—it must still attempt the action to the best of its capability. If you win the contest, the spell (and the contest) continues, with you making a new ability check as a bonus action on your turn. The spell ends when it expires or when the creature wins the contest.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for every two slot levels above 2nd. Each creature must be within 30 feet of another creature when you cast the spell.","save":"wis"},{"id":"deepm_benediction","name":"Benediction","level":0,"school":"Abjuration","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":["cleric","warlock","wizard"],"desc":"You call down a blessing in the name of an angel of protection. A creature you can see within range shimmers with a faint white light. The next time the creature takes damage, it rolls a d4 and reduces the damage by the result. The spell then ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_bestial-fury","name":"Bestial Fury","level":2,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You instill primal fury into a creature you can see within range. The target must make a Charisma saving throw; a creature can choose to fail this saving throw. On a failure, the target must use its action to attack its nearest enemy it can see with unarmed strikes or natural weapons. For the duration, the target's attacks deal an extra 1d6 damage of the same type dealt by its weapon, and the target can't be charmed or frightened. If there are no enemies within reach, the target can use its action to repeat the saving throw, ending the effect on a success.\n\nThis spell has no effect on undead or constructs.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.","save":"cha"},{"id":"deepm_binding-oath","name":"Binding Oath","level":4,"school":"Necromancy","time":"10 minutes","range":"30 feet","components":"V, S","duration":"Until dispelled","classes":["bard","cleric"],"desc":"You seal an agreement between two or more willing creatures with an oath in the name of the god of justice, using ceremonial blessings during which both the oath and the consequences of breaking it are set: if any of the sworn break this vow, they are struck by a curse. For each individual that does so, you choose one of the options given in the [bestow curse](https://api.open5e.com/spells/bestow-curse) spell. When the oath is broken, all participants are immediately aware that this has occurred, but they know no other details.\n\nThe curse effect of binding oath can't be dismissed by [dispel magic](https://api.open5e.com/spells/dispel-magic), but it can be removed with [dispel evil and good](https://api.open5e.com/spells/dispel-evil-and-good)[remove curse](https://api.open5e.com/remove-curse), or [wish](https://api.open5e.com/spells/wish). Remove curse functions only if the spell slot used to cast it is equal to or higher than the spell slot used to cast **binding oath**. Depending on the nature of the oath, one creature's breaking it may or may not invalidate the oath for the other targets. If the oath is completely broken, the spell ends for every affected creature, but curse effects already bestowed remain until dispelled.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_biting-arrow","name":"Biting Arrow","level":0,"school":"Evocation","time":"Action","range":"Self","components":"V, M (an arrow or a thrown weapon)","duration":"1 round","classes":["druid","sorcerer","wizard"],"desc":"As part of the action used to cast this spell, you make a ranged weapon attack with a bow, a crossbow, or a thrown weapon. The effect is limited to a range of 120 feet despite the weapon's range, and the attack is made with disadvantage if the target is in the weapon's long range.\n\nIf the weapon attack hits, it deals damage as usual. In addition, the target becomes coated in thin frost until the start of your next turn. If the target uses its reaction before the start of your next turn, it immediately takes 1d6 cold damage and the spell ends.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The spell's damage, for both the ranged attack and the cold damage, increases by 1d6 when you reach 5th level (+1d6 and 2d6), 11th level (+2d6 and 3d6), and 17th level (+3d6 and 4d6).","damage":"1d6 cold"},{"id":"deepm_bitter-chains","name":"Bitter Chains","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a spiked metal ring)","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"The spiked ring in your hand expands into a long, barbed chain to ensnare a creature you touch. Make a melee spell attack against the target. On a hit, the target is bound in metal chains for the duration. While bound, the target can move only at half speed and has disadvantage on attack rolls, saving throws, and Dexterity checks. If it moves more than 5 feet during a turn, it takes 3d6 piercing damage from the barbs.\n\nThe creature can escape from the chains by using an action and making a successful Strength or Dexterity check against your spell save DC, or if the chains are destroyed. The chains have AC 18 and 20 hit points.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"3d6 piercing","save":"dex","attack":true},{"id":"deepm_black-goats-blessing","name":"Black Goat’s Blessing","level":0,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 round","classes":["bard","cleric","druid","ranger","sorcerer","warlock","wizard"],"desc":"You raise your hand with fingers splayed and utter an incantation of the Black Goat with a Thousand Young. Your magic is blessed with the eldritch virility of the All‑Mother. The target has disadvantage on saving throws against spells you cast until the end of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_black-hand","name":"Black Hand","level":4,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":["warlock","wizard"],"desc":"You gather the powers of darkness into your fist and fling dark, paralyzing flame at a target within 30 feet. If you make a successful ranged spell attack, this spell siphons vitality from the target into you. For the duration, the target has disadvantage (and you have advantage) on attack rolls, ability checks, and saving throws made with Strength, Dexterity, or Constitution. An affected target makes a Constitution saving throw (with disadvantage) at the end of its turn, ending the effect on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_black-ribbons","name":"Black Ribbons","level":1,"school":"Conjuration","time":"Action","range":"40 feet","components":"V, S, M (a piece of ribbon)","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"You pull pieces of the plane of shadow into your own reality, causing a 20-foot cube to fill with inky ribbons that turn the area into difficult terrain and wrap around nearby creatures. Any creature that ends its turn in the area becomes restrained by the ribbons until the end of its next turn, unless it makes a successful Dexterity saving throw. Once a creature succeeds on this saving throw, it can't be restrained again by the ribbons, but it's still affected by the difficult terrain.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_black-sunshine","name":"Black Sunshine","level":8,"school":"Illusion","time":"Action","range":"Self","components":"V, M (a discolored pearl, which the spell consumes)","duration":"1 minute","classes":["sorcerer","wizard"],"desc":"You hold up a flawed pearl and it disappears, leaving behind a magic orb in your hand that pulses with dim purple light. Allies that you designate become invisible if they're within 60 feet of you and if light from the orb can reach the space they occupy. An invisible creature still casts a faint, purple shadow.\n\nThe orb can be used as a thrown weapon to attack an enemy. On a hit, the orb explodes in a flash of light and the spell ends. The targeted enemy and each creature within 10 feet of it must make a successful Dexterity saving throw or be blinded for 1 minute. A creature blinded in this way repeats the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_black-swan-storm","name":"Black Swan Storm","level":2,"school":"Evocation","time":"Action","range":"30 feet","components":"V, S, M (a feather from a black swan)","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"You call forth a whirlwind of black feathers that fills a 5-foot cube within range. The feathers deal 2d8 force damage to creatures in the cube's area and radiate darkness, causing the illumination level within 20 feet of the cube to drop by one step (from bright light to dim light, and from dim light to darkness). Creatures that make a successful Dexterity saving throw take half the damage and are still affected by the change in light.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the feathers deal an extra 1d8 force damage for each slot level above 2nd.","save":"dex"},{"id":"deepm_black-well","name":"Black Well","level":6,"school":"Necromancy","time":"Action","range":"300 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You summon a seething sphere of dark energy 5 feet in diameter at a point within range. The sphere pulls creatures toward it and devours the life force of those it envelops. Every creature other than you that starts its turn within 90 feet of the black well must make a successful Strength saving throw or be pulled 50 feet toward the well. A creature pulled into the well takes 6d8 necrotic damage and is stunned; a successful Constitution saving throw halves the damage and causes the creature to become incapacitated. A creature that starts its turn inside the well also makes a Constitution saving throw; the creature is stunned on a failed save or incapacitated on a success. An incapacitated creature that leaves the well recovers immediately and can take actions and reactions on that turn. A creature takes damage only upon entering the well—it takes no additional damage for remaining there—but if it leaves the well and is pulled back in again, it takes damage again. A total of nine Medium creatures, three Large creatures, or one Huge creature can be inside the well's otherdimensional space at one time. When the spell's duration ends, all creatures inside it tumble out in a heap, landing prone.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, the damage dealt by the well increases by 1d8—and the well pulls creatures an additional 5 feet—for each slot level above 6th.","damage":"6d8 necrotic","save":"str"},{"id":"deepm_blade-of-my-brother","name":"Blade of my Brother","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (melee weapon owned by a dead ally of the target)","duration":"4 rounds","classes":["cleric"],"desc":"You touch a melee weapon that was used by an ally who is now dead, and it leaps into the air and flies to another ally (chosen by you) within 15 feet of you. The weapon enters that ally's space and moves when the ally moves. If the weapon or the ally is forced to move more than 5 feet from the other, the spell ends.\n\nThe weapon acts on your turn by making an attack if a target presents itself. Its attack modifier equals your spellcasting level + the weapon's inherent magical bonus, if any; it receives only its own inherent magical bonus to damage. The weapon fights for up to 4 rounds or until your concentration is broken, after which the spell ends and it falls to the ground.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_blade-of-wrath","name":"Blade of Wrath","level":3,"school":"Evocation","time":"Bonus Action","range":"Self","components":"V, S, M (a rebuke of evil, written in Celestial)","duration":"10 minutes","classes":["cleric","warlock","wizard"],"desc":"You create a sword of pure white fire in your free hand. The blade is similar in size and shape to a longsword, and it lasts for the duration. The blade disappears if you let go of it, but you can call it forth again as a bonus action.\n\nYou can use your action to make a melee spell attack with the blade. On a hit, the target takes 2d8 fire damage and 2d8 radiant damage. An aberration, fey, fiend, or undead creature damaged by the blade must succeed on a Wisdom saving throw or be frightened until the start of your next turn.\n\nThe blade sheds bright light in a 20-foot radius and dim light for an additional 20 feet.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, either the fire damage or the radiant damage (your choice) increases by 1d8 for each slot level above 3rd.","damage":"2d8 fire","save":"wis","attack":true},{"id":"deepm_blazing-chariot","name":"Blazing Chariot","level":5,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S, M (a small golden wheel worth 250 gp)","duration":"1 hour","classes":["cleric","warlock","wizard"],"desc":"Calling upon the might of the angels, you conjure a flaming chariot made of gold and mithral in an unoccupied 10-foot‐square space you can see within range. Two horses made of fire and light pull the chariot. You and up to three other Medium or smaller creatures you designate can board the chariot (at the cost of 5 feet of movement) and are unharmed by the flames. Any other creature that touches the chariot or hits it (or a creature riding in it) with a melee attack while within 5 feet of the chariot takes 3d6 fire damage and 3d6 radiant damage. The chariot has AC 18 and 50 hit points, is immune to fire, poison, psychic, and radiant damage, and has resistance to all other nonmagical damage. The horses are not separate creatures but are part of the chariot. The chariot vanishes if it is reduced to 0 hit points, and any creature riding it falls out. The chariot has a speed of 50 feet and a flying speed of 40 feet.\n\nOn your turn, you can guide the chariot in place of your own movement. You can use a bonus action to direct it to take the Dash, Disengage, or Dodge action. As an action, you can use the chariot to overrun creatures in its path. On this turn, the chariot can enter a hostile creature's space. The creature takes damage as if it had touched the chariot, is shunted to the nearest unoccupied space that it can occupy, and must make a successful Strength saving throw or fall prone in that space.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"3d6 fire","save":"str"},{"id":"deepm_bleating-call","name":"Bleating Call","level":2,"school":"Enchantment","time":"Action","range":"90 feet","components":"S, M (a bit of fur or hair from a young beast or humanoid)","duration":"1 minute","classes":["bard","ranger","sorcerer","wizard"],"desc":"You create a sound on a point within range. The sound's volume can range from a whisper to a scream, and it can be any sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\n\nEach creature that starts its turn within 30 feet of the sound and can hear it must make a Wisdom saving throw. On a failed save, the target must take the Dash or Disengage action and move toward the sound by the safest available route on each of its turns. When it arrives to the source of the sound, the target must use its action to examine the sound. Once it has examined the sound, the target determines the sound is illusory and can no longer hear it, ending the spell's effects on that target and preventing the target from being affected by the sound again for the duration of the spell. If a target takes damage from you or a creature friendly to you, it is no longer under the effects of this spell.\n\nCreatures that can't be charmed are immune to this spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_bleed","name":"Bleed","level":1,"school":"Necromancy","time":"Bonus Action","range":"Self","components":"V, S, M (a drop of blood)","duration":"1 minute","classes":["ranger","warlock"],"desc":"Crackling energy coats the blade of one weapon you are carrying that deals slashing damage. Until the spell ends, when you hit a creature with the weapon, the weapon deals an extra 1d4 necrotic damage and the creature must make a Constitution saving throw. On a failed save, the creature suffers a bleeding wound. Each time you hit a creature with this weapon while it suffers from a bleeding wound, your weapon deals an extra 1 necrotic damage for each time you have previously hit the creature with this weapon (to a maximum of 10 necrotic damage).\n\nAny creature can take an action to stanch the bleeding wound by succeeding on a Wisdom (Medicine) check against your spell save DC. The wound also closes if the target receives magical healing. This spell has no effect on undead or constructs.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_bless-the-dead","name":"Bless the Dead","level":0,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":["cleric","druid","warlock"],"desc":"You grant a blessing to one deceased creature, enabling it to cross over to the realm of the dead in peace. A creature that benefits from **bless the dead** can't become undead. The spell has no effect on living creatures or the undead.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_blessed-halo","name":"Blessed Halo","level":2,"school":"Evocation","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":["cleric","warlock","wizard"],"desc":"A nimbus of golden light surrounds your head for the duration. The halo sheds bright light in a 20-foot radius and dim light for an additional 20 feet.\n\nThis spell grants you a pool of 10 points of healing. When you cast the spell and as an action on subsequent turns during the spell's duration, you can expend points from this pool to restore an equal number of hit points to one creature within 20 feet that you can see.\n\nAdditionally, you have advantage on Charisma checks made against good creatures within 20 feet.\n\nIf any of the light created by this spell overlaps an area of magical darkness created by a spell of 2nd level or lower, the spell that created the darkness is dispelled.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the spell's pool of healing points increases by 5 for each spell slot above 2nd, and the spell dispels magical darkness created by a spell of a level equal to the slot used to cast this spell."},{"id":"deepm_blizzard","name":"Blizzard","level":7,"school":"Conjuration","time":"Action","range":"100 feet","components":"V, S","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"A howling storm of thick snow and ice crystals appears in a cylinder 40 feet high and 40 feet in diameter within range. The area is heavily obscured by the swirling snow. When the storm appears, each creature in the area takes 8d8 cold damage, or half as much damage with a successful Constitution saving throw. A creature also makes this saving throw and takes damage when it enters the area for the first time on a turn or ends its turn there. In addition, a creature that takes cold damage from this spell has disadvantage on Constitution saving throws to maintain concentration until the start of its next turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"8d8 cold","save":"con"},{"id":"deepm_blood-and-steel","name":"Blood and Steel","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":["cleric","sorcerer","wizard"],"desc":"When you cast this spell, you cut your hand and take 1d4 slashing damage that can't be healed until you take a long rest. You then touch a construct; it must make a successful Constitution saving throw or be charmed by you for the duration. If you or your allies are fighting the construct, it has advantage on the saving throw. Even constructs that are immune to charm effects can be affected by this spell.\n\nWhile the construct is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as, “Attack the ghouls,” “Block the bridge,” or, “Fetch that bucket.” If the construct completes the order and doesn't receive further direction from you, it defends itself.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the construct takes only the actions you specify and does nothing you haven't ordered it to do. During this time, you can also cause the construct to use a reaction, but doing this requires you to use your own reaction as well.\n\nEach time the construct takes damage, it makes a new Constitution saving throw against the spell. If the saving throw succeeds, the spell ends.\n\nIf the construct is already under your control when the spell is cast, it gains an Intelligence of 10 (unless its own Intelligence is higher, in which case it retains the higher score) for 4 hours. The construct is capable of acting independently, though it remains loyal to you for the spell's duration. You can also grant the target a bonus equal to your Intelligence modifier on one skill in which you have proficiency.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 5th‑level spell slot, the duration is concentration, up to 10 minutes. When you use a 6th-level spell slot, the duration is concentration, up to 1 hour. When you use a spell slot of 7th level or higher, the duration is concentration, up to 8 hours.","save":"con"},{"id":"deepm_blood-armor","name":"Blood Armor","level":3,"school":"Necromancy","time":"Bonus Action","range":"Self","components":"V, S (you must have just struck a foe with a melee weapon)","duration":"1 hour","classes":["sorcerer","warlock","wizard"],"desc":"When you strike a foe with a melee weapon attack, you can immediately cast **blood armor** as a bonus action. The foe you struck must contain blood; if the target doesn't bleed, the spell ends without effect. The blood flowing from your foe magically increases in volume and forms a suit of armor around you, granting you an Armor Class of 18 + your Dexterity modifier for the spell's duration. This armor has no Strength requirement, doesn't hinder spellcasting, and doesn't incur disadvantage on Dexterity (Stealth) checks.\n\nIf the creature you struck was a celestial, **blood armor** also grants you advantage on Charisma saving throws for the duration of the spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_blood-lure","name":"Blood Lure","level":2,"school":"Enchantment","time":"Action","range":"10 feet","components":"V, S, M (a container or pool of blood)","duration":"1 minute","classes":["cleric","sorcerer","wizard"],"desc":"You point at any location (a jar, a bowl, even a puddle) within range that contains at least a pint of blood. Each creature that feeds on blood and is within 60 feet of that location must make a Charisma saving throw. (This includes undead, such as vampires.) A creature that has Keen Smell or any similar scent-boosting ability has disadvantage on the saving throw, while undead have advantage on the saving throw. On a failed save, the creature is attracted to the blood and must move toward it unless impeded.\n\nOnce an affected creature reaches the blood, it tries to consume it, foregoing all other actions while the blood is present. A successful attack against an affected creature ends the effect, as does the consumption of the blood, which requires an action by an affected creature.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_blood-offering","name":"Blood Offering","level":3,"school":"Necromancy","time":"1 minute","range":"Touch","components":"V, S","duration":"Instantaneous","classes":["druid","ranger","sorcerer","warlock","wizard"],"desc":"You touch the corpse of a creature that isn't undead or a construct and consume its life force. You must have dealt damage to the creature before it died, and it must have been dead for no more than 1 hour. You regain a number of hit points equal to 1d4 × the creature's challenge rating (minimum of 1d4). The creature can be restored to life only by means of a [true resurrection](https://api.open5e.com/spells/true-resurrection) or a [wish](https://api.open5e.com/spells/wish) spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_blood-puppet","name":"Blood Puppet","level":4,"school":"Transmutation","time":"Action","range":"100 feet","components":"V, M (a drop of blood from the target)","duration":"1 minute","classes":["cleric","sorcerer","wizard"],"desc":"With a sample of its blood, you are able to magically control a creature's actions, like a marionette on magical strings. Choose a creature you can see within range whose blood you hold. The target must succeed on a Constitution saving throw, or you gain control over its physical activity (as long as you interact with the blood material component each round). As a bonus action on your turn, you can direct the creature to perform various activities. You can specify a simple and general course of action, such as, “Attack that creature,” “Run over there,” or, “Fetch that object.” If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability. The target is aware of being controlled. At the end of each of its turns, the target can make another Constitution saving throw. On a success, the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_blood-scarab","name":"Blood Scarab","level":1,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, M (a drop of the caster’s blood, and the exoskeleton of a scarab beetle)","duration":"Instantaneous","classes":["cleric","warlock"],"desc":"Your blood is absorbed into the beetle's exoskeleton to form a beautiful, rubylike scarab that flies toward a creature of your choice within range. The target must make a successful Constitution saving throw or take 1d6 necrotic damage. You gain temporary hit points equal to the necrotic damage dealt.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the number of scarabs increases by one for each slot level above 1st. You can direct the scarabs at the same target or at different targets. Each target makes a single saving throw, regardless of the number of scarabs targeting it.","save":"con"},{"id":"deepm_blood-spoor","name":"Blood Spoor","level":4,"school":"Divination","time":"Action","range":"Self","components":"V, S, M (a drop of the quarry’s blood)","duration":"10 minutes","classes":[],"desc":"By touching a drop of your quarry's blood (spilled or drawn within the past hour), you can follow the creature's trail unerringly across any surface or under water, no matter how fast you are moving. If your quarry takes flight, you can follow its trail along the ground—or through the air, if you have the means to fly.\n\nIf your quarry moves magically (such as by way of a [dimension door](https://api.open5e.com/spells/dimension-door) or a [teleport](https://api.open5e.com/spells/teleport) spell), you sense its trail as a straight path leading from where the magical movement started to where it ended. Such a route might lead through lethal or impassable barriers. This spell even reveals the route of a creature using [pass without trace](https://api.open5e.com/spells/pass-without-trace), but it fails to locate a creature protected by [nondetection](https://api.open5e.com/spells/nondetection) or by other effects that prevent [scrying](https://api.open5e.com/spells/scrying) spells or cause [divination](https://api.open5e.com/spells/divination) spells to fail. If your quarry moves to another plane, its trail ends without trace, but **blood spoor** picks up the trail again if the caster moves to the same plane as the quarry before the spell's duration expires.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_blood-tide","name":"Blood Tide","level":0,"school":"Necromancy","time":"Action","range":"25 feet","components":"V","duration":"4 rounds","classes":["sorcerer","wizard"],"desc":"When you cast this spell, a creature you designate within range must succeed on a Constitution saving throw or bleed from its nose, eyes, ears, and mouth. This bleeding deals no damage but imposes a –2 penalty on the creature's Intelligence, Charisma, and Wisdom checks. **Blood tide** has no effect on undead or constructs.\n\nA bleeding creature might attract the attention of creatures such as stirges, sharks, or giant mosquitoes, depending on the circumstances.\n\nA [cure wounds](https://api.open5e.com/spells/cure-wounds) spell stops the bleeding before the duration of blood tide expires, as does a successful DC 10 Wisdom (Medicine) check.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The spell's duration increases to 2 minutes when you reach 5th level, to 10 minutes when you reach 11th level, and to 1 hour when you reach 17th level.","save":"con"},{"id":"deepm_blood-to-acid","name":"Blood to Acid","level":9,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"When you cast this spell, you designate a creature within range and convert its blood into virulent acid. The target must make a Constitution saving throw. On a failed save, it takes 10d12 acid damage and is stunned by the pain for 1d4 rounds. On a successful save, it takes half the damage and isn't stunned.\n\nCreatures without blood, such as constructs and plants, are not affected by this spell. If **blood to acid** is cast on a creature composed mainly of blood, such as a [blood elemental](https://api.open5e.com/monsters/blood-elemental) or a [blood zombie](https://api.open5e.com/monsters/blood-zombie), the creature is slain by the spell if its saving throw fails.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"10d12 acid","save":"con"},{"id":"deepm_bloodhound","name":"Bloodhound","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a drop of ammonia)","duration":"8 hours","classes":["druid","ranger","sorcerer","wizard"],"desc":"You touch a willing creature to grant it an enhanced sense of smell. For the duration, that creature has advantage on Wisdom (Perception) checks that rely on smell and Wisdom (Survival) checks to follow tracks.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 3rd-level spell slot, you also grant the target blindsight out to a range of 30 feet for the duration."},{"id":"deepm_bloodshot","name":"Bloodshot","level":2,"school":"Conjuration","time":"Action","range":"40 feet","components":"V, S","duration":"Instantaneous","classes":["sorcerer","warlock","wizard"],"desc":"You launch a jet of boiling blood from your eyes at a creature within range. You take 1d6 necrotic damage and make a ranged spell attack against the target. If the attack hits, the target takes 2d10 fire damage plus 2d8 psychic damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the fire damage increases by 1d10 for each slot level above 2nd.","damage":"2d10 fire","attack":true},{"id":"deepm_bloody-hands","name":"Bloody Hands","level":1,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"You cause the hands (or other appropriate body parts, such as claws or tentacles) of a creature within range to bleed profusely. The target must succeed on a Constitution saving throw or take 1 necrotic damage each round and suffer disadvantage on all melee and ranged attack rolls that require the use of its hands for the spell's duration.\n\nCasting any spell that has somatic or material components while under the influence of this spell requires a DC 10 Constitution saving throw. On a failed save, the spell is not cast but it is not lost; the casting can be attempted again in the next round.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_bloody-smite","name":"Bloody Smite","level":1,"school":"Necromancy","time":"Bonus Action","range":"Self","components":"V","duration":"1 minute","classes":["cleric","druid","ranger","wizard"],"desc":"The next time during the spell's duration that you hit a creature with a melee weapon attack, your weapon pulses with a dull red light, and the attack deals an extra 1d6 necrotic damage to the target. Until the spell ends, the target must make a Constitution saving throw at the start of each of its turns. On a failed save, it takes 1d6 necrotic damage, it bleeds profusely from the mouth, and it can't speak intelligibly or cast spells that have a verbal component. On a successful save, the spell ends. If the target or an ally within 5 feet of it uses an action to tend the wound and makes a successful Wisdom (Medicine) check against your spell save DC, or if the target receives magical healing, the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"1d6 necrotic","save":"con"},{"id":"deepm_bloom","name":"Bloom","level":8,"school":"Conjuration","time":"1 hour","range":"1 mile","components":"V, S, M (a silver acorn worth 500 gp, which is consumed in the casting)","duration":"1 year","classes":["cleric","druid","wizard"],"desc":"You plant a silver acorn in solid ground and spend an hour chanting a litany of praises to the natural world, after which the land within 1 mile of the acorn becomes extremely fertile, regardless of its previous state. Any seeds planted in the area grow at twice the natural rate. Food harvested regrows within a week. After one year, the land slowly reverts to its normal fertility, unable to stave off the march of nature.\n\nChoose one of the following effects, which appears and grows immediately:\n- A field planted with vegetables of your choice, ready for harvest.\n- A thick forest of stout trees and ample undergrowth.\n- A grassland with wildflowers and fodder for grazing.\n- An orchard of fruit trees of your choice, growing in orderly rows and ready for harvest.\nLiving creatures that take a short rest within the area of a bloom spell receive the maximum hit points for Hit Dice expended. **Bloom** counters the effects of a [desolation](https://api.open5e.com/spells/desolation) spell.\n\n**Ritual Focus.** If you expend your ritual focus, the duration becomes permanent.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_boiling-blood","name":"Boiling Blood","level":4,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (a vial of blood)","duration":"1 minute","classes":["sorcerer","warlock","wizard"],"desc":"You cause the blood within a creature's body to boil with supernatural heat. Choose one creature that you can see within range that isn't a construct or an undead. The target must make a Constitution saving throw. On a successful save, it takes 2d6 fire damage and the spell ends. On a failed save, the creature takes 4d6 fire damage and is blinded. At the end of each of its turns, the target can make another Constitution saving throw. On a success, the spell ends. On a failure, the creature takes an additional 2d6 fire damage and remains blinded.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th. The creatures must be within 30 feet of each other when you target them.","damage":"2d6 fire","save":"con"},{"id":"deepm_boiling-oil","name":"Boiling Oil","level":2,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a vial of oil)","duration":"1 minute","classes":["sorcerer","wizard"],"desc":"You conjure a shallow, 15-foot-radius pool of boiling oil centered on a point within range. The pool is difficult terrain, and any creature that enters the pool or starts its turn there must make a Dexterity saving throw. On a failed save, the creature takes 3d8 fire damage and falls prone. On a successful save, a creature takes half as much damage and doesn't fall prone.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","damage":"3d8 fire","save":"dex"},{"id":"deepm_bolster-undead","name":"Bolster Undead","level":1,"school":"Necromancy","time":"Action","range":"60 feet","components":"V, S, M (a sprinkle of unholy water)","duration":"1 hour","classes":["cleric","sorcerer","warlock","wizard"],"desc":"You suffuse an area with negative energy to increase the difficulty of harming or affecting undead creatures.\n\nChoose up to three undead creatures within range. When a targeted creature makes a saving throw against being turned or against spells or effects that deal radiant damage, the target has advantage on the saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional undead creature for each slot level above 1st."},{"id":"deepm_booster-shot","name":"Booster Shot","level":3,"school":"Evocation","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":["ranger","sorcerer","warlock"],"desc":"You imbue a two-handed ranged weapon (typically a shortbow, longbow, light crossbow, or heavy crossbow) that you touch with a random magical benefit. While the spell lasts, a projectile fired from the weapon has an effect that occurs on a hit in addition to its normal damage. Roll a d6 to determine the additional effect for each casting of this spell.\n\nD6 | EFFECT\n1 | 2d10 acid damage to all creatures within 10 feet of the target\n2 | 2d10 lightning damage to the target and 1d10 lightning damage to all creatures in a 5-foot-wide line between the weapon and the target\n3 | 2d10 necrotic damage to the target, and the target has disadvantage on its first attack roll before the start of the weapon user's next turn\n4 | 2d10 cold damage to the target and 1d10 cold damage to all other creatures in a 60-foot cone in front of the weapon\n5 | 2d10 force damage to the target, and the target is pushed 20 feet\n6 | 2d10 psychic damage to the target, and the target is stunned until the start of the weapon user's next turn","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, all damage increases by 1d10 for each slot level above 3rd."},{"id":"deepm_boreass-breath","name":"Boreas’s Breath","level":2,"school":"Transmutation","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":["cleric","druid","ranger","wizard"],"desc":"You freeze standing water in a 20-foot cube or running water in a 10-foot cube centered on you. The water turns to solid ice. The surface becomes difficult terrain, and any creature that ends its turn on the ice must make a successful DC 10 Dexterity saving throw or fall prone.\n\nCreatures that are partially submerged in the water when it freezes become restrained. While restrained in this way, a creature takes 1d6 cold damage at the end of its turn. It can break free by using an action to make a successful Strength check against your spell save DC.\n\nCreatures that are fully submerged in the water when it freezes become incapacitated and cannot breathe. While incapacitated in this way, a creature takes 2d6 cold damage at the end of its turn. A trapped creature makes a DC 20 Strength saving throw after taking this damage at the end of its turn, breaking free from the ice on a success.\n\nThe ice has AC 10 and 15 hit points. It is vulnerable to fire damage, has resistance to nonmagical slashing and piercing damage, and is immune to cold, necrotic, poison, psychic, and thunder damage.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the size of the cube increases by 10 feet for each slot level above 2nd.","damage":"1d6 cold","save":"dex"},{"id":"deepm_bottled-arcana","name":"Bottled Arcana","level":5,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (an empty glass container)","duration":"24 hours","classes":[],"desc":"By touching an empty, stoppered glass container such as a vial or flask, you magically enable it to hold a single spell. To be captured, the spell must be cast within 1 round of casting **bottled arcana** and it must be intentionally cast into the container. The container can hold one spell of 3rd level or lower. The spell can be held in the container for as much as 24 hours, after which the container reverts to a mundane vessel and any magic inside it dissipates harmlessly.\n\nAs an action, any creature can unstop the container, thereby releasing the spell. If the spell has a range of self, the creature opening the container is affected; otherwise, the creature opening the container designates the target according to the captured spell's description. If a creature opens the container unwittingly (not knowing that the container holds a spell), the spell targets the creature opening the container or is centered on its space instead (whichever is more appropriate). [Dispel magic](https://api.open5e.com/spells/dispel-magic) cast on the container targets **bottled arcana**, not the spell inside. If **bottled arcana** is dispelled, the container becomes mundane and the spell inside dissipates harmlessly.\n\nUntil the spell in the container is released, its caster can't regain the spell slot used to cast that spell. Once the spell is released, its caster regains the use of that slot normally.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the level of the spell the container can hold increases by one for every slot level above 5th."},{"id":"deepm_bottomless-stomach","name":"Bottomless Stomach","level":1,"school":"Transmutation","time":"Action","range":"Self","components":"V","duration":"1 hour","classes":[],"desc":"When you cast this spell, you gain the ability to consume dangerous substances and contain them in an extradimensional reservoir in your stomach. The spell allows you to swallow most liquids, such as acids, alcohol, poison, and even quicksilver, and hold them safely in your stomach. You are unaffected by swallowing the substance, but the spell doesn't give you resistance or immunity to the substance in general; for example, you could safely drink a bucket of a black dragon's acidic spittle, but you'd still be burned if you were caught in the dragon's breath attack or if that bucket of acid were dumped over your head.\n\nThe spell allows you to store up to 10 gallons of liquid at one time. The liquid doesn't need to all be of the same type, and different types don't mix while in your stomach. Any liquid in excess of 10 gallons has its normal effect when you try to swallow it.\n\nAt any time before you stop concentrating on the spell, you can regurgitate up to 1 gallon of liquid stored in your stomach as a bonus action. The liquid is vomited into an adjacent 5-foot square. A target in that square must succeed on a DC 15 Dexterity saving throw or be affected by the liquid. The GM determines the exact effect based on the type of liquid regurgitated, using 1d6 damage of the appropriate type as the baseline.\n\nWhen you stop concentrating on the spell, its duration expires, or it's dispelled, the extradimensional reservoir and the liquid it contains cease to exist.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_breathtaking-wind","name":"Breathtaking Wind","level":1,"school":"Evocation","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You target a creature with a blast of wintry air. That creature must make a successful Constitution saving throw or become unable to speak or cast spells with a vocal component for the duration of the spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_breeze-compass","name":"Breeze Compass","level":3,"school":"Divination","time":"Action","range":"Self","components":"V, S, M (a magnetized needle)","duration":"1 hour","classes":[],"desc":"When you cast **breeze compass**, you must clearly imagine or mentally describe a location. It doesn't need to be a location you've been to as long as you know it exists on the Material Plane. Within moments, a gentle breeze arises and blows along the most efficient path toward that destination. Only you can sense this breeze, and whenever it brings you to a decision point (a fork in a passageway, for example), you must make a successful DC 8 Intelligence (Arcana) check to deduce which way the breeze indicates you should go. On a failed check, the spell ends. The breeze guides you around cliffs, lava pools, and other natural obstacles, but it doesn't avoid enemies or hostile creatures.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_brimstone-infusion","name":"Brimstone Infusion","level":0,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a flask of alchemist's fire and 5 gp worth of brimstone)","duration":"24 hours","classes":[],"desc":"You infuse an ordinary flask of alchemist's fire with magical brimstone. While so enchanted, the alchemist's fire can be thrown 40 feet instead of 20, and it does 2d6 fire damage instead of 1d4. The Dexterity saving throw to extinguish the flames uses your spell save DC instead of DC 10. Infused alchemist's fire returns to its normal properties after 24 hours.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_brittling","name":"Brittling","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (an icicle)","duration":"Instantaneous","classes":[],"desc":"This spell uses biting cold to make a metal or stone object you touch become brittle and more easily shattered. The object's hit points are reduced by a number equal to your level as a spellcaster, and Strength checks to shatter or break the object are made with advantage if they occur within 1 minute of the spell's casting. If the object isn't shattered during this time, it reverts to the state it was in before the spell was cast.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_broken-charge","name":"Broken Charge","level":1,"school":"Enchantment","time":"Reaction","range":"10 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"When an enemy that you can see moves to within 5 feet of you, you utter a perplexing word that alters the foe's course. The enemy must make a successful Wisdom saving throw or take 2d4 psychic damage and use the remainder of its speed to move in a direction of your choosing.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the target takes an additional 2d4 psychic damage for each slot level above 1st.","save":"wis"},{"id":"deepm_by-the-light-of-the-moon","name":"By the Light of the Moon","level":2,"school":"Divination","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"The area within 30 feet of you becomes bathed in magical moonlight. In addition to providing dim light, it highlights objects and locations that are hidden or that hold a useful clue. Until the spell ends, all Wisdom (Perception) and Intelligence (Investigation) checks made in the area are made with advantage.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_by-the-light-of-the-watchful-moon","name":"By the Light of the Watchful Moon","level":4,"school":"Divination","time":"Action","range":"90 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Regardless of the time of day or your location, you command the watchful gaze of the moon to illuminate threats to you and your allies. Shafts of bright moonlight, each 5 feet wide, shine down from the sky (or from the ceiling if you are indoors), illuminating all spaces within range that contain threats, whether they are enemies, traps, or hidden hazards. An enemy creature that makes a successful Charisma saving throw resists the effect and is not picked out by the moon's glow.\n\nThe glow does not make invisible creatures visible, but it does indicate an invisible creature's general location (somewhere within the 5-foot beam). The light continues to illuminate any target that moves, but a target that moves out of the spell's area is no longer illuminated. A threat that enters the area after the spell is cast is not subject to the spell's effect.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_call-shadow-mastiff","name":"Call Shadow Mastiff","level":3,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a dog’s tooth)","duration":"1 minute","classes":[],"desc":"You conjure a [shadow mastiff](https://api.open5e.com/monsters/shadow-mastiff) from the plane of shadow. This creature obeys your verbal commands to aid you in battle or to seek out a specific creature. It has the body of a large dog with a smooth black coat, 2 feet high at the shoulder and weighing 200 pounds.\n\nThe mastiff is friendly to you and your companions. Roll initiative for the mastiff; it acts on its own turn. It obeys simple, verbal commands from you, within its ability to act. Giving a command takes no action on your part.\n\nThe mastiff disappears when it drops to 0 hit points or when the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_calm-of-the-storm","name":"Calm of the Storm","level":3,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S, M (an amethyst worth 250 gp, which the spell consumes)","duration":"Instantaneous","classes":[],"desc":"While visualizing the world as you wish it was, you lay your hands upon a creature other than yourself and undo the effect of a chaos magic surge that affected the creature within the last minute. Reality reshapes itself as if the surge never happened, but only for that creature.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the time since the chaos magic surge can be 1 minute longer for each slot level above 3rd."},{"id":"deepm_candles-insight","name":"Candle’s Insight","level":1,"school":"Divination","time":"Action","range":"10 feet","components":"V, S, M (a blessed candle)","duration":"10 minutes","classes":[],"desc":"**Candle's insight** is cast on its target as the component candle is lit. The candle burns for up to 10 minutes unless it's extinguished normally or by the spell's effect. While the candle burns, the caster can question the spell's target, and the candle reveals whether the target speaks truthfully. An intentionally misleading or partial answer causes the flame to flicker and dim. An outright lie causes the flame to flare and then go out, ending the spell. The candle judges honesty, not absolute truth; the flame burns steadily through even an outrageously false statement, as long as the target believes it's true.\n\n**Candle's insight** is used across society: by merchants while negotiating deals, by inquisitors investigating heresy, and by monarchs as they interview foreign diplomats. In some societies, casting candle's insight without the consent of the spell's target is considered a serious breach of hospitality.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_carmello-voltas-irksome-preserves","name":"Carmello-Volta’s Irksome Preserves","level":2,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S, M (a small berry or a piece of fruit)","duration":"1 minute","classes":[],"desc":"At your command, delicious fruit jam oozes from a small mechanical device (such as a crossbow trigger, a lock, or a clockwork toy), rendering the device inoperable until the spell ends and the device is cleaned with a damp cloth. Cleaning away the jam takes an action, but doing so has no effect until the spell ends. One serving of the jam can be collected in a suitable container. If it's eaten (as a bonus action) within 24 hours, the jam restores 1d4 hit points. The jam's flavor is determined by the material component.\n\nThe spell can affect constructs, with two limitations. First, the target creature negates the effect with a successful Dexterity saving throw. Second, unless the construct is Tiny, only one component (an eye, a knee, an elbow, and so forth) can be disabled. The affected construct has disadvantage on attack rolls and ability checks that depend on the disabled component until the spell ends and the jam is removed.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_catapult","name":"Catapult","level":6,"school":"Transmutation","time":"Action","range":"400 feet","components":"V, S, M (a small platinum lever and fulcrum worth 400 gp)","duration":"Instantaneous","classes":[],"desc":"You magically hurl an object or creature weighing 500 pounds or less 40 feet through the air in a direction of your choosing (including straight up). Objects hurled at specific targets require a spell attack roll to hit. A thrown creature takes 6d10 bludgeoning damage from the force of the throw, plus any appropriate falling damage, and lands prone. If the target of the spell is thrown against another creature, the total damage is divided evenly between them and both creatures are knocked prone.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d10, the distance thrown increases by 10 feet, and the weight thrown increases by 100 pounds for each slot level above 6th.","damage":"6d10 bludgeoning"},{"id":"deepm_catch-the-breath","name":"Catch the Breath","level":3,"school":"Transmutation","time":"Reaction","range":"Self","components":"V","duration":"Instantaneous","classes":[],"desc":"You can cast this spell as a reaction when you're targeted by a breath weapon. Doing so gives you advantage on your saving throw against the breath weapon. If your saving throw succeeds, you take no damage from the attack even if a successful save normally only halves the damage.\n\nWhether your saving throw succeeded or failed, you absorb and store energy from the attack. On your next turn, you can make a ranged spell attack against a target within 60 feet. On a hit, the target takes 3d10 force damage. If you opt not to make this attack, the stored energy dissipates harmlessly.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the damage done by your attack increases by 1d10 for each slot level above 3rd.","damage":"3d10 force","attack":true},{"id":"deepm_caustic-blood","name":"Caustic Blood","level":2,"school":"Transmutation","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Your blood becomes caustic when exposed to the air. When you take piercing or slashing damage, you can use your reaction to select up to three creatures within 30 feet of you. Each target takes 1d10 acid damage unless it makes a successful Dexterity saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the number of targets increases by one for each slot level above 2nd, to a maximum of six targets.","damage":"1d10 acid","save":"dex"},{"id":"deepm_caustic-torrent","name":"Caustic Torrent","level":8,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a chip of bone pitted by acid)","duration":"Instantaneous","classes":[],"desc":"A swirling jet of acid sprays from you in a direction you choose. The acid fills a line 60 feet long and 5 feet wide. Each creature in the line takes 14d6 acid damage, or half as much damage if it makes a successful Dexterity saving throw. A creature reduced to 0 hit points by this spell is killed, and its body is liquefied. In addition, each creature other than you that's in the line or within 5 feet of it is poisoned for 1 minute by toxic fumes. Creatures that don't breathe or that are immune to acid damage aren't poisoned. A poisoned creature can repeat the Constitution saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"14d6 acid","save":"dex"},{"id":"deepm_caustic-touch","name":"Caustic Touch","level":0,"school":"Evocation","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Your hand sweats profusely and becomes coated in a film of caustic slime. Make a melee spell attack against a creature you touch. On a hit, the target takes 1d8 acid damage. If the target was concentrating on a spell, it has disadvantage on its Constitution saving throw to maintain concentration.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","damage":"1d8 acid","save":"con","attack":true},{"id":"deepm_celebration","name":"Celebration","level":7,"school":"Enchantment","time":"Action","range":"90 feet","components":"V, S, M (a small party favor)","duration":"1 hour","classes":[],"desc":"You create a 30-foot-radius area around a point that you choose within range. An intelligent creature that enters the area or starts its turn there must make a Wisdom saving throw. On a failed save, the creature starts to engage in celebratory revelry: drinking, singing, laughing, and dancing. Affected creatures are reluctant to leave the area until the spell ends, preferring to continue the festivities. They forsake appointments, cease caring about their woes, and generally behave in a cordial (if not hedonistic) manner. This preoccupation with merrymaking occurs regardless of an affected creature's agenda or alignment. Assassins procrastinate, servants join in the celebration rather than working, and guards abandon their posts.\n\nThe effect ends on a creature when it is attacked, takes damage, or is forced to leave the area. A creature that makes a successful saving throw can enter or leave the area without danger of being enchanted. A creature that fails the saving throw and is forcibly removed from the area must repeat the saving throw if it returns to the area.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, the spell lasts for an additional hour for each slot level above 7th.\n\n**Ritual Focus.** If you expend your ritual focus, an unaffected intelligent creature must make a new saving throw every time it starts its turn in the area, even if it has previously succeeded on a save against the spell.","save":"wis"},{"id":"deepm_chains-of-the-goddess","name":"Chains of the Goddess","level":5,"school":"Enchantment","time":"Action","range":"90 feet","components":"V, S, M (1 foot of iron chain)","duration":"1 minute","classes":[],"desc":"Choose a creature you can see within 90 feet. The target must make a successful Wisdom saving throw or be restrained by chains of psychic force and take 6d8 bludgeoning damage. A restrained creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a successful save. While restrained in this way, the creature also takes 6d8 bludgeoning damage at the start of each of your turns.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"6d8 bludgeoning","save":"wis"},{"id":"deepm_chains-of-torment","name":"Chains of Torment","level":4,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (an iron chain link dipped in blood)","duration":"1 minute","classes":[],"desc":"You are surrounded by an aura of dim light in a 10-foot radius as you conjure an iron chain that extends out to a creature you can see within 30 feet. The creature must make a successful Dexterity saving throw or be grappled (escape DC equal to your spell save DC). While grappled in this way, the creature is also restrained. A creature that's restrained at the start of its turn takes 4d6 psychic damage. You can have only one creature restrained in this way at a time.\n\nAs an action, you can scan the mind of the creature that's restrained by your chain. If the creature gets a failure on a Wisdom saving throw, you learn one discrete piece of information of your choosing known by the creature (such as a name, a password, or an important number). The effect is otherwise harmless.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the psychic damage increases by 1d6 for each slot level above 4th.","damage":"4d6 psychic","save":"dex"},{"id":"deepm_champions-weapon","name":"Champion’s Weapon","level":2,"school":"Conjuration","time":"Bonus Action","range":"Self","components":"V, S","duration":"10 minutes","classes":[],"desc":"A spectral version of a melee weapon of your choice materializes in your hand. It has standard statistics for a weapon of its kind, but it deals force damage instead of its normal damage type and it sheds dim light in a 10-foot radius. You have proficiency with this weapon for the spell's duration. The weapon can be wielded only by the caster; the spell ends if the weapon is held by a creature other than you or if you start your turn more than 10 feet from the weapon.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the weapon deals an extra 1d8 force damage for each slot level above 2nd."},{"id":"deepm_chaotic-form","name":"Chaotic Form","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"10 minutes","classes":[],"desc":"You cause the form of a willing creature to become malleable, dripping and flowing according to the target's will as if the creature were a vaguely humanoid-shaped ooze. The creature is not affected by difficult terrain, it has advantage on Dexterity (Acrobatics) checks made to escape a grapple, and it suffers no penalties when squeezing through spaces one size smaller than itself. The target's movement is halved while it is affected by **chaotic form**.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the duration increases by 10 minutes for each slot level above 4th."},{"id":"deepm_chaotic-vitality","name":"Chaotic Vitality","level":2,"school":"Conjuration","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Make a melee spell attack against a creature that has a number of Hit Dice no greater than your level and has at least 1 hit point. On a hit, you conjure pulsating waves of chaotic energy within the creature and yourself. After a brief moment that seems to last forever, your hit point total changes, as does the creature's. Roll a d100 and increase or decrease the number rolled by any number up to your spellcasting level, then find the result on the Hit Point Flux table. Apply that result both to yourself and the target creature. Any hit points gained beyond a creature's normal maximum are temporary hit points that last for 1 round per caster level.\n\nFor example, a 3rd-level spellcaster who currently has 17 of her maximum 30 hit points casts **chaotic vitality** on a creature with 54 hit points and rolls a 75 on the Hit Point Flux table. The two creatures have a combined total of 71 hit points. A result of 75 indicates that both creatures get 50 percent of the total, so the spellcaster and the target end up with 35 hit points each. In the spellcaster's case, 5 of those hit points are temporary and will last for 3 rounds.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the maximum Hit Dice of the affected creature increases by 2 for each slot level above 2nd.\n ## Hit Point Flux \nSIZE | HP\n01–09 | 0\n10–39 | 1\n40–69 | 25 percent of total\n70–84 | 50 percent of total\n85–94 | 75 percent of total\n95–99 | 100 percent of total\n100 | 200 percent of total, and both creatures gain the effect of a haste spell that lasts for 1 round per caster level"},{"id":"deepm_chaotic-world","name":"Chaotic World","level":6,"school":"Illusion","time":"Action","range":"60 feet","components":"V, M (seven irregular pieces of colored cloth that you throw into the air)","duration":"1 minute","classes":[],"desc":"You throw a handful of colored cloth into the air while screaming a litany of disjointed phrases. A moment later, a 30-foot cube centered on a point within range fills with multicolored light, cacophonous sound, overpowering scents, and other confusing sensory information. The effect is dizzying and overwhelming. Each enemy within the cube must make a successful Intelligence saving throw or become blinded and deafened, and fall prone. An affected enemy cannot stand up or recover from the blindness or deafness while within the area, but all three conditions end immediately for a creature that leaves the spell's area.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"int"},{"id":"deepm_chilling-words","name":"Chilling Words","level":3,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S, M (a strip of paper with writing on it)","duration":"1 hour","classes":[],"desc":"You utter a short phrase and designate a creature within range to be affected by it. The target must make a Wisdom saving throw to avoid the spell. On a failed save, the target is susceptible to the phrase for the duration of the spell. At any later time while the spell is in effect, you and any of your allies within range when you cast the spell can use an action to utter the phrase, which causes the target to freeze in fear. Each of you can use the phrase against the target once only, and the target must be within 30 feet of the speaker for the phrase to be effective.\n\nWhen the target hears the phrase, it must make a successful Constitution saving throw or take 1d6 psychic damage and become restrained for 1 round. Whether this saving throw succeeds or fails, the target can't be affected by the phrase for 1 minute afterward.\n\nYou can end the spell early by making a final utterance of the phrase (even if you've used the phrase on this target previously). On hearing this final utterance, the target takes 4d6 psychic damage and is restrained for 1 minute or, with a successful Constitution saving throw, it takes half the damage and is restrained for 1 round.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d6 psychic","save":"wis"},{"id":"deepm_chronal-lance","name":"Chronal Lance","level":1,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You inflict the ravages of aging on up to three creatures within range, temporarily discomfiting them and making them appear elderly for a time. Each target must make a successful Wisdom saving throw, or its walking speed is halved (round up to the nearest 5-foot increment) and it has disadvantage on Dexterity checks (but not saving throws). An affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.","save":"wis"},{"id":"deepm_circle-of-wind","name":"Circle of Wind","level":1,"school":"Abjuration","time":"Action","range":"Self","components":"V, S, M (a crystal ring)","duration":"8 hours","classes":[],"desc":"Light wind encircles you, leaving you in the center of a mild vortex. For the duration, you gain a +2 bonus to your AC against ranged attacks. You also have advantage on saving throws against extreme environmental heat and against harmful gases, vapors, and inhaled poisons.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_clash-of-glaciers","name":"Clash of Glaciers","level":5,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a piece of cracked glass)","duration":"Instantaneous","classes":[],"desc":"You conjure up icy boulders that crush creatures in a line 100 feet long. Each creature in the area takes 5d6 bludgeoning damage plus 5d6 cold damage, or half the damage with a successful Dexterity saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d6 for each slot level above 5th. You decide whether each extra die deals bludgeoning or cold damage.","damage":"5d6 bludgeoning","save":"dex"},{"id":"deepm_claws-of-darkness","name":"Claws of Darkness","level":0,"school":"Evocation","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"You shape shadows into claws that grow from your fingers and drip inky blackness. The claws have a reach of 10 feet. While the spell lasts, you can make a melee spell attack with them that deals 1d10 cold damage.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","attack":true},{"id":"deepm_claws-of-the-earth-dragon","name":"Claws of the Earth Dragon","level":5,"school":"Evocation","time":"Action","range":"60 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"You summon the power of the earth dragon and shoot a ray at one target within 60 feet. The target falls prone and takes 6d8 bludgeoning damage from being slammed to the ground. If the target was flying or levitating, it takes an additional 1d6 bludgeoning damage per 10 feet it falls. If the target makes a successful Strength saving throw, damage is halved, it doesn't fall, and it isn't knocked prone.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the damage done by the attack increases by 1d8 and the range increases by 10 feet for each slot level above 5th.","damage":"6d8 bludgeoning","save":"str"},{"id":"deepm_clearing-the-field","name":"Clearing the Field","level":2,"school":"Transmutation","time":"Action","range":"40 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"With a harsh word and a vicious chopping motion, you cause every tree, shrub, and stump within 40 feet of you to sink into the ground, leaving the vacated area clear of plant life that might otherwise hamper movement or obscure sight. Overgrown areas that counted as difficult terrain become clear ground and no longer hamper movement. The original plant life instantly rises from the ground again when the spell ends or is dispelled. Plant creatures are not affected by **clearing the field**.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the spell lasts for an additional hour for each slot level above 2nd.\n\n**Ritual Focus.** If you expend your ritual focus, plant creatures in the area must make a successful Constitution saving throw or be affected as though by a [enlarge/reduce](https://api.open5e.com/spells/enlargereduce) spell."},{"id":"deepm_cloak-of-shadow","name":"Cloak of Shadow","level":1,"school":"Illusion","time":"Bonus Action","range":"Self","components":"V","duration":"1 minute","classes":[],"desc":"You cloak yourself in shadow, giving you advantage on Dexterity (Stealth) checks against creatures that rely on sight.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_clockwork-bolt","name":"Clockwork Bolt","level":0,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S, M (an arrow or crossbow bolt)","duration":"1 round","classes":[],"desc":"You imbue an arrow or crossbow bolt with clockwork magic just as you fire it at your target; spinning blades materialize on the missile after it strikes to further mutilate your enemy.\n\nAs part of the action used to cast this spell, you make a ranged weapon attack with a bow or a crossbow against one creature within range. If the attack hits, the missile embeds in the target. Unless the target (or an ally of it within 5 feet) uses an action to remove the projectile (which deals no additional damage), the target takes an additional 1d8 slashing damage at the end of its next turn from spinning blades that briefly sprout from the missile's shaft. Afterward, the projectile reverts to normal.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell deals more damage when you reach higher levels. At 5th level, the ranged attack deals an extra 1d8 slashing damage to the target, and the target takes an additional 1d8 slashing damage (2d8 total) if the embedded ammunition isn't removed. Both damage amounts increase by 1d8 again at 11th level and at 17th level.","damage":"1d8 slashing"},{"id":"deepm_closing-in","name":"Closing In","level":3,"school":"Illusion","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Choose a creature you can see within range. The target must succeed on a Wisdom saving throw, which it makes with disadvantage if it's in an enclosed space. On a failed save, the creature believes the world around it is closing in and threatening to crush it. Even in open or clear terrain, the creature feels as though it is sinking into a pit, or that the land is rising around it. The creature has disadvantage on ability checks and attack rolls for the duration, and it takes 2d6 psychic damage at the end of each of its turns. An affected creature repeats the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd.","damage":"2d6 psychic","save":"wis"},{"id":"deepm_cobra-fangs","name":"Cobra Fangs","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a drop of snake venom or a patch of snakeskin)","duration":"1 minute","classes":[],"desc":"The spell causes the target to grow great, snake-like fangs. An unwilling creature must make a Wisdom saving throw to avoid the effect. The spell fails if the target already has a bite attack that deals poison damage.\n\nIf the target doesn't have a bite attack, it gains one. The target is proficient with the bite, and it adds its Strength modifier to the attack and damage rolls. The damage is piercing and the damage die is a d4.\n\nWhen the target hits a creature with its bite attack, the creature must make a Constitution saving throw, taking 3d6 poison damage on a failed save, or half as much damage on a successful one.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the target's bite counts as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.","save":"wis"},{"id":"deepm_compelled-movement","name":"Compelled Movement","level":3,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S, M (the embalmed body of a millipede with its right legs removed, worth at least 50 gp)","duration":"1 minute","classes":[],"desc":"Choose two living creatures (not constructs or undead) you can see within range. Each must make a Charisma saving throw. On a failed save, a creature is compelled to use its movement to move toward the other creature. Its route must be as direct as possible, but it avoids dangerous terrain and enemies. If the creatures are within 5 feet of each other at the end of either one's turn, their bodies fuse together. Fused creatures still take their own turns, but they can't move, can't use reactions, and have disadvantage on attack rolls, Dexterity saving throws, and Constitution checks to maintain concentration.\n\nA fused creature can use its action to make a Charisma saving throw. On a success, the creature breaks free and can move as it wants. It can become fused again, however, if it's within 5 feet of a creature that's still under the spell's effect at the end of either creature's turn.\n\n**Compelled movement** doesn't affect a creature that can't be charmed or that is incorporeal.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the number of creatures you can affect increases by one for every two slot levels above 3rd.","save":"cha"},{"id":"deepm_compelling-fate","name":"Compelling Fate","level":3,"school":"Divination","time":"Action","range":"30 feet","components":"V, M (a sprinkling of silver dust worth 20 gp)","duration":"1 round","classes":[],"desc":"You view the actions of a single creature you can see through the influence of the stars, and you read what is written there. If the target fails a Charisma saving throw, you can predict that creature's actions. This has the following effects:\n- You have advantage on attack rolls against the target.\n- For every 5 feet the target moves, you can move 5 feet (up to your normal movement) on the target's turn when it has completed its movement. This is deducted from your next turn's movement.\n- As a reaction at the start of the target's turn, you can warn yourself and allies that can hear you of the target's offensive intentions; any creature targeted by the target's next attack gains a +2 bonus to AC or to its saving throw against that attack.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the duration is extended by 1 round for each slot level above 3rd.","save":"cha"},{"id":"deepm_comprehend-wild-shape","name":"Comprehend Wild Shape","level":2,"school":"Divination","time":"Action","range":"Touch","components":"V, S, M (two or more matching carved totems)","duration":"1 hour","classes":[],"desc":"Give one of the carved totems to an ally while keeping the other yourself. For the duration of the spell, you and whoever holds the other totem can communicate while either of you is in a beast shape. This isn't a telepathic link; you simply understand each other's verbal communication, similar to the effect of a speak with animals spell. This effect doesn't allow a druid in beast shape to cast spells.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can increase the number of target creatures by two for each slot level above 2nd. Each creature must receive a matching carved totem."},{"id":"deepm_confound-senses","name":"Confound Senses","level":3,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S, M (a broken compass)","duration":"10 minutes","classes":[],"desc":"This spell befuddles the minds of up to six creatures that you can see within range, causing the creatures to see images of shifting terrain. Each target that fails an Intelligence saving throw is reduced to half speed until the spell ends because of confusion over its surroundings, and it makes ranged attack rolls with disadvantage.\n\nAffected creatures also find it impossible to keep track of their location. They automatically fail Wisdom (Survival) checks to avoid getting lost. Whenever an affected creature must choose between one or more paths, it chooses at random and immediately forgets which direction it came from.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"int"},{"id":"deepm_conjure-fey-hound","name":"Conjure Fey Hound","level":5,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a wooden or metal whistle)","duration":"1 hour","classes":[],"desc":"You summon a fey hound to fight by your side. A [hound of the night](https://api.open5e.com/monsters/hound-of-the-night) appears in an unoccupied space that you can see within range. The hound disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned hound is friendly to you and your companions. Roll initiative for the summoned hound, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the hound, it stands by your side and attacks nearby creatures that are hostile to you but otherwise takes no actions.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, you summon two hounds. When you cast this spell using a 9th-level spell slot, you summon three hounds."},{"id":"deepm_conjure-forest-defender","name":"Conjure Forest Defender","level":6,"school":"Conjuration","time":"1 hour","range":"30 feet","components":"V, S, M (one humanoid body, which the spell consumes)","duration":"Until destroyed","classes":[],"desc":"When you cast this spell in a forest, you fasten sticks and twigs around a body. The body comes to life as a [forest defender](https://api.open5e.com/monsters/forest-defender). The forest defender is friendly to you and your companions. Roll initiative for the forest defender, which has its own turns. It obeys any verbal or mental commands that you issue to it (no action required by you), as long as you remain within its line of sight. If you don't issue any commands to the forest defender, if you are out of its line of sight, or if you are unconscious, it defends itself from hostile creatures but otherwise takes no actions. A body sacrificed to form the forest defender is permanently destroyed and can be restored to life only by means of a [true resurrection](https://api.open5e.com/spells/true-resurrection) or a [wish](https://api.open5e.com/spells/wish) spell. You can have only one forest defender under your control at a time. If you cast this spell again, the previous forest defender crumbles to dust.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 9th‐level spell slot, you summon two forest defenders instead of one, and you can control up to two forest defenders at a time."},{"id":"deepm_conjure-greater-spectral-dead","name":"Conjure Greater Spectral Dead","level":7,"school":"Conjuration","time":"1 minute","range":"60 feet","components":"V, S, M (a handful of bone dust, a crystal prism worth at least 100 gp, and a platinum coin)","duration":"1 hour","classes":[],"desc":"You summon an incorporeal undead creature that appears in an unoccupied space you can see within range. You choose one of the following options for what appears:\n- One [wraith](https://api.open5e.com/monsters/wraith)\n- One [spectral guardian](https://api.open5e.com/monsters/spectral-guardian)\n- One [wolf spirit swarm](https://api.open5e.com/monsters/wolf-spirit-swarm)\nSummoned creatures disappear when they drop to 0 hit points or when the spell ends.\n\nThe summoned creature doesn't attack you or your companions for the duration. Roll initiative for the summoned creature, which has its own turns. The creature attacks your enemies and tries to stay within 60 feet of you, but it otherwise controls its own actions. The summoned creature despises being bound and might harm or impede you and your companions by any means at its disposal other than direct attacks if the opportunity arises. At the beginning of the creature's turn, you can use your reaction to verbally command it. The creature obeys your commands for that turn, and you take 1d6 psychic damage at the end of the turn. If your concentration is broken, the creature doesn't disappear. Instead, you can no longer command it, it becomes hostile to you and your companions, and it attacks you and your allies if it believes it has a chance to win the fight or to inflict meaningful harm; otherwise it flees. You can't dismiss the uncontrolled creature, but it disappears 1 hour after you summoned it.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 9th‐level spell slot, you summon a [deathwisp](https://api.open5e.com/monsters/deathwisp) or two [ghosts](https://api.open5e.com/monsters/ghost) instead."},{"id":"deepm_conjure-minor-voidborn","name":"Conjure Minor Voidborn","level":5,"school":"Conjuration","time":"1 minute","range":"90 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"You summon fiends or aberrations that appear in unoccupied spaces you can see within range. You choose one of the following options:\n- One creature of challenge rating 2 or lower\n- Two creatures of challenge rating 1 or lower\n- Four creatures of challenge rating 1/2 or lower\n- Eight creatures of challenge rating 1/4 or lower\nSummoned creatures disappear when they drop to 0 hit points or when the spell ends.\n\nThe summoned creatures do not directly attack you or your companions. Roll initiative for the summoned creatures as a group; they take their own turns on their initiative result. They attack your enemies and try to stay within 90 feet of you, but they control their own actions. The summoned creatures despise being bound, so they might harm or impede you and your companions with secondary effects (but not direct attacks) if the opportunity arises. At the beginning of the creatures' turn, you can use your reaction to verbally command them. They obey your commands on that turn, and you take 1d6 psychic damage at the end of the turn.\n\nIf your concentration is broken, the spell ends but the creatures don't disappear. Instead, you can no longer command them, and they become hostile to you and your companions. They will attack you and your allies if they believe they have a chance to win the fight or to inflict meaningful harm, but they won't fight if they fear it would mean their own death. You can't dismiss the creatures, but they disappear 1 hour after being summoned.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 7th‑or 9th-level spell slot, you choose one of the summoning options above, and more creatures appear­—twice as many with a 7th-level spell slot and three times as many with a 9th-level spell slot."},{"id":"deepm_conjure-scarab-swarm","name":"Conjure Scarab Swarm","level":2,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a beetle carapace)","duration":"10 minutes","classes":[],"desc":"You summon swarms of scarab beetles to attack your foes. Two swarms of insects (beetles) appear in unoccupied spaces that you can see within range.\n\nEach swarm disappears when it drops to 0 hit points or when the spell ends. The swarms are friendly to you and your allies. Make one initiative roll for both swarms, which have their own turns. They obey verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures but otherwise take no actions.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_conjure-shadow-titan","name":"Conjure Shadow Titan","level":7,"school":"Conjuration","time":"1 minute","range":"90 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"You summon a shadow titan, which appears in an unoccupied space that you can see within range. The shadow titan's statistics are identical to a [stone giant's](https://api.open5e.com/monsters/stone-giant), with two differences: its camouflage ability works in dim light instead of rocky terrain, and the “rocks” it hurls are composed of shadow-stuff and cause cold damage.\n\nThe shadow titan is friendly to you and your companions. Roll initiative for the shadow titan; it acts on its own turn. It obeys verbal or telepathic commands that you issue to it (giving a command takes no action on your part). If you don't issue any commands to the shadow titan, it defends itself from hostile creatures but otherwise takes no actions.\n\nThe shadow titan disappears when it drops to 0 hit points or when the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_conjure-spectral-dead","name":"Conjure Spectral Dead","level":2,"school":"Conjuration","time":"1 minute","range":"60 feet","components":"V, S, M (a handful of bone dust, a crystal prism, and a silver coin)","duration":"1 hour","classes":[],"desc":"You summon a [shroud](https://api.open5e.com/monsters/shroud) to do your bidding. The creature appears in an unoccupied space that you can see within range. The creature is friendly to you and your allies for the duration. Roll initiative for the creature, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the creature, it defends itself from hostile creatures but otherwise takes no actions. The creature disappears when it drops to 0 hit points or when the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 3rd-level spell slot, you can choose to summon two [shrouds](https://api.open5e.com/monsters/shroud) or one [specter](https://api.open5e.com/monsters/specter). When you cast this spell with a spell slot of 4th level or higher, you can choose to summon four [shrouds](https://api.open5e.com/monsters/shroud) or one [will-o'-wisp](https://api.open5e.com/monsters/will-o-wisp)."},{"id":"deepm_conjure-undead","name":"Conjure Undead","level":3,"school":"Conjuration","time":"1 minute","range":"30 feet","components":"V, S, M (a humanoid skull)","duration":"1 hour","classes":[],"desc":"You summon a [shadow](https://api.open5e.com/monsters/shadow) to do your bidding. The creature appears in an unoccupied space that you can see within range. The creature is friendly to you and your allies for the duration. Roll initiative for the shadow, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the creature, it defends itself from hostile creatures but otherwise takes no actions. The shadow disappears when the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 4th-level spell slot, you can choose to summon a [wight](https://api.open5e.com/monsters/wight) or a [shadow](https://api.open5e.com/monsters/shadow). When you cast this spell with a spell slot of 5th level or higher, you can choose to summon a [ghost](https://api.open5e.com/monsters/ghost), a [shadow](https://api.open5e.com/monsters/shadow), or a [wight](https://api.open5e.com/monsters/wight)."},{"id":"deepm_conjure-voidborn","name":"Conjure Voidborn","level":7,"school":"Conjuration","time":"Action","range":"90 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"You summon a fiend or aberration of challenge rating 6 or lower, which appears in an unoccupied space that you can see within range. The creature disappears when it drops to 0 hit points or when the spell ends.\n\nRoll initiative for the creature, which takes its own turns. It attacks the nearest creature on its turn. At the start of the fiend's turn, you can use your reaction to command the creature by speaking in Void Speech. It obeys your verbal command, and you take 2d6 psychic damage at the end of the creature's turn.\n\nIf your concentration is broken, the spell ends but the creature doesn't disappear. Instead, you can no longer issue commands to the fiend, and it becomes hostile to you and your companions. It will attack you and your allies if it believes it has a chance to win the fight or to inflict meaningful harm, but it won't fight if it fears doing so would mean its own death. You can't dismiss the creature, but it disappears 1 hour after you summoned it.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, the challenge rating increases by 1 for each slot level above 7th."},{"id":"deepm_consult-the-storm","name":"Consult the Storm","level":4,"school":"Divination","time":"Action","range":"90 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"You ask a question of an entity connected to storms, such as an elemental, a deity, or a primal spirit, and the entity replies with destructive fury.\n\nAs part of the casting of the spell, you must speak a question consisting of fifteen words or fewer. Choose a point within range. A short, truthful answer to your question booms from that point. It can be heard clearly by any creature within 600 feet. Each creature within 15 feet of the point takes 7d6 thunder damage, or half as much damage with a successful Constitution saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d6 for each slot level above 4th.","damage":"7d6 thunder","save":"con"},{"id":"deepm_converse-with-dragon","name":"Converse With Dragon","level":1,"school":"Divination","time":"Action","range":"Self","components":"V","duration":"10 minutes","classes":[],"desc":"You gain limited telepathy, allowing you to communicate with any creature within 120 feet of you that has the dragon type, regardless of the creature's languages. A dragon can choose to make a Charisma saving throw to prevent telepathic contact with itself.\n\nThis spell doesn't change a dragon's disposition toward you or your allies, it only opens a channel of communication. In some cases, unwanted telepathic contact can worsen the dragon's attitude toward you.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_costly-victory","name":"Costly Victory","level":8,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"You select up to ten enemies you can see that are within range. Each target must make a Wisdom saving throw. On a failed save, that creature is cursed to burst into flame if it reduces one of your allies to 0 hit points before this spell's duration expires. The affected creature takes 6d8 fire damage and 6d8 radiant damage when it bursts into flame.\n\nIf the affected creature is wearing flammable material (or is made of flammable material, such as a plant creature), it catches on fire and continues burning; the creature takes fire damage equal to your spellcasting ability modifier at the end of each of its turns until the creature or one of its allies within 5 feet of it uses an action to extinguish the fire.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"6d8 fire","save":"wis"},{"id":"deepm_create-ring-servant","name":"Create Ring Servant","level":8,"school":"Transmutation","time":"1 minute","range":"Touch","components":"V, S, M (two metal rings)","duration":"1 hour","classes":[],"desc":"You touch two metal rings and infuse them with life, creating a short-lived but sentient construct known as a [ring servant](https://api.open5e.com/monsters/ring-servant). The ring servant appears adjacent to you. It reverts form, changing back into the rings used to cast the spell, when it drops to 0 hit points or when the spell ends.\n\nThe ring servant is friendly to you and your companions for the duration. Roll initiative for the ring servant, which acts on its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the ring servant, it defends itself and you from hostile creatures but otherwise takes no actions.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_create-thunderstaff","name":"Create Thunderstaff","level":7,"school":"Transmutation","time":"10 minutes","range":"Touch","components":"V, S, M (a quarterstaff)","duration":"Instantaneous","classes":[],"desc":"After you cast **create thunderstaff** on a normal quarterstaff, the staff must then be mounted in a noisy location, such as a busy marketplace, and left there for 60 days. During that time, the staff gradually absorbs ambient sound.\n\nAfter 60 days, the staff is fully charged and can't absorb any more sound. At that point, it becomes a **thunderstaff**, a +1 quarterstaff that has 10 charges. When you hit on a melee attack with the staff and expend 1 charge, the target takes an extra 1d8 thunder damage. You can cast a [thunderwave](https://api.open5e.com/spells/thunderwave) spell from the staff as a bonus action by expending 2 charges. The staff cannot be recharged.\n\nIf the final charge is not expended within 60 days, the staff becomes nonmagical again.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"1d8 thunder"},{"id":"deepm_creeping-ice","name":"Creeping Ice","level":2,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You create a sheet of ice that covers a 5-foot square within range and lasts for the spell's duration. The iced area is difficult terrain.\n\nA creature in the area where you cast the spell must make a successful Strength saving throw or be restrained by ice that rapidly encases it. A creature restrained by the ice takes 2d6 cold damage at the start of its turn. A restrained creature can use an action to make a Strength check against your spell save DC, freeing itself on a success, but it has disadvantage on this check. The creature can also be freed (and the spell ended) by dealing at least 20 damage to the ice. The restrained creature takes half the damage from any attacks against the ice.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th to 6th level, the area increases to a 10-foot square, the ice deals 4d6 cold damage, and 40 damage is needed to melt each 5-foot square. When you cast this spell using a spell slot of 7th level or higher, the area increases to a 20-foot square, the ice deals 6d6 cold damage, and 60 damage is needed to melt each 5-foot square.","damage":"2d6 cold","save":"str"},{"id":"deepm_crushing-curse","name":"Crushing Curse","level":0,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You speak a word of Void Speech. Choose a creature you can see within range. If the target can hear you, it must succeed on a Wisdom saving throw or take 1d6 psychic damage and be deafened for 1 minute, except that it can still hear Void Speech. A creature deafened in this way can repeat the saving throw at the end of each of its turns, ending the effect on a success.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).","save":"wis"},{"id":"deepm_crushing-trample","name":"Crushing Trample","level":2,"school":"Transmutation","time":"Action","range":"Self","components":"V, S","duration":"1 round","classes":[],"desc":"Upon casting this spell, you are filled with a desire to overrun your foes. You immediately move up to twice your speed in a straight line, trampling every foe in your path that is of your size category or smaller. If you try to move through the space of an enemy whose size is larger than yours, your movement (and the spell) ends. Each enemy whose space you move through must make a successful Strength saving throw or be knocked prone and take 4d6 bludgeoning damage. If you have hooves, add your Strength modifier (minimum of +1) to the damage.\n\nYou move through the spaces of foes whether or not they succeed on their Strength saving throws. You do not provoke opportunity attacks while moving under the effect of **crushing trample**.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_cure-beast","name":"Cure Beast","level":1,"school":"Evocation","time":"Bonus Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"A beast of your choice that you can see within range regains a number of hit points equal to 1d6 + your spellcasting modifier.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d6 for each slot level above 1st."},{"id":"deepm_curse-of-boreas","name":"Curse of Boreas","level":6,"school":"Transmutation","time":"Action","range":"100 feet","components":"V, S","duration":"Permanent","classes":[],"desc":"You designate a creature within range that you can see. If the target fails a Charisma saving throw, it and its equipment are frozen solid, becoming an inert statue of ice. The creature is effectively paralyzed, but mental activity does not cease, and signs of life are detectable; the creature still breathes and its heart continues to beat, though both acts are almost imperceptible. If the ice statue is broken or damaged while frozen, the creature will have matching damage or injury when returned to its original state. [Dispel magic](https://api.open5e.com/spells/dispel-magic) can't end this spell, but it can allow the target to speak (but not move or cast spells) for a number of rounds equal to the spell slot used. [Greater restoration](https://api.open5e.com/spells/greater-restoration) or more potent magic is needed to free a creature from the ice.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_curse-of-dust","name":"Curse of Dust","level":7,"school":"Necromancy","time":"10 minutes","range":"500 feet","components":"V, S, M (a piece of spoiled food)","duration":"5 days","classes":[],"desc":"You cast a curse on a creature within range that you're familiar with, causing it to be unsatiated by food no matter how much it eats. This effect isn't merely an issue of perception; the target physically can't draw sustenance from food. Within minutes after the spell is cast, the target feels constant hunger no matter how much food it consumes. The target must make a Constitution saving throw 24 hours after the spell is cast and every 24 hours thereafter. On a failed save, the target gains one level of exhaustion. The effect ends when the duration expires or when the target makes two consecutive successful saves.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_curse-of-incompetence","name":"Curse of Incompetence","level":3,"school":"Necromancy","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"By making mocking gestures toward one creature within\nrange that can see you, you leave the creature incapable of\nperforming at its best. If the target fails on an Intelligence\nsaving throw, roll a d4 and refer to the following table to\ndetermine what the target does on its turn. An affected\ntarget repeats the saving throw at the end of each of its\nturns, ending the effect on itself on a success or applying\nthe result of another roll on the table on a failure.\n\nD4 | RESULT\n1 | Target spends its turn shouting mocking words at caster and takes a -5 penalty to its initiative roll.\n2 | Target stands transfixed and blinking, takes no action.\n3 | Target flees or fights (50 percent chance of each).\n4 | Target charges directly at caster, enraged.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_curse-of-the-grave","name":"Curse of the Grave","level":7,"school":"Necromancy","time":"Action","range":"120 feet","components":"V, S, M (a pinch of dirt from a freshly dug grave)","duration":"Until dispelled","classes":[],"desc":"You tap your connection to death to curse a humanoid, making the grim pull of the grave stronger on that creature's soul.\n\nChoose one humanoid you can see within range. The target must succeed on a Constitution saving throw or become cursed. A [remove curse](https://api.open5e.com/spells/remove-curse) spell or similar magic ends this curse. While cursed in this way, the target suffers the following effects:\n- The target fails death saving throws on any roll but a 20.\n- If the target dies while cursed, it rises 1 round later as a vampire spawn under your control and is no longer cursed.\n- The target, as a vampire spawn, seeks you out in an attempt to serve its new master. You can have only one vampire spawn under your control at a time through this spell. If you create another, the existing one turns to dust. If you or your companions do anything harmful to the target, it can make a Wisdom saving throw. On a success, it is no longer under your control.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_curse-of-yig","name":"Curse of Yig","level":5,"school":"Transmutation","time":"1 minute","range":"60 feet","components":"V, S, M (a drop of snake venom)","duration":"1 hour","classes":[],"desc":"This spell transforms a Small, Medium, or Large creature that you can see within range into a [servant of Yig](https://api.open5e.com/monsters/servant-of-yig). An unwilling creature can attempt a Wisdom saving throw, negating the effect with a success. A willing creature is automatically affected and remains so for as long as you maintain concentration on the spell.\n\nThe transformation lasts for the duration or until the target drops to 0 hit points or dies. The target's statistics, including mental ability scores, are replaced by the statistics of a servant of Yig. The transformed creature's alignment becomes neutral evil, and it is both friendly to you and reverent toward the Father of Serpents. Its equipment is unchanged. If the transformed creature was unwilling, it makes a Wisdom saving throw at the end of each of its turns. On a successful save, the spell ends, the creature's alignment and personality return to normal, and it regains its former attitude toward you and toward Yig.\n\nWhen it reverts to its normal form, the creature has the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_curse-ring","name":"Curse Ring","level":5,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M (250 gp worth of diamond dust, which the spell consumes)","duration":"Permanent until discharged","classes":[],"desc":"You lay a curse upon a ring you touch that isn't being worn or carried. When you cast this spell, select one of the possible effects of [bestow curse](https://api.open5e.com/spells/bestow-curse). The next creature that willingly wears the ring suffers the chosen effect with no saving throw. The curse transfers from the ring to the wearer once the ring is put on; the ring becomes a mundane ring that can be taken off, but the curse remains on the creature that wore the ring until the curse is removed or dispelled. An [identify](https://api.open5e.com/spells/identify) spell cast on the cursed ring reveals the fact that it is cursed.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_cursed-gift","name":"Cursed Gift","level":4,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S, M (an object worth at least 75 gp)","duration":"24 hours","classes":[],"desc":"**Cursed gift** imbues an object with a harmful magical effect that you or another creature in physical contact with you is currently suffering from. If you give this object to a creature that freely accepts it during the duration of the spell, the recipient must make a Charisma saving throw. On a failed save, the harmful effect is transferred to the recipient for the duration of the spell (or until the effect ends). Returning the object to you, destroying it, or giving it to someone else has no effect. Remove curse and comparable magic can relieve the individual who received the item, but the harmful effect still returns to the previous victim when this spell ends if the effect's duration has not expired.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the duration increases by 24 hours for each slot level above 4th.","save":"cha"},{"id":"deepm_cynophobia","name":"Cynophobia","level":3,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S, M (a dog’s tooth)","duration":"8 hours","classes":[],"desc":"Choose a creature that you can see within range. The target must succeed on a Wisdom saving throw or develop an overriding fear of canids, such as dogs, wolves, foxes, and worgs. For the duration, the first time the target sees a canid, the target must succeed on a Wisdom saving throw or become frightened of that canid until the end of its next turn. Each time the target sees a different canid, it must make the saving throw. In addition, the target has disadvantage on ability checks and attack rolls while a canid is within 10 feet of it.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 5th-level spell slot, the duration is 24 hours. When you use a 7th-level spell slot, the duration is 1 month. When you use a spell slot of 8th or 9th level, the spell lasts until it is dispelled.","save":"wis"},{"id":"deepm_daggerhawk","name":"Daggerhawk","level":2,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a dagger)","duration":"1 minute","classes":[],"desc":"When **daggerhawk** is cast on a nonmagical dagger, a ghostly hawk appears around the weapon. The hawk and dagger fly into the air and make a melee attack against one creature you select within 60 feet, using your spell attack modifier and dealing piercing damage equal to 1d4 + your Intelligence modifier on a hit. On your subsequent turns, you can use an action to cause the daggerhawk to attack the same target. The daggerhawk has AC 14 and, although it's invulnerable to all damage, a successful attack against it that deals bludgeoning, force, or slashing damage sends the daggerhawk tumbling, so it can't attack again until after your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_dark-dementing","name":"Dark Dementing","level":5,"school":"Illusion","time":"Action","range":"120 feet","components":"V, S, M (a moonstone)","duration":"10 minutes","classes":[],"desc":"A dark shadow creeps across the target's mind and leaves a small bit of shadow essence behind, triggering a profound fear of the dark. A creature you designate within range must make a Charisma saving throw. If it fails, the target becomes frightened of you for the duration. A frightened creature can repeat the saving throw each time it takes damage, ending the effect on a success. While frightened in this way, the creature will not willingly enter or attack into a space that isn't brightly lit. If it's in dim light or darkness, the creature must either move toward bright light or create its own (by lighting a lantern, casting a [light](https://api.open5e.com/spells/light) spell, or the like).","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_dark-heraldry","name":"Dark Heraldry","level":3,"school":"Necromancy","time":"Action","range":"60 feet","components":"V","duration":"1 minute","classes":[],"desc":"Dark entities herald your entry into combat, instilling an existential dread in your enemies. Designate a number of creatures up to your spellcasting ability modifier (minimum of one) that you can see within range and that have an alignment different from yours. Each of those creatures takes 5d8 psychic damage and becomes frightened of you; a creature that makes a successful Wisdom saving throw takes half as much damage and is not frightened.\n\nA creature frightened in this way repeats the saving throw at the end of each of its turns, ending the effect on itself on a success. The creature makes this saving throw with disadvantage if you can see it.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd.","damage":"5d8 psychic","save":"wis"},{"id":"deepm_dark-maw","name":"Dark Maw","level":0,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"1 round","classes":[],"desc":"Thick, penumbral ichor drips from your shadow-stained mouth, filling your mouth with giant shadow fangs. Make a melee spell attack against the target. On a hit, the target takes 1d8 necrotic damage as your shadowy fangs sink into it. If you have a bite attack (such as from a racial trait or a spell like [alter self](https://api.open5e.com/spells/after-self)), you can add your spellcasting ability modifier to the damage roll but not to your temporary hit points.\n\nIf you hit a humanoid target, you gain 1d4 temporary hit points until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","damage":"1d8 necrotic","attack":true},{"id":"deepm_dark-path","name":"Dark Path","level":2,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S, M (a lodestone)","duration":"1 minute","classes":[],"desc":"You conjure a shadowy road between two points within range to create a bridge or path. This effect can bridge a chasm or create a smooth path through difficult terrain. The dark path is 10 feet wide and up to 50 feet long. It can support up to 500 pounds of weight at one time. A creature that adds more weight than the path can support sinks through the path as if it didn't exist.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_darkbolt","name":"Darkbolt","level":2,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You utter a quick invocation to create a black nimbus around your hand, then hurl three rays of darkness at one or more targets in range. The rays can be divided between targets however you like. Make a ranged spell attack for each target (not each ray); each ray that hits deals 1d10 cold damage. A target that was hit by one or more rays must make a successful Constitution saving throw or be unable to use reactions until the start of its next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you create one additional ray for each slot level above 2nd.","save":"con","attack":true},{"id":"deepm_dead-walking","name":"Dead Walking","level":2,"school":"Illusion","time":"Action","range":"10 feet","components":"V, S, M (a copper piece)","duration":"1 hour","classes":[],"desc":"As part of the casting of this spell, you place a copper piece under your tongue. This spell makes up to six willing creatures you can see within range invisible to undead for the duration. Anything a target is wearing or carrying is invisible as long as it is on the target's person. The spell ends for all targets if one target attacks or casts a spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 3rd-level spell slot, it lasts for 1 hour without requiring your concentration. When you cast this spell using a spell slot of 4th level or higher, the duration increases by 1 hour for each slot level above 3rd."},{"id":"deepm_deadly-sting","name":"Deadly Sting","level":8,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a thorn)","duration":"1 minute","classes":[],"desc":"You grow a 10-foot-long tail as supple as a whip, tipped with a horrible stinger. During the spell's duration, you can use the stinger to make a melee spell attack with a reach of 10 feet. On a hit, the target takes 1d4 piercing damage plus 4d10 poison damage, and a creature must make a successful Constitution saving throw or become vulnerable to poison damage for the duration of the spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"1d4 piercing","save":"con","attack":true},{"id":"deepm_death-gods-touch","name":"Death God’s Touch","level":7,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"This spell allows you to shred the life force of a creature you touch. You become invisible and make a melee spell attack against the target. On a hit, the target takes 10d10 necrotic damage. If this damage reduces the target to 0 hit points, the target dies. Whether the attack hits or misses, you remain invisible until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, the damage increases by 2d10 for each slot level above 7th.","damage":"10d10 necrotic","attack":true},{"id":"deepm_decay","name":"Decay","level":0,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M (a handful of ash)","duration":"Instantaneous","classes":[],"desc":"Make a melee spell attack against a creature you touch. On a hit, the target takes 1d10 necrotic damage. If the target is a Tiny or Small nonmagical object that isn't being worn or carried by a creature, it automatically takes maximum damage from the spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell's damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).","damage":"1d10 necrotic"},{"id":"deepm_decelerate","name":"Decelerate","level":2,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (a toy top)","duration":"1 minute","classes":[],"desc":"You slow the flow of time around a creature within range that you can see. The creature must make a successful Wisdom saving throw, or its walking speed is halved (round up to the nearest 5-foot increment). The creature can repeat the saving throw at the end of each of its turns, ending the effect on a success. Until the spell ends, on a failed save the target's speed is halved again at the start of each of your turns. For example, if a creature with a speed of 30 feet fails its initial saving throw, its speed drops to 15 feet. At the start of your next turn, the creature's speed drops to 10 feet on a failed save, then to 5 feet on the following round on another failed save. **Decelerate** can't reduce a creature's speed to less than 5 feet.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can affect an additional creature for each slot level above 2nd.","save":"wis"},{"id":"deepm_deep-breath","name":"Deep Breath","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"2 hours","classes":[],"desc":"The recipient of this spell can breathe and function normally in thin atmosphere, suffering no ill effect at altitudes of up to 20,000 feet. If more than one creature is touched during the casting, the duration is divided evenly among all creatures touched.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the duration increases by 2 hours for each slot level above 1st."},{"id":"deepm_defile-healing","name":"Defile Healing","level":7,"school":"Necromancy","time":"Reaction","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You attempt to reverse the energy of a healing spell so that it deals damage instead of healing. If the healing spell is being cast with a spell slot of 5th level or lower, the slot is expended but the spell restores no hit points. In addition, each creature that was targeted by the healing spell takes necrotic damage equal to the healing it would have received, or half as much damage with a successful Constitution saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level, it can reverse a healing spell being cast using a spell slot of 6th level or lower. If you use a 9th-level spell slot, it can reverse a healing spell being cast using a spell slot of 7th level or lower.","save":"con"},{"id":"deepm_delay-potion","name":"Delay Potion","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"1 hour","classes":[],"desc":"Upon casting this spell, you delay the next potion you consume from taking effect for up to 1 hour. You must consume the potion within 1 round of casting **delay potion**; otherwise the spell has no effect. At any point during **delay potion's** duration, you can use a bonus action to cause the potion to go into effect. When the potion is activated, it works as if you had just drunk it. While the potion is delayed, it has no effect at all and you can consume and benefit from other potions normally.\n\nYou can delay only one potion at a time. If you try to delay the effect of a second potion, the spell fails, the first potion has no effect, and the second potion has its normal effect when you drink it.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_delayed-healing","name":"Delayed Healing","level":3,"school":"Evocation","time":"1 minute","range":"Touch","components":"V, M (a bloodstone worth 100 gp, which the spell consumes)","duration":"Instantaneous","classes":[],"desc":"Touch a living creature (not a construct or undead) as you cast the spell. The next time that creature takes damage, it immediately regains hit points equal to 1d4 + your spellcasting ability modifier (minimum of 1).","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the healing increases by 1d4 for each slot level above 3rd."},{"id":"deepm_demon-within","name":"Demon Within","level":3,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S, M (a vial of blood from a humanoid killed within the previous 24 hours)","duration":"1 minute","classes":[],"desc":"One humanoid of your choice within range becomes a gateway for a demon to enter the plane of existence you are on. You choose the demon's type from among those of challenge rating of 4 or lower. The target must make a Wisdom saving throw. On a success, the gateway fails to open, and the spell has no effect. On a failed save, the target takes 4d6 force damage from the demon's attempt to claw its way through the gate. For the spell's duration, you can use a bonus action to further agitate the demon, dealing an additional 2d6 force damage to the target each time.\n\nIf the target drops to 0 hit points while affected by this spell, the demon tears through the body and appears in the same space as its now incapacitated or dead victim. You do not control this demon; it is free to either attack or leave the area as it chooses. The demon disappears after 24 hours or when it drops to 0 hit points.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d6 force","save":"wis"},{"id":"deepm_desiccating-breath","name":"Desiccating Breath","level":4,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a clump of dried clay)","duration":"Instantaneous","classes":[],"desc":"You spew forth a cloud of black dust that draws all moisture from a 30-foot cone. Each animal in the cone takes 4d10 necrotic damage, or half as much damage if it makes a successful Constitution saving throw. The damage is 6d10 for plants and plant creatures, also halved on a successful Constitution saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d10 necrotic","save":"con"},{"id":"deepm_desolation","name":"Desolation","level":8,"school":"Necromancy","time":"1 hour","range":"Self","components":"V, S, M (an obsidian acorn worth 500 gp, which is consumed in the casting)","duration":"1 year","classes":[],"desc":"You plant an obsidian acorn in solid ground and spend an hour chanting a litany of curses to the natural world, after which the land within 1 mile of the acorn becomes infertile, regardless of its previous state. Nothing will grow there, and all plant life in the area dies over the course of a day. Plant creatures are not affected. Spells that summon plants, such as [entangle](https://api.open5e.com/spells/entangle), require an ability check using the caster's spellcasting ability against your spell save DC. On a successful check, the spell functions normally; if the check fails, the spell is countered by **desolation**.\n\nAfter one year, the land slowly reverts to its normal fertility, unable to stave off the march of nature.\n\nA living creature that finishes a short rest within the area of a **desolation** spell halves the result of any Hit Dice it expends. Desolation counters the effects of a [bloom](https://api.open5e.com/spells/bloom) spell.\n\n**Ritual Focus.** If you expend your ritual focus, the duration becomes permanent.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_destructive-resonance","name":"Destructive Resonance","level":2,"school":"Enchantment","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You shout a scathing string of Void Speech that assaults the minds of those before you. Each creature in a 15-foot cone that can hear you takes 4d6 psychic damage, or half that damage with a successful Wisdom saving throw. A creature damaged by this spell can't take reactions until the start of its next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.","damage":"4d6 psychic","save":"wis"},{"id":"deepm_detect-dragons","name":"Detect Dragons","level":2,"school":"Divination","time":"Action","range":"Self","components":"V, S","duration":"10 minutes","classes":[],"desc":"You can detect the presence of dragons and other draconic creatures within your line of sight and 120 feet, regardless of disguises, illusions, and alteration magic such as polymorph. The information you uncover depends on the number of consecutive rounds you spend an action studying a subject or area. On the first round of examination, you detect whether any draconic creatures are present, but not their number, location, identity, or type. On the second round, you learn the number of such creatures as well as the general condition of the most powerful one. On the third and subsequent rounds, you make a DC 15 Intelligence (Arcana) check; if it succeeds, you learn the age, type, and location of one draconic creature. Note that the spell provides no information on the turn in which it is cast, unless you have the means to take a second action that turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_devas-wings","name":"Deva’s Wings","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a wing feather from any bird)","duration":"10 minutes","classes":[],"desc":"You touch a willing creature. The target grows feathery wings of pure white that grant it a flying speed of 60 feet and the ability to hover. When the target takes the Attack action, it can use a bonus action to make a melee weapon attack with the wings, with a reach of 10 feet. If the wing attack hits, the target takes bludgeoning damage equal to 1d6 + your spellcasting ability modifier and must make a successful Strength saving throw or fall prone. When the spell ends, the wings disappear, and the target falls if it was aloft.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you can target one additional target for each slot level above 4th.","save":"str"},{"id":"deepm_dimensional-shove","name":"Dimensional Shove","level":3,"school":"Conjuration","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"This spell pushes a creature you touch through a dimensional portal, causing it to disappear and then reappear a short distance away. If the target fails a Wisdom saving throw, it disappears from its current location and reappears 30 feet away from you in a direction of your choice. This travel can take it through walls, creatures, or other solid surfaces, but the target can't reappear inside a solid object or not on solid ground; instead, it reappears in the nearest safe, unoccupied space along the path of travel.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the target is shoved an additional 30 feet for each slot level above 3rd.","save":"wis"},{"id":"deepm_disquieting-gaze","name":"Disquieting Gaze","level":1,"school":"Necromancy","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"Your eyes burn with scintillating motes of unholy crimson light. Until the spell ends, you have advantage on Charisma (Intimidation) checks made against creatures that can see you, and you have advantage on spell attack rolls that deal necrotic damage to creatures that can see your eyes.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_disruptive-aura","name":"Disruptive Aura","level":8,"school":"Evocation","time":"Action","range":"150 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"A warping, prismatic aura surrounds and outlines each creature inside a 10-foot cube within range. The aura sheds dim light out to 10 feet, and the the locations of hidden or invisible creatures are outlined. If a creature in the area tries to cast a spell or use a magic item, it must make a Wisdom saving throw. On a successful save, the spell or item functions normally. On a failed save, the effect of the spell or the item is suppressed for the duration of the aura. Time spent suppressed counts against the duration of the spell's or item's effect.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 9th‐level spell slot, the cube is 20 feet on a side.","save":"wis"},{"id":"deepm_distracting-divination","name":"Distracting Divination","level":2,"school":"Divination","time":"Reaction","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Foresight tells you when and how to be just distracting enough to foil an enemy spellcaster. When an adjacent enemy tries to cast a spell, make a melee spell attack against that enemy. On a hit, the enemy's spell fails and has no effect; the enemy's action is used up but the spell slot isn't expended.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","attack":true},{"id":"deepm_distraction-cascade","name":"Distraction Cascade","level":2,"school":"Divination","time":"Reaction","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"With a flash of foresight, you throw a foe off balance. Choose one creature you can see that your ally has just declared as the target of an attack. Unless that creature makes a successful Charisma saving throw, attacks against it are made with advantage until the end of this turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_doom-of-blue-crystal","name":"Doom of Blue Crystal","level":3,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a blue crystal)","duration":"3 rounds","classes":[],"desc":"You are surrounded by a field of glowing, blue energy lasting 3 rounds. Creatures within 5 feet of you, including yourself, must make a Constitution saving throw when the spell is cast and again at the start of each of your turns while the spell is in effect. A creature whose saving throw fails is restrained; a restrained creature whose saving throw fails is paralyzed; and a paralyzed creature whose saving throw fails is petrified and transforms into a statue of blue crystal. As with all concentration spells, you can end the field at any time (no action required). If you are turned to crystal, the spell ends after all affected creatures make their saving throws. Restrained and paralyzed creatures recover immediately when the spell ends, but petrification is permanent.\n\nCreatures turned to crystal can see, hear, and smell normally, but they don't need to eat or breathe. If shatter is cast on a crystal creature, it must succeed on a Constitution saving throw against the caster's spell save DC or be killed.\n\nCreatures transformed into blue crystal can be restored with dispel magic, greater restoration, or comparable magic.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_doom-of-consuming-fire","name":"Doom of Consuming Fire","level":2,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a dead coal or a fistful of ashes)","duration":"1 minute","classes":[],"desc":"You are wreathed in cold, purple fire that damages creatures near you. You take 1d6 cold damage each round for the duration of the spell. Creatures within 5 feet of you when you cast the spell and at the start of each of your turns while the spell is in effect take 1d8 cold damage.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 3rd-level spell slot, the purple fire extends 10 feet from you, you take 1d8 cold damage, and other creatures take 1d10 cold damage. When you cast this spell using a 4th‐level slot, the fire extends 15 feet from you, you take1d10 cold damage, and other creatures take 1d12 cold damage. When you cast this spell using a slot of 5th level or higher, the fire extends to 20 feet, you take 1d12 cold damage, and other creatures take 1d20 cold damage."},{"id":"deepm_doom-of-dancing-blades","name":"Doom of Dancing Blades","level":3,"school":"Illusion","time":"Action","range":"Self","components":"V, S","duration":"1 hour","classes":[],"desc":"When you cast **doom of dancing blades**, you create 1d4 illusory copies of your weapon that float in the air 5 feet from you. These images move with you, spinning, shifting, and mimicking your attacks. When you are hit by a melee attack but the attack roll exceeded your Armor Class by 3 or less, one illusory weapon parries the attack; you take no damage and the illusory weapon is destroyed. When you are hit by a melee attack that an illusory weapon can't parry (the attack roll exceeds your AC by 4 or more), you take only half as much damage from the attack, and an illusory weapon is destroyed. Spells and effects that affect an area or don't require an attack roll affect you normally and don't destroy any illusory weapons.\n\nIf you make a melee attack that scores a critical hit while **doom of dancing blades** is in effect on you, all your illusory weapons also strike the target and deal 1d8 bludgeoning, piercing, or slashing damage (your choice) each.\n\nThe spell ends when its duration expires or when all your illusory weapons are destroyed or expended.\n\nAn attacker must be able to see the illusory weapons to be affected. The spell has no effect if you are invisible or in total darkness or if the attacker is blinded.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_doom-of-disenchantment","name":"Doom of Disenchantment","level":3,"school":"Abjuration","time":"Action","range":"Self","components":"V, S","duration":"5 rounds","classes":[],"desc":"When you cast **doom of disenchantment**, your armor and shield glow with light. When a creature hits you with an attack, the spell counters any magic that provides the attack with a bonus to hit or to damage. For example, a +1 weapon would still be considered magical, but it gets neither +1 to hit nor +1 to damage on any attack against you.\n\nThe spell also suppresses other magical properties of the attack. A [sword of wounding](https://api.open5e.com/magicitems/sword-of-wounding), for example, can't cause ongoing wounds on you, and you recover hit points lost to the weapon's damage normally. If the attack was a spell, it's affected as if you had cast [counterspell](https://api.open5e.com/spells/counterspell), using Charisma as your spellcasting ability. Spells with a duration of instantaneous, however, are unaffected.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_doom-of-serpent-coils","name":"Doom of Serpent Coils","level":4,"school":"Necromancy","time":"Action","range":"Self","components":"V, S, M (a vial of poison)","duration":"Instantaneous","classes":[],"desc":"You drink a dose of venom or other poison and spread the effect to other living things around you. If the poison normally allows a saving throw, your save automatically fails. You suffer the effect of the poison normally before spreading the poison to all other living creatures within 10 feet of you. Instead of making the usual saving throw against the poison, each creature around you makes a Constitution saving throw against the spell. On a successful save, a target suffers no damage or other effect from the poison and is immune to further castings of **doom of serpent coils** for 24 hours. On a failed save, a target doesn't suffer the poison's usual effect; instead, it takes 4d6 poison damage and is poisoned. While poisoned in this way, a creature repeats the saving throw at the end of each of its turns. On a subsequent failed save, it takes 4d6 poison damage and is still poisoned. On a subsequent successful save, it is no longer poisoned and is immune to further castings of **doom of serpent coils** for 24 hours.\n\nMultiple castings of this spell have no additional effect on creatures that are already poisoned by it. The effect can be ended by [protection from poison](https://api.open5e.com/spells/protection-from-poison) or comparable magic.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d6 poison","save":"con"},{"id":"deepm_doom-of-the-cracked-shield","name":"Doom of the Cracked Shield","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Doom of the cracked shield is cast on a melee weapon. The next time that weapon is used, it destroys the target's nonmagical shield or damages nonmagical armor, in addition to the normal effect of the attack. If the foe is using a nonmagical shield, it breaks into pieces. If the foe doesn't use a shield, its nonmagical armor takes a -2 penalty to AC. If the target doesn't use armor or a shield, the spell is expended with no effect.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_doom-of-the-earthen-maw","name":"Doom of the Earthen Maw","level":4,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"The ground within 30 feet of a point you designate turns into filthy and slippery muck. This spell affects sand, earth, mud, and ice, but not stone, wood, or other material. For the duration, the ground in the affected area is difficult terrain. A creature in the area when you cast the spell must succeed on a Strength saving throw or be restrained by the mud until the spell ends. A restrained creature can free itself by using an action to make a successful Strength saving throw. A creature that frees itself or that enters the area after the spell was cast is affected by the difficult terrain but doesn't become restrained.\n\nEach round, a restrained creature sinks deeper into the muck. A Medium or smaller creature that is restrained for 3 rounds becomes submerged at the end of its third turn. A Large creature becomes submerged after 4 rounds. Submerged creatures begin suffocating if they aren't holding their breath. A creature that is still submerged when the spell ends is sealed beneath the newly solidified ground. The creature can escape only if someone else digs it out or it has a burrowing speed.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_doom-of-the-slippery-rogue","name":"Doom of the Slippery Rogue","level":2,"school":"Conjuration","time":"Action","range":"40 feet","components":"V, S, M (bacon fat)","duration":"1 minute","classes":[],"desc":"A **doom of the slippery rogue** spell covers a 20-foot-by-20-foot section of wall or floor within range with a thin coating of grease. If a vertical surface is affected, each climber on that surface must make a successful DC 20 Strength (Athletics) check or immediately fall from the surface unless it is held in place by ropes or other climbing gear. A creature standing on an affected floor falls prone unless it makes a successful Dexterity saving throw. Creatures that try to climb or move through the affected area can move no faster than half speed (this is cumulative with the usual reduction for climbing), and any movement must be followed by a Strength saving throw (for climbing) or a Dexterity saving throw (for walking). On a failed save, the moving creature falls or falls prone.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_douse-light","name":"Douse Light","level":0,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"With a simple gesture, you can put out a single small source of light within range. This spell extinguishes a torch, a candle, a lantern, or a [light](https://api.open5e.com/spells/light) or [dancing lights](https://api.open5e.com/spells/dancing-lights) cantrip.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_draconic-smite","name":"Draconic Smite","level":1,"school":"Evocation","time":"Bonus Action","range":"Self","components":"V","duration":"1 minute","classes":[],"desc":"The next time you hit a creature with a melee weapon attack during the spell's duration, your weapon takes on the form of a silver dragon's head. Your attack deals an extra 1d6 cold damage, and up to four other creatures of your choosing within 30 feet of the attack's target must each make a successful Constitution saving throw or take 1d6 cold damage.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the extra cold damage and the cold damage dealt to the secondary creatures increases by 1d6 for each slot level above 1st.","save":"con"},{"id":"deepm_dragon-breath","name":"Dragon Breath","level":5,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a piece of a dragon’s tooth)","duration":"1 minute","classes":[],"desc":"You summon draconic power to gain a breath weapon. When you cast dragon breath, you can immediately exhale a cone or line of elemental energy, depending on the type of dragon you select. While the spell remains active, roll a d6 at the start of your turn. On a roll of 5 or 6, you can take a bonus action that turn to use the breath weapon again.\n\nWhen you cast the spell, choose one of the dragon types listed below. Your choice determines the affected area and the damage of the breath attack for the spell's duration.\n\nDragon Type | Area | Damage\nBlack | 30-foot line, 5 feet wide | 6d6 acid damage\nBlue | 30-foot line, 5 feet wide | 6d6 lightning damage\nGreen | 15-foot cone | 6d6 poison damage\nRed | 15-foot cone | 6d6 fire damage\nWhite | 15-foot cone | 6d6 cold damage","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 2d6 for each slot level above 5th."},{"id":"deepm_dragon-roar","name":"Dragon Roar","level":0,"school":"Evocation","time":"Action","range":"30 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"Your voice is amplified to assault the mind of one creature. The target must make a Charisma saving throw. If it fails, the target takes 1d4 psychic damage and is frightened until the start of your next turn. A target can be affected by your dragon roar only once per 24 hours.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4).","damage":"1d4 psychic","save":"cha"},{"id":"deepm_drown","name":"Drown","level":3,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S, M (a small piece of flotsam or seaweed)","duration":"Instantaneous","classes":[],"desc":"You cause a creature's lungs to fill with seawater. Unless the target makes a successful Constitution saving throw, it immediately begins suffocating. A suffocating creature can't speak or perform verbal spell components. It can hold its breath, and thereafter can survive for a number of rounds equal to its Constitution modifier (minimum of 1 round), after which it drops to 0 hit points and is dying. Huge or larger creatures are unaffected, as are creatures that can breathe water or that don't require air.\n\nA suffocating (not dying) creature can repeat the saving throw at the end of each of its turns, ending the effect on a success.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd.\n\nNOTE: Midgard Heroes Handbook has a very different [drown-heroes-handbook/drown](https://api.open5e.com/spells/drown) spell.","save":"con"},{"id":"deepm_dryads-kiss","name":"Dryad’s Kiss","level":3,"school":"Conjuration","time":"Action","range":"120 feet","components":"V, M (a flower petal or a drop of blood)","duration":"1 minute","classes":[],"desc":"You perform an ancient incantation that summons flora from the fey realm. A creature you can see within range is covered with small, purple buds and takes 3d8 necrotic damage; a successful Wisdom saving throw negates the damage but doesn't prevent the plant growth. The buds can be removed by the target or an ally of the target within 5 feet who uses an action to make a successful Intelligence (Nature) or Wisdom (Medicine) check against your spell save DC, or by a [greater restoration](https://api.open5e.com/spells/greater-restoration) or [blight](https://api.open5e.com/spells/blight) spell. While the buds remain, whenever the target takes damage from a source other than this spell, one bud blossoms into a purple and yellow flower that deals an extra 1d8 necrotic damage to the target. Once four blossoms have formed in this way, the buds can no longer be removed by nonmagical means. The buds and blossoms wilt and fall away when the spell ends, provided the creature is still alive.\n\nIf a creature affected by this spell dies, sweet-smelling blossoms quickly cover its body. The flowers wilt and die after one month.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"If this spell is cast using a spell slot of 5th level or higher, the number of targets increases by one for every two slot levels above 3rd.","damage":"3d8 necrotic","save":"wis"},{"id":"deepm_earthskimmer","name":"Earthskimmer","level":4,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a piece of shale or slate)","duration":"1 minute","classes":[],"desc":"You cause earth and stone to rise up beneath your feet, lifting you up to 5 feet. For the duration, you can use your movement to cause the slab to skim along the ground or other solid, horizontal surface at a speed of 60 feet. This movement ignores difficult terrain. If you are pushed or moved against your will by any means other than teleporting, the slab moves with you.\n\nUntil the end of your turn, you can enter the space of a creature up to one size larger than yourself when you take the Dash action. The creature must make a Strength saving throw. It takes 4d6 bludgeoning damage and is knocked prone on a failed save, or takes half as much damage and isn't knocked prone on a succesful one.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d6 bludgeoning","save":"str"},{"id":"deepm_earworm-melody","name":"Earworm Melody","level":1,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You sing or play a catchy tune that only one creature of your choice within range can hear. Unless the creature makes a successful Wisdom saving throw, the verse becomes ingrained in its head. If the target is concentrating on a spell, it must make a Constitution check with disadvantage against your spell save DC in order to maintain concentration.\n\nFor the spell's duration, the target takes 2d4 psychic damage at the start of each of its turns as the melody plays over and over in its mind. The target repeats the saving throw at the end of each of its turns, ending the effect on a success. On a failed save, the target must also repeat the Constitution check with disadvantage if it is concentrating on a spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"If you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d4 for each slot level above 1st.","damage":"2d4 psychic","save":"wis"},{"id":"deepm_echoes-of-steel","name":"Echoes of Steel","level":4,"school":"Evocation","time":"Bonus Action","range":"Self","components":"S","duration":"1 minute","classes":[],"desc":"When you hit a creature with a melee weapon attack, you can use a bonus action to cast echoes of steel. All creatures you designate within 30 feet of you take thunder damage equal to the damage from the melee attack, or half as much damage with a successful Constitution saving throw.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_ectoplasm","name":"Ectoplasm","level":2,"school":"Necromancy","time":"Action","range":"60 feet","components":"V, S, M (a pinch of bone dust)","duration":"1 minute","classes":[],"desc":"You call forth an ectoplasmic manifestation of Medium size that appears in an unoccupied space of your choice within range that you can see. The manifestation lasts for the spell's duration. Any creature that ends its turn within 5 feet of the manifestation takes 2d6 psychic damage, or half the damage with a successful Wisdom saving throw.\n\nAs a bonus action, you can move the manifestation up to 30 feet. It can move through a creature's space but can't remain in the same space as that creature. If it enters a creature's space, that creature takes 2d6 psychic damage, or half the damage with a successful Wisdom saving throw. On a failed save, the creature also has disadvantage on Dexterity checks until the end of its next turn.\n\nWhen you move the manifestation, it can flow through a gap as small as 1 square inch, over barriers up to 5 feet tall, and across pits up to 10 feet wide. The manifestation sheds dim light in a 10-foot radius. It also leaves a thin film of ectoplasmic residue on everything it touches or moves through. This residue doesn't illuminate the surroundings but does glow dimly enough to show the manifestation's path. The residue dissipates 1 round after it is deposited.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.","damage":"2d6 psychic","save":"wis"},{"id":"deepm_eidetic-memory","name":"Eidetic Memory","level":5,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a string tied in a knot)","duration":"1 hour","classes":[],"desc":"When you cast this spell, you can recall any piece of information you've ever read or heard in the past. This ability translates into a +10 bonus on Intelligence checks for the duration of the spell.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_eldritch-communion","name":"Eldritch Communion","level":5,"school":"Divination","time":"1 minute","range":"Self","components":"V, S, M (corvid entrails, a dried opium poppy, and a glass dagger)","duration":"1 minute","classes":[],"desc":"You contact a Great Old One and ask one question that can be answered with a one-sentence reply no more than twenty words long. You must ask your question before the spell ends. There is a 25 percent chance that the answer contains a falsehood or is misleading in some way. (The GM determines this secretly.)\n\nGreat Old Ones have vast knowledge, but they aren't omniscient, so if your question pertains to information beyond the Old One's knowledge, the answer might be vacuous, gibberish, or an angry, “I don't know.”\n\nThis also reveals the presence of all aberrations within 300 feet of you. There is a 1-in-6 chance that each aberration you become aware of also becomes aware of you.\n\nIf you cast **eldritch communion** two or more times before taking a long rest, there is a cumulative 25 percent chance for each casting after the first that you receive no answer and become afflicted with short-term madness.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_elemental-horns","name":"Elemental Horns","level":2,"school":"Evocation","time":"Action","range":"Touch","components":"V, S, M (a brass wand)","duration":"1 minute","classes":[],"desc":"The target of this spell must be a creature that has horns, or the spell fails. **Elemental horns** causes the touched creature's horns to crackle with elemental energy. Select one of the following energy types when casting this spell: acid, cold, fire, lightning, or radiant. The creature's gore attack deals 3d6 damage of the chosen type in addition to any other damage the attack normally deals.\n\nAlthough commonly seen among tieflings and minotaurs, this spell is rarely employed by other races.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 2d6 for each slot level above 2nd."},{"id":"deepm_elemental-twist","name":"Elemental Twist","level":2,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a thin piece of copper twisted around itself)","duration":"1 minute","classes":[],"desc":"During this spell's duration, reality shifts around you whenever you cast a spell that deals acid, cold, fire, lightning, poison, or thunder damage. Assign each damage type a number and roll a d6 to determine the type of damage this casting of the spell deals. In addition, the spell's damage increases by 1d6. All other properties or effects of the spell are unchanged.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_emanation-of-yoth","name":"Emanation of Yoth","level":4,"school":"Necromancy","time":"1 minute","range":"90 feet","components":"V, S, M (a fistful of grave earth and a vial of child’s blood)","duration":"1 hour","classes":[],"desc":"You call forth a [ghost](https://api.open5e.com/monsters/ghost)// that takes the form of a spectral, serpentlike assassin. It appears in an unoccupied space that you can see within range. The ghost disappears when it's reduced to 0 hit points or when the spell ends.\n\nThe ghost is friendly to you and your companions for the duration of the spell. Roll initiative for the ghost, which takes its own turns. It obeys verbal commands that you issue to it (no action required by you). If you don't issue a command to it, the ghost defends itself from hostile creatures but doesn't move or take other actions.\n\nYou are immune to the ghost's Horrifying Visage action but can willingly become the target of the ghost's Possession ability. You can end this effect on yourself as a bonus action.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th or 7th level, you call forth two ghosts. If you cast it using a spell slot of 8th or 9th level, you call forth three ghosts."},{"id":"deepm_enchant-ring","name":"Enchant Ring","level":6,"school":"Enchantment","time":"Action","range":"Touch","components":"V, S, M (500 gp worth of diamond dust, which the spell consumes)","duration":"Permanent until discharged","classes":[],"desc":"You enchant a ring you touch that isn't being worn or carried. The next creature that willingly wears the ring becomes charmed by you for 1 week or until it is harmed by you or one of your allies. If the creature dons the ring while directly threatened by you or one of your allies, the spell fails.\n\nThe charmed creature regards you as a friend. When the spell ends, it doesn't know it was charmed by you, but it does realize that its attitude toward you has changed (possibly greatly) in a short time. How the creature reacts to you and regards you in the future is up to the GM.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_encroaching-shadows","name":"Encroaching Shadows","level":6,"school":"Illusion","time":"1 hour","range":"150 feet","components":"V, S, M (a drop of blood smeared on a silver rod worth 100 gp)","duration":"12 hours","classes":[],"desc":"You cause menacing shadows to invade an area 200 feet on a side and 50 feet high, centered on a point within range. Illumination in the area drops one step (from bright light to dim, or from dim light to darkness). Any spell that creates light in the area that is cast using a lower-level spell slot than was used to cast encroaching shadows is dispelled, and a spell that creates light doesn't function in the area if that spell is cast using a spell slot of 5th level or lower. Nonmagical effects can't increase the level of illumination in the affected area.\n\nA spell that creates darkness or shadow takes effect in the area as if the spell slot expended was one level higher than the spell slot actually used.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, the effect lasts for an additional 12 hours for each slot level above 6th.\n\n**Ritual Focus.** If you expend your ritual focus, the spell's duration increases by 12 hours, and it cannot be dispelled by a spell that creates light, even if that spell is cast using a higher-level spell slot."},{"id":"deepm_encrypt-decrypt","name":"Encrypt / Decrypt","level":0,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"By touching a page of written information, you can encode its contents. All creatures that try to read the information when its contents are encoded see the markings on the page as nothing but gibberish. The effect ends when either **encrypt / decrypt** or [dispel magic](https://api.open5e.com/spells/dispel-magic) is cast on the encoded writing, which turns it back into its normal state.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_endow-attribute","name":"Endow Attribute","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a ring worth at least 200 gp, which the spell consumes)","duration":"1 hour","classes":[],"desc":"You touch a creature with a ring that has been etched with symbols representing a particular ability (Strength, Dexterity, and so forth). The creature must make a successful Constitution saving throw or lose one-fifth (rounded down) of its points from that ability score. Those points are absorbed into the ring and stored there for the spell's duration. If you then use an action to touch the ring to another creature on a later turn, the absorbed ability score points transfer to that creature. Once the points are transferred to another creature, you don't need to maintain concentration on the spell; the recipient creature retains the transferred ability score points for the remainder of the hour.\n\nThe spell ends if you lose concentration before the transfer takes place, if either the target or the recipient dies, or if either the target or the recipient is affected by a successful [dispel magic](https://api.open5e.com/spells/dispel-magic) spell. When the spell ends, the ability score points return to the original owner. Before then, that creature can't regain the stolen attribute points, even with greater restoration or comparable magic.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"If you cast this spell using a spell slot of 7th or 8th level, the duration is 8 hours. If you use a 9th‐level spell slot, the duration is 24 hours.","save":"con"},{"id":"deepm_energy-absorption","name":"Energy Absorption","level":5,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":[],"desc":"A creature you touch has resistance to acid, cold, fire, force, lightning, and thunder damage until the spell ends.\n\nIf the spell is used against an unwilling creature, you must make a melee spell attack with a reach of 5 feet. If the attack hits, for the duration of the spell the affected creature must make a saving throw using its spellcasting ability whenever it casts a spell that deals one of the given damage types. On a failed save, the spell is not cast but its slot is expended; on a successful save, the spell is cast but its damage is halved before applying the effects of saving throws, resistance, and other factors.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","attack":true},{"id":"deepm_energy-foreknowledge","name":"Energy Foreknowledge","level":4,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"When you cast this spell, you gain resistance to every type of energy listed above that is dealt by the spell hitting you. This resistance lasts until the end of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you can include one additional ally in its effect for each slot level above 4th. Affected allies must be within 15 feet of you."},{"id":"deepm_enhance-greed","name":"Enhance Greed","level":2,"school":"Divination","time":"Action","range":"Self","components":"V, S","duration":"10 minutes","classes":[],"desc":"You detect precious metals, gems, and jewelry within 60 feet. You do not discern their exact location, only their presence and direction. Their exact location is revealed if you are within 10 feet of the spot.\n\n**Enhance greed** penetrates barriers but is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of dirt or wood.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the duration of the spell increases by 1 minute, and another 10 feet can be added to its range, for each slot level above 2nd."},{"id":"deepm_entomb","name":"Entomb","level":6,"school":"Transmutation","time":"Action","range":"90 feet","components":"V, S, M (a chip of granite)","duration":"8 hours","classes":[],"desc":"You cause slabs of rock to burst out of the ground or other stone surface to form a hollow, 10-foot cube within range. A creature inside the cube when it forms must make a successful Dexterity saving throw or be trapped inside the stone tomb. The tomb is airtight, with enough air for a single Medium or Small creature to breathe for 8 hours. If more than one creature is trapped inside, divide the time evenly between all the occupants. A Large creature counts as four Medium creatures. If the creature is still trapped inside when the air runs out, it begins to suffocate.\n\nThe tomb has AC 18 and 50 hit points. It is resistant to fire, cold, lightning, bludgeoning, and slashing damage, is immune to poison and psychic damage, and is vulnerable to thunder damage. When reduced to 0 hit points, the tomb crumbles into harmless powder.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_entropic-damage-field","name":"Entropic Damage Field","level":3,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (a silver wire)","duration":"1 minute","classes":[],"desc":"By twisting a length of silver wire around your finger, you tie your fate to those around you. When you take damage, that damage is divided equally between you and all creatures in range who get a failure on a Charisma saving throw. Any leftover damage that can't be divided equally is taken by you. Creatures that approach to within 60 feet of you after the spell was cast are also affected. A creature is allowed a new saving throw against this spell each time you take damage, and a successful save ends the spell's effect on that creature.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_essence-instability","name":"Essence Instability","level":5,"school":"Transmutation","time":"Action","range":"120 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You cause the target to radiate a harmful aura. Both the target and every creature beginning or ending its turn within 20 feet of the target suffer 2d6 poison damage per round. The target can make a Constitution saving throw each round to negate the damage and end the affliction. Success means the target no longer takes damage from the aura, but the aura still persists around the target for the full duration.\n\nCreatures affected by the aura must make a successful Constitution saving throw each round to negate the damage. The aura moves with the original target and is unaffected by [gust of wind](https://api.open5e.com/spells/gust-of-wind) and similar spells.\n\nThe aura does not detect as magical or poison, and is invisible, odorless, and intangible (though the spell's presence can be detected on the original target). [Protection from poison](https://api.open5e.com/spells/protection-from-poison) negates the spell's effects on targets but will not dispel the aura. A foot of metal or stone, two inches of lead, or a force effect such as [mage armor](https://api.open5e.com/spells/mage-armor) or [wall of force](https://api.open5e.com/spells/wall-of-force) will block it.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the aura lasts 1 minute longer and the poison damage increases by 1d6 for each slot level above 5th.","save":"con"},{"id":"deepm_evercold","name":"Evercold","level":4,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (an insect that froze to death)","duration":"Until dispelled","classes":[],"desc":"You target a creature within the spell's range, and that creature must make a successful Wisdom saving throw or take 1d6 cold damage. In addition, the target is cursed to feel as if it's exposed to extreme cold. For the duration of **evercold**, the target must make a successful DC 10 Constitution saving throw at the end of each hour or gain one level of exhaustion. The target has advantage on the hourly saving throws if wearing suitable cold-weather clothing, but it has disadvantage on saving throws against other spells and magic that deal cold damage (regardless of its clothing) for the spell's duration.\n\nThe spell can be ended by its caster or by [dispel magic](https://api.open5e.com/spells/dispel-magic) or [remove curse](https://api.open5e.com/spells/remove-curse).","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_exsanguinate","name":"Exsanguinate","level":5,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (a desiccated horse heart)","duration":"1 minute","classes":[],"desc":"You cause the body of a creature within range to become engorged with blood or ichor. The target must make a Constitution saving throw. On a successful save, it takes 2d6 bludgeoning damage. On a failed save, it takes 4d6 bludgeoning damage each round, it is incapacitated, and it cannot speak, as it vomits up torrents of blood or ichor. In addition, its hit point maximum is reduced by an amount equal to the damage taken. The target dies if this effect reduces its hit point maximum to 0.\n\nAt the end of each of its turns, a creature can make a Constitution saving throw, ending the effect on a success—except for the reduction of its hit point maximum, which lasts until the creature finishes a long rest.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, you can target one additional creature for each slot level above 5th.","damage":"2d6 bludgeoning","save":"con"},{"id":"deepm_exsanguinating-cloud","name":"Exsanguinating Cloud","level":5,"school":"Necromancy","time":"Action","range":"100 feet","components":"V, S","duration":"5 minutes","classes":[],"desc":"When you cast this spell, a rose-colored mist billows up in a 20-foot radius, centered on a point you indicate within range, making the area heavily obscured and draining blood from living creatures in the cloud. The cloud spreads around corners. It lasts for the duration or until strong wind disperses it, ending the spell.\n\nThis cloud leaches the blood or similar fluid from creatures in the area. It doesn't affect undead or constructs. Any creature in the cloud when it's created or at the start of your turn takes 6d6 necrotic damage and gains one level of exhaustion; a successful Constitution saving throw halves the damage and prevents the exhaustion.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"6d6 necrotic","save":"con"},{"id":"deepm_extract-knowledge","name":"Extract Knowledge","level":6,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M (a blank page)","duration":"Instantaneous","classes":[],"desc":"By touching a recently deceased corpse, you gain one specific bit of knowledge from it that was known to the creature in life. You must form a question in your mind as part of casting the spell; if the corpse has an answer to your question, it reveals the information to you telepathically. The answer is always brief—no more than a sentence—and very specific to the framed question. It doesn't matter whether the creature was your friend or enemy; the spell compels it to answer in any case.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_fault-line","name":"Fault Line","level":6,"school":"Evocation","time":"Action","range":"Self","components":"V, S","duration":"Permanent","classes":[],"desc":"The ground thrusts sharply upward along a 5-foot-wide, 60‐foot-long line that you designate. All spaces affected by the spell become difficult terrain. In addition, all creatures in the affected area are knocked prone and take 8d6 bludgeoning damage. Creatures that make a successful Dexterity saving throw take half as much damage and are not knocked prone. This spell doesn't damage permanent structures.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_feather-field","name":"Feather Field","level":1,"school":"Abjuration","time":"Reaction","range":"Self","components":"V, S, M (fletching from an arrow)","duration":"1 round","classes":[],"desc":"A magical barrier of chaff in the form of feathers appears and protects you. Until the start of your next turn, you have a +5 bonus to AC against ranged attacks by magic weapons.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast **feather field** using a spell slot of 2nd level or higher, the duration is increased by 1 round for each slot level above 1st."},{"id":"deepm_feather-travel","name":"Feather Travel","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"V, M (a feather)","duration":"1 hour","classes":[],"desc":"The target of **feather travel** (along with its clothing and other gear) transforms into a feather and drifts on the wind. The drifting creature has a limited ability to control its travel. It can move only in the direction the wind is blowing and at the speed of the wind. It can, however, shift up, down, or sideways 5 feet per round as if caught by a gust, allowing the creature to aim for an open window or doorway, to avoid a flame, or to steer around an animal or another creature. When the spell ends, the feather settles gently to the ground and transforms back into the original creature.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, two additional creatures can be transformed per slot level above 2nd."},{"id":"deepm_fey-crown","name":"Fey Crown","level":5,"school":"Abjuration","time":"Action","range":"Self","components":"V, S, M (five flowers of different colors)","duration":"1 hour","classes":[],"desc":"By channeling the ancient wards of the Seelie Court, you create a crown of five flowers on your head. While wearing this crown, you have advantage on saving throws against spells and other magical effects and are immune to being charmed. As a bonus action, you can choose a creature within 30 feet of you (including yourself). Until the end of its next turn, the chosen creature is invisible and has advantage on saving throws against spells and other magical effects. Each time a chosen creature becomes invisible, one of the blossoms in the crown closes. After the last of the blossoms closes, the spell ends at the start of your next turn and the crown disappears.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the crown can have one additional flower for each slot level above 5th. One additional flower is required as a material component for each additional flower in the crown."},{"id":"deepm_find-kin","name":"Find Kin","level":1,"school":"Divination","time":"Action","range":"Touch","components":"V, S, M (a freshly dug up tree root that is consumed by the spell)","duration":"Instantaneous","classes":[],"desc":"You touch one willing creature or make a melee spell attack against an unwilling creature, which is entitled to a Wisdom saving throw. On a failed save, or automatically if the target is willing, you learn the identity, appearance, and location of one randomly selected living relative of the target.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"wis","attack":true},{"id":"deepm_fire-darts","name":"Fire Darts","level":2,"school":"Evocation","time":"Action","range":"20 feet","components":"V, S, M (a fire the size of a small campfire or larger)","duration":"Instantaneous","classes":[],"desc":"When this spell is cast on any fire that's at least as large as a small campfire or cooking fire, three darts of flame shoot out from the fire toward creatures within 30 feet of the fire. Darts can be directed against the same or separate targets as the caster chooses. Each dart deals 4d6 fire damage, or half as much damage if its target makes a successful Dexterity saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.","save":"dex"},{"id":"deepm_fire-under-the-tongue","name":"Fire Under the Tongue","level":1,"school":"Transmutation","time":"Action","range":"5 feet","components":"V, S","duration":"24 hours","classes":[],"desc":"You can ingest a nonmagical fire up to the size of a normal campfire that is within range. The fire is stored harmlessly in your mouth and dissipates without effect if it is not used before the spell ends. You can spit out the stored fire as an action. If you try to hit a particular target, then treat this as a ranged attack with a range of 5 feet. Campfire-sized flames deal 2d6 fire damage, while torch-sized flames deal 1d6 fire damage. Once you have spit it out, the fire goes out immediately unless it hits flammable material that can keep it fed.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_firewalk","name":"Firewalk","level":6,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"10 minutes","classes":[],"desc":"The creature you cast **firewalk** on becomes immune to fire damage. In addition, that creature can walk along any burning surface, such as a burning wall or burning oil spread on water, as if it were solid and horizontal. Even if there is no other surface to walk on, the creature can walk along the tops of the flames.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, two additional creatures can be affected for each slot level above 6th."},{"id":"deepm_fist-of-iron","name":"Fist of Iron","level":0,"school":"Transmutation","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"You transform your naked hand into iron. Your unarmed attacks deal 1d6 bludgeoning damage and are considered magical.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_flame-wave","name":"Flame Wave","level":4,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a drop of tar, pitch, or oil)","duration":"Instantaneous","classes":[],"desc":"A rushing burst of fire rips out from you in a rolling wave, filling a 40-foot cone. Each creature in the area must make a Dexterity saving throw. A creature takes 6d8 fire damage and is pushed 20 feet away from you on a failed save; on a successful save, the creature takes half as much damage and isn't pushed.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 3rd.","damage":"6d8 fire","save":"dex"},{"id":"deepm_flesh-to-paper","name":"Flesh to Paper","level":3,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"1 hour","classes":[],"desc":"A willing creature you touch becomes as thin as a sheet of paper until the spell ends. Anything the target is wearing or carrying is also flattened. The target can't cast spells or attack, and attack rolls against it are made with disadvantage. It has advantage on Dexterity (Stealth) checks while next to a wall or similar flat surface. The target can move through a space as narrow as 1 inch without squeezing. If it occupies the same space as an object or a creature when the spell ends, the creature is shunted to the nearest unoccupied space and takes force damage equal to twice the number of feet it was moved.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd."},{"id":"deepm_flickering-fate","name":"Flickering Fate","level":4,"school":"Divination","time":"Action","range":"Touch","components":"V, S","duration":"1 round","classes":[],"desc":"You or a creature that you touch can see a few seconds into the future. When the spell is cast, each other creature within 30 feet of the target must make a Wisdom saving throw. Those that fail must declare, in initiative order, what their next action will be. The target of the spell declares his or her action last, after hearing what all other creatures will do. Each creature that declared an action must follow its declaration as closely as possible when its turn comes. For the duration of the spell, the target has advantage on attack rolls, ability checks, and saving throws, and creatures that declared their actions have disadvantage on attack rolls against the target.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_fluctuating-alignment","name":"Fluctuating Alignment","level":4,"school":"Enchantment","time":"Action","range":"120 feet","components":"V, S","duration":"10 minutes","classes":[],"desc":"You channel the force of chaos to taint your target's mind. A target that gets a failure on a Wisdom saving throw must roll 1d20 and consult the Alignment Fluctuation table to find its new alignment, and it must roll again after every minute of the spell's duration. The target's alignment stops fluctuating and returns to normal when the spell ends. These changes do not make the affected creature friendly or hostile toward the caster, but they can cause creatures to behave in unpredictable ways.\n ## Alignment Fluctuation \nD20 | Alignment\n1-2 | Chaotic good\n3-4 | Chaotic neutral\n5-7 | Chaotic evil\n8-9 | Neutral evil\n10-11 | Lawful evil\n12-14 | Lawful good\n15-16 | Lawful neutral\n17-18 | Neutral good\n19-20 | Neutral","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_flurry","name":"Flurry","level":1,"school":"Transmutation","time":"Bonus Action","range":"Self","components":"V, S, M (a fleck of quartz)","duration":"1 round","classes":[],"desc":"A flurry of snow surrounds you and extends to a 5-foot radius around you. While it lasts, anyone trying to see into, out of, or through the affected area (including you) has disadvantage on Wisdom (Perception) checks and attack rolls.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_forest-native","name":"Forest Native","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a clump of soil from a forest)","duration":"1 hour","classes":[],"desc":"While in a forest, you touch a willing creature and infuse it with the forest's energy, creating a bond between the creature and the environment. For the duration of the spell, as long as the creature remains within the forest, its movement is not hindered by difficult terrain composed of natural vegetation. In addition, the creature has advantage on saving throws against environmental effects such as excessive heat or cold or high altitude.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_forest-sanctuary","name":"Forest Sanctuary","level":9,"school":"Abjuration","time":"1 minute","range":"300 feet","components":"V, S, M (a bowl of fresh rainwater and a tree branch)","duration":"24 hours","classes":[],"desc":"While in a forest, you create a protective, 200-foot cube centered on a point you can see within range. The atmosphere inside the cube has the lighting, temperature, and moisture that is most ideal for the forest, regardless of the lighting or weather outside the area. The cube is transparent, and creatures and objects can move freely through it. The cube protects the area inside it from storms, strong winds, and floods, including those created by magic such as [control weather](https://api.open5e.com/spells/control-weather)[control water](https://api.open5e.com/spells/control-water), or [meteor swarm](https://api.open5e.com/spells/meteor-swarm). Such spells can't be cast while the spellcaster is in the cube.\n\nYou can create a permanently protected area by casting this spell at the same location every day for one year.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_foretell-distraction","name":"Foretell Distraction","level":1,"school":"Divination","time":"Bonus Action","range":"Self","components":"S","duration":"Instantaneous","classes":[],"desc":"Thanks to your foreknowledge, you know exactly when your foe will take his or her eyes off you. Casting this spell has the same effect as making a successful Dexterity (Stealth) check, provided cover or concealment is available within 10 feet of you. It doesn't matter whether enemies can see you when you cast the spell; they glance away at just the right moment. You can move up to 10 feet as part of casting the spell, provided you're able to move (not restrained or grappled or reduced to a speed of less than 10 feet for any other reason). This move doesn't count as part of your normal movement. After the spell is cast, you must be in a position where you can remain hidden: a lightly obscured space, for example, or a space where you have total cover. Otherwise, enemies see you again immediately and you're not hidden.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_form-of-the-gods","name":"Form of the Gods","level":9,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a holy symbol)","duration":"1 hour","classes":[],"desc":"By drawing on the energy of the gods, you can temporarily assume the form of your patron's avatar. Form of the gods transforms you into an entirely new shape and brings about the following changes (summarized below and in the [avatar form](https://api.open5e.com/monsters/avatar-form) stat block).\n- Your size becomes Large, unless you were already at least that big.\n- You gain resistance to nonmagical bludgeoning, piercing, and slashing damage and to one other damage type of your choice.\n- You gain a Multiattack action option, allowing you to make two slam attacks and a bite.\n- Your ability scores change to reflect your new form, as shown in the stat block.\n\nYou remain in this form until you stop concentrating on the spell or until you drop to 0 hit points, at which time you revert to your natural form.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_freeze-blood","name":"Freeze Blood","level":3,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":[],"desc":"When you cast **freeze blood** as a successful melee spell attack against a living creature with a circulatory system, the creature's blood freezes. For the spell's duration, the affected creature's speed is halved and it takes 2d6 cold damage at the start of each of its turns. If the creature takes bludgeoning damage from a critical hit, the attack's damage dice are rolled three times instead of twice. At the end of each of its turns, the creature can make a Constitution saving throw, ending the effect on a success.\n\nNOTE: This was previously a 5th-level spell that did 4d10 cold damage.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"2d6 cold","save":"con"},{"id":"deepm_freeze-potion","name":"Freeze Potion","level":1,"school":"Transmutation","time":"Reaction","range":"25 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"A blue spark flies from your hand and strikes a potion vial, drinking horn, waterskin, or similar container, instantly freezing the contents. The substance melts normally thereafter and is not otherwise harmed, but it can't be consumed while it's frozen.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the range increases by 5 feet for each slot level above 1st."},{"id":"deepm_freezing-fog","name":"Freezing Fog","level":3,"school":"Conjuration","time":"Action","range":"100 feet","components":"V, S","duration":"5 minutes","classes":[],"desc":"The spell creates a 20-foot-radius sphere of mist similar to a [fog cloud](https://api.open5e.com/spells/fog-cloud) spell centered on a point you can see within range. The cloud spreads around corners, and the area it occupies is heavily obscured. A wind of moderate or greater velocity (at least 10 miles per hour) disperses it in 1 round. The fog is freezing cold; any creature that ends its turn in the area must make a Constitution saving throw. It takes 2d6 cold damage and gains one level of exhaustion on a failed save, or takes half as much damage and no exhaustion on a successful one.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","damage":"2d6 cold","save":"con"},{"id":"deepm_frenzied-bolt","name":"Frenzied Bolt","level":2,"school":"Evocation","time":"Action","range":"120 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You direct a bolt of rainbow colors toward a creature of your choice within range. If the bolt hits, the target takes 3d8 damage, of a type determined by rolling on the Random Damage Type table. If your attack roll (not the adjusted result) was odd, the bolt leaps to a new target of your choice within range that has not already been targeted by frenzied bolt, requiring a new spell attack roll to hit. The bolt continues leaping to new targets until you roll an even number on your spell attack roll, miss a target, or run out of potential targets. You and your allies are legal targets for this spell if you are particularly lucky—or unlucky.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you create an additional bolt for each slot level above 2nd. Each potential target can be hit only once by each casting of the spell, not once per bolt.\n \n **Random Damage Type** \n \nd10 | Damage Type\n1 | Acid\n2 | Cold\n3 | Fire\n4 | Force\n5 | Lightning\n6 | Necrotic\n7 | Poision\n8 | Psychic\n9 | Radiant\n10 | Thunder"},{"id":"deepm_frostbite","name":"Frostbite","level":5,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S, M (a strip of dried flesh that has been frozen at least once)","duration":"1 minute","classes":[],"desc":"Biting cold settles onto a creature you can see. The creature must make a Constitution saving throw. On a failed save, the creature takes 4d8 cold damage. In addition, for the duration of the spell, the creature's speed is halved, it has disadvantage on attack rolls and ability checks, and it takes another 4d8 cold damage at the start of each of its turns.\n\nAn affected creature can repeat the saving throw at the start of each of its turns. The effect ends when the creature makes its third successful save.\n\nCreatures that are immune to cold damage are unaffected by **frostbite**.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, you can target two additional creatures for each slot level above 5th.","damage":"4d8 cold","save":"con"},{"id":"deepm_frostbitten-fingers","name":"Frostbitten Fingers","level":3,"school":"Evocation","time":"Action","range":"30 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"You fire a ray of intense cold that instantly induces frostbite. With a successful ranged spell attack, this spell causes one of the target's hands to lose sensation. When the spell is cast, the target must make a successful Dexterity saving throw to maintain its grip on any object with the affected hand. The saving throw must be repeated every time the target tries to manipulate, wield, or pick up an item with the affected hand. Additionally, the target has disadvantage on Dexterity checks or Strength checks that require the use of both hands.\n\nAfter every 10 minutes of being affected by frostbitten fingers, the target must make a successful Constitution saving throw, or take 1d6 cold damage and lose one of the fingers on the affected hand, beginning with the pinkie.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_frozen-razors","name":"Frozen Razors","level":3,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S, M (water from a melted icicle)","duration":"1 minute","classes":[],"desc":"Razor-sharp blades of ice erupt from the ground or other surface, filling a 20-foot cube centered on a point you can see within range. For the duration, the area is lightly obscured and is difficult terrain. A creature that moves more than 5 feet into or inside the area on a turn takes 2d6 slashing damage and 3d6 cold damage, or half as much damage if it makes a successful Dexterity saving throw. A creature that takes cold damage from frozen razors is reduced to half speed until the start of its next turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","damage":"2d6 slashing","save":"dex"},{"id":"deepm_furious-hooves","name":"Furious Hooves","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a nail)","duration":"1 minute","classes":[],"desc":"You enhance the feet or hooves of a creature you touch, imbuing it with power and swiftness. The target doubles its walking speed or increases it by 30 feet, whichever addition is smaller. In addition to any attacks the creature can normally make, this spell grants two hoof attacks, each of which deals bludgeoning damage equal to 1d6 + plus the target's Strength modifier (or 1d8 if the target of the spell is Large). For the duration of the spell, the affected creature automatically deals this bludgeoning damage to the target of its successful shove attack.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_fusillade-of-ice","name":"Fusillade of Ice","level":4,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a dagger shaped like an icicle)","duration":"Instantaneous","classes":[],"desc":"You unleash a spray of razor-sharp ice shards. Each creature in the 30-foot cone takes 4d6 cold damage and 3d6 piercing damage, or half as much damage with a successful Dexterity saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by your choice of 1d6 cold damage or 1d6 piercing damage for each slot level above 4th. You can make a different choice (cold damage or piercing damage) for each slot level above 4th. Casting this spell with a spell slot of 6th level or higher increases the range to a 60-foot cone.","damage":"7d6 cold","save":"dex"},{"id":"deepm_gear-barrage","name":"Gear Barrage","level":2,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a handful of gears and sprockets worth 5 gp)","duration":"Instantaneous","classes":[],"desc":"You create a burst of magically propelled gears. Each creature within a 60-foot cone takes 3d8 slashing damage, or half as much damage with a successful Dexterity saving throw. Constructs have disadvantage on the saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"3d8 slashing","save":"dex"},{"id":"deepm_ghoul-kings-cloak","name":"Ghoul King’s Cloak","level":8,"school":"Transmutation","time":"Action","range":"Touch","components":"V","duration":"1 minute","classes":[],"desc":"You touch a creature, giving it some of the power of a ghoul king. The target gains the following benefits for the duration:\n- Its Armor Class increases by 2, to a maximum of 20.\n- When it uses the Attack action to make a melee weapon attack or a ranged weapon attack, it can make one additional attack of the same kind.\n- It is immune to necrotic damage and radiant damage.\n- It can't be reduced to less than 1 hit point.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 9th-level spell slot, the spell lasts for 10 minutes and doesn't require concentration."},{"id":"deepm_gird-the-spirit","name":"Gird the Spirit","level":1,"school":"Abjuration","time":"Reaction","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Your magic protects the target creature from the lifesapping energies of the undead. For the duration, the target has immunity to effects from undead creatures that reduce its ability scores, such as a shadow's Strength Drain, or its hit point maximum, such as a specter's Life Drain. This spell doesn't prevent damage from those attacks; it prevents only the reduction in ability score or hit point maximum.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_glacial-cascade","name":"Glacial Cascade","level":8,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a piece of alexandrite)","duration":"Instantaneous","classes":[],"desc":"By harnessing the power of ice and frost, you emanate pure cold, filling a 30-foot-radius sphere. Creatures other than you in the sphere take 10d8 cold damage, or half as much damage with a successful Constitution saving throw. A creature killed by this spell is transformed into ice, leaving behind no trace of its original body.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_glacial-fog","name":"Glacial Fog","level":7,"school":"Evocation","time":"Action","range":"100 feet","components":"V, S, M (crystalline statue of a polar bear worth at least 25 gp)","duration":"1 minute","classes":[],"desc":"As you cast this spell, a 30-foot-radius sphere centered on a point within range becomes covered in a frigid fog. Each creature that is in the area at the start of its turn while the spell remains in effect must make a Constitution saving throw. On a failed save, a creature takes 12d6 cold damage and gains one level of exhaustion, and it has disadvantage on Perception checks until the start of its next turn. On a successful save, the creature takes half the damage and ignores the other effects.\n\nStored devices and tools are all frozen by the fog: crossbow mechanisms become sluggish, weapons are stuck in scabbards, potions turn to ice, bag cords freeze together, and so forth. Such items require the application of heat for 1 round or longer in order to become useful again.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, the damage increases by 1d6 for each slot level above 7th.","damage":"12d6 cold","save":"con"},{"id":"deepm_gliding-step","name":"Gliding Step","level":1,"school":"Abjuration","time":"Action","range":"Self","components":"V, S","duration":"10 minutes","classes":[],"desc":"Provided you're not carrying more of a load than your carrying capacity permits, you can walk on the surface of snow rather than wading through it, and you ignore its effect on movement. Ice supports your weight no matter how thin it is, and you can travel on ice as if you were wearing ice skates. You still leave tracks normally while under these effects.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the duration increases by 10 minutes for each slot level above 1st."},{"id":"deepm_glimpse-of-the-void","name":"Glimpse of the Void","level":8,"school":"Enchantment","time":"Action","range":"120 feet","components":"V, S, M (a scrap of parchment with Void glyph scrawlings)","duration":"1 minute","classes":[],"desc":"Muttering Void Speech, you force images of terror and nonexistence upon your foes. Each creature in a 30-foot cube centered on a point within range must make an Intelligence saving throw. On a failed save, the creature goes insane for the duration. While insane, a creature takes no actions other than to shriek, wail, gibber, and babble unintelligibly. The GM controls the creature's movement, which is erratic.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"int"},{"id":"deepm_gloomwrought-barrier","name":"Gloomwrought Barrier","level":3,"school":"Conjuration","time":"Action","range":"100 feet","components":"V, S, M (a piece of obsidian)","duration":"1 minute","classes":[],"desc":"When you cast this spell, you erect a barrier of energy drawn from the realm of death and shadow. This barrier is a wall 20 feet high and 60 feet long, or a ring 20 feet high and 20 feet in diameter. The wall is transparent when viewed from one side of your choice and translucent—lightly obscuring the area beyond it—from the other. A creature that tries to move through the wall must make a successful Wisdom saving throw or stop in front of the wall and become frightened until the start of the creature's next turn, when it can try again to move through. Once a creature makes a successful saving throw against the wall, it is immune to the effect of this barrier.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_gluey-globule","name":"Gluey Globule","level":3,"school":"Conjuration","time":"Action","range":"120 feet","components":"V, S, M (a drop of glue)","duration":"1 minute or 1 hour","classes":[],"desc":"You make a ranged spell attack to hurl a large globule of sticky, magical glue at a creature within 120 feet. If the attack hits, the target creature is restrained. A restrained creature can break free by using an action to make a successful Strength saving throw. When the creature breaks free, it takes 2d6 slashing damage from the glue tearing its skin. If your ranged spell attack roll was a critical hit or exceeded the target's AC by 5 or more, the Strength saving throw is made with disadvantage. The target can also be freed by an application of universal solvent or by taking 20 acid damage. The glue dissolves when the creature breaks free or at the end of 1 minute.\n\nAlternatively, **gluey globule** can also be used to glue an object to a solid surface or to another object. In this case, the spell works like a single application of [sovereign glue](https://api.open5e.com/spells/sovereign-glue) and lasts for 1 hour.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"2d6 slashing","save":"str","attack":true},{"id":"deepm_glyph-of-shifting","name":"Glyph of Shifting","level":2,"school":"Conjuration","time":"10 minutes","range":"Touch","components":"V, S, M (powdered diamond worth at least 50 gp, which the spell consumes)","duration":"Instantaneous","classes":[],"desc":"You create a hidden glyph by tracing it on a surface or object that you touch. When you cast the spell, you can also choose a location that's known to you, within 5 miles, and on the same plane of existence, to serve as the destination for the glyph's shifting effect.\n  The glyph is triggered when it's touched by a creature that's not aware of its presence. The triggering creature must make a successful Wisdom saving throw or be teleported to the glyph's destination. If no destination was set, the creature takes 4d4 force damage and is knocked prone.\n  The glyph disappears after being triggered or when the spell's duration expires.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, its duration increases by 24 hours and the maximum distance to the destination increases by 5 miles for each slot level above 2nd.","damage":"4d4 force","save":"wis"},{"id":"deepm_goats-hoof-charm","name":"Goat's Hoof Charm","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a goat’s hoof)","duration":"1 minute","classes":[],"desc":"A creature you touch traverses craggy slopes with the surefootedness of a mountain goat. When ascending a slope that would normally be difficult terrain for it, the target can move at its full speed instead. The target also gains a +2 bonus on Dexterity checks and saving throws to prevent falling, to catch a ledge or otherwise stop a fall, or to move along a narrow ledge.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can increase the duration by 1 minute, or you can affect one additional creature, for each slot level above 1st.","save":"dex"},{"id":"deepm_going-in-circles","name":"Going in Circles","level":3,"school":"Illusion","time":"10 minutes","range":"Sight","components":"V, S, M (a piece of the target terrain)","duration":"24 hours","classes":[],"desc":"You make natural terrain in a 1-mile cube difficult to traverse. A creature in the affected area has disadvantage on Wisdom (Survival) checks to follow tracks or travel safely through the area as paths through the terrain seem to twist and turn nonsensically. The terrain itself isn't changed, only the perception of those inside it. A creature who succeeds on two Wisdom (Survival) checks while within the terrain discerns the illusion for what it is and sees the illusory twists and turns superimposed on the terrain. A creature that reenters the area after exiting it before the spell ends is affected by the spell even if it previously succeeded in traversing the terrain. A creature with truesight can see through the illusion and is unaffected by the spell. A creature that casts find the path automatically succeeds in discovering a way out of the terrain.\n  When you cast this spell, you can designate a password. A creature that speaks the password as it enters the area automatically sees the illusion and is unaffected by the spell.\n  If you cast this spell on the same spot every day for one year, the illusion lasts until it is dispelled.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_gordolays-pleasant-aroma","name":"Gordolay’s Pleasant Aroma","level":1,"school":"Transmutation","time":"Action","range":"120 feet","components":"S, M (a few flower petals or a piece of fruit, which the spell consumes)","duration":"1 minute","classes":[],"desc":"You create an intoxicating aroma that fills the area within 30 feet of a point you can see within range. Creatures in this area smell something they find so pleasing that it's distracting. Each creature in the area that makes an attack roll must first make a Wisdom saving throw; on a failed save, the attack is made with disadvantage. Only a creature's first attack in a round is affected this way; subsequent attacks are resolved normally. On a successful save, a creature becomes immune to the effect of this particular scent, but they can be affected again by a new casting of the spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_grasp-of-the-tupilak","name":"Grasp of the Tupilak","level":5,"school":"Necromancy","time":"Action","range":"Self","components":"V, S, M (tupilak idol)","duration":"1 hour or until triggered","classes":[],"desc":"This spell functions only against an arcane or divine spellcaster that prepares spells in advance and that has at least one unexpended spell slot of 6th level or lower. If you make a successful melee attack against such a creature before the spell ends, in addition to the usual effect of that attack, the target takes 2d4 necrotic damage and one or more of the victim's available spell slots are transferred to you, to be used as your own. Roll a d6; the result equals the total levels of the slots transferred. Spell slots of the highest possible level are transferred before lower-level slots.\n\nFor example, if you roll a 5 and the target has at least one 5th-level spell slot available, that slot transfers to you. If the target's highest available spell slot is 3rd level, then you might receive a 3rd-level slot and a 2nd-level slot, or a 3rd-level slot and two 1st-level slots if no 2nd-level slot is available.\n\nIf the target has no available spell slots of an appropriate level—for example, if you roll a 2 and the target has expended all of its 1st- and 2nd-level spell slots—then **grasp of the tupilak** has no effect, including causing no necrotic damage. If a stolen spell slot is of a higher level than you're able to use, treat it as of the highest level you can use.\n\nUnused stolen spell slots disappear, returning whence they came, when you take a long rest or when the creature you stole them from receives the benefit of [remove curse](https://api.open5e.com/spells/remove-curse)[greater restoration](https://api.open5e.com/greater-restoration), or comparable magic.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"2d4 necrotic"},{"id":"deepm_greater-maze","name":"Greater Maze","level":9,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S","duration":"10 minutes","classes":[],"desc":"This spell functions as [maze](https://api.open5e.com/spells/maze), but the target must make a Dexterity saving throw each time it starts its turn in the maze. The target takes 4d6 psychic damage on a failed save, or half as much damage on a success.\n\nEscaping this maze is especially difficult. To do so, the target must use an action to make a DC 20 Intelligence check. It escapes when it makes its second successful check.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d6 psychic","save":"dex"},{"id":"deepm_greater-seal-of-sanctuary","name":"Greater Seal of Sanctuary","level":9,"school":"Abjuration","time":"1 minute","range":"Touch","components":"V, S, M (incense and special inks worth 500 gp, which the spell consumes)","duration":"24 hours","classes":[],"desc":"You inscribe an angelic seal on the ground, the floor, or other solid surface of a structure. The seal creates a spherical sanctuary with a radius of 100 feet, centered on the seal. For the duration, aberrations, elementals, fey, fiends, and undead that approach to within 5 feet of the boundary know they are about to come into contact with a deadly barrier. If such a creature moves so as to touch the boundary, or tries to cross the boundary by any means, including teleportation and extradimensional travel, it must make a Charisma saving throw. On a failed save, it takes 15d8 radiant damage, is repelled to 5 feet outside the boundary, and can't target anything inside the boundary with attacks, spells, or abilities until the spell ends. On a successful save, the creature takes half as much radiant damage and can cross the boundary. If the creature is a fiend that isn't on its home plane, it is immediately destroyed (no saving throw) instead of taking damage.\n\nAberrations, elementals, fey, and undead that are within 100 feet of the seal (inside the boundary) have disadvantage on ability checks, attack rolls, and saving throws, and each such creature takes 4d8 radiant damage at the start of its turn.\n\nCreatures other than aberrations, elementals, fey, fiends, and undead can't be charmed or frightened while within 100 feet of the seal.\n\nThe seal has AC 18, 75 hit points, resistance to bludgeoning, piercing, and slashing damage, and immunity to psychic and poison damage. Ranged attacks against the seal are made with disadvantage. If it is scribed on the surface of an object that is later destroyed (such as a wooden door), the seal is not damaged and remains in place, perhaps suspended in midair. The spell ends only if the seal itself is reduced to 0 hit points.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","damage":"15d8 radiant","save":"cha"},{"id":"deepm_green-decay","name":"Green Decay","level":4,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"1 hour","classes":[],"desc":"Your touch inflicts a nauseating, alien rot. Make a melee spell attack against a creature within your reach. On a hit, you afflict the creature with the supernatural disease green decay (see below), and creatures within 15 feet of the target who can see it must make a successful Constitution saving throw or become poisoned until the end of their next turn.\n\nYou lose concentration on this spell if you can't see the target at the end of your turn.\n\n**Green Decay.** The flesh of a creature that has this disease is slowly consumed by a virulent extraterrestrial fungus. While the disease persists, the creature has disadvantage on Charisma and Wisdom checks and on Wisdom saving throws, and it has vulnerability to acid, fire, and necrotic damage. An affected creature must make a Constitution saving throw at the end of each of its turns. On a failed save, the creature takes 1d6 necrotic damage, and its hit point maximum is reduced by an amount equal to the necrotic damage taken. If the creature gets three successes on these saving throws before it gets three failures, the disease ends immediately (but the damage and the hit point maximum reduction remain in effect). If the creature gets three failures on these saving throws before it gets three successes, the disease lasts for the duration of the spell, and no further saving throws are allowed.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition","damage":"1d6 necrotic","save":"con","attack":true},{"id":"deepm_grudge-match","name":"Grudge Match","level":2,"school":"Evocation","time":"Action","range":"100 feet","components":"V, S","duration":"1 round","classes":[],"desc":"This spell affects any creatures you designate within range, as long as the group contains an equal number of allies and enemies. If the number of allies and enemies targeted isn't the same, the spell fails. For the duration of the spell, each target gains a +2 bonus on saving throws, attack rolls, ability checks, skill checks, and weapon damage rolls made involving other targets of the spell. All affected creatures can identify fellow targets of the spell by sight. If an affected creature makes any of the above rolls against a non-target, it takes a -2 penalty on that roll.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the duration increases by 1 round for each slot level above 2nd."},{"id":"deepm_guest-of-honor","name":"Guest of Honor","level":1,"school":"Enchantment","time":"10 minutes","range":"Touch","components":"V, M (a signet ring worth 25 gp)","duration":"10 minutes","classes":[],"desc":"You whisper words of encouragement, and a creature that you touch gains confidence along with approval from strangers. For the spell's duration, the target puts its best foot forward and strangers associate the creature with positive feelings. The target adds 1d4 to all Charisma (Persuasion) checks made to influence the attitudes of others.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the effect lasts for an additional 10 minutes for each slot level above 1st.\n\n**Ritual Focus.** If you expend your ritual focus, the effect lasts for 24 hours."},{"id":"deepm_guiding-star","name":"Guiding Star","level":1,"school":"Divination","time":"10 minutes","range":"Self","components":"V, S","duration":"8 hours","classes":[],"desc":"By observing the stars or the position of the sun, you are able to determine the cardinal directions, as well as the direction and distance to a stated destination. You can't become directionally disoriented or lose track of the destination. The spell doesn't, however, reveal the best route to your destination or warn you about deep gorges, flooded rivers, or other impassable or treacherous terrain.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_hamstring","name":"Hamstring","level":0,"school":"Evocation","time":"Action","range":"60 feet","components":"S","duration":"Instantaneous","classes":[],"desc":"You create an arrow of eldritch energy and send it at a target you can see within range. Make a ranged spell attack against the target. On a hit, the target takes 1d4 force damage, and it can't take reactions until the end of its next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4).","damage":"1d4 force","attack":true},{"id":"deepm_hard-heart","name":"Hard Heart","level":1,"school":"Enchantment","time":"Action","range":"Touch","components":"V, S, M (an iron key)","duration":"10 minutes","classes":[],"desc":"You imbue your touch with the power to make a creature aloof, hardhearted, and unfeeling. The creature you touch as part of casting this spell must make a Wisdom saving throw; a creature can choose to fail this saving throw unless it's currently charmed. On a successful save, this spell fails. On a failed save, the target becomes immune to being charmed for the duration; if it's currently charmed, that effect ends. In addition, Charisma checks against the target are made with disadvantage for the spell's duration.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd or 4th level, the duration increases to 1 hour. If you use a spell slot of 5th level or higher, the duration is 8 hours.","save":"wis"},{"id":"deepm_harry","name":"Harry","level":4,"school":"Enchantment","time":"Action","range":"120 feet","components":"V, S, M (a bit of fur from a game animal)","duration":"Instantaneous","classes":[],"desc":"You instill an irresistible sense of insecurity and terror in the target. The target must make a Wisdom saving throw. On a failed save, the target has disadvantage on Dexterity (Stealth) checks to avoid your notice and is frightened of you while you are within its line of sight. While you are within 1 mile of the target, you have advantage on Wisdom (Survival) checks to track the target, and the target can't take a long rest, terrified you are just around the corner. The target can repeat the saving throw once every 10 minutes, ending the spell on a success.\n  On a successful save, the target isn't affected, and you can't use this spell against it again for 24 hours.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell with a 6th-level spell slot, the duration is concentration, up to 8 hours and the target can repeat the saving throw once each hour. When you use a spell slot of 8th level or higher, the duration is concentration, up to 24 hours, and the target can repeat the saving throw every 8 hours.","save":"wis"},{"id":"deepm_harrying-hounds","name":"Harrying Hounds","level":5,"school":"Enchantment","time":"Action","range":"180 feet","components":"V, S, M (a tuft of fur from a hunting dog)","duration":"8 hours","classes":[],"desc":"When you cast this spell, choose a direction (north, south, northeast, or the like). Each creature in a 20-foot-radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it. When an affected creature travels, it travels at a fast pace in the opposite direction of the direction you chose as it believes a pack of dogs or wolves follows it from the chosen direction.\n  When an affected creature isn't traveling, it is frightened of your chosen direction. The affected creature occasionally hears howls or sees glowing eyes in the darkness at the edge of its vision in that direction. An affected creature will not stop at a destination, instead pacing half-circles around the destination until the effect ends, terrified the pack will overcome it if it stops moving.\n  An affected creature can make a Wisdom saving throw at the end of each 4-hour period, ending the effect on itself on a success. An affected creature moves along the safest available route unless it has nowhere to move, such as if it arrives at the edge of a cliff. When an affected creature can't safely move in the opposite direction of your chosen direction, it cowers in place, defending itself from hostile creatures but otherwise taking no actions. In such circumstances, the affected creature can repeat the saving throw every minute, ending the effect on itself on a success. The spell's effect is suspended when an affected creature is engaged in combat, allowing it to move as necessary to face hostile creatures.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the duration increases by 4 hours for each slot level above 5th. If an affected creature travels for more than 8 hours, it risks exhaustion as if on a forced march.","save":"wis"},{"id":"deepm_harsh-light-of-summers-glare","name":"Harsh Light of Summer’s Glare","level":8,"school":"Enchantment","time":"Action","range":"90 feet","components":"V, S","duration":"1 round","classes":[],"desc":"You emit a burst of brilliant light, which bears down oppressively upon all creatures within range that can see you. Creatures with darkvision that fail a Constitution saving throw are blinded and stunned. Creatures without darkvision that fail a Constitution saving throw are blinded. This is not a gaze attack, and it cannot be avoided by averting one's eyes or wearing a blindfold.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_heart-seeking-arrow","name":"Heart-Seeking Arrow","level":4,"school":"Transmutation","time":"Bonus Action","range":"Self","components":"V","duration":"1 minute","classes":[],"desc":"The next time you make a ranged weapon attack during the spell's duration, the weapon's ammunition—or the weapon itself if it's a thrown weapon—seeks its target's vital organs. Make the attack roll as normal. On a hit, the weapon deals an extra 6d6 damage of the same type dealt by the weapon, or half as much damage on a miss as it streaks unerringly toward its target. If this attack reduces the target to 0 hit points, the target has disadvantage on its next death saving throw, and, if it dies, it can be restored to life only by means of a true resurrection or a wish spell. This spell has no effect on undead or constructs.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the extra damage on a hit increases by 1d6 for each slot level above 4th."},{"id":"deepm_heart-to-heart","name":"Heart to Heart","level":1,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M (a drop of your blood)","duration":"1 hour","classes":[],"desc":"For the duration, you and the creature you touch remain stable and unconscious if reduced to 0 hit points while the other has 1 or more hit points. If you touch a dying creature, it becomes stable but remains unconscious while it has 0 hit points. If both of you are reduced to 0 hit points, you must both make death saving throws, as normal. If you or the target regain hit points, either of you can choose to split those hit points between the two of you if both of you are within 60 feet of each other.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_heartache","name":"Heartache","level":2,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S, M (a silver locket)","duration":"Instantaneous","classes":[],"desc":"You force an enemy to experience pangs of unrequited love and emotional distress. These feelings manifest with such intensity that the creature takes 5d6 psychic damage on a failed Charisma saving throw, or half the damage on a successful save.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can target an additional enemy for each slot level above 2nd.","damage":"5d6 psychic","save":"cha"},{"id":"deepm_heartstop","name":"Heartstop","level":2,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"10 minutes","classes":[],"desc":"You slow the beating of a willing target's heart to the rate of one beat per minute. The creature's breathing almost stops. To a casual or brief observer, the subject appears dead. At the end of the spell, the creature returns to normal with no ill effects.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_heartstrike","name":"Heartstrike","level":2,"school":"Divination","time":"Bonus Action","range":"Self","components":"V, S, M (an arrow, bolt, or other missile)","duration":"Instantaneous","classes":[],"desc":"The spirits of ancient archers carry your missiles straight to their targets. You have advantage on ranged weapon attacks until the start of your next turn, and you can ignore penalties for your enemies having half cover or three-quarters cover, and for an area being lightly obscured, when making those attacks.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_heavenly-crown","name":"Heavenly Crown","level":6,"school":"Enchantment","time":"Action","range":"Self","components":"V, S, M (a small golden crown worth 50 gp)","duration":"1 minute","classes":[],"desc":"A glowing, golden crown appears on your head and sheds dim light in a 30-foot radius. When you cast the spell (and as a bonus action on subsequent turns, until the spell ends), you can target one willing creature within 30 feet of you that you can see. If the target can hear you, it can use its reaction to make one melee weapon attack and then move up to half its speed, or vice versa.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_hedrens-birds-of-clay","name":"Hedren’s Birds of Clay","level":3,"school":"Conjuration","time":"Action","range":"Self","components":"V, M (a clay figurine shaped like a bird)","duration":"5 minutes","classes":[],"desc":"You create a number of clay pigeons equal to 1d4 + your spellcasting modifier (minimum of one) that swirl around you. When you are the target of a ranged weapon attack or a ranged spell attack and before the attack roll is made, you can use your reaction to shout “Pull!” When you do, one clay pigeon maneuvers to block the incoming attack. If the attack roll is less than 10 + your proficiency bonus, the attack misses. Otherwise, make a check with your spellcasting ability modifier and compare it to the attack roll. If your roll is higher, the attack is intercepted and has no effect. Regardless of whether the attack is intercepted, one clay pigeon is expended. The spell ends when the last clay pigeon is used.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, add 1 to your to your roll for each slot level above 3rd when determining if an attack misses or when making a check to intercept the attack."},{"id":"deepm_hematomancy","name":"Hematomancy","level":3,"school":"Divination","time":"1 minute","range":"Touch","components":"V, S, M (a drop of a creature’s blood)","duration":"Instantaneous","classes":[],"desc":"You can learn information about a creature whose blood you possess. The target must make a Wisdom saving throw. If the target knows you're casting the spell, it can fail the saving throw voluntarily if it wants you to learn the information. On a successful save, the target isn't affected, and you can't use this spell against it again for 24 hours. On a failed save, or if the blood belongs to a dead creature, you learn the following information:\n- The target's most common name (if any).\n- The target's creature type (and subtype, if any), gender, and which of its ability scores is highest (though not the exact numerical score).\n- The target's current status (alive, dead, sick, wounded, healthy, etc.).\n- The circumstances of the target shedding the blood you're holding (bleeding wound, splatter from an attack, how long ago it was shed, etc.).\nAlternatively, you can forgo all of the above information and instead use the blood as a beacon to track the target. For 1 hour, as long as you are on the same plane of existence as the creature, you know the direction and distance to the target's location at the time you cast this spell. While moving toward the location, if you are presented with a choice of paths, the spell automatically indicates which path provides the shortest and most direct route to the location.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_heros-steel","name":"Hero's Steel","level":3,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a warrior's amulet worth 5 gp)","duration":"1 minute","classes":[],"desc":"You infuse the metal of a melee weapon you touch with the fearsome aura of a mighty hero. The weapon's wielder has advantage on Charisma (Intimidation) checks made while aggressively brandishing the weapon. In addition, an opponent that currently has 30 or fewer hit points and is struck by the weapon must make a successful Charisma saving throw or be stunned for 1 round. If the creature has more than 30 hit points but fewer than the weapon's wielder currently has, it becomes frightened instead; a frightened creature repeats the saving throw at the end of each of its turns, ending the effect on itself on a successful save. A creature that succeeds on the saving throw is immune to castings of this spell on the same weapon for 24 hours.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_hide-in-ones-shadow","name":"Hide in One’s Shadow","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"S, M (charcoal)","duration":"3 hours","classes":[],"desc":"When you touch a willing creature with a piece of charcoal while casting this spell, the target and everything it carries blends into and becomes part of the target's shadow, which remains discernible, although its body seems to disappear. The shadow is incorporeal, has no weight, and is immune to all but psychic and radiant damage. The target remains aware of its surroundings and can move, but only as a shadow could move—flowing along surfaces as if the creature were moving normally. The creature can step out of the shadow at will, resuming its physical shape in the shadow's space and ending the spell.\n\nThis spell cannot be cast in an area devoid of light, where a shadow would not normally appear. Even a faint light source, such as moonlight or starlight, is sufficient. If that light source is removed, or if the shadow is flooded with light in such a way that the physical creature wouldn't cast a shadow, the spell ends and the creature reappears in the shadow's space.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_hoarfrost","name":"Hoarfrost","level":0,"school":"Evocation","time":"Bonus Action","range":"Touch","components":"V, S, M (a melee weapon)","duration":"1 minute","classes":[],"desc":"A melee weapon you are holding is imbued with cold. For the duration, a rime of frost covers the weapon and light vapor rises from it if the temperature is above freezing. The weapon becomes magical and deals an extra 1d4 cold damage on a successful hit. The spell ends after 1 minute, or earlier if you make a successful attack with the weapon or let go of it.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4)."},{"id":"deepm_hobble","name":"Hobble","level":0,"school":"Evocation","time":"Bonus Action","range":"30 feet","components":"V, S, M (a broken rabbit’s foot)","duration":"Instantaneous","classes":[],"desc":"You create an ethereal trap in the space of a creature you can see within range. The target must succeed on a Dexterity saving throw or its speed is halved until the end of its next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_hobble-mount","name":"Hobble Mount","level":1,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"1 hour","classes":[],"desc":"When you cast **hobble mount** as a successful melee spell attack against a horse, wolf, or other four-legged or two-legged beast being ridden as a mount, that beast is disabled so that it can't move at its normal speed without incurring injury. An affected creature that moves more than half its base speed in a turn takes 2d6 bludgeoning damage.\n\nThis spell has no effect on a creature that your GM deems to not be a mount.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 2d6 for each slot level above 1st.","damage":"2d6 bludgeoning"},{"id":"deepm_holy-ground","name":"Holy Ground","level":5,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a vial of holy water that is consumed in the casting)","duration":"10 minutes","classes":[],"desc":"You invoke divine powers to bless the ground within 60 feet of you. Creatures slain in the affected area cannot be raised as undead by magic or by the abilities of monsters, even if the corpse is later removed from the area. Any spell of 4th level or lower that would summon or animate undead within the area fails automatically. Such spells cast with spell slots of 5th level or higher function normally.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the level of spells that are prevented from functioning increases by 1 for each slot level above 5th."},{"id":"deepm_hone-blade","name":"Hone Blade","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a chip of whetstone or lodestone)","duration":"Instantaneous","classes":[],"desc":"You magically sharpen the edge of any bladed weapon or object you are touching. The target weapon gets a +1 bonus to damage on its next successful hit.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_hunger-of-leng","name":"Hunger of Leng","level":4,"school":"Enchantment","time":"Action","range":"90 feet","components":"V, S, M (a pinch of salt and a drop of the caster’s blood)","duration":"1 minute","classes":[],"desc":"You curse a creature that you can see in range with an insatiable, ghoulish appetite. If it has a digestive system, the creature must make a successful Wisdom saving throw or be compelled to consume the flesh of living creatures for the duration.\n\nThe target gains a bite attack and moves to and attacks the closest creature that isn't an undead or a construct. The target is proficient with the bite, and it adds its Strength modifier to the attack and damage rolls. The damage is piercing and the damage die is a d4. If the target is larger than Medium, its damage die increases by 1d4 for each size category it is above Medium. In addition, the target has advantage on melee attack rolls against any creature that doesn't have all of its hit points.\n\nIf there isn't a viable creature within range for the target to attack, it deals piercing damage to itself equal to 2d4 + its Strength modifier. The target can repeat the saving throw at the end of each of its turns, ending the effect on a success. If the target has two consecutive failures, **hunger of Leng** lasts its full duration with no further saving throws allowed.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_hunters-endurance","name":"Hunter's Endurance","level":1,"school":"Enchantment","time":"1 minute","range":"Self","components":"V, S, M (a fingernail, lock of hair, bit of fur, or drop of blood from the target, if unfamiliar)","duration":"24 hours","classes":[],"desc":"You call on the land to sustain you as you hunt your quarry. Describe or name a creature that is familiar to you. If you aren't familiar with the target creature, you must use a fingernail, lock of hair, bit of fur, or drop of blood from it as a material component to target that creature with this spell. Until the spell ends, you have advantage on all Wisdom (Perception) and Wisdom (Survival) checks to find and track the target, and you must actively pursue the target as if under a geas. In addition, you don't suffer from exhaustion levels you gain from pursuing your quarry, such as from lack of rest or environmental hazards between you and the target, while the spell is active. When the spell ends, you suffer from all levels of exhaustion that were suspended by the spell. The spell ends only after 24 hours, when the target is dead, when the target is on a different plane, or when the target is restrained in your line of sight.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_hunting-stand","name":"Hunting Stand","level":4,"school":"Conjuration","time":"1 minute","range":"120 feet","components":"V, S, M (a crude model of the stand)","duration":"8 hours","classes":[],"desc":"You make a camouflaged shelter nestled in the branches of a tree or among a collection of stones. The shelter is a 10-foot cube centered on a point within range. It can hold as many as nine Medium or smaller creatures. The atmosphere inside the shelter is comfortable and dry, regardless of the weather outside. The shelter's camouflage provides a modicum of concealment to its inhabitants; a creature outside the shelter has disadvantage on Wisdom (Perception) and Intelligence (Investigation) checks to detect or locate a creature within the shelter.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_ice-fortress","name":"Ice Fortress","level":5,"school":"Conjuration","time":"1 minute","range":"60 feet","components":"V, S, M (a miniature keep carved from ice or glass that is consumed in the casting)","duration":"Until dispelled or destroyed","classes":[],"desc":"A gleaming fortress of ice springs from a square area of ground that you can see within range. It is a 10-foot cube (including floor and roof). The fortress can't overlap any other structures, but any creatures in its space are harmlessly lifted up as the ice rises into position. The walls are made of ice (AC 13), have 120 hit points each, and are immune to cold, necrotic, poison, and psychic damage. Reducing a wall to 0 hit points destroys it and has a 50 percent chance to cause the roof to collapse. A damaged wall can be repaired by casting a spell that deals cold damage on it, on a point-for-point basis.\n\nEach wall has two arrow slits. One wall also includes an ice door with an [arcane lock](https://api.open5e.com/spells/arcane-lock). You designate at the time of the fort's creation which creatures can enter the fortification. The door has AC 18 and 60 hit points, or it can be broken open with a successful DC 25 Strength (Athletics) check (DC 15 if the [arcane lock](https://api.open5e.com/spells/arcane-lock) is dispelled).\n\nThe fortress catches and reflects light, so that creatures outside the fortress who rely on sight have disadvantage on Perception checks and attack rolls made against those within the fortress if it's in an area of bright sunlight.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, you can increase the length or width of the fortification by 5 feet for every slot level above 5th. You can make a different choice (width or length) for each slot level above 5th."},{"id":"deepm_ice-hammer","name":"Ice Hammer","level":2,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a miniature hammer carved from ice or glass)","duration":"1 hour","classes":[],"desc":"When you cast **ice hammer**, a warhammer fashioned from ice appears in your hands. This weapon functions as a standard warhammer in all ways, and it deals an extra 1d10 cold damage on a hit. You can drop the warhammer or give it to another creature.\n\nThe warhammer melts and is destroyed when it or its user accumulates 20 or more fire damage, or when the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can create one additional hammer for each slot level above 2nd. Alternatively, you can create half as many hammers (round down), but each is oversized (1d10 bludgeoning damage, or 1d12 if wielded with two hands, plus 2d8 cold damage). Medium or smaller creatures have disadvantage when using oversized weapons, even if they are proficient with them."},{"id":"deepm_ice-soldiers","name":"Ice Soldiers","level":7,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, M (vial of water)","duration":"1 minute","classes":[],"desc":"You pour water from the vial and cause two [ice soldiers](https://api.open5e.com/monsters/ice-soldier) to appear within range. The ice soldiers cannot form if there is no space available for them. The ice soldiers act immediately on your turn. You can mentally command them (no action required by you) to move and act where and how you desire. If you command an ice soldier to attack, it attacks that creature exclusively until the target is dead, at which time the soldier melts into a puddle of water. If an ice soldier moves farther than 30 feet from you, it immediately melts.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, you create one additional ice soldier."},{"id":"deepm_icicle-daggers","name":"Icicle Daggers","level":1,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a miniature dagger shaped like an icicle)","duration":"Instantaneous or special","classes":[],"desc":"When you cast this spell, three icicles appear in your hand. Each icicle has the same properties as a dagger but deals an extra 1d4 cold damage on a hit.\n\nThe icicle daggers melt a few seconds after leaving your hand, making it impossible for other creatures to wield them. If the surrounding temperature is at or below freezing, the daggers last for 1 hour. They melt instantly if you take 10 or more fire damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"If you cast this spell using a spell slot of 2nd level or higher, you can create two additional daggers for each slot level above 1st. If you cast this spell using a spell slot of 4th level or higher, daggers that leave your hand don't melt until the start of your next turn."},{"id":"deepm_icy-grasp-of-the-void","name":"Icy Grasp of the Void","level":7,"school":"Evocation","time":"Action","range":"120 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You summon the cold, inky darkness of the Void into being around a creature that you can see. The target takes 10d10 cold damage and is restrained for the duration; a successful Constitution saving throw halves the damage and negates the restrained condition. A restrained creature gains one level of exhaustion at the start of each of its turns. Creatures immune to cold and that do not breathe do not gain exhaustion. A creature restrained in this way can repeat the saving throw at the end of each of its turns, ending the spell on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"10d10 cold","save":"con"},{"id":"deepm_icy-manipulation","name":"Icy Manipulation","level":6,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (a piece of ice preserved from the plane of elemental ice)","duration":"1 minute","classes":[],"desc":"One creature you can see within range must make a Constitution saving throw. On a failed save, the creature is petrified (frozen solid). A petrified creature can repeat the saving throw at the end of each of its turns, ending the effect on itself if it makes two successful saves. If a petrified creature gets two failures on the saving throw (not counting the original failure that caused the petrification), the petrification becomes permenant.\n\nThe petrification also becomes permanent if you maintain concentration on this spell for a full minute. A permanently petrified/frozen creature can be restored to normal with [greater restoration](https://api.open5e.com/spells/greater-restoration) or comparable magic, or by casting this spell on the creature again and maintaining concentration for a full minute.\n\nIf the frozen creature is damaged or broken before it recovers from being petrified, the injury carries over to its normal state.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_ill-fated-word","name":"Ill-Fated Word","level":1,"school":"Divination","time":"Reaction","range":"30 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"You call out a distracting epithet to a creature, worsening its chance to succeed at whatever it's doing. Roll a d4 and subtract the number rolled from an attack roll, ability check, or saving throw that the target has just made; the target uses the lowered result to determine the outcome of its roll.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_illuminate-spoor","name":"Illuminate Spoor","level":1,"school":"Divination","time":"Action","range":"Touch","components":"V, S, M (a firefly)","duration":"1 hour","classes":[],"desc":"You touch a set of tracks created by a single creature. That set of tracks and all other tracks made by the same creature give off a faint glow. You and up to three creatures you designate when you cast this spell can see the glow. A creature that can see the glow automatically succeeds on Wisdom (Survival) checks to track that creature. If the tracks are covered by obscuring objects such as leaves or mud, you and the creatures you designate have advantage on Wisdom (Survival) checks to follow the tracks.\n  If the creature leaving the tracks changes its tracks, such as by adding or removing footwear, the glow stops where the tracks change. Until the spell ends, you can use an action to touch and illuminate a new set of tracks.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the duration is concentration, up to 8 hours. When you use a spell slot of 5th level or higher, the duration is concentration, up to 24 hours."},{"id":"deepm_impending-ally","name":"Impending Ally","level":3,"school":"Conjuration","time":"Action","range":"40 feet","components":"V, S, M (a broken chain link)","duration":"2 rounds","classes":[],"desc":"You summon a duplicate of yourself as an ally who appears in an unoccupied space you can see within range. You control this ally, whose turn comes immediately after yours. When you or the ally uses a class feature, spell slot, or other expendable resource, it's considered expended for both of you. When the spell ends, or if you are killed, the ally disappears immediately.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the duration is extended by 1 round for every two slot levels above 3rd."},{"id":"deepm_innocuous-aspect","name":"Innocuous Aspect","level":3,"school":"Illusion","time":"Action","range":"Self","components":"V, S, M (a paper ring)","duration":"10 minutes","classes":[],"desc":"An area of false vision encompasses all creatures within 20 feet of you. You and each creature in the area that you choose to affect take on the appearance of a harmless creature or object, chosen by you. Each image is identical, and only appearance is affected. Sound, movement, or physical inspection can reveal the ruse.\n\nA creature that uses its action to study the image visually can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, that creature sees through the image.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_insightful-maneuver","name":"Insightful Maneuver","level":1,"school":"Divination","time":"Bonus Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"With a flash of insight, you know how to take advantage of your foe's vulnerabilities. Until the end of your turn, the target has vulnerability to one type of damage (your choice). Additionally, if the target has any other vulnerabilities, you learn them.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_inspiring-speech","name":"Inspiring Speech","level":4,"school":"Enchantment","time":"10 minutes","range":"60 feet","components":"V","duration":"1 hour","classes":[],"desc":"The verbal component of this spell is a 10-minute-long, rousing speech. At the end of the speech, all your allies within the affected area who heard the speech gain a +1 bonus on attack rolls and advantage on saving throws for 1 hour against effects that cause the charmed or frightened condition. Additionally, each recipient gains temporary hit points equal to your spellcasting ability modifier. If you move farther than 1 mile from your allies or you die, this spell ends. A character can be affected by only one casting of this spell at a time; subsequent, overlapping castings have no additional effect and don't extend the spell's duration.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_instant-fortification","name":"Instant Fortification","level":5,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (a statuette of a keep worth 250 gp, which is consumed in the casting)","duration":"Permanent","classes":[],"desc":"Through this spell, you transform a miniature statuette of a keep into an actual fort. The fortification springs from the ground in an unoccupied space within range. It is a 10- foot cube (including floor and roof).\n\nEach wall has two arrow slits. One wall also includes a metal door with an [arcane lock](https://api.open5e.com/spells/arcane-lock) effect on it. You designate at the time of the fort's creation which creatures can ignore the lock and enter the fortification. The door has AC 20 and 60 hit points, and it can be broken open with a successful DC 25 Strength (Athletics) check. The walls are made of stone (AC 15) and are immune to necrotic, poison, and psychic damage. Each 5-foot-square section of wall has 90 hit points. Reducing a section of wall to 0 hit points destroys it, allowing access to the inside of the fortification.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, you can increase the length or width of the fortification by 5 feet for each slot level above 5th. You can make a different choice (width or length) for each slot level above 5th."},{"id":"deepm_instant-siege-weapon","name":"Instant Siege Weapon","level":4,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (raw materials with a value in gp equal to the hit points of the siege weapon to be created)","duration":"Permanent","classes":[],"desc":"With this spell, you instantly transform raw materials into a siege engine of Large size or smaller (the GM has information on this topic). The raw materials for the spell don't need to be the actual components a siege weapon is normally built from; they just need to be manufactured goods made of the appropriate substances (typically including some form of finished wood and a few bits of worked metal) and have a gold piece value of no less than the weapon's hit points.\n\nFor example, a mangonel has 100 hit points. **Instant siege weapon** will fashion any collection of raw materials worth at least 100 gp into a mangonel. Those materials might be lumber and fittings salvaged from a small house, or 100 gp worth of finished goods such as three wagons or two heavy crossbows. The spell also creates enough ammunition for ten shots, if the siege engine uses ammunition.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level, a Huge siege engine can be made; at 8th level, a Gargantuan siege engine can be made. In addition, for each slot level above 4th, the spell creates another ten shots' worth of ammunition."},{"id":"deepm_instant-snare","name":"Instant Snare","level":2,"school":"Abjuration","time":"Action","range":"120 feet","components":"V, S, M (a loop of twine)","duration":"24 hours","classes":[],"desc":"You create a snare on a point you can see within range. You can leave the snare as a magical trap, or you can use your reaction to trigger the trap when a Large or smaller creature you can see moves within 10 feet of the snare. If you leave the snare as a trap, a creature must succeed on an Intelligence (Investigation) or Wisdom (Perception) check against your spell save DC to find the trap.\n  When a Large or smaller creature moves within 5 feet of the snare, the trap triggers. The creature must succeed on a Dexterity saving throw or be magically pulled into the air. The creature is restrained and hangs upside down 5 feet above the snare's location for 1 minute. A restrained creature can repeat the saving throw at the end of each of its turns, escaping the snare on a success. Alternatively, a creature, including the restrained target, can use its action to make an Intelligence (Arcana) check against your spell save DC. On a success, the restrained creature is freed, and the snare resets itself 1 minute later. If the creature succeeds on the check by 5 or more, the snare is destroyed instead.\n  This spell alerts you with a ping in your mind when the trap is triggered if you are within 1 mile of the snare. This ping awakens you if you are sleeping.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can create one additional snare for each slot level above 3rd. When you receive the mental ping that a trap was triggered, you know which snare was triggered if you have more than one.","save":"int"},{"id":"deepm_ire-of-the-mountain","name":"Ire of the Mountain","level":3,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M (a piece of coal)","duration":"Instantaneous","classes":[],"desc":"An **ire of the mountain** spell melts nonmagical objects that are made primarily of metal. Choose one metal object weighing 10 pounds or less that you can see within range. Tendrils of blistering air writhe toward the target. A creature holding or wearing the item must make a Dexterity saving throw. On a successful save, the creature takes 1d8 fire damage and the spell has no further effect. On a failed save, the targeted object melts and is destroyed, and the creature takes 4d8 fire damage if it is wearing the object, or 2d8 fire damage if it is holding the object. If the object is not being held or worn by a creature, it is automatically melted and rendered useless. This spell cannot affect magic items.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional object for each slot level above 3rd.","damage":"1d8 fire","save":"dex"},{"id":"deepm_iron-hand","name":"Iron Hand","level":0,"school":"Abjuration","time":"Bonus Action","range":"Self","components":"V, S","duration":"1 hour","classes":[],"desc":"**Iron hand** is a common spell among metalsmiths and other crafters who work with heat. When you use this spell, one of your arms becomes immune to fire damage, allowing you to grasp red-hot metal, scoop up molten glass with your fingers, or reach deep into a roaring fire to pick up an object. In addition, if you take the Dodge action while you're protected by **iron hand**, you have resistance to fire damage until the start of your next turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_kareefs-entreaty","name":"Kareef’s Entreaty","level":1,"school":"Abjuration","time":"Reaction","range":"60 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"Your kind words offer hope and support to a fallen comrade. Choose a willing creature you can see within range that is about to make a death saving throw. The creature gains advantage on the saving throw, and if the result of the saving throw is 18 or higher, the creature regains 3d4 hit points immediately.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the creature adds 1 to its death saving throw for every two slot levels above 1st and regains an additional 1d4 hit points for each slot level above 1st if its saving throw result is 18 or higher."},{"id":"deepm_keening-wail","name":"Keening Wail","level":4,"school":"Necromancy","time":"Action","range":"Self","components":"V, S, M (a ringed lock of hair from an undead creature)","duration":"Instantaneous","classes":[],"desc":"You emit an unholy shriek from beyond the grave. Each creature in a 15-foot cone must make a Constitution saving throw. A creature takes 6d6 necrotic damage on a failed save, or half as much damage on a successful one. If a creature with 50 hit points or fewer fails the saving throw by 5 or more, it is instead reduced to 0 hit points. This wail has no effect on constructs and undead.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d6 for each slot level above 4th.","damage":"6d6 necrotic","save":"con"},{"id":"deepm_killing-fields","name":"Killing Fields","level":5,"school":"Transmutation","time":"10 minutes","range":"300 feet","components":"V, S, M (a game animal, which must be sacrificed as part of casting the spell)","duration":"24 hours","classes":[],"desc":"You invoke primal spirits of nature to transform natural terrain in a 100-foot cube in range into a private hunting preserve. The area can't include manufactured structures and if such a structure exists in the area, the spell ends.\n  While you are conscious and within the area, you are aware of the presence and direction, though not exact location, of each beast and monstrosity with an Intelligence of 3 or lower in the area. When a beast or monstrosity with an Intelligence of 3 or lower tries to leave the area, it must make a Wisdom saving throw. On a failure, it is disoriented, uncertain of its surroundings or direction, and remains within the area for 1 hour. On a success, it leaves the area.\n  When you cast this spell, you can specify individuals that are helped by the area's effects. All other creatures in the area are hindered by the area's effects. You can also specify a password that, when spoken aloud, gives the speaker the benefits of being helped by the area's effects.\n  Killing fields creates the following effects within the area.\n   **Pack Hunters.** A helped creature has advantage on attack rolls against a hindered creature if at least one helped ally is within 5 feet of the hindered creature and the helped ally isn't incapacitated. Slaying. Once per turn, when a helped creature hits with any weapon, the weapon deals an extra 1d6 damage of its type to a hindered creature. Tracking. A helped creature has advantage on Wisdom (Survival) and Dexterity (Stealth) checks against a hindered creature.\n  You can create a permanent killing field by casting this spell in the same location every day for one year. Structures built in the area after the killing field is permanent don't end the spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"int"},{"id":"deepm_kiss-of-the-succubus","name":"Kiss of the Succubus","level":5,"school":"Necromancy","time":"Action","range":"Touch","components":"S","duration":"Instantaneous","classes":[],"desc":"You kiss a willing creature or one you have charmed or held spellbound through spells or abilities such as [dominate person](https://api.open5e.com/spells/dominate-person). The target must make a Constitution saving throw. A creature takes 5d10 psychic damage on a failed save, or half as much damage on a successful one. The target's hit point maximum is reduced by an amount equal to the damage taken; this reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d10 for each slot level above 5th.","damage":"5d10 psychic","save":"con"},{"id":"deepm_kobolds-fury","name":"Kobold’s Fury","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a kobold scale)","duration":"1 round","classes":[],"desc":"Your touch infuses the rage of a threatened kobold into the target. The target has advantage on melee weapon attacks until the end of its next turn. In addition, its next successful melee weapon attack against a creature larger than itself does an additional 2d8 damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_labyrinth-mastery","name":"Labyrinth Mastery","level":4,"school":"Divination","time":"Action","range":"Self","components":"V, S, M (a piece of blank parchment)","duration":"1 hour","classes":[],"desc":"Upon casting this spell, you immediately gain a sense of your surroundings. If you are in a physical maze or any similar structure with multiple paths and dead ends, this spell guides you to the nearest exit, although not necessarily along the fastest or shortest route.\n\nIn addition, while the spell is guiding you out of such a structure, you have advantage on ability checks to avoid being surprised and on initiative rolls.\n\nYou gain a perfect memory of all portions of the structure you move through during the spell's duration. If you revisit such a portion, you recognize that you've been there before and automatically notice any changes to the environment.\n\nAlso, while under the effect of this spell, you can exit any [maze](https://api.open5e.com/spells/maze) spell (and its lesser and greater varieties) as an action without needing to make an Intelligence check.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_labyrinthine-howl","name":"Labyrinthine Howl","level":5,"school":"Illusion","time":"Action","range":"60 feet","components":"V, S, M (a dead mouse)","duration":"1 round","classes":[],"desc":"You let loose the howl of a ravenous beast, causing each enemy within range that can hear you to make a Wisdom saving throw. On a failed save, a creature believes it has been transported into a labyrinth and is under attack by savage beasts. An affected creature must choose either to face the beasts or to curl into a ball for protection. A creature that faces the beasts takes 7d8 psychic damage, and then the spell ends on it. A creature that curls into a ball falls prone and is stunned until the end of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 2d8 for each slot level above 5th.","damage":"7d8 psychic","save":"wis"},{"id":"deepm_lacerate","name":"Lacerate","level":2,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S, M (a shard of bone or crystal)","duration":"Instantaneous","classes":[],"desc":"You make a swift cutting motion through the air to lacerate a creature you can see within range. The target must make a Constitution saving throw. It takes 4d8 slashing damage on a failed save, or half as much damage on a successful one. If the saving throw fails by 5 or more, the wound erupts with a violent spray of blood, and the target gains one level of exhaustion.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","damage":"4d8 slashing","save":"con"},{"id":"deepm_lair-sense","name":"Lair Sense","level":2,"school":"Divination","time":"1 minute","range":"120 feet","components":"V, S, M (treasure worth at least 500 gp, which is not consumed in casting)","duration":"24 hours","classes":[],"desc":"You set up a magical boundary around your lair. The boundary can't exceed the dimensions of a 100-foot cube, but within that maximum, you can shape it as you like—to follow the walls of a building or cave, for example. While the spell lasts, you instantly become aware of any Tiny or larger creature that enters the enclosed area. You know the creature's type but nothing else about it. You are also aware when creatures leave the area.\n\nThis awareness is enough to wake you from sleep, and you receive the knowledge as long as you're on the same plane of existence as your lair.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, add 50 feet to the maximum dimensions of the cube and add 12 hours to the spell's duration for each slot level above 2nd."},{"id":"deepm_last-rays-of-the-dying-sun","name":"Last Rays of the Dying Sun","level":7,"school":"Evocation","time":"Action","range":"40 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"A burst of searing heat explodes from you, dealing 6d6 fire damage to all enemies within range. Immediately afterward, a wave of frigid cold rolls across the same area, dealing 6d6 cold damage to enemies. A creature that makes a successful Dexterity saving throw takes half the damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th or 9th level, the damage from both waves increases by 1d6 for each slot level above 7th.","save":"dex"},{"id":"deepm_lava-stone","name":"Lava Stone","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, M (a sling stone)","duration":"Instantaneous","classes":[],"desc":"When you cast **lava stone** on a piece of sling ammo, the stone or bullet becomes intensely hot. As a bonus action, you can launch the heated stone with a sling: the stone increases in size and melts into a glob of lava while in flight. Make a ranged spell attack against the target. If it hits, the target takes 1d8 bludgeoning damage plus 6d6 fire damage. The target takes additional fire damage at the start of each of your next three turns, starting with 4d6, then 2d6, and then 1d6. The additional damage can be avoided if the target or an ally within 5 feet of the target scrapes off the lava. This is done by using an action to make a successful Wisdom (Medicine) check against your spellcasting save DC. The spell ends if the heated sling stone isn't used immediately.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"1d8 bludgeoning","attack":true},{"id":"deepm_lay-to-rest","name":"Lay to Rest","level":5,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a pinch of grave dirt)","duration":"Instantaneous","classes":[],"desc":"A pulse of searing light rushes out from you. Each undead creature within 15 feet of you must make a Constitution saving throw. A target takes 8d6 radiant damage on a failed save, or half as much damage on a successful one.\n  An undead creature reduced to 0 hit points by this spell disintegrates in a burst of radiant motes, leaving anything it was wearing or carrying in a space it formerly occupied.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"8d6 radiant","save":"con"},{"id":"deepm_legend-killer","name":"Legend Killer","level":7,"school":"Divination","time":"Action","range":"60 feet","components":"V, S, M (a silver scroll describing the spell’s target worth at least 1,000 gp, which the spell consumes)","duration":"1 minute","classes":[],"desc":"You tap into the life force of a creature that is capable of performing legendary actions. When you cast the spell, the target must make a successful Constitution saving throw or lose the ability to take legendary actions for the spell's duration. A creature can't use legendary resistance to automatically succeed on the saving throw against this spell. An affected creature can repeat the saving throw at the end of each of its turns, regaining 1 legendary action on a successful save. The target continues repeating the saving throw until the spell ends or it regains all its legendary actions.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_legion","name":"Legion","level":3,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a toy soldier)","duration":"1 minute","classes":[],"desc":"You call down a legion of shadowy soldiers in a 10-foot cube. Their features resemble a mockery of once-living creatures. Whenever a creature starts its turn inside the cube or within 5 feet of it, or enters the cube for the first time on its turn, the conjured shades make an attack using your melee spell attack modifier; on a hit, the target takes 3d8 necrotic damage. The space inside the cube is difficult terrain.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"3d8 necrotic"},{"id":"deepm_legion-of-rabid-squirrels","name":"Legion of Rabid Squirrels","level":3,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (an acorn or nut)","duration":"1 minute","classes":[],"desc":"While in a forest, you call a legion of rabid squirrels to descend from the nearby trees at a point you can see within range. The squirrels form into a swarm that uses the statistics of a [swarm of poisonous snakes](https://api.open5e.com/monsters/swarm-of-poisonous-snakes), except it has a climbing speed of 30 feet rather than a swimming speed. The legion of squirrels is friendly to you and your companions. Roll initiative for the legion, which has its own turns. The legion of squirrels obeys your verbal commands (no action required by you). If you don't issue any commands to the legion, it defends itself from hostile creatures but otherwise takes no actions. If you command it to move farther than 60 feet from you, the spell ends and the legion disperses back into the forest. A canid, such as a dog, wolf, fox, or worg, has disadvantage on attack rolls against targets other than the legion of rabid squirrels while the swarm is within 60 feet of the creature. When the spell ends, the squirrels disperse back into the forest.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the legion's poison damage increases by 1d6 for each slot level above 3rd."},{"id":"deepm_lesser-maze","name":"Lesser Maze","level":3,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"This spell functions as [maze](https://api.open5e.com/spells/maze), but the target can resist being sent to the extradimensional prison with a successful Intelligence saving throw. In addition, the maze is easier to navigate, requiring only a DC 12 Intelligence check to escape.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"int"},{"id":"deepm_life-drain","name":"Life Drain","level":6,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"With a snarled word of Void Speech, you create a swirling vortex of purple energy. Choose a point you can see within range. Creatures within 15 feet of the point take 10d6 necrotic damage, or half that damage with a successful Constitution saving throw. For each creature damaged by the spell, you can choose one other creature within range, including yourself, that is not a construct or undead. The secondary targets regain hit points equal to half the necrotic damage you dealt.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, the vortex's damage increases by 1d6 for each slot level above 6th.","save":"con"},{"id":"deepm_life-from-death","name":"Life from Death","level":3,"school":"Necromancy","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"Your touch can siphon energy from undead to heal your wounds. Make a melee spell attack against an undead creature within your reach. On a hit, the target takes 2d6 radiant damage, and you or an ally within 30 feet of you regains hit points equal to half the amount of radiant damage dealt. If used on an ally, this effect can restore the ally to no more than half of the ally's hit point maximum. This effect can't heal an undead or a construct. Until the spell ends, you can make the attack again on each of your turns as an action.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","damage":"2d6 radiant","attack":true},{"id":"deepm_life-hack","name":"Life Hack","level":8,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (a ruby worth 500 gp, which is consumed during the casting)","duration":"1 hour","classes":[],"desc":"Choose up to five creatures that you can see within range. Each of the creatures gains access to a pool of temporary hit points that it can draw upon over the spell's duration or until the pool is used up. The pool contains 120 temporary hit points. The number of temporary hit points each individual creature can draw is determined by dividing 120 by the number of creatures with access to the pool. Hit points are drawn as a bonus action by the creature gaining the temporary hit points. Any number can be drawn at once, up to the maximum allowed.\n\nA creature can't draw temporary hit points from the pool while it has temporary hit points from any source, including a previous casting of this spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_life-sense","name":"Life Sense","level":3,"school":"Divination","time":"Action","range":"Self","components":"V, S, M (a clear piece of quartz)","duration":"10 minutes","classes":[],"desc":"For the duration, you can sense the location of any creature that isn't a construct or an undead within 30 feet of you, regardless of impediments to your other senses. This spell doesn't sense creatures that are dead. A creature trying to hide its life force from you can make a Charisma saving throw. On a success, you can't sense the creature with this casting of the spell. If you cast the spell again, the creature must make the saving throw again to remain hidden from your senses.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_life-transference-arrow","name":"Life Transference Arrow","level":1,"school":"Necromancy","time":"Action","range":"120 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You create a glowing arrow of necrotic magic and command it to strike a creature you can see within range. The arrow can have one of two effects; you choose which at the moment of casting. If you make a successful ranged spell attack, you and the target experience the desired effect. If the attack misses, the spell fails.\n- The arrow deals 2d6 necrotic damage to the target, and you heal the same amount of hit points.\n- You take 2d6 necrotic damage, and the target heals the same amount of hit points.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the spell's damage and hit points healed increase by 1d6 for each slot level above 1st."},{"id":"deepm_litany-of-sure-hands","name":"Litany of Sure Hands","level":1,"school":"Divination","time":"Bonus Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"This spell allows a creature within range to quickly perform a simple task (other than attacking or casting a spell) as a bonus action on its turn. Examples include finding an item in a backpack, drinking a potion, and pulling a rope. Other actions may also fall into this category, depending on the GM's ruling. The target also ignores the loading property of weapons.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_living-shadows","name":"Living Shadows","level":5,"school":"Enchantment","time":"Action","range":"120 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You whisper sibilant words of void speech that cause shadows to writhe with unholy life. Choose a point you can see within range. Writhing shadows spread out in a 15-foot-radius sphere centered on that point, grasping at creatures in the area. A creature that starts its turn in the area or that enters the area for the first time on its turn must make a successful Strength saving throw or be restrained by the shadows. A creature that starts its turn restrained by the shadows must make a successful Constitution saving throw or gain one level of exhaustion.\n\nA restrained creature can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success, it frees itself.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_lock-armor","name":"Lock Armor","level":2,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (a pinch of rust and metal shavings)","duration":"1 minute","classes":[],"desc":"You target a piece of metal equipment or a metal construct. If the target is a creature wearing metal armor or is a construct, it makes a Wisdom saving throw to negate the effect. On a failed save, the spell causes metal to cling to metal, making it impossible to move pieces against each other. This effectively paralyzes a creature that is made of metal or that is wearing metal armor with moving pieces; for example, scale mail would lock up because the scales must slide across each other, but a breastplate would be unaffected. Limited movement might still be possible, depending on how extensive the armor is, and speech is usually not affected. Metal constructs are paralyzed. An affected creature or construct can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. A grease spell dispels lock armor on everything in its area.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.","save":"wis"},{"id":"deepm_looping-trail","name":"Looping Trail","level":4,"school":"Transmutation","time":"1 minute","range":"Touch","components":"V, S, M (a piece of rope twisted into a loop)","duration":"8 hours","classes":[],"desc":"You touch a trail no more than 1 mile in length, reconfiguring it to give it switchbacks and curves that make the trail loop back on itself. For the duration, the trail makes subtle changes in its configuration and in the surrounding environment to give the impression of forward progression along a continuous path. A creature on the trail must succeed on a Wisdom (Survival) check to notice that the trail is leading it in a closed loop.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_lovesick","name":"Lovesick","level":4,"school":"Enchantment","time":"Action","range":"90 feet","components":"V, S, M (a handful of red rose petals)","duration":"1 minute","classes":[],"desc":"This spell causes creatures to behave unpredictably, as they randomly experience the full gamut of emotions of someone who has fallen head over heels in love. Each creature in a 10-foot-radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it.\n\nAn affected target can't take reactions and must roll a d10 at the start of each of its turns to determine its behavior for that turn.\n\nd10 | Behavior\n1-3 | The creature spends its turn moping like a lovelorn teenager; it doesn't move or take actions.\n4–5 | The creature bursts into tears, takes the Dash action, and uses all its movement to run off in a random direction. To determine the direction, roll a d8 and assign a direction to each die face.\n6 | The creature uses its action to remove one item of clothing or piece of armor. Each round spent removing pieces of armor reduces its AC by 1.\n7–8 | The creature drops anything it is holding in its hands and passionately embraces a randomly determined creature. Treat this as a grapple attempt which uses the Attack action.\n9 | The creature flies into a jealous rage and uses its action to make a melee attack against a randomly determined creature.\n10 | The creature can act and move normally.\nAt the end of each of its turns, an affected target can make a Wisdom saving throw, ending the effect on itself on a successful save.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the radius of the sphere increases by 5 feet for each slot level above 4th.","save":"wis"},{"id":"deepm_maddening-whispers","name":"Maddening Whispers","level":2,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You whisper a string of Void Speech toward a target within range that can hear you. The target must succeed on a Charisma saving throw or be incapacitated. While incapacitated by this spell, the target's speed is 0, and it can't benefit from increases to its speed. To maintain the effect for the duration, you must use your action on subsequent turns to continue whispering; otherwise, the spell ends. The spell also ends if the target takes damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_maim","name":"Maim","level":5,"school":"Necromancy","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Your hands become claws bathed in necrotic energy. Make a melee spell attack against a creature you can reach. On a hit, the target takes 4d6 necrotic damage and a section of its body of your choosing withers:\n   **Upper Limb.** The target has disadvantage on Strength checks, and, if it has the Multiattack action, it has disadvantage on its first attack roll each round.\n   **Lower Limb.** The target's speed is reduced by 10 feet, and it has disadvantage on Dexterity checks.\n   **Body.** Choose one damage type: bludgeoning, piercing, or slashing. The target loses its resistance to that damage type. If the target doesn't have resistance to the chosen damage type, it is vulnerable to that damage type instead.\n  The effect is permanent until removed by remove curse, greater restoration, or similar magic.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d6 necrotic","attack":true},{"id":"deepm_malevolent-waves","name":"Malevolent Waves","level":8,"school":"Abjuration","time":"Action","range":"Self","components":"V, S, M (a profane object that has been bathed in blood)","duration":"1 minute","classes":[],"desc":"You create an invisible miasma that fills the area within 30 feet of you. All your allies have advantage on Dexterity (Stealth) checks they make within 30 feet of you, and all your enemies are poisoned while within that radius.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_mammons-due","name":"Mammon’s Due","level":9,"school":"Conjuration","time":"1 hour","range":"500 feet","components":"V, S, M (11 gilded human skulls worth 150 gp each, which are consumed by the spell)","duration":"1 minute","classes":[],"desc":"You summon a cylindrical sinkhole filled with burning ash and grasping arms made of molten metal at a point on the ground you can see within range. The sinkhole is 20 feet deep and 50 feet in diameter, and is difficult terrain. A creature that's in the area when the spell is cast, or that begins its turn in the area or enters it during its turn, takes 10d6 fire damage and must make a Strength or Dexterity (creature's choice) saving throw. On a failed save, the creature is restrained by the molten arms, which try to drag it below the surface of the ash.\n\nA creature that's restrained by the arms at the start of your turn must make a successful Strength saving throw or be pulled 5 feet farther down into the ash. A creature pulled below the surface is blinded, deafened, and can't breathe. To escape, a creature must use an action to make a successful Strength or Dexterity check against your spell save DC. On a successful check, the creature is no longer restrained and can move through the difficult terrain of the ash pit. It doesn't need to make a Strength or Dexterity saving throw this turn to not be grabbed by the arms again, but it must make the saving throw as normal if it's still in the ash pit at the start of its next turn.\n\nThe diameter of the ash pit increases by 10 feet at the start of each of your turns for the duration of the spell. The ash pit remains after the spell ends, but the grasping arms disappear and restrained creatures are freed automatically. As the ash slowly cools, it deals 1d6 less fire damage for each hour that passes after the spell ends.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition","damage":"10d6 fire","save":"str"},{"id":"deepm_mark-prey","name":"Mark Prey","level":2,"school":"Divination","time":"Bonus Action","range":"120 feet","components":"V","duration":"1 hour","classes":[],"desc":"You choose a creature you can see within range as your prey. Until the spell ends, you have advantage on Wisdom (Perception) and Wisdom (Survival) checks to find or track your prey. In addition, the target is outlined in light that only you can see. Any attack roll you make against your prey has advantage if you can see it, and your prey can't benefit from being invisible against you. If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn to mark a new target as your prey.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours."},{"id":"deepm_mass-hobble-mount","name":"Mass Hobble Mount","level":3,"school":"Necromancy","time":"Action","range":"60 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"When you cast **mass hobble mount**, you make separate ranged spell attacks against up to six horses, wolves, or other four-legged or two-legged beasts being ridden as mounts within 60 feet of you. The targets can be different types of beasts and can have different numbers of legs. Each beast hit by your spell is disabled so that it can't move at its normal speed without incurring injury. An affected creature that moves more than half its base speed in a turn takes 4d6 bludgeoning damage.\n\nThis spell has no effect on a creature that your GM deems to not be a mount.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd.","damage":"4d6 bludgeoning"},{"id":"deepm_mass-surge-dampener","name":"Mass Surge Dampener","level":5,"school":"Abjuration","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute, or until expended","classes":[],"desc":"Using your strength of will, you protect up to three creatures other than yourself from the effect of a chaos magic surge. A protected creature can make a DC 13 Charisma saving throw to negate the effect of a chaos magic surge that does not normally allow a saving throw, or it gains advantage on a saving throw that is normally allowed. Once a protected creature makes a successful saving throw allowed by **mass surge dampener**, the spell's effect ends for that creature.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_maw-of-needles","name":"Maw of Needles","level":1,"school":"Transmutation","time":"Bonus Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"A spiny array of needle-like fangs protrudes from your gums, giving you a spiny bite. For the duration, you can use your action to make a melee spell attack with the bite. On a hit, the target takes 2d6 piercing damage and must succeed on a Dexterity saving throw or some of the spines in your mouth break off, sticking in the target. Until this spell ends, the target must succeed on a Constitution saving throw at the start of each of its turns or take 1d6 piercing damage from the spines. If you hit a target that has your spines stuck in it, your attack deals extra damage equal to your spellcasting ability modifier, and more spines don't break off in the target. Your spines can stick in only one target at a time. If your spines stick into another target, the spines on the previous target crumble to dust, ending the effect on that target.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage of the spiny bite and the spines increases by 1d6 for every two slot levels above 1st.","damage":"2d6 piercing","save":"dex","attack":true},{"id":"deepm_memento-mori","name":"Memento Mori","level":0,"school":"Necromancy","time":"Action","range":"Self","components":"V, S","duration":"1 round","classes":[],"desc":"You transform yourself into a horrifying vision of death, rotted and crawling with maggots, exuding the stench of the grave. Each creature that can see you must succeed on a Charisma saving throw or be stunned until the end of your next turn.\n\nA creature that succeeds on the saving throw is immune to further castings of this spell for 24 hours.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_mephitic-croak","name":"Mephitic Croak","level":2,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a dead toad and a dram of arsenic worth 10 gp)","duration":"Instantaneous","classes":[],"desc":"You release an intensely loud burp of acidic gas in a 15-foot cone. Creatures in the area take 2d6 acid damage plus 2d6 thunder damage, or half as much damage with a successful Dexterity saving throw. A creature whose Dexterity saving throw fails must also make a successful Constitution saving throw or be stunned and poisoned until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, both acid and thunder damage increase by 1d6 for each slot level above 2nd.","save":"dex"},{"id":"deepm_mind-exchange","name":"Mind Exchange","level":3,"school":"Transmutation","time":"1 minute","range":"60 feet","components":"V, S, M (a prism and silver coin)","duration":"8 hours","classes":[],"desc":"One humanoid of your choice that you can see within range must make a Charisma saving throw. On a failed save, you project your mind into the body of the target. You use the target's statistics but don't gain access to its knowledge, class features, or proficiencies, retaining your own instead. Meanwhile, the target's mind is shunted into your body, where it uses your statistics but likewise retains its own knowledge, class features, and proficiencies.\n\nThe exchange lasts until either of the the two bodies drops to 0 hit points, until you end it as a bonus action, or until you are forced out of the target body by an effect such as a [dispel magic](https://api.open5e.com/spells/dispel-magic) or [dispel evil and good](https://api.open5e.com/spells/dispel-evil-and-good) spell (the latter spell defeats **mind exchange** even though possession by a humanoid isn't usually affected by that spell). When the effect of this spell ends, both switched minds return to their original bodies. The target of the spell is immune to mind exchange for 24 hours after succeeding on the saving throw or after the exchange ends.\n\nThe effects of the exchange can be made permanent with a [wish](https://api.open5e.com/spells/wish) spell or comparable magic.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_mire","name":"Mire","level":3,"school":"Transmutation","time":"Action","range":"100 feet","components":"V, S, M (a vial of sand mixed with water)","duration":"1 hour","classes":[],"desc":"When you cast mire, you create a 10-foot-diameter pit of quicksand, sticky mud, or a similar dangerous natural hazard suited to the region. A creature that's in the area when the spell is cast or that enters the affected area must make a successful Strength saving throw or sink up to its waist and be restrained by the mire. From that point on, the mire acts as quicksand, but the DC for Strength checks to escape from the quicksand is equal to your spell save DC. A creature outside the mire trying to pull another creature free receives a +5 bonus on its Strength check.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_misstep","name":"Misstep","level":0,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You gesture to a creature within range that you can see. If the target fails a Wisdom saving throw, it uses its reaction to move 5 feet in a direction you dictate. This movement does not provoke opportunity attacks. The spell automatically fails if you direct the target into a dangerous area such as a pit trap, a bonfire, or off the edge of a cliff, or if the target has already used its reaction.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_mist-of-wonders","name":"Mist of Wonders","level":2,"school":"Conjuration","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"A colorful mist surrounds you out to a radius of 30 feet. Creatures inside the mist see odd shapes in it and hear random sounds that don't make sense. The very concepts of order and logic don't seem to exist inside the mist.\n\nAny 1st-level spell that's cast in the mist by another caster or that travels through the mist is affected by its strange nature. The caster must make a Constitution saving throw when casting the spell. On a failed save, the spell transforms into another 1st-level spell the caster knows (chosen by the GM from those available), even if that spell is not currently prepared. The altered spell's slot level or its original target or targeted area can't be changed. Cantrips are unaffected. If (in the GM's judgment) none of the caster's spells known of that level can be transformed, the spell being cast simply fails.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, it affects any spell cast using a spell slot of any lower level. For instance, using a 6th-level slot enables you to transform a spell of 5th level or lower into another spell of the same level.","save":"con"},{"id":"deepm_monstrous-empathy","name":"Monstrous Empathy","level":3,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","classes":[],"desc":"This spell lets you forge a connection with a monstrosity. Choose a monstrosity that you can see within range. It must see and hear you. If the monstrosity's Intelligence is 4 or higher, the spell fails. Otherwise, the monstrosity must succeed on a Wisdom saving throw or be charmed by you for the spell's duration. If you or one of your companions harms the target, the spell ends.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can affect one additional monstrosity for each slot level above 3rd.","save":"int"},{"id":"deepm_moon-trap","name":"Moon Trap","level":4,"school":"Abjuration","time":"1 hour","range":"Self","components":"V, S, M (powdered silver worth 250 gp)","duration":"Up to 8 hours","classes":[],"desc":"While casting this spell under the light of the moon, you inscribe a glyph that covers a 10-foot-square area on a flat, stationary surface such as a floor or a wall. Once the spell is complete, the glyph is invisible in moonlight but glows with a faint white light in darkness.\n\nAny creature that touches the glyph, except those you designate during the casting of the spell, must make a successful Wisdom saving throw or be drawn into an inescapable maze until the sun rises.\n\nThe glyph lasts until the next sunrise, at which time it flares with bright light, and any creature trapped inside returns to the space it last occupied, unharmed. If that space has become occupied or dangerous, the creature appears in the nearest safe unoccupied space.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_mosquito-bane","name":"Mosquito Bane","level":1,"school":"Necromancy","time":"Action","range":"50 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"This spell kills any insects or swarms of insects within range that have a total of 25 hit points or fewer.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the number of hit points affected increases by 15 for each slot level above 1st. Thus, a 2nd-level spell kills insects or swarms that have up to 40 hit points, a 3rd-level spell kills those with 55 hit points or fewer, and so forth, up to a maximum of 85 hit points for a slot of 6th level or higher."},{"id":"deepm_mud-pack","name":"Mud Pack","level":1,"school":"Conjuration","time":"Action","range":"Touch","components":"V, S, M (a clump of mud)","duration":"1 hour","classes":[],"desc":"This spell covers you or a willing creature you touch in mud consistent with the surrounding terrain. For the duration, the spell protects the target from extreme cold and heat, allowing the target to automatically succeed on Constitution saving throws against environmental hazards related to temperature. In addition, the target has advantage on Dexterity (Stealth) checks while traveling at a slow pace in the terrain related to the component for this spell.\n\nIf the target is subject to heavy precipitation for 1 minute, the precipitation removes the mud, ending the spell.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the duration is 8 hours and you can target up to ten willing creatures within 30 feet of you.","save":"con"},{"id":"deepm_negative-image","name":"Negative Image","level":2,"school":"Conjuration","time":"Action","range":"120 feet","components":"V, S, M (a piece of reflective obsidian)","duration":"Instantaneous","classes":[],"desc":"You create a shadow-tunnel between your location and one other creature you can see within range. You and that creature instantly swap positions. If the target creature is unwilling to exchange places with you, it can resist the effect by making a Charisma saving throw. On a successful save, the spell has no effect.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_nether-weapon","name":"Nether Weapon","level":4,"school":"Enchantment","time":"Action","range":"Touch","components":"V, S, M (ink, chalk, or some other writing medium)","duration":"1 hour","classes":[],"desc":"You whisper in Void Speech and touch a weapon. Until the spell ends, the weapon turns black, becomes magical if it wasn't before, and deals 2d6 necrotic damage (in addition to its normal damage) on a successful hit. A creature that takes necrotic damage from the enchanted weapon can't regain hit points until the start of your next turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d6 for each slot level above 4th."},{"id":"deepm_night-terrors","name":"Night Terrors","level":4,"school":"Illusion","time":"Action","range":"120 feet","components":"V, S, M (a crow’s eye)","duration":"1 minute","classes":[],"desc":"You amplify the fear that lurks in the heart of all creatures. Select a target point you can see within the spell's range. Every creature within 20 feet of that point becomes frightened until the start of your next turn and must make a successful Wisdom saving throw or become paralyzed. A paralyzed creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. Creatures immune to being frightened are not affected by **night terrors**.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_nightfall","name":"Nightfall","level":3,"school":"Evocation","time":"Action","range":"100 feet","components":"V, S","duration":"10 minutes","classes":[],"desc":"You call upon night to arrive ahead of schedule. With a sharp word, you create a 30-foot-radius cylinder of night centered on a point on the ground within range. The cylinder extends vertically for 100 feet or until it reaches an obstruction, such as a ceiling. The area inside the cylinder is normal darkness, and thus heavily obscured. Creatures inside the darkened cylinder can see illuminated areas outside the cylinder normally.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_nip-at-the-heels","name":"Nip at the Heels","level":2,"school":"Illusion","time":"Action","range":"30 feet","components":"V, S, M (a dog’s tooth)","duration":"1 minute","classes":[],"desc":"You create an illusory pack of wild dogs that bark and nip at one creature you can see within range, which must make a Wisdom saving throw. On a failed save, the target has disadvantage on ability checks and attack rolls for the duration as it is distracted by the dogs. At the end of each of its turns, the target can make a Wisdom saving throw, ending the effect on itself on a successful save. A target that is at least 10 feet off the ground (in a tree, flying, and so forth) has advantage on the saving throw, staying just out of reach of the jumping and barking dogs.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd.","save":"wis"},{"id":"deepm_not-dead-yet","name":"Not Dead Yet","level":4,"school":"Necromancy","time":"1 minute","range":"Touch","components":"V, S, M (a cloth doll filled with herbs and diamond dust worth 100 gp)","duration":"1 hour","classes":[],"desc":"You cast this spell while touching the cloth doll against the intact corpse of a Medium or smaller humanoid that died within the last hour. At the end of the casting, the body reanimates as an undead creature under your control. While the spell lasts, your consciousness resides in the animated body. You can use an action to manipulate the body's limbs in order to make it move, and you can see and hear through the body's eyes and ears, but your own body becomes unconscious. The animated body can neither attack nor defend itself. This spell doesn't change the appearance of the corpse, so further measures might be needed if the body is to be used in a way that involves fooling observers into believing it's still alive. The spell ends instantly, and your consciousness returns to your body, if either your real body or the animated body takes any damage.\n\nYou can't use any of the target's abilities except for nonmagical movement and darkvision. You don't have access to its knowledge, proficiencies, or anything else that was held in its now dead mind, and you can't make it speak.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_not-this-day","name":"Not This Day!","level":5,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S","duration":"24 hours","classes":[],"desc":"The creature you touch gains protection against either a specific damage type (slashing, poison, fire, radiant, and the like) or a category of creature (giant, beast, elemental, monstrosity, and so forth) that you name when the spell is cast. For the next 24 hours, the target has advantage on saving throws involving that type of damage or kind of creature, including death saving throws if the attack that dropped the target to 0 hit points is affected by this spell. A character can be under the effect of only a single **not this day!** spell at one time; a second casting on the same target cancels the preexisting protection.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_orb-of-light","name":"Orb of Light","level":2,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S","duration":"1 round","classes":[],"desc":"An orb of light the size of your hand shoots from your fingertips toward a creature within range, which takes 3d8 radiant damage and is blinded for 1 round. A target that makes a successful Dexterity saving throw takes half the damage and is not blinded.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","damage":"3d8 radiant","save":"dex"},{"id":"deepm_outflanking-boon","name":"Outflanking Boon","level":3,"school":"Illusion","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"This spell targets one enemy, which must make a Wisdom saving throw. On a failed save, an illusory ally of yours appears in a space from which it threatens to make a melee attack against the target. Your allies gain advantage on melee attacks against the target for the duration because of the distracting effect of the illusion. An affected target repeats the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the spell targets one additional enemy for each slot level above 3rd.","save":"wis"},{"id":"deepm_paragon-of-chaos","name":"Paragon of Chaos","level":8,"school":"Transmutation","time":"Action","range":"Self","components":"V","duration":"1 minute","classes":[],"desc":"You become a humanoid-shaped swirling mass of color and sound. You gain resistance to bludgeoning, piercing, and slashing damage, and immunity to poison and psychic damage. You are also immune to the following conditions: exhaustion, paralyzed, petrified, poisoned, and unconscious. Finally, you gain truesight to 30 feet and can teleport 30 feet as a move.\n\nEach round, as a bonus action, you can cause an automatic chaos magic surge, choosing either yourself or another creature you can see within 60 feet as the caster for the purpose of resolving the effect. You must choose the target before rolling percentile dice to determine the nature of the surge. The DC of any required saving throw is calculated as if you were the caster.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_pendulum","name":"Pendulum","level":1,"school":"Enchantment","time":"Action","range":"Touch","components":"V, S, M (a small pendulum or metronome made of brass and rosewood worth 10 gp)","duration":"1 minute","classes":[],"desc":"You give the touched creature an aspect of regularity in its motions and fortunes. If the target gets a failure on a Wisdom saving throw, then for the duration of the spell it doesn't make d20 rolls—to determine the results of attack rolls, ability checks, and saving throws it instead follows the sequence 20, 1, 19, 2, 18, 3, 17, 4, and so on.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_phantom-dragon","name":"Phantom Dragon","level":3,"school":"Illusion","time":"Action","range":"Touch","components":"V, S, M (a piece of dragon egg shell)","duration":"1 hour","classes":[],"desc":"You tap your dragon magic to make an ally appear as a draconic beast. The target of the spell appears to be a dragon of size Large or smaller. When seeing this illusion, observers make a Wisdom saving throw to see through it.\n\nYou can use an action to make the illusory dragon seem ferocious. Choose one creature within 30 feet of the illusory dragon to make a Wisdom saving throw. If it fails, the creature is frightened. The creature remains frightened until it uses an action to make a successful Wisdom saving throw or the spell's duration expires.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, increase the number of targets the illusion can affect by one for each slot level above 3rd.","save":"wis"},{"id":"deepm_pitfall","name":"Pitfall","level":4,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"A pit opens under a Huge or smaller creature you can see within range that does not have a flying speed. This pit isn't a simple hole in the floor or ground, but a passage to an extradimensional space. The target must succeed on a Dexterity saving throw or fall into the pit, which closes over it. At the end of your next turn, a new portal opens 20 feet above where the pit was located, and the creature falls out. It lands prone and takes 6d6 bludgeoning damage.\n\nIf the original target makes a successful saving throw, you can use a bonus action on your turn to reopen the pit in any location within range that you can see. The spell ends when a creature has fallen through the pit and taken damage, or when the duration expires.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"6d6 bludgeoning","save":"dex"},{"id":"deepm_poisoned-volley","name":"Poisoned Volley","level":2,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"By drawing back and releasing an imaginary bowstring, you summon forth dozens of glowing green arrows. The arrows dissipate when they hit, but all creatures in a 20-foot square within range take 3d8 poison damage and become poisoned. A creature that makes a successful Constitution saving throw takes half as much damage and is not poisoned.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","save":"con"},{"id":"deepm_potency-of-the-pack","name":"Potency of the Pack","level":3,"school":"Transmutation","time":"Action","range":"25 feet","components":"V, S, M (a few hairs from a wolf)","duration":"1 minute","classes":[],"desc":"You bestow lupine traits on a group of living creatures that you designate within range. Choose one of the following benefits to be gained by all targets for the duration:\n- **Thick Fur.** Each target sprouts fur over its entire body, giving it a +2 bonus to Armor Class.\n- **Keen Hearing and Smell.** Each target has advantage on Wisdom (Perception) checks that rely on hearing or smell.\n- **Pack Tactics.** Each affected creature has advantage on an attack roll against a target if at least one of the attacker's allies (also under the effect of this spell) is within 5 feet of the target of the attack and the ally isn't incapacitated.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the duration increases by 1 minute for each slot level above 3rd."},{"id":"deepm_power-word-kneel","name":"Power Word Kneel","level":2,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S, M (an emerald worth at least 100 gp)","duration":"Instantaneous","classes":[],"desc":"When you shout this word of power, creatures within 20 feet of a point you specify are compelled to kneel down facing you. A kneeling creature is treated as prone. Up to 55 hit points of creatures are affected, beginning with those that have the fewest hit points. A kneeling creature makes a Wisdom saving throw at the end of its turn, ending the effect on itself on a successful save. The effect ends immediately on any creature that takes damage while kneeling.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_power-word-pain","name":"Power Word Pain","level":4,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S, M (a quill jabbed into your own body)","duration":"Instantaneous","classes":[],"desc":"When you utter this word of power, one creature within 60 feet of you takes 4d10 force damage. At the start of each of its turns, the creature must make a successful Constitution saving throw or take an extra 4d10 force damage. The effect ends on a successful save.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d10 force","save":"con"},{"id":"deepm_primal-infusion","name":"Primal Infusion","level":5,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a bit of fur from a carnivorous animal)","duration":"1 minute","classes":[],"desc":"You channel the fury of nature, drawing on its power. Until the spell ends, you gain the following benefits:\n- You gain 30 temporary hit points. If any of these remain when the spell ends, they are lost.\n- You have advantage on attack rolls when one of your allies is within 5 feet of the target and the ally isn't incapacitated.\n- Your weapon attacks deal an extra 1d10 damage of the same type dealt by the weapon on a hit.\n- You gain a +2 bonus to AC.\n- You have proficiency on Constitution saving throws.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_prismatic-ray","name":"Prismatic Ray","level":5,"school":"Evocation","time":"Action","range":"100 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"A ray of shifting color springs from your hand. Make a ranged spell attack against a single creature you can see within range. The ray's effect and the saving throw that applies to it depend on which color is dominant when the beam strikes its target, determined by rolling a d8.\n\nd8 | Color | Effect | Saving Throw\n1 | Red | 8d10 fire damage | Dexterity\n2 | Orange | 8d10 acid damage | Dexterity\n3 | Yellow | 8d10 lightning damage | Dexterity\n4 | Green | Target Poisoned | Constitution\n5 | Blue | Target Deafened | Constitution\n6 | Indigo | Target Frightened | Wisdom\n7 | Violet | Target Stunned | Constitution\n8 | Shifting Ray | Target Blinded | Constitution\nA target takes half as much damage on a successful Dexterity saving throw. A successful Constitution or Wisdom saving throw negates the effect of a ray that inflicts a condition on the target; on a failed save, the target is affected for 5 rounds or until the effect is negated. If the result of your attack roll is a critical hit, you can choose the color of the beam that hits the target, but the attack does not deal additional damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex","attack":true},{"id":"deepm_protection-from-the-void","name":"Protection from the Void","level":1,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S, M (a small bar of silver worth 15 sp, which the spell consumes)","duration":"10 minutes","classes":[],"desc":"Until the spell ends, one willing creature you touch has resistance to necrotic and psychic damage and has advantage on saving throws against Void spells.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_protective-ice","name":"Protective Ice","level":3,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S, M (a seed encased in ice or glass)","duration":"1 hour","classes":[],"desc":"When you cast **protective ice**, you encase a willing target in icy, medium armor equivalent to a breastplate (AC 14). A creature without the appropriate armor proficiency has the usual penalties. If the target is already wearing armor, it only uses the better of the two armor classes.\n\nA creature striking a target encased in **protective ice** with a melee attack while within 5 feet of it takes 1d6 cold damage.\n\nIf the armor's wearer takes fire damage, an equal amount of damage is done to the armor, which has 30 hit points and is damaged only when its wearer takes fire damage. Damaged ice can be repaired by casting a spell that deals cold damage on it, on a point-for-point basis, but the armor can't have more than 30 points repaired.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 4th-level spell slot, it creates splint armor (AC 17, 40 hit points). If you cast this spell using a 5th-level spell slot, it creates plate armor (AC 18, 50 hit points). The armor's hit points increase by 10 for each spell slot above 5th, but the AC remains 18. Additionally, if you cast this spell using a spell slot of 4th level or higher, the armor deals an extra +2 cold damage for each spell slot above 3rd.","damage":"1d6 cold"},{"id":"deepm_puff-of-smoke","name":"Puff of Smoke","level":0,"school":"Evocation","time":"Bonus Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"By harnessing the elemental power of fire, you warp nearby air into obscuring smoke. One creature you can see within range must make a Dexterity saving throw. If it fails, the creature is blinded until the start of your next turn. **Puff of smoke** has no effect on creatures that have tremorsense or blindsight.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_pummelstone","name":"Pummelstone","level":0,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a pebble)","duration":"Instantaneous","classes":[],"desc":"You cause a fist-sized chunk of stone to appear and hurl itself against the spell's target. Make a ranged spell attack. On a hit, the target takes 1d6 bludgeoning damage and must roll a d4 when it makes an attack roll or ability check during its next turn, subtracting the result of the d4 from the attack or check roll.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).","damage":"1d6 bludgeoning","attack":true},{"id":"deepm_pyroclasm","name":"Pyroclasm","level":9,"school":"Evocation","time":"Action","range":"500 feet","components":"V, S, M (a shard of obsidian)","duration":"1 minute","classes":[],"desc":"You point toward an area of ground or a similar surface within range. A geyser of lava erupts from the chosen spot. The geyser is 5 feet in diameter and 40 feet high. Each creature in the cylinder when it erupts or at the start of your turn takes 10d8 fire damage, or half as much damage if it makes a successful Dexterity saving throw.\n\nThe geyser also forms a pool of lava at its base. Initially, the pool is the same size as the geyser, but at the start of each of your turns for the duration, the pool's radius increases by 5 feet. A creature in the pool of lava (but not in the geyser) at the start of your turn takes 5d8 fire damage.\n\nWhen a creature leaves the pool of lava, its speed is reduced by half and it has disadvantage on Dexterity saving throws, caused by a hardening layer of lava. These penalties last until the creature uses an action to break the hardened stone away from itself.\n\nIf you maintain concentration on **pyroclasm** for a full minute, the lava geyser and pool harden into permanent, nonmagical stone. A creature in either area when the stone hardens is restrained until the stone is broken away.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"10d8 fire","save":"dex"},{"id":"deepm_quick-time","name":"Quick Time","level":4,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S, M (any seed)","duration":"Instantaneous","classes":[],"desc":"You make one living creature or plant within range move rapidly in time compared to you. The target becomes one year older. For example, you could cast this spell on a seedling, which causes the plant to sprout from the soil, or you could cast this spell on a newly hatched duckling, causing it to become a full-grown duck. If the target is a creature with an Intelligence of 3 or higher, it must succeed on a Constitution saving throw to resist the aging. It can choose to fail the saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you increase the target's age by one additional year for each slot level above 4th.","save":"int"},{"id":"deepm_quicken","name":"Quicken","level":0,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":[],"desc":"You touch one willing creature. Once before the duration of the spell expires, the target can roll a d4 and add the number rolled to an initiative roll or Dexterity saving throw it has just made. The spell then ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_quicksilver-mantle","name":"Quicksilver Mantle","level":4,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a nonmagical cloak and a dram of quicksilver worth 10 gp)","duration":"1 hour","classes":[],"desc":"You transform an ordinary cloak into a highly reflective, silvery garment. This mantle increases your AC by 2 and grants advantage on saving throws against gaze attacks. In addition, whenever you are struck by a ray such as a [ray of enfeeblement](https://api.open5e.com/spells/ray-of-enfeeblement), [scorching ray](https://api.open5e.com/spells/scorching-ray), or even [disintegrate](https://api.open5e.com/spells/disintegrate), roll 1d4. On a result of 4, the cloak deflects the ray, which instead strikes a randomly selected target within 10 feet of you. The cloak deflects only the first ray that strikes it each round; rays after the first affect you as normal.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_quintessence","name":"Quintessence","level":8,"school":"Transmutation","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"By calling upon an archangel, you become infused with celestial essence and take on angelic features such as golden skin, glowing eyes, and ethereal wings. For the duration of the spell, your Armor Class can't be lower than 20, you can't be frightened, and you are immune to necrotic damage.\n\nIn addition, each hostile creature that starts its turn within 120 feet of you or enters that area for the first time on a turn must succeed on a Wisdom saving throw or be frightened for 1 minute. A creature frightened in this way is restrained. A frightened creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature's saving throw is successful or if the effect ends for it, the creature is immune to the frightening effect of the spell until you cast **quintessence** again.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_raid-the-lair","name":"Raid the Lair","level":4,"school":"Abjuration","time":"10 minutes","range":"Self","components":"V, S, M (a piece of the dragon whose lair you are raiding)","duration":"1 hour","classes":[],"desc":"You create an invisible circle of protective energy centered on yourself with a radius of 10 feet. This field moves with you. The caster and all allies within the energy field are protected against dragons' lair actions.\n- Attack rolls resulting directly from lair actions are made with disadvantage.\n- Saving throws resulting directly from lair actions are made with advantage, and damage done by these lair actions is halved.\n- Lair actions occur on an initiative count 10 lower than normal.\n\nThe caster has advantage on Constitution saving throws to maintain concentration on this spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_rain-of-blades","name":"Rain of Blades","level":5,"school":"Conjuration","time":"Action","range":"25 feet","components":"V, S, M (shard of metal from a weapon)","duration":"4 rounds","classes":[],"desc":"You call down a rain of swords, spears, and axes. The blades fill 150 square feet (six 5-foot squares, a circle 15 feet in diameter, or any other pattern you want as long as it forms one contiguous space at least 5 feet wide in all places. The blades deal 6d6 slashing damage to each creature in the area at the moment the spell is cast, or half as much damage on a successful Dexterity saving throw. An intelligent undead injured by the blades is frightened for 1d4 rounds if it fails a Charisma saving throw. Most of the blades break or are driven into the ground on impact, but enough survive intact that any single piercing or slashing melee weapon can be salvaged from the affected area and used normally if it is claimed before the spell ends. When the duration expires, all the blades (including the one that was salvaged) disappear.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, an unbroken blade can be picked up and used as a magical +1 weapon until it disappears.","save":"dex"},{"id":"deepm_ray-of-alchemical-negation","name":"Ray of Alchemical Negation","level":4,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You launch a ray of blazing, polychromatic energy from your fingertips. Make a ranged spell attack against an alchemical item or a trap that uses alchemy to achieve its ends, such as a trap that sprays acid, releases poisonous gas, or triggers an explosion of alchemist's fire. A hit destroys the alchemical reagents, rendering them harmless. The attack is made against the most suitable object Armor Class.\n\nThis spell can also be used against a creature within range that is wholly or partially composed of acidic, poisonous, or alchemical components, such as an alchemical golem or an ochre jelly. In that case, a hit deals 6d6 force damage, and the target must make a successful Constitution saving throw or it deals only half as much damage with its acidic, poisonous, or alchemical attacks for 1 minute. A creature whose damage is halved can repeat the saving throw at the end of each of its turns, ending the effect on a success.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con","attack":true},{"id":"deepm_ray-of-life-suppression","name":"Ray of Life Suppression","level":4,"school":"Necromancy","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You launch a swirling ray of disruptive energy at a creature within range. Make a ranged spell attack. On a hit, the creature takes 6d8 necrotic damage and its maximum hit points are reduced by an equal amount. This reduction lasts until the creature finishes a short or long rest, or until it receives the benefit of a [greater restoration](https://api.open5e.com/spells/greater-restoration) spell or comparable magic.\n\nThis spell has no effect on constructs or undead.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"6d8 necrotic","attack":true},{"id":"deepm_reaver-spirit","name":"Reaver Spirit","level":3,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You inspire allies to fight with the savagery of berserkers. You and any allies you can see within range have advantage on Strength checks and Strength saving throws; resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks; and a +2 bonus to damage with melee weapons.\n\nWhen the spell ends, each affected creature must succeed on a Constitution saving throw or gain 1d4 levels of exhaustion.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the bonus to damage increases by 1 for each slot level above 2nd.","save":"str"},{"id":"deepm_reposition","name":"Reposition","level":4,"school":"Conjuration","time":"Bonus Action","range":"30 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"You designate up to three friendly creatures (one of which can be yourself) within range. Each target teleports to an unoccupied space of its choosing that it can see within 30 feet of itself.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the spell targets one additional friendly creature for each slot level above 4th."},{"id":"deepm_reset","name":"Reset","level":4,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Choose up to four creatures within range. If a target is your ally, it can reroll initiative, keeping whichever of the two results it prefers. If a target is your enemy, it must make a successful Wisdom saving throw or reroll initiative, keeping whichever of the two results you prefer. Changes to the initiative order go into effect at the start of the next round.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you can affect one additional creature for each slot level above 4th.","save":"wis"},{"id":"deepm_reverberate","name":"Reverberate","level":2,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a metal ring)","duration":"Instantaneous","classes":[],"desc":"You touch the ground at your feet with the metal ring, creating an impact that shakes the earth ahead of you. Creatures and unattended objects touching the ground in a 15-foot cone emanating from you take 4d6 thunder damage, and creatures fall prone; a creature that makes a successful Dexterity saving throw takes half the damage and does not fall prone.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.","save":"dex"},{"id":"deepm_revive-beast","name":"Revive Beast","level":2,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M (emeralds worth 100 gp, which the spell consumes)","duration":"Instantaneous","classes":[],"desc":"You touch a beast that has died within the last minute. That beast returns to life with 1 hit point. This spell can't return to life a beast that has died of old age, nor can it restore any missing body parts.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_right-the-stars","name":"Right the Stars","level":7,"school":"Divination","time":"10 minutes","range":"Self","components":"V, S, M (seven black candles and a circle of powdered charred bone or basalt)","duration":"1 hour","classes":[],"desc":"You subtly warp the flow of space and time to enhance your conjurations with cosmic potency. Until the spell ends, the maximum duration of any conjuration spell you cast that requires concentration is doubled, any creature that you summon or create with a conjuration spell has 30 temporary hit points, and you have advantage on Charisma checks and Charisma saving throws.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_ring-strike","name":"Ring Strike","level":1,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (two metal rings)","duration":"1 hour","classes":[],"desc":"You infuse two metal rings with magic, causing them to revolve in a slow orbit around your head or hand. For the duration, when you hit a target within 60 feet of you with an attack, you can launch one of the rings to strike the target as well. The target takes 1d10 bludgeoning damage and must succeed on a Strength saving throw or be pushed 5 feet directly away from you. The ring is destroyed when it strikes.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can affect up to two additional rings for each spell slot level above 1st.","damage":"1d10 bludgeoning","save":"str"},{"id":"deepm_ring-ward","name":"Ring Ward","level":7,"school":"Abjuration","time":"Action","range":"Self","components":"V, S, M (an iron ring worth 200 gp, which the spell consumes)","duration":"1 hour","classes":[],"desc":"The iron ring you use to cast the spell becomes a faintly shimmering circlet of energy that spins slowly around you at a radius of 15 feet. For the duration, you and your allies inside the protected area have advantage on saving throws against spells, and all affected creatures gain resistance to one type of damage of your choice.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_riptide","name":"Riptide","level":3,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S","duration":"1 round","classes":[],"desc":"With a sweeping gesture, you cause water to swell up into a 20-foot tall, 20-foot radius cylinder centered on a point on the ground that you can see. Each creature in the cylinder must make a Strength saving throw. On a failed save, the creature is restrained and suspended in the cylinder; on a successful save, the creature moves to just outside the nearest edge of the cylinder.\n\nAt the start of your next turn, you can direct the current of the swell as it dissipates. Choose one of the following options.\n- **Riptide.** The water in the cylinder flows in a direction you choose, sweeping along each creature in the cylinder. An affected creature takes 3d8 bludgeoning damage and is pushed 40 feet in the chosen direction, landing prone.\n- **Undertow.** The water rushes downward, pulling each creature in the cylinder into an unoccupied space at the center. Each creature is knocked prone and must make a successful Constitution saving throw or be stunned until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"3d8 bludgeoning","save":"str"},{"id":"deepm_rolling-thunder","name":"Rolling Thunder","level":2,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a sliver of metal from a gong)","duration":"Instantaneous","classes":[],"desc":"A tremendous bell note explodes from your outstretched hand and rolls forward in a line 30 feet long and 5 feet wide. Each creature in the line must make a successful Constitution saving throw or be deafened for 1 minute. A creature made of material such as stone, crystal, or metal has disadvantage on its saving throw against this spell.\n\nWhile a creature is deafened in this way, it is wreathed in thundering energy; it takes 2d8 thunder damage at the start of its turn, and its speed is halved. A deafened creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","damage":"2d8 thunder","save":"con"},{"id":"deepm_rotting-corpse","name":"Rotting Corpse","level":2,"school":"Necromancy","time":"10 minutes","range":"Touch","components":"V, M (a rotting piece of flesh from an undead creature)","duration":"3 days","classes":[],"desc":"Your familiarity with the foul effects of death allows you to prevent a dead body from being returned to life using anything but the most powerful forms of magic.\n\nYou cast this spell by touching a creature that died within the last 24 hours. The body immediately decomposes to a state that prevents the body from being returned to life by the [raise dead](https://api.open5e.com/spells/raise-dead) spell (though a [resurrection](https://api.open5e.com/spells/resurrection) spell still works). At the end of this spell's duration, the body decomposes to a rancid slime, and it can't be returned to life except through a [true resurrection](https://api.open5e.com/spells/true-resurrection) spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can affect one additional corpse for each slot level above 2nd."},{"id":"deepm_rune-of-imprisonment","name":"Rune of Imprisonment","level":3,"school":"Abjuration","time":"Action","range":"30 feet","components":"V, S, M (ink)","duration":"1 minute","classes":[],"desc":"You trace a glowing black rune in the air which streaks toward and envelops its target. Make a ranged spell attack against the target. On a successful hit, the rune absorbs the target creature, leaving only the glowing rune hanging in the space the target occupied. The subject can take no actions while imprisoned, nor can the subject be targeted or affected by any means. Any spell durations or conditions affecting the creature are postponed until the creature is freed. A dying creature does not lose hit points or stabilize until freed.\n\nA creature adjacent to the rune can use a move action to attempt to disrupt its energies; doing so allows the imprisoned creature to make a Wisdom saving throw. On a success, this disruption negates the imprisonment and ends the effect. Disruption can be attempted only once per round.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis","attack":true},{"id":"deepm_salt-lash","name":"Salt Lash","level":3,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a pinch of salt worth 1 sp, which is consumed during the casting)","duration":"10 minutes","classes":[],"desc":"You create a long, thin blade of razor-sharp salt crystals. You can wield it as a longsword, using your spellcasting ability to modify your weapon attack rolls. The sword deals 2d8 slashing damage on a hit, and any creature struck by the blade must make a successful Constitution saving throw or be stunned by searing pain until the start of your next turn. Constructs and undead are immune to the blade's secondary (stun) effect; plants and creatures composed mostly of water, such as water elementals, also take an additional 2d8 necrotic damage if they fail the saving throw.\n\nThe spell lasts until you stop concentrating on it, the duration expires, or you let go of the blade for any reason.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_sand-ship","name":"Sand Ship","level":4,"school":"Transmutation","time":"1 minute","range":"30 feet","components":"V, S, M (a boat or ship of 10,000 gp value or less)","duration":"24 hours","classes":[],"desc":"Casting **sand ship** on a water vessel up to the size of a small sailing ship transforms it into a vessel capable of sailing on sand as easily as water. The vessel still needs a trained crew and relies on wind or oars for propulsion, but it moves at its normal speed across sand instead of water for the duration of the spell. It can sail only over sand, not soil or solid rock. For the duration of the spell, the vessel doesn't float; it must be beached or resting on the bottom of a body of water (partially drawn up onto a beach, for example) when the spell is cast, or it sinks into the water.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_sanguine-horror","name":"Sanguine Horror","level":5,"school":"Conjuration","time":"Action","range":"5 feet","components":"V, S, M (a miniature dagger)","duration":"1 hour","classes":[],"desc":"When you cast this spell, you prick yourself with the material component, taking 1 piercing damage. The spell fails if this damage is prevented or negated in any way. From the drop of blood, you conjure a [blood elemental](https://api.open5e.com/monsters/blood-elemental). The blood elemental is friendly to you and your companions for the duration. It disappears when it's reduced to 0 hit points or when the spell ends.\n\nRoll initiative for the elemental, which has its own turns. It obeys verbal commands from you (no action required by you). If you don't issue any commands to the blood elemental, it defends itself but otherwise takes no actions. If your concentration is broken, the blood elemental doesn't disappear, but you lose control of it and it becomes hostile to you and your companions. An uncontrolled blood elemental cannot be dismissed by you, and it disappears 1 hour after you summoned it.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_scale-rot","name":"Scale Rot","level":4,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (a piece of rotten meat)","duration":"1 minute","classes":[],"desc":"You summon death and decay to plague your enemies. For dragons, this act often takes the form of attacking a foe's armor and scales, as a way of weakening an enemy dragon and leaving it plagued by self-doubt and fear. (This enchantment is useful against any armored creature, not just dragons.)\n\nOne creature of your choice within range that has natural armor must make a Constitution saving throw. If it fails, attacks against that creature's Armor Class are made with advantage, and the creature can't regain hit points through any means while the spell remains in effect. An affected creature can end the spell by making a successful Constitution saving throw, which also makes the creature immune to further castings of **scale rot** for 24 hours.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the number of affected targets increases by one for each slot level above 4th.","save":"con"},{"id":"deepm_scentless","name":"Scentless","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (1 ounce of pure water)","duration":"1 hour","classes":[],"desc":"You touch a willing creature or object that is not being worn or carried. For the duration, the target gives off no odor. A creature that relies on smell has disadvantage on Wisdom (Perception) checks to detect the target and Wisdom (Survival) checks to track the target. The target is invisible to a creature that relies solely on smell to sense its surroundings. This spell has no effect on targets with unusually strong scents, such as ghasts.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_screaming-ray","name":"Screaming Ray","level":1,"school":"Evocation","time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You create a ray of psychic energy to attack your enemies. Make a ranged spell attack against a creature. On a hit, the target takes 1d4 psychic damage and is deafened until the end of your next turn. If the target succeeds on a Constitution saving throw, it is not deafened.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you create one additional ray for each slot level above 1st. You can direct the rays at one target or several.","damage":"1d4 psychic","save":"con","attack":true},{"id":"deepm_scribe","name":"Scribe","level":0,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"This spell enables you to create a copy of a one-page written work by placing a blank piece of paper or parchment near the work that you are copying. All the writing, illustrations, and other elements in the original are reproduced in the new document, in your handwriting or drawing style. The new medium must be large enough to accommodate the original source. Any magical properties of the original aren't reproduced, so you can't use scribe to make copies of spell scrolls or magic books.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_scry-ambush","name":"Scry Ambush","level":4,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You foresee your foe's strike a split second before it occurs. When you cast this spell successfully, you also designate a number of your allies that can see or hear you equal to your spellcasting ability modifier + your proficiency bonus. Those allies are also not surprised by the attack and can act normally in the first round of combat.\n\nIf you would be surprised, you must make a check using your spellcasting ability at the moment your reaction would be triggered. The check DC is equal to the current initiative count. On a failed check, you are surprised and can't use your reaction to cast this spell until after your next turn. On a successful check, you can use your reaction to cast this spell immediately.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_sculpt-snow","name":"Sculpt Snow","level":2,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"When you **cast sculpt** snow in an area filled with snow, you can create one Large object, two Medium objects, or four smaller objects from snow. With a casting time of 1 action, your sculptings bear only a crude resemblance to generic creatures or objects. If you increase the casting time to 1 minute, your creations take on a more realistic appearance and can even vaguely resemble specific creatures; the resemblance isn't strong enough to fool anyone, but the creature can be recognized. The sculptures are as durable as a typical snowman.\n\nSculptures created by this spell can be animated with [animate objects](https://api.open5e.com/spells/animate-objects) or comparable magic. Animated sculptures gain the AC, hit points, and other attributes provided by that spell. When they attack, they deal normal damage plus a similar amount of cold damage; an animated Medium sculpture, for example, deals 2d6 + 1 bludgeoning damage plus 2d6 + 1 cold damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can sculpt one additional Large object for each slot level above 2nd. Two Large objects can be replaced with one Huge object."},{"id":"deepm_seal-of-sanctuary","name":"Seal of Sanctuary","level":7,"school":"Abjuration","time":"1 minute","range":"Touch","components":"V, S, M (incense and special inks worth 250 gp, which the spell consumes)","duration":"24 hours","classes":[],"desc":"You inscribe an angelic seal on the ground, the floor, or other solid surface of a structure. The seal creates a spherical sanctuary with a radius of 50 feet, centered on the seal. For the duration, aberrations, elementals, fey, fiends, and undead that approach to within 5 feet of the boundary know they are about to come into contact with a deadly barrier. If such a creature moves so as to touch the boundary, or tries to cross the boundary by any means, including teleportation and extradimensional travel, it must make a Charisma saving throw. On a failed save, it takes 10d8 radiant damage, is repelled to 5 feet outside the boundary, and can't target anything inside the boundary with attacks, spells, or abilities until the spell ends. On a successful save, the creature takes half as much radiant damage and can cross the boundary. If the creature is a fiend that isn't on its home plane, it is immediately destroyed (no saving throw) instead of taking damage.\n\nAberrations, elementals, fey, and undead that are within 50 feet of the seal (inside the boundary) have disadvantage on ability checks, attack rolls, and saving throws, and each such creature takes 2d8 radiant damage at the start of its turn.\n\nCreatures other than aberrations, elementals, fey, fiends, and undead can't be charmed or frightened while within 50 feet of the seal.\n\nThe seal has AC 18, 50 hit points, resistance to bludgeoning, piercing, and slashing damage, and immunity to psychic and poison damage. Ranged attacks against the seal are made with disadvantage. If it is scribed on the surface of an object that is later destroyed (such as a wooden door), the seal is not damaged and remains in place, perhaps suspended in midair. The spell ends only if the seal is reduced to 0 hit points.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","damage":"10d8 radiant","save":"cha"},{"id":"deepm_searing-sun","name":"Searing Sun","level":4,"school":"Transmutation","time":"Action","range":"200 feet","components":"V, S, M (a magnifying lens)","duration":"1 minute","classes":[],"desc":"This spell intensifies the light and heat of the sun, so that it burns exposed flesh. You must be able to see the sun when you cast the spell. The searing sunlight affects a cylindrical area 50 feet in radius and 200 feet high, centered on the a point within range. Each creature that starts its turn in that area takes 5d8 fire damage, or half the damage with a successful Constitution saving throw. A creature that's shaded by a solid object —such as an awning, a building, or an overhanging boulder— has advantage on the saving throw. On your turn, you can use an action to move the center of the cylinder up to 20 feet along the ground in any direction.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"5d8 fire","save":"con"},{"id":"deepm_see-beyond","name":"See Beyond","level":5,"school":"Divination","time":"Action","range":"Touch","components":"V, S, M (a transparent crystal)","duration":"1 hour","classes":[],"desc":"This spell enables a willing creature you touch to see through any obstructions as if they were transparent. For the duration, the target can see into and through opaque objects, creatures, spells, and effects that obstruct line of sight to a range of 30 feet. Inside that distance, the creature can choose what it perceives as opaque and what it perceives as transparent as freely and as naturally as it can shift its focus from nearby to distant objects.\n\nAlthough the creature can see any target within 30 feet of itself, all other requirements must still be satisfied before casting a spell or making an attack against that target. For example, the creature can see an enemy that has total cover but can't shoot that enemy with an arrow because the cover physically prevents it. That enemy could be targeted by a [geas](https://api.open5e.com/spells/geas) spell, however, because [geas](https://api.open5e.com/spells/geas) needs only a visible target.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_seed-of-destruction","name":"Seed of Destruction","level":8,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S, M (five teeth from a still-living humanoid and a vial of the caster’s blood)","duration":"1 hour","classes":[],"desc":"This spell impregnates a living creature with a rapidly gestating [hydra](https://api.open5e.com/spells/hydra) that consumes the target from within before emerging to wreak havoc on the world. Make a ranged spell attack against a living creature within range that you can see. On a hit, you implant a five‑headed embryonic growth into the creature. Roll 1d3 + 1 to determine how many rounds it takes the embryo to mature.\n\nDuring the rounds when the embryo is gestating, the affected creature takes 5d4 slashing damage at the start of its turn, or half the damage with a successful Constitution saving throw.\n\nWhen the gestation period has elapsed, a tiny hydra erupts from the target's abdomen at the start of your turn. The hydra appears in an unoccupied space adjacent to the target and immediately grows into a full-size Huge aberration. Nearby creatures are pushed away to clear a sufficient space as the hydra grows. This creature is a standard hydra, but with the ability to cast [bane](https://api.open5e.com/spells/bane) as an action (spell save DC 11) requiring no spell components. Roll initiative for the hydra, which takes its own turns. It obeys verbal commands that you issue to it (no action required by you). If you don't give it a command or it can't follow your command, the hydra attacks the nearest living creature.\n\nAt the end of each of the hydra's turns, you must make a DC 15 Charisma saving throw. On a successful save, the hydra remains under your control and friendly to you and your companions. On a failed save, your control ends, the hydra becomes hostile to all creatures, and it attacks the nearest creature to the best of its ability.\n\nThe hydra disappears at the end of the spell's duration, or its existence can be cut short with a [wish](https://api.open5e.com/spells/wish) spell or comparable magic, but nothing less. The embryo can be destroyed before it reaches maturity by using a [dispel magic](https://api.open5e.com/spells/dispel-magic) spell under the normal rules for dispelling high-level magic.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","damage":"5d4 slashing","save":"con","attack":true},{"id":"deepm_seeping-death","name":"Seeping Death","level":3,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"3 days","classes":[],"desc":"Your touch inflicts a virulent, flesh-eating disease. Make a melee spell attack against a creature within your reach. On a hit, the creature's Dexterity score is reduced by 1d4, and it is afflicted with the seeping death disease for the duration.\n\nSince this spell induces a natural disease in its target, any effect that removes a disease or otherwise ameliorates a disease's effects apply to it and can end the spell early.\n\n**Seeping Death.** The creature's flesh is slowly liquefied by a lingering necrotic pestilence. At the end of each long rest, the diseased creature must succeed on a Constitution saving throw or its Dexterity score is reduced by 1d4. The reduction lasts until the target finishes a long rest after the disease is cured. If the disease reduces the creature's Dexterity to 0, the creature dies.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex","attack":true},{"id":"deepm_seers-reaction","name":"Seer’s Reaction","level":1,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Your foreknowledge allows you to act before others, because you knew what was going to happen. When you cast this spell, make a new initiative roll with a +5 bonus. If the result is higher than your current initiative, your place in the initiative order changes accordingly. If the result is also higher than the current place in the initiative order, you take your next turn immediately and then use the higher number starting in the next round.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_semblance-of-dread","name":"Semblance of Dread","level":0,"school":"Illusion","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"You adopt the visage of the faceless god Nyarlathotep. For the duration, any creature within 10 feet of you and able to see you can't willingly move closer to you unless it makes a successful Wisdom saving throw at the start of its turn. Constructs and undead are immune to this effect.\n\nFor the duration of the spell, you also gain vulnerability to radiant damage and have advantage on saving throws against effects that cause the frightened condition.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_shade","name":"Shade","level":2,"school":"Abjuration","time":"Action","range":"Self","components":"V, S","duration":"10 minutes","classes":[],"desc":"You create a magical screen across your eyes. While the screen remains, you are immune to blindness caused by visible effects, such as [color spray](https://api.open5e.com/spells/color-spray). The spell doesn't alleviate blindness that's already been inflicted on you. If you normally suffer penalties on attacks or ability checks while in sunlight, those penalties don't apply while you're under the effect of this spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the duration of the spell increases by 10 minutes for each slot level above 2nd."},{"id":"deepm_shadow-armor","name":"Shadow Armor","level":1,"school":"Abjuration","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You can siphon energy from the plane of shadow to protect yourself from an immediate threat. As a reaction, you pull shadows around yourself to distort reality. The attack against you is made with disadvantage, and you have resistance to radiant damage until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_shadow-bite","name":"Shadow Bite","level":0,"school":"Illusion","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You create a momentary needle of cold, sharp pain in a creature within range. The target must make a successful Constitution saving throw or take 1d6 necrotic damage immediately and have its speed halved until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell's damage increases to 2d6 when you reach 5th level, 3d6 when you reach 11th level, and 4d6 when you reach 17th level.","save":"con"},{"id":"deepm_shadow-blindness","name":"Shadow Blindness","level":0,"school":"Illusion","time":"Action","range":"Touch","components":"V, S","duration":"1 round","classes":[],"desc":"You make a melee spell attack against a creature you touch that has darkvision as an innate ability; on a hit, the target's darkvision is negated until the spell ends. This spell has no effect against darkvision that derives from a spell or a magic item. The target retains all of its other senses.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","attack":true},{"id":"deepm_shadow-hands","name":"Shadow Hands","level":1,"school":"Evocation","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"A freezing blast of shadow explodes out from you in a 10-foot cone. Any creature caught in the shadow takes 2d4 necrotic damage and is frightened; a successful Wisdom saving throw halves the damage and negates the frightened condition.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the damage dealt by the attack increases by 2d4 for each slot level above 1st.","damage":"2d4 necrotic","save":"wis"},{"id":"deepm_shadow-monsters","name":"Shadow Monsters","level":4,"school":"Illusion","time":"Action","range":"120 feet","components":"V, S, M (a doll)","duration":"1 minute","classes":[],"desc":"You choose up to two creatures within range. Each creature must make a Wisdom saving throw. On a failed save, the creature perceives its allies as hostile, shadowy monsters, and it must attack its nearest ally. An affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th.","save":"wis"},{"id":"deepm_shadow-puppets","name":"Shadow Puppets","level":2,"school":"Illusion","time":"Action","range":"60 feet","components":"V, S, M (a pinch of powdered lead)","duration":"1 minute","classes":[],"desc":"You animate the shadow of a creature within range, causing it to attack that creature. As a bonus action when you cast the spell, or as an action on subsequent rounds while you maintain concentration, make a melee spell attack against the creature. If it hits, the target takes 2d8 psychic damage and must make a successful Intelligence saving throw or be incapacitated until the start of your next turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.","damage":"2d8 psychic","save":"int","attack":true},{"id":"deepm_shadow-trove","name":"Shadow Trove","level":3,"school":"Transmutation","time":"1 minute","range":"5 feet","components":"V, S, M (ink made from the blood of a raven)","duration":"1 hour","classes":[],"desc":"You paint a small door approximately 2 feet square on a hard surface to create a portal into the void of space. The portal “peels off” the surface you painted it on and follows you when you move, always floating in the air within 5 feet of you. An icy chill flows out from the portal. You can place up to 750 pounds of nonliving matter in the portal, where it stays suspended in the frigid void until you withdraw it. Items that are still inside the shadow trove when the duration ends spill out onto the ground. You can designate a number of creatures up to your Intelligence modifier who have access to the shadow trove; only you and those creatures can move objects into the portal.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the duration increases by 2 hours for each slot level above 3rd."},{"id":"deepm_shadows-brought-to-light","name":"Shadows Brought to Light","level":2,"school":"Divination","time":"10 minutes","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"If a creature you designate within range fails a Charisma saving throw, you cause the target's shadow to come to life and reveal one of the creature's most scandalous secrets: some fact that the target would not want widely known (GM's choice). When casting the spell, you choose whether everyone present will hear the secret, in which case the shadow speaks loudly in a twisted version of the target's voice, or if the secret is whispered only to you. The shadow speaks in the target's native language.\n\nIf the target does not have a scandalous secret or does not have a spoken language, the spell fails as if the creature's saving throw had succeeded.\n\nIf the secret was spoken aloud, the target takes a −2 penalty to Charisma checks involving anyone who was present when it was revealed. This penalty lasts until you finish a long rest.\n\n**Ritual Focus.** If you expend your ritual focus, the target has disadvantage on Charisma checks instead of taking the −2 penalty.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_shadowy-retribution","name":"Shadowy Retribution","level":4,"school":"Necromancy","time":"10 minutes","range":"Self","components":"V, S, M (a small silver cup filled with the caster’s blood)","duration":"12 hours","classes":[],"desc":"You fill a small silver cup with your own blood (taking 1d4 piercing damage) while chanting vile curses in the dark. Once the chant is completed, you consume the blood and swear an oath of vengeance against any who harm you.\n\nIf you are reduced to 0 hit points, your oath is invoked; a shadow materializes within 5 feet of you. The shadow attacks the creature that reduced you to 0 hit points, ignoring all other targets, until it or the target is slain, at which point the shadow dissipates into nothing.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, an additional shadow is conjured for each slot level above 4th.\n\n**Ritual Focus.** If you expend your ritual focus, the spell summons a banshee instead of a shadow. If you also use a higher-level spell slot, additional undead are still shadows."},{"id":"deepm_shared-sacrifice","name":"Shared Sacrifice","level":2,"school":"Evocation","time":"1 minute","range":"60 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"You and up to five of your allies within range contribute part of your life force to create a pool that can be used for healing. Each target takes 5 necrotic damage (which can't be reduced but can be healed normally), and those donated hit points are channeled into a reservoir of life essence. As an action, any creature who contributed to the pool of hit points can heal another creature by touching it and drawing hit points from the pool into the injured creature. The injured creature heals a number of hit points equal to your spellcasting ability modifier, and the hit points in the pool decrease by the same amount. This process can be repeated until the pool is exhausted or the spell's duration expires.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"5 necrotic"},{"id":"deepm_sheen-of-ice","name":"Sheen of Ice","level":2,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S, M (water within a glass globe)","duration":"1 minute","classes":[],"desc":"A small icy globe shoots from your finger to a point within range and then explodes in a spray of ice. Each creature within 20 feet of that point must make a successful Dexterity saving throw or become coated in ice for 1 minute. Ice-coated creatures move at half speed. An invisible creature becomes outlined by the ice so that it loses the benefits of invisibility while the ice remains. The spell ends for a specific creature if that creature takes 5 or more fire damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"5 fire","save":"dex"},{"id":"deepm_shifting-the-odds","name":"Shifting the Odds","level":2,"school":"Divination","time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","classes":[],"desc":"By wrapping yourself in strands of chaotic energy, you gain advantage on the next attack roll or ability check that you make. Fate is a cruel mistress, however, and her scales must always be balanced. The second attack roll or ability check (whichever occurs first) that you make after casting **shifting the odds** is made with disadvantage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_shiver","name":"Shiver","level":0,"school":"Evocation","time":"Action","range":"30 feet","components":"V, S, M (humanoid tooth)","duration":"1 round","classes":[],"desc":"You fill a humanoid creature with such cold that its teeth begin to chatter and its body shakes uncontrollably. Roll 5d8; the total is the maximum hit points of a creature this spell can affect. The affected creature must succeed on a Constitution saving throw, or it cannot cast a spell or load a missile weapon until the end of your next turn. Once a creature has been affected by this spell, it is immune to further castings of this spell for 24 hours.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The maximum hit points you can affect increases by 4d8 when you reach 5th level (9d8), 11th level (13d8), and 17th level (17d8).","save":"con"},{"id":"deepm_shroud-of-death","name":"Shroud of Death","level":4,"school":"Necromancy","time":"Action","range":"Self","components":"V, S, M (a piece of ice)","duration":"10 rounds","classes":[],"desc":"You call up a black veil of necrotic energy that devours the living. You draw on the life energy of all living creatures within 30 feet of you that you can see. When you cast the spell, every living creature within 30 feet of you that you can see takes 1 necrotic damage, and all those hit points transfer to you as temporary hit points. The damage and the temporary hit points increase to 2 per creature at the start of your second turn concentrating on the spell, 3 per creature at the start of your third turn, and so on. All living creatures you can see within 30 feet of you at the start of each of your turns are affected. A creature can avoid the effect by moving more than 30 feet away from you or by getting out of your line of sight, but it becomes susceptible again if the necessary conditions are met. The temporary hit points last until the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"1 necrotic"},{"id":"deepm_sidestep-arrow","name":"Sidestep Arrow","level":3,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"With a few perfectly timed steps, you interpose a foe between you and danger. You cast this spell when an enemy makes a ranged attack or a ranged spell attack against you but before the attack is resolved. At least one other foe must be within 10 feet of you when you cast **sidestep arrow**. As part of casting the spell, you can move up to 15 feet to a place where an enemy lies between you and the attacker. If no such location is available, the spell has no effect. You must be able to move (not restrained or grappled or prevented from moving for any other reason), and this move does not provoke opportunity attacks. After you move, the ranged attack is resolved with the intervening foe as the target instead of you.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_sign-of-koth","name":"Sign of Koth","level":7,"school":"Abjuration","time":"Turn","range":"Self","components":"V, S, M (a platinum dagger and a powdered black pearl worth 500 gp, which the spell consumes)","duration":"Until dispelled","classes":[],"desc":"You invoke the twilight citadels of Koth to create a field of magical energy in the shape of a 60-foot-radius, 60-foot‑tall cylinder centered on you. The only visible evidence of this field is a black rune that appears on every doorway, window, or other portal inside the area.\n\nChoose one of the following creature types: aberration, beast, celestial, dragon, elemental, fey, fiend, giant, humanoid, monstrosity, ooze, plant, or undead. The sign affects creatures of the chosen type (including you, if applicable) in the following ways:\n- The creatures can't willingly enter the cylinder's area by nonmagical means; the cylinder acts as an invisible, impenetrable wall of force. If an affected creature tries to enter the cylinder's area by using teleportation, a dimensional shortcut, or other magical means, it must make a successful Charisma saving throw or the attempt fails.\n- They cannot hear any sounds that originate inside the cylinder.\n- They have disadvantage on attack rolls against targets inside the cylinder.\n- They can't charm, frighten, or possess creatures inside the cylinder.\nCreatures that aren't affected by the field and that take a short rest inside it regain twice the usual number of hit points for each Hit Die spent at the end of the rest.\n\nWhen you cast this spell, you can choose to reverse its magic; doing this will prevent affected creatures from leaving the area instead of from entering it, make them unable to hear sounds that originate outside the cylinder, and so forth. In this case, the field provides no benefit for taking a short rest.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, the radius increases by 30 feet for each slot level above 7th.","save":"cha"},{"id":"deepm_silhouette","name":"Silhouette","level":0,"school":"Illusion","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":[],"desc":"You create a shadow play against a screen or wall. The surface can encompass up to 100 square feet. The number of creatures that can see the shadow play equals your Intelligence score. The shadowy figures make no sound but they can dance, run, move, kiss, fight, and so forth. Most of the figures are generic types—a rabbit, a dwarf—but a number of them equal to your Intelligence modifier can be recognizable as specific individuals.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_sir-mittinzs-move-curse","name":"Sir Mittinz’s Move Curse","level":3,"school":"Transmutation","time":"1 hour","range":"20 feet","components":"V, S, M (a finely crafted hollow glass sphere and incense worth 50 gp, which the spell consumes)","duration":"Instantaneous","classes":[],"desc":"When you are within range of a cursed creature or object, you can transfer the curse to a different creature or object that's also within range. The curse must be transferred from object to object or from creature to creature.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_sleep-of-the-deep","name":"Sleep of the Deep","level":3,"school":"Illusion","time":"Action","range":"60 feet","components":"V, S, M (a pinch of black sand, a tallow candle, and a drop of cephalopod ink)","duration":"8 hours","classes":[],"desc":"Your magic haunts the dreams of others. Choose a sleeping creature that you are aware of within range. Creatures that don't sleep, such as elves, can't be targeted. The creature must succeed on a Wisdom saving throw or it garners no benefit from the rest, and when it awakens, it gains one level of exhaustion and is afflicted with short‑term madness.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can affect one additional creature for each slot level above 3rd.","save":"wis"},{"id":"deepm_slippery-fingers","name":"Slippery Fingers","level":1,"school":"Enchantment","time":"Bonus Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You set a series of small events in motion that cause the targeted creature to drop one nonmagical item of your choice that it's currently holding, unless it makes a successful Charisma saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_slither","name":"Slither","level":2,"school":"Transmutation","time":"Action","range":"Self","components":"V, M (ashes from a wooden statue of you, made into ink and used to draw your portrait, worth 50 gp)","duration":"1 minute","classes":[],"desc":"You momentarily become a shadow (a humanoid-shaped absence of light, not the undead creature of that name). You can slide under a door, through a keyhole, or through any other tiny opening. All of your equipment is transformed with you, and you can move up to your full speed during the spell's duration. While in this form, you have advantage on Dexterity (Stealth) checks made in darkness or dim light and you are immune to nonmagical bludgeoning, piercing, and slashing damage. You can dismiss this spell by using an action to do so.\n\nIf you return to your normal form while in a space too small for you (such as a mouse hole, sewer pipe, or the like), you take 4d6 force damage and are pushed to the nearest space within 50 feet big enough to hold you. If the distance is greater than 50 feet, you take an extra 1d6 force damage for every additional 10 feet traveled.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can target an additional willing creature that you touch for each slot level above 2nd."},{"id":"deepm_snow-boulder","name":"Snow Boulder","level":4,"school":"Transmutation","time":"Action","range":"90 feet","components":"V, S, M (a handful of snow)","duration":"4 rounds","classes":[],"desc":"A ball of snow forms 5 feet away from you and rolls in the direction you point at a speed of 30 feet, growing larger as it moves. To roll the boulder into a creature, you must make a successful ranged spell attack. If the boulder hits, the creature must make a successful Dexterity saving throw or be knocked prone and take the damage indicated below. Hitting a creature doesn't stop the snow boulder's movement or impede its growth, as long as you continue to maintain concentration on the effect. When the spell ends, the boulder stops moving.\n\nRound | Size | Damage\n1 | Small | 1d6 bludgeoning\n2 | Medium | 2d6 bludgeoning\n3 | Large | 4d6 bludgeoning\n4 | Huge | 6d6 bludgeoning","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_snow-fort","name":"Snow Fort","level":2,"school":"Conjuration","time":"Action","range":"120 feet","components":"V, S, M (a ring carved from chalk or white stone)","duration":"Instantaneous","classes":[],"desc":"This spell creates a simple “fort” from packed snow. The snow fort springs from the ground in an unoccupied space within range. It encircles a 10-foot area with sloping walls 4 feet high. The fort provides half cover (+2 AC) against ranged and melee attacks coming from outside the fort. The walls have AC 12, 30 hit points per side, are immune to cold, necrotic, poison, and psychic damage, and are vulnerable to fire damage. A damaged wall can be repaired by casting a spell that deals cold damage on it, on a point-for-point basis, up to a maximum of 30 points.\n\nThe spell also creates a dozen snowballs that can be thrown (range 20/60) and that deal 1d4 bludgeoning damage plus 1d4 cold damage on a hit.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_snowy-coat","name":"Snowy Coat","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"1 hour","classes":[],"desc":"This spell makes a slight alteration to a target creature's appearance that gives it advantage on Dexterity (Stealth) checks to hide in snowy terrain. In addition, the target can use a bonus action to make itself invisible in snowy terrain for 1 minute. The spell ends at the end of the minute or when the creature attacks or casts a spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st."},{"id":"deepm_song-of-the-forest","name":"Song of the Forest","level":3,"school":"Transmutation","time":"10 minutes","range":"Self","components":"V, S, M (a dried leaf, crumpled and released)","duration":"10 minutes","classes":[],"desc":"You attune your senses to the natural world, so that you detect every sound that occurs within 60 feet: wind blowing through branches, falling leaves, grazing deer, trickling streams, and more. You can clearly picture the source of each sound in your mind. The spell gives you tremorsense out to a range of 10 feet. In addition, you have advantage on Wisdom (Perception) checks that rely on hearing. Creatures that make no noise or that are magically silent cannot be detected by this spell's effect.\n\n**Song of the forest** functions only in natural environments; it fails if cast underground, in a city, or in a building that isolates the caster from nature (GM's discretion).\n\n**Ritual Focus.** If you expend your ritual focus, the spell also gives you blindsight out to a range of 30 feet.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_speak-with-inanimate-object","name":"Speak with Inanimate Object","level":1,"school":"Divination","time":"Action","range":"Touch","components":"V, S","duration":"10 minutes","classes":[],"desc":"You awaken a spirit that resides inside an inanimate object such as a rock, a sign, or a table, and can ask it up to three yes-or-no questions. The spirit is indifferent toward you unless you have done something to harm or help it. The spirit can give you information about its environment and about things it has observed (with its limited senses), and it can act as a spy for you in certain situations. The spell ends when its duration expires or after you have received answers to three questions.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_spin","name":"Spin","level":2,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You designate a creature you can see within range and tell it to spin. The creature can resist this command with a successful Wisdom saving throw. On a failed save, the creature spins in place for the duration of the spell. A spinning creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. A creature that has spun for 1 round or longer becomes dizzy and has disadvantage on attack rolls and ability checks until 1 round after it stops spinning.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_spinning-axes","name":"Spinning Axes","level":4,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (an iron ring)","duration":"Instantaneous","classes":[],"desc":"Spinning axes made of luminous force burst out from you to strike all creatures within 10 feet of you. Each of those creatures takes 5d8 force damage, or half the damage with a successful Dexterity saving throw. Creatures damaged by this spell that aren't undead or constructs begin bleeding. A bleeding creature takes 2d6 necrotic damage at the end of each of its turns for 1 minute. A creature can stop the bleeding for itself or another creature by using an action to make a successful Wisdom (Medicine) check against your spell save DC or by applying any amount of magical healing.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th.","damage":"5d8 force","save":"dex"},{"id":"deepm_spiteful-weapon","name":"Spiteful Weapon","level":3,"school":"Necromancy","time":"Action","range":"25 feet","components":"V, S, M (a melee weapon that has been used to injure the target)","duration":"5 rounds","classes":[],"desc":"You create a connection between the target of the spell, an attacker that injured the target during the last 24 hours, and the melee weapon that caused the injury, all of which must be within range when the spell is cast.\n\nFor the duration of the spell, whenever the attacker takes damage while holding the weapon, the target must make a Charisma saving throw. On a failed save, the target takes the same amount and type of damage, or half as much damage on a successful one. The attacker can use the weapon on itself and thus cause the target to take identical damage. A self-inflicted wound hits automatically, but damage is still rolled randomly.\n\nOnce the connection is established, it lasts for the duration of the spell regardless of range, so long as all three elements remain on the same plane. The spell ends immediately if the attacker receives any healing.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The target has disadvantage on its Charisma saving throws if **spiteful weapon** is cast using a spell slot of 5th level or higher.","save":"cha"},{"id":"deepm_spur-mount","name":"Spur Mount","level":1,"school":"Transmutation","time":"Bonus Action","range":"Touch","components":"V, S, M (an apple or a sugar cube)","duration":"1 round","classes":[],"desc":"You urge your mount to a sudden burst of speed. Until the end of your next turn, you can direct your mount to use the Dash or Disengage action as a bonus action. This spell has no effect on a creature that you are not riding.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_staff-of-violet-fire","name":"Staff of Violet Fire","level":4,"school":"Evocation","time":"Bonus Action","range":"Self","components":"V, S, M (mummy dust)","duration":"Special","classes":[],"desc":"You create a quarterstaff of pure necrotic energy that blazes with intense purple light; it appears in your chosen hand. If you let it go, it disappears, though you can evoke it again as a bonus action if you have maintained concentration on the spell.\n\nThis staff is an extremely unstable and impermanent magic item; it has 10 charges and does not require attunement. The wielder can use one of three effects:\n- By using your action to make a melee attack and expending 1 charge, you can attack with it. On a hit, the target takes 5d10 necrotic damage.\n- By expending 2 charges, you can release bolts of necrotic fire against up to 3 targets as ranged attacks for 1d8+4 necrotic damage each.\n\nThe staff disappears and the spell ends when all the staff's charges have been expended or if you stop concentrating on the spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the melee damage increases by 1d10 for every two slot levels above 4th, or you add one additional ranged bolt for every two slot levels above 4th.","damage":"5d10 necrotic"},{"id":"deepm_stanch","name":"Stanch","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"1 hour","classes":[],"desc":"The target's blood coagulates rapidly, so that a dying target stabilizes and any ongoing bleeding or wounding effect on the target ends. The target can't be the source of blood for any spell or effect that requires even a drop of blood.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_starburst","name":"Starburst","level":0,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You cause a mote of starlight to appear and explode in a 5-foot cube you can see within range. If a creature is in the cube, it must succeed on a Charisma saving throw or take 1d8 radiant damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"This spell's damage increases to 2d8 when you reach 5th level, 3d8 when you reach 11th level, and 4d8 when you reach 17th level.","save":"cha"},{"id":"deepm_starfall","name":"Starfall","level":5,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You cause bolts of shimmering starlight to fall from the heavens, striking up to five creatures that you can see within range. Each bolt strikes one target, dealing 6d6 radiant damage, knocking the target prone, and blinding it until the start of your next turn. A creature that makes a successful Dexterity saving throw takes half the damage, is not knocked prone, and is not blinded. If you name fewer than five targets, excess bolts strike the ground harmlessly.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, you can create one additional bolt for each slot level above 5th.","save":"dex"},{"id":"deepm_starry-vision","name":"Starry Vision","level":7,"school":"Divination","time":"Reaction","range":"100 feet","components":"V, M (a sprinkle of gold dust worth 400 gp)","duration":"1 minute","classes":[],"desc":"This spell acts as [compelling fate](https://api.open5e.com/spells/compelling-fate), except as noted above (**starry** vision can be cast as a reaction, has twice the range of [compelling fate](https://api.open5e.com/spells/compelling-fate), and lasts up to 1 minute). At the end of each of its turns, the target repeats the Charisma saving throw, ending the effect on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, the bonus to AC increases by 1 for each slot level above 7th.","save":"cha"},{"id":"deepm_stars-heart","name":"Star's Heart","level":9,"school":"Transmutation","time":"Action","range":"50 feet","components":"V, S, M (an ioun stone)","duration":"1 minute","classes":[],"desc":"This spell increases gravity tenfold in a 50-foot radius centered on you. Each creature in the area other than you drops whatever it's holding, falls prone, becomes incapacitated, and can't move. If a solid object (such as the ground) is encountered when a flying or levitating creature falls, the creature takes three times the normal falling damage. Any creature except you that enters the area or starts its turn there must make a successful Strength saving throw or fall prone and become incapacitated and unable to move. A creature that starts its turn prone and incapacitated makes a Strength saving throw. On a failed save, the creature takes 8d6 bludgeoning damage; on a successful save, it takes 4d6 bludgeoning damage, it's no longer incapacitated, and it can move at half speed.\n\nAll ranged weapon attacks inside the area have a normal range of 5 feet and a maximum range of 10 feet. The same applies to spells that create missiles that have mass, such as [flaming sphere](https://api.open5e.com/spells/flaming-sphere). A creature under the influence of a [freedom of movement](https://api.open5e.com/spells/freedom-of-movement) spell or comparable magic has advantage on the Strength saving throws required by this spell, and its speed isn't reduced once it recovers from being incapacitated.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"8d6 bludgeoning","save":"str"},{"id":"deepm_steal-warmth","name":"Steal Warmth","level":3,"school":"Necromancy","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"When you cast **steal warmth** after taking cold damage, you select a living creature within 5 feet of you. That creature takes the cold damage instead, or half the damage with a successful Constitution saving throw. You regain hit points equal to the amount of cold damage taken by the target.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the distance to the target you can affect with this spell increases by 5 feet for each slot level above 3rd.","save":"con"},{"id":"deepm_steam-blast","name":"Steam Blast","level":4,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a tiny copper kettle or boiler)","duration":"Instantaneous","classes":[],"desc":"You unleash a burst of superheated steam in a 15-foot radius around you. All other creatures in the area take 5d8 fire damage, or half as much damage on a successful Dexterity saving throw. Nonmagical fires smaller than a bonfire are extinguished, and everything becomes wet.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th.","save":"dex"},{"id":"deepm_steam-whistle","name":"Steam Whistle","level":8,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a small brass whistle)","duration":"Instantaneous","classes":[],"desc":"You open your mouth and unleash a shattering scream. All other creatures in a 30-foot radius around you take 10d10 thunder damage and are deafened for 1d8 hours. A successful Constitution saving throw halves the damage and reduces the deafness to 1 round.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_stench-of-rot","name":"Stench of Rot","level":2,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (a live maggot)","duration":"1 hour","classes":[],"desc":"Choose one creature you can see within range that isn't a construct or an undead. The target must succeed on a Charisma saving throw or become cursed for the duration of the spell. While cursed, the target reeks of death and rot, and nothing short of magic can mask or remove the smell. The target has disadvantage on all Charisma checks and on Constitution saving throws to maintain concentration on spells. A creature with the Keen Smell trait, or a similar trait indicating the creature has a strong sense of smell, can add your spellcasting ability modifier to its Wisdom (Perception) or Wisdom (Survival) checks to find the target. A [remove curse](https://api.open5e.com/spells/remove-curse) spell or similar magic ends the spell early.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the duration increases by 1 hour for each slot level above 2nd.","save":"cha"},{"id":"deepm_storm-of-wings","name":"Storm of Wings","level":4,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M (a drop of honey)","duration":"1 minute","classes":[],"desc":"You create a storm of spectral birds, bats, or flying insects in a 15-foot-radius sphere on a point you can see within range. The storm spreads around corners, and its area is lightly obscured. Each creature in the storm when it appears and each a creature that starts its turn in the storm is affected by the storm.\n  As a bonus action on your turn, you can move the storm up to 30 feet. As an action on your turn, you can change the storm from one type to another, such as from a storm of bats to a storm of insects.\n  **Bats.** The creature takes 4d6 necrotic damage, and its speed is halved while within the storm as the bats cling to it and drain its blood.\n  **Birds.** The creature takes 4d6 slashing damage, and has disadvantage on attack rolls while within the storm as the birds fly in the way of the creature's attacks.\n  **Insects.** The creature takes 4d6 poison damage, and it must make a Constitution saving throw each time it casts a spell while within the storm. On a failed save, the creature fails to cast the spell, losing the action but not the spell slot.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"4d6 necrotic","save":"con"},{"id":"deepm_sudden-dawn","name":"Sudden Dawn","level":3,"school":"Evocation","time":"Action","range":"100 feet","components":"V, S","duration":"10 minutes","classes":[],"desc":"You call upon morning to arrive ahead of schedule. With a sharp word, you create a 30-foot-radius cylinder of light centered on a point on the ground within range. The cylinder extends vertically for 100 feet or until it reaches an obstruction, such as a ceiling. The area inside the cylinder is brightly lit.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_summon-eldritch-servitor","name":"Summon Eldritch Servitor","level":5,"school":"Conjuration","time":"1 minute","range":"60 feet","components":"V, S, M (a vial of the caster’s blood and a silver dagger)","duration":"1 hour","classes":[],"desc":"You summon eldritch aberrations that appear in unoccupied spaces you can see within range. Choose one of the following options for what appears:\n- Two [ghasts of Leng](https://api.open5e.com/monsters/ghast-of-leng)\n- One [shantak](https://api.open5e.com/monsters/shantak)\n\nWhen the summoned creatures appear, you must make a Charisma saving throw. On a success, the creatures are friendly to you and your allies. On a failure, the creatures are friendly to no one and attack the nearest creatures, pursuing and fighting for as long as possible.\n\nRoll initiative for the summoned creatures, which take their own turns as a group. If friendly to you, they obey your verbal commands (no action required by you to issue a command), or they attack the nearest living creature if they are not commanded otherwise.\n\nEach round when you maintain concentration on the spell, you must make a successful DC 15 Wisdom saving throw at the end of your turn or take 1d4 psychic damage. If the total of this damage exceeds your Wisdom score, you gain 1 point of Void taint and you are afflicted with a form of short-term madness. The same penalty applies when the damage exceeds twice your Wisdom score, three times your Wisdom score, and so forth, if you maintain concentration for that long.\n\nA summoned creature disappears when it drops to 0 hit points or when the spell ends. If you stop concentrating on the spell before 1 hour has elapsed, the creatures become uncontrolled and hostile until they disappear 1d6 rounds later or until they are killed.","concentration":true,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a 7th- or 8th-level spell slot, you can summon four [ghasts of Leng](https://api.open5e.com/monsters/ghast-of-leng) or a [hound of Tindalos](https://api.open5e.com/monsters/hound-of-tindalos). When you cast it with a 9th-level spell slot, you can summon five [ghasts of Leng](https://api.open5e.com/monsters/ghast-of-leng) or a [nightgaunt](https://api.open5e.com/monsters/nightgaunt).","save":"cha"},{"id":"deepm_summon-star","name":"Summon Star","level":8,"school":"Conjuration","time":"Action","range":"90 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You summon a friendly star from the heavens to do your bidding. It appears in an unoccupied space you can see within range and takes the form of a glowing humanoid with long white hair. All creatures other than you who view the star must make a successful Wisdom saving throw or be charmed for the duration of the spell. A creature charmed in this way can repeat the Wisdom saving throw at the end of each of its turns. On a success, the creature is no longer charmed and is immune to the effect of this casting of the spell. In all other ways, the star is equivalent to a [deva](https://api.open5e.com/monsters/deva). It understands and obeys verbal commands you give it. If you do not give the star a command, it defends itself and attacks the last creature that attacked it. The star disappears when it drops to 0 hit points or when the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_surge-dampener","name":"Surge Dampener","level":3,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S","duration":"1 minute, until expended","classes":[],"desc":"Using your strength of will, you cause one creature other than yourself that you touch to become so firmly entrenched within reality that it is protected from the effects of a chaos magic surge. The protected creature can make a DC 13 Charisma saving throw to negate the effect of a chaos magic surge that does not normally allow a saving throw, or it gains advantage on a saving throw that is normally allowed. Once the protected creature makes a successful saving throw allowed by **surge dampener**, the spell ends.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_surprise-blessing","name":"Surprise Blessing","level":5,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S","duration":"10 minutes","classes":[],"desc":"You touch a willing creature and choose one of the conditions listed below that the creature is currently subjected to. The condition's normal effect on the target is suspended, and the indicated effect applies instead. This spell's effect on the target lasts for the duration of the original condition or until the spell ends. If this spell ends before the original condition's duration expires, you become affected by the condition for as long as it lasts, even if you were not the original recipient of the condition.\n\n**Blinded:** The target gains truesight out to a range of 10 feet and can see 10 feet into the Ethereal Plane.\n\n**Charmed:** The target's Charisma score becomes 19, unless it is already higher than 19, and it gains immunity to charm effects.\n\n**Frightened:** The target emits a 10-foot-radius aura of dread. Each creature the target designates that starts its turn in the aura must make a successful Wisdom saving throw or be frightened of the target. A creature frightened in this way that starts its turn outside the aura repeats the saving throw, ending the condition on itself on a success.\n\n**Paralyzed:** The target can use one extra bonus action or reaction per round.\n\n**Petrified:** The target gains a +2 bonus to AC.\n\n**Poisoned:** The target heals 2d6 hit points at the start of its next turn, and it gains immunity to poison damage and the poisoned condition.\n\n**Stunned:** The target has advantage on Intelligence, Wisdom, and Charisma saving throws.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"cha"},{"id":"deepm_symbol-of-sorcery","name":"Symbol of Sorcery","level":7,"school":"Evocation","time":"10 minutes","range":"Touch","components":"V, S, M (a stick of incense worth 20 gp)","duration":"8 hours","classes":[],"desc":"You draw an arcane symbol on an object, wall, or other surface at least 5 feet wide. When a creature other than you approaches within 5 feet of the symbol, that act triggers an arcane explosion. Each creature in a 60-foot cone must make a successful Wisdom saving throw or be stunned. A stunned creature repeats the saving throw at the end of each of its turns, ending the effect on itself on a successful save. After this symbol explodes or when the duration expires, its power is spent and the spell ends.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_talons-of-a-hungry-land","name":"Talons of a Hungry Land","level":7,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S","duration":"10 minutes","classes":[],"desc":"You cause three parallel lines of thick, flared obsidian spikes to erupt from the ground. They appear within range on a solid surface, last for the duration, and provide three‐quarters cover to creatures behind them. You can make lines (up to 60 feet long, 10 feet high, and 5 feet thick) or form a circle (20 feet in diameter, up to 15 feet high and 5 feet thick).\n\nWhen the lines appear, each creature in their area must make a Dexterity saving throw. Creatures takes 8d8 slashing damage, or half as much damage on a successful save.\n\nA creature can move through the lines at the risk of cutting itself on the exposed edges. For every 1 foot a creature moves through the lines, it must spend 4 feet of movement. Furthermore, the first time a creature enters the lines on a turn or ends its turn there, the creature must make a Dexterity saving throw. It takes 8d8 slashing damage on a failure, or half as much damage on a success.\n\nWhen you stop concentrating on the spell, you can cause the obsidian spikes to explode, dealing 5d8 slashing damage to any creature within 15 feet, or half as much damage on a successful Dexterity save.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, the damage from all effects of the lines increases by 1d8 for each slot level above 7th.","damage":"8d8 slashing","save":"dex"},{"id":"deepm_targeting-foreknowledge","name":"Targeting Foreknowledge","level":3,"school":"Divination","time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","classes":[],"desc":"Twisting the knife, slapping with the butt of the spear, slashing out again as you recover from a lunge, and countless other double-strike maneuvers are skillful ways to get more from your weapon. By casting this spell as a bonus action after making a successful melee weapon attack, you deal an extra 2d6 damage of the weapon's type to the target. In addition, if your weapon attack roll was a 19 or higher, it is a critical hit and increases the weapon's damage dice as normal. The extra damage from this spell is not increased on a critical hit.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_thin-the-ice","name":"Thin the Ice","level":1,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (a piece of sunstone)","duration":"Instantaneous","classes":[],"desc":"You target a point within range. That point becomes the top center of a cylinder 10 feet in radius and 40 feet deep. All ice inside that area melts immediately. The uppermost layer of ice seems to remain intact and sturdy, but it covers a 40-foot-deep pit filled with ice water. A successful Wisdom (Survival) check or passive Perception check against your spell save DC notices the thin ice. If a creature weighing more than 20 pounds (or a greater weight specified by you when casting the spell) treads over the cylinder or is already standing on it, the ice gives way. Unless the creature makes a successful Dexterity saving throw, it falls into the icy water, taking 2d6 cold damage plus whatever other problems are caused by water, by armor, or by being drenched in a freezing environment. The water gradually refreezes normally.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_thousand-darts","name":"Thousand Darts","level":3,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a set of mithral darts worth 25 gp)","duration":"Instantaneous","classes":[],"desc":"You launch thousands of needlelike darts in a 5-foot‐wide line that is 120 feet long. Each creature in the line takes 6d6 piercing damage, or half as much damage if it makes a successful Dexterity saving throw. The first creature struck by the darts makes the saving throw with disadvantage.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","damage":"6d6 piercing","save":"dex"},{"id":"deepm_throes-of-ecstasy","name":"Throes of Ecstasy","level":3,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M (a hazel or oak wand)","duration":"1 minute","classes":[],"desc":"Choose a humanoid that you can see within range. The target must succeed on a Constitution saving throw or become overcome with euphoria, rendering it incapacitated for the duration. The target automatically fails Wisdom saving throws, and attack rolls against the target have advantage. At the end of each of its turns, the target can make another Constitution saving throw. On a successful save, the spell ends on the target and it gains one level of exhaustion. If the spell continues for its maximum duration, the target gains three levels of exhaustion when the spell ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional humanoid for each slot level above 3rd. The humanoids must be within 30 feet of each other when you target them.","save":"con"},{"id":"deepm_thunder-bolt","name":"Thunder Bolt","level":0,"school":"Evocation","time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You cast a knot of thunder at one enemy. Make a ranged spell attack against the target. If it hits, the target takes 1d8 thunder damage and can't use reactions until the start of your next turn.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"1d8 thunder","attack":true},{"id":"deepm_thunderclap","name":"Thunderclap","level":3,"school":"Evocation","time":"Action","range":"Self","components":"S","duration":"Instantaneous","classes":[],"desc":"You clap your hands, emitting a peal of thunder. Each creature within 20 feet of you takes 8d4 thunder damage and is deafened for 1d8 rounds, or it takes half as much damage and isn't deafened if it makes a successful Constitution saving throw. On a saving throw that fails by 5 or more, the creature is also stunned for 1 round.\n\nThis spell doesn't function in an area affected by a [silence](https://api.open5e.com/spells/silence) spell. Very brittle material such as crystal might be shattered if it's within range, at the GM's discretion; a character holding such an object can protect it from harm by making a successful Dexterity saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"8d4 thunder","save":"con"},{"id":"deepm_thunderous-charge","name":"Thunderous Charge","level":1,"school":"Transmutation","time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","classes":[],"desc":"With a thunderous battle cry, you move up to 10 feet in a straight line and make a melee weapon attack. If it hits, you can choose to either gain a +5 bonus on the attack's damage or shove the target 10 feet.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the distance you can move increases by 10 feet, and the attack deals an additional 1d6 thunder damage, for each slot level above 1st."},{"id":"deepm_thunderous-stampede","name":"Thunderous Stampede","level":2,"school":"Transmutation","time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","classes":[],"desc":"This spell acts as [thunderous charge](https://api.open5e.com/spells/thunderous-charge), but affecting up to three targets within range, including yourself. A target other than you must use its reaction to move and attack under the effect of thunderous stampede.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the distance your targets can move increases by 10 feet, and the attack deals an additional 1d6 thunder damage, for each slot level above 2nd."},{"id":"deepm_thunderous-wave","name":"Thunderous Wave","level":3,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You initiate a shock wave centered at a point you designate within range. The wave explodes outward into a 30-foot-radius sphere. This force deals no damage directly, but every creature the wave passes through must make a Strength saving throw. On a failed save, a creature is pushed 30 feet and knocked prone; if it strikes a solid obstruction, it also takes 5d6 bludgeoning damage. On a successful save, a creature is pushed 15 feet and not knocked prone, and it takes 2d6 bludgeoning damage if it strikes an obstruction. The spell also emits a thunderous boom that can be heard within 400 feet.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"5d6 bludgeoning","save":"str"},{"id":"deepm_thunderstorm","name":"Thunderstorm","level":5,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M (a piece of lightning-fused glass)","duration":"1 hour","classes":[],"desc":"You touch a willing creature, and it becomes surrounded by a roiling storm cloud 30 feet in diameter, erupting with (harmless) thunder and lightning. The creature gains a flying speed of 60 feet. The cloud heavily obscures the creature inside it from view, though it is transparent to the creature itself.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_tidal-barrier","name":"Tidal Barrier","level":1,"school":"Abjuration","time":"Action","range":"Self","components":"V, S, M (a piece of driftwood)","duration":"1 minute","classes":[],"desc":"A swirling wave of seawater surrounds you, crashing and rolling in a 10-foot radius around your space. The area is difficult terrain, and a creature that starts its turn there or that enters it for the first time on a turn must make a Strength saving throw. On a failed save, the creature is pushed 10 feet away from you and its speed is reduced to 0 until the start of its next turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_time-in-a-bottle","name":"Time in a Bottle","level":9,"school":"Transmutation","time":"Action","range":"Sight","components":"V","duration":"1 minute","classes":[],"desc":"You designate a spot within your sight. Time comes under your control in a 20-foot radius centered on that spot. You can freeze it, reverse it, or move it forward by as much as 1 minute as long as you maintain concentration. Nothing and no one, yourself included, can enter the field or affect what happens inside it. You can choose to end the effect at any moment as an action on your turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_time-jump","name":"Time Jump","level":8,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You touch a construct and throw it forward in time if it fails a Constitution saving throw. The construct disappears for 1d4 + 1 rounds, during which time it cannot act or be acted upon in any way. When the construct returns, it is unaware that any time has passed.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_time-loop","name":"Time Loop","level":6,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M (a metal loop)","duration":"1 minute","classes":[],"desc":"You capture a creature within range in a loop of time. The target is teleported to the space where it began its most recent turn. The target then makes a Wisdom saving throw. On a successful save, the spell ends. On a failed save, the creature must repeat the activities it undertook on its previous turn, following the sequence of moves and actions to the best of its ability. It doesn't need to move along the same path or attack the same target, but if it moved and then attacked on its previous turn, its only option is to move and then attack on this turn. If the space where the target began its previous turn is occupied or if it's impossible for the target to take the same action (if it cast a spell but is now unable to do so, for example), the target becomes incapacitated.\n\nAn affected target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. For as long as the spell lasts, the target teleports back to its starting point at the start of each of its turns, and it must repeat the same sequence of moves and actions.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_time-slippage","name":"Time Slippage","level":8,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S, M (the heart of a chaotic creature of challenge rating 5 or higher, worth 500 gp)","duration":"1 minute","classes":[],"desc":"You ensnare a creature within range in an insidious trap, causing different parts of its body to function at different speeds. The creature must make an Intelligence saving throw. On a failed save, it is stunned until the end of its next turn. On a success, the creature's speed is halved and it has disadvantage on attack rolls and saving throws until the end of its next turn. The creature repeats the saving throw at the end of each of its turns, with the same effects for success and failure. In addition, the creature has disadvantage on Strength or Dexterity saving throws but advantage on Constitution or Charisma saving throws for the spell's duration (a side effect of the chronal anomaly suffusing its body). The spell ends if the creature makes three successful saves in a row.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"int"},{"id":"deepm_time-step","name":"Time Step","level":2,"school":"Conjuration","time":"Action","range":"Self","components":"V","duration":"Instantaneous","classes":[],"desc":"You briefly step forward in time. You disappear from your location and reappear at the start of your next turn in a location of your choice that you can see within 30 feet of the space you disappeared from. You can't be affected by anything that happens during the time you're missing, and you aren't aware of anything that happens during that time.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_time-vortex","name":"Time Vortex","level":4,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"This spell destabilizes the flow of time, enabling you to create a vortex of temporal fluctuations that are visible as a spherical distortion with a 10-foot radius, centered on a point within range. Each creature in the area when you cast the spell must succeed on a Wisdom saving throw or be affected by the time vortex. While the spell lasts, a creature that enters the sphere or starts its turn inside the sphere must also succeed on a Wisdom saving throw or be affected. On a successful save, it becomes immune to this casting of the spell.\n\nAn affected creature can't take reactions and rolls a d10 at the start of its turn to determine its behavior for that turn.\n\nD10 | EFFECT\n1–2 | The creature is affected as if by a slow spell until the start of its next turn.\n3–5 | The creature is stunned until the start of its next turn.\n6–8 | The creature's current initiative result is reduced by 5. The creature begins using this new initiative result in the next round. Multiple occurrences of this effect for the same creature are cumulative.\n9–10 | The creature's speed is halved (round up to the nearest 5-foot increment) until the start of its next turn.\nYou can move the temporal vortex 10 feet each round as a bonus action. An affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, the radius of the sphere increases by 5 feet for each slot level above 4th.","save":"wis"},{"id":"deepm_timely-distraction","name":"Timely Distraction","level":2,"school":"Evocation","time":"Action","range":"25 feet","components":"V, S, M (a handful of sand or dirt thrown in the air)","duration":"3 rounds","classes":[],"desc":"You call forth a swirling, crackling wave of constantly shifting pops, flashes, and swept-up debris. This chaos can confound one creature. If the target gets a failure on a Wisdom saving throw, roll a d4 and consult the following table to determine the result. An affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. Otherwise, the spell ends when its duration expires.\n\nD4 | Effect\n1 | Blinded\n2 | Stunned\n3 | Deafened\n4 | Prone","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_tireless","name":"Tireless","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"S, M (an ever-wound spring worth 50 gp)","duration":"24 hours","classes":[],"desc":"You grant machinelike stamina to a creature you touch for the duration of the spell. The target requires no food or drink or rest. It can move at three times its normal speed overland and perform three times the usual amount of labor. The target is not protected from fatigue or exhaustion caused by a magical effect.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_tongue-of-sand","name":"Tongue of Sand","level":3,"school":"Illusion","time":"1 minute","range":"30 feet","components":"V, S","duration":"Until dispelled","classes":[],"desc":"**Tongue of sand** is similar in many ways to [magic mouth](https://api.open5e.com/spells/magic-mouth). When you cast it, you implant a message in a quantity of sand. The sand must fill a space no smaller than 4 square feet and at least 2 inches deep. The message can be up to 25 words. You also decide the conditions that trigger the speaking of the message. When the message is triggered, a mouth forms in the sand and delivers the message in a raspy, whispered voice that can be heard by creatures within 10 feet of the sand.\n\nAdditionally, **tongue of sand** has the ability to interact in a simple, brief manner with creatures who hear its message. For up to 10 minutes after the message is triggered, questions addressed to the sand will be answered as you would answer them. Each answer can be no more than ten words long, and the spell ends after a second question is answered.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_tongue-tied","name":"Tongue Tied","level":5,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You make a choking motion while pointing at a target, which must make a successful Wisdom saving throw or become unable to communicate verbally. The target's speech becomes garbled, and it has disadvantage on Charisma checks that require speech. The creature can cast a spell that has a verbal component only by making a successful Constitution check against your spell save DC. On a failed check, the creature's action is used but the spell slot isn't expended.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_torrent-of-fire","name":"Torrent of Fire","level":4,"school":"Conjuration","time":"Round","range":"Self","components":"V, S, M (a piece of obsidian)","duration":"Instantaneous","classes":[],"desc":"You harness the power of fire contained in ley lines with this spell. You create a 60-foot cone of flame. Creatures in the cone take 6d6 fire damage, or half as much damage with a successful Dexterity saving throw. You can then flow along the flames, reappearing anywhere inside the cone's area. This repositioning doesn't count as movement and doesn't trigger opportunity attacks.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"dex"},{"id":"deepm_touch-of-the-unliving","name":"Touch of the Unliving","level":3,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":[],"desc":"Make a melee spell attack against a creature you can reach. On a hit, the target takes 2d6 necrotic damage and, if it is not an undead creature, it is paralyzed until the end of its next turn. Until the spell ends, you can make the attack again on each of your turns as an action.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd.","damage":"2d6 necrotic"},{"id":"deepm_tracer","name":"Tracer","level":3,"school":"Divination","time":"Bonus Action","range":"Self","components":"V, S, M (a drop of bright paint)","duration":"8 hours","classes":[],"desc":"When you cast this spell and as a bonus action on each of your turns until the spell ends, you can imbue a piece of ammunition you fire from a ranged weapon with a tiny, invisible beacon. If a ranged attack roll with an imbued piece of ammunition hits a target, the beacon is transferred to the target. The weapon that fired the ammunition is attuned to the beacon and becomes warm to the touch when it points in the direction of the target as long as the target is on the same plane of existence as you. You can have only one tracer target at a time. If you put a tracer on a different target, the effect on the previous target ends.\n  A creature must succeed on an Intelligence (Arcana) check against your spell save DC to notice the magical beacon.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_treasure-chasm","name":"Treasure Chasm","level":2,"school":"Enchantment","time":"Action","range":"100 feet","components":"V, S, M (a gold coin)","duration":"1 minute","classes":[],"desc":"You cause the glint of a golden coin to haze over the vision of one creature in range. The target creature must make a Wisdom saving throw. If it fails, it sees a gorge, trench, or other hole in the ground, at a spot within range chosen by you, which is filled with gold and treasure. On its next turn, the creature must move toward that spot. When it reaches the spot, it becomes incapacitated, as it devotes all its attention to scooping imaginary treasure into its pockets or a pouch.\n\nAn affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. The effect also ends if the creature takes damage from you or one of your allies.\n\nCreatures with the dragon type have disadvantage on the initial saving throw but have advantage on saving throws against this spell made after reaching the designated spot.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_tree-heal","name":"Tree Heal","level":0,"school":"Evocation","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You touch a plant and it regains 1d4 hit points. Alternatively, you can cure it of one disease or remove pests from it. Once you cast this spell on a plant or plant creature, you can't cast it on that target again for 24 hours. This spell can be used only on plants and plant creatures.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_tree-running","name":"Tree Running","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"S, M (a maple catkin)","duration":"1 hour","classes":[],"desc":"One willing creature you touch gains a climbing speed equal to its walking speed. This climbing speed functions only while the creature is in contact with a living plant or fungus that's growing from the ground. The creature can cling to an appropriate surface with just one hand or with just its feet, leaving its hands free to wield weapons or cast spells. The plant doesn't give under the creature's weight, so the creature can walk on the tiniest of tree branches, stand on a leaf, or run across the waving top of a field of wheat without bending a stalk or touching the ground.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_tree-speak","name":"Tree Speak","level":1,"school":"Divination","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":[],"desc":"You touch a tree and ask one question about anything that might have happened in its immediate vicinity (such as “Who passed by here?”). You get a mental sensation of the response, which lasts for the duration of the spell. Trees do not have a humanoid's sense of time, so the tree might speak about something that happened last night or a hundred years ago. The sensation you receive might include sight, hearing, vibration, or smell, all from the tree's perspective. Trees are particularly attentive to anything that might harm the forest and always report such activities when questioned.\n\nIf you cast this spell on a tree that contains a creature that can merge with trees, such as a dryad, you can freely communicate with the merged creature for the duration of the spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_trench","name":"Trench","level":2,"school":"Transmutation","time":"1 minute","range":"60 feet","components":"V, S","duration":"Permanent","classes":[],"desc":"By making a scooping gesture, you cause the ground to slowly sink in an area 5 feet wide and 60 feet long, originating from a point within range. When the casting is finished, a 5-foot-deep trench is the result.\n\nThe spell works only on flat, open ground (not on stone or paved surfaces) that is not occupied by creatures or objects.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can increase the width of the trench by 5 feet or the length by 30 feet for each slot level above 2nd. You can make a different choice (width or length) for each slot level above 2nd."},{"id":"deepm_trick-question","name":"Trick Question","level":1,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You pose a question that can be answered by one word, directed at a creature that can hear you. The target must make a successful Wisdom saving throw or be compelled to answer your question truthfully. When the answer is given, the target knows that you used magic to compel it.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_triumph-of-ice","name":"Triumph of Ice","level":7,"school":"Transmutation","time":"Action","range":"100 feet","components":"V, S, M (a stone extracted from glacial ice)","duration":"1 minute","classes":[],"desc":"You transform one of the four elements—air, earth, fire, or water—into ice or snow. The affected area is a sphere with a radius of 100 feet, centered on you. The specific effect depends on the element you choose.\n- **Air.** Vapor condenses into snowfall. If the effect of a [fog cloud](https://api.open5e.com/spells/fog-cloud) spell, a [stinking cloud](https://api.open5e.com/spells/stinking-cloud), or similar magic is in the area, this spell negates it. A creature of elemental air within range takes 8d6 cold damage—and, if airborne, it must make a successful Constitution saving throw at the start of its turn to avoid being knocked prone (no falling damage).\n- **Earth.** Soil freezes into permafrost to a depth of 10 feet. A creature burrowing through the area has its speed halved until the area thaws, unless it can burrow through solid rock. A creature of elemental earth within range must make a successful Constitution saving throw or take 8d6 cold damage.\n- **Fire.** Flames or other sources of extreme heat (such as molten lava) on the ground within range transform into shards of ice, and the area they occupy becomes difficult terrain. Each creature in the previously burning area takes 2d6 slashing damage when the spell is cast and 1d6 slashing damage for every 5 feet it moves in the area (unless it is not hindered by icy terrain) until the spell ends; a successful Dexterity saving throw reduces the slashing damage by half. A creature of elemental fire within range must make a successful Constitution saving throw or take 8d6 cold damage and be stunned for 1d6 rounds.\n- **Water.** Open water (a pond, lake, or river) freezes to a depth of 4 feet. A creature on the surface of the water when it freezes must make a successful Dexterity saving throw to avoid being trapped in the ice. A trapped creature can free itself by using an action to make a successful Strength (Athletics) check. A creature of elemental water within range takes no damage from the spell but is paralyzed for 1d6 rounds unless it makes a successful Constitution saving throw, and it treats the affected area as difficult terrain.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"8d6 cold","save":"con"},{"id":"deepm_twist-the-skein","name":"Twist the Skein","level":1,"school":"Enchantment","time":"Reaction","range":"30 feet","components":"S","duration":"Instantaneous","classes":[],"desc":"You tweak a strand of a creature's fate as it attempts an attack roll, saving throw, or skill check. Roll a d20 and subtract 10 to produce a number from 10 to –9. Add that number to the creature's roll. This adjustment can turn a failure into a success or vice versa, or it might not change the outcome at all.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_umbral-storm","name":"Umbral Storm","level":9,"school":"Necromancy","time":"Action","range":"120 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You create a channel to a region of the Plane of Shadow that is inimical to life and order. A storm of dark, raging entropy fills a 20-foot-radius sphere centered on a point you can see within range. Any creature that starts its turn in the storm or enters it for the first time on its turn takes 6d8 necrotic damage and gains one level of exhaustion; a successful Constitution saving throw halves the damage and prevents the exhaustion.\n\nYou can use a bonus action on your turn to move the area of the storm 30 feet in any direction.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"6d8 necrotic","save":"con"},{"id":"deepm_uncontrollable-transformation","name":"Uncontrollable Transformation","level":7,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (the bill of a platypus)","duration":"1 hour","classes":[],"desc":"You infuse your body with raw chaos and will it to adopt a helpful mutation. Roll a d10 and consult the Uncontrollable Transformation table below to determine what mutation occurs. You can try to control the shifting of your body to gain a mutation you prefer, but doing so is taxing; you can roll a d10 twice and choose the result you prefer, but you gain one level of exhaustion. At the end of the spell, your body returns to its normal form.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 8th level or higher, you gain an additional mutation for each slot level above 7th. You gain one level of exhaustion for each mutation you try to control.\n ## Uncontrollable Transformation \nD10 | Mutation\n1 | A spindly third arm sprouts from your shoulder. As a bonus action, you can use it to attack with a light weapon. You have advantage on Dexterity (Sleight of Hand) checks and any checks that require the manipulation of tools.\n2 | Your skin is covered by rough scales that increase your AC by 1 and give you resistance to a random damage type (roll on the Damage Type table).\n3 | A puckered orifice grows on your back. You can forcefully expel air from it, granting you a flying speed of 30 feet. You must land at the end of your turn. In addition, as a bonus action, you can try to push a creature away with a blast of air. The target is pushed 5 feet away from you if it fails a Strength saving throw with a DC equal to 10 + your Constitution modifier.\n4 | A second face appears on the back of your head. You gain darkvision out to a range of 120 feet and advantage on sight‐based and scent-based Wisdom (Perception) checks. You become adept at carrying on conversations with yourself.\n5 | You grow gills that not only allow you to breathe underwater but also filter poison out of the air. You gain immunity to inhaled poisons.\n6 | Your hindquarters elongate, and you grow a second set of legs. Your base walking speed increases by 10 feet, and your carrying capacity becomes your Strength score multiplied by 20.\n7 | You become incorporeal and can move through other creatures and objects as if they were difficult terrain. You take 1d10 force damage if you end your turn inside an object. You can't pick up or interact with physical objects that you weren't carrying when you became incorporeal.\n8 | Your limbs elongate and flatten into prehensile paddles. You gain a swimming speed equal to your base walking speed and have advantage on Strength (Athletics) checks made to climb or swim. In addition, your unarmed strikes deal 1d6 bludgeoning damage.\n9 | Your head fills with a light gas and swells to four times its normal size, causing your hair to fall out. You have advantage on Intelligence and Wisdom ability checks and can levitate up to 5 feet above the ground.\n10 | You grow three sets of feathered wings that give you a flying speed equal to your walking speed and the ability to hover.\n ## Damage Type \n\nd10 | Damage Type\n1 | Acid\n2 | Cold\n3 | Fire\n4 | Force\n5 | Lightning\n6 | Necrotic\n7 | Poison\n8 | Psychic\n9 | Radiant\n10 | Thunder"},{"id":"deepm_undermine-armor","name":"Undermine Armor","level":1,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You unravel the bonds of reality that hold a suit of armor together. A target wearing armor must succeed on a Constitution saving throw or its armor softens to the consistency of candle wax, decreasing the target's AC by 2.\n\n**Undermine armor** has no effect on creatures that aren't wearing armor.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_unholy-defiance","name":"Unholy Defiance","level":2,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (a pinch of earth from a grave)","duration":"1 minute","classes":[],"desc":"Until the spell ends, undead creatures within range have advantage on saving throws against effects that turn undead. If an undead creature within this area has the Turning Defiance trait, that creature can roll a d4 when it makes a saving throw against an effect that turns undead and add the number rolled to the saving throw.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_unleash-effigy","name":"Unleash Effigy","level":9,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"10 minutes","classes":[],"desc":"You cause a stone statue that you can see within 60 feet of you to animate as your ally. The statue has the statistics of a [stone golem](https://api.open5e.com/monsters/stone-golem). It takes a turn immediately after your turn. As a bonus action on your turn, you can order the golem to move and attack, provided you're within 60 feet of it. Without orders from you, the statue does nothing.\n\nWhenever the statue has 75 hit points or fewer at the start of your turn or it is more than 60 feet from you at the start of your turn, you must make a successful DC 16 spellcasting check or the statue goes berserk. On each of its turns, the berserk statue attacks you or one of your allies. If no creature is near enough to be attacked, the statue dashes toward the nearest one instead. Once the statue goes berserk, it remains berserk until it's destroyed.\n\nWhen the spell ends, the animated statue reverts to a normal, mundane statue.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_unluck-on-that","name":"Unluck On That","level":1,"school":"Enchantment","time":"Reaction","range":"25 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"By uttering a swift curse (“Unluck on that!”), you bring misfortune to the target's attempt; the affected creature has disadvantage on the roll.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the range of the spell increases by 5 feet for each slot level above 1st."},{"id":"deepm_unseen-strangler","name":"Unseen Strangler","level":3,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S, M (a pinch of sulfur and a live rodent)","duration":"8 hours","classes":[],"desc":"You conjure an immaterial, tentacled aberration in an unoccupied space you can see within range, and you specify a password that the phantom recognizes. The entity remains where you conjured it until the spell ends, until you dismiss it as an action, or until you move more than 80 feet from it.\n\nThe strangler is invisible to all creatures except you, and it can't be harmed. When a Small or larger creature approaches within 30 feet of it without speaking the password that you specified, the strangler starts whispering your name. This whispering is always audible to you, regardless of other sounds in the area, as long as you're conscious. The strangler sees invisible creatures and can see into the Ethereal Plane. It ignores illusions.\n\nIf any creatures hostile to you are within 5 feet of the strangler at the start of your turn, the strangler attacks one of them with a tentacle. It makes a melee weapon attack with a bonus equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 3d6 bludgeoning damage, and a Large or smaller creature is grappled (escape DC = your spellcasting ability modifier + your proficiency bonus). Until this grapple ends, the target is restrained, and the strangler can't attack another target. If the strangler scores a critical hit, the target begins to suffocate and can't speak until the grapple ends.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_vine-trestle","name":"Vine Trestle","level":2,"school":"Conjuration","time":"10 minutes","range":"30 feet","components":"V, S, M (a 1-inch piece of green vine that is consumed in the casting)","duration":"1 hour","classes":[],"desc":"You cause a vine to sprout from the ground and crawl across a surface or rise into the air in a direction chosen by you. The vine must sprout from a solid surface (such as the ground or a wall), and it is strong enough to support 600 pounds of weight along its entire length. The vine collapses immediately if that 600-pound limit is exceeded. A vine that collapses from weight or damage instantly disintegrates.\n\nThe vine has many small shoots, so it can be climbed with a successful DC 5 Strength (Athletics) check. It has AC 8, hit points equal to 5 × your spellcasting level, and a damage threshold of 5.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the vine can support an additional 30 pounds, and its damage threshold increases by 1 for each slot level above 2nd.\n\n**Ritual Focus.** If you expend your ritual focus, the vine is permanent until destroyed or dispelled."},{"id":"deepm_visage-of-madness","name":"Visage of Madness","level":4,"school":"Enchantment","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"When you cast this spell, your face momentarily becomes that of a demon lord, frightful enough to drive enemies mad. Every foe that's within 30 feet of you and that can see you must make a Wisdom saving throw. On a failed save, a creature claws savagely at its eyes, dealing piercing damage to itself equal to 1d6 + the creature's Strength modifier. The creature is also stunned until the end of its next turn and blinded for 1d4 rounds. A creature that rolls maximum damage against itself (a 6 on the d6) is blinded permanently.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_vital-mark","name":"Vital Mark","level":3,"school":"Transmutation","time":"10 minutes","range":"Touch","components":"V, S","duration":"24 hours","classes":[],"desc":"You mark an unattended magic item (including weapons and armor) with a clearly visible stain of your blood. The exact appearance of the bloodstain is up to you. The item's magical abilities don't function for anyone else as long as the bloodstain remains on it. For example, a **+1 flaming longsword** with a vital mark functions as a nonmagical longsword in the hands of anyone but the caster, but it still functions as a **+1 flaming longsword** for the caster who placed the bloodstain on it. A [wand of magic missiles](https://api.open5e.com/spells/wand-of-magic-missiles) would be no more than a stick in the hands of anyone but the caster.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 4th level or higher on the same item for 28 consecutive days, the effect becomes permanent until dispelled."},{"id":"deepm_void-rift","name":"Void Rift","level":9,"school":"Evocation","time":"Action","range":"300 feet","components":"V, S, M (a black opal worth 500 gp, carved with a Void glyph)","duration":"1 minute","classes":[],"desc":"You speak a hideous string of Void Speech that leaves your mouth bloodied, causing a rift into nothingness to tear open. The rift takes the form of a 10-foot-radius sphere, and it forms around a point you can see within range. The area within 40 feet of the sphere's outer edge becomes difficult terrain as the Void tries to draw everything into itself. A creature that starts its turn within 40 feet of the sphere or that enters that area for the first time on its turn must succeed on a Strength saving throw or be pulled 15 feet toward the rift. A creature that starts its turn in the rift or that comes into contact with it for the first time on its turn takes 8d10 necrotic damage. Creatures inside the rift are blinded and deafened. Unattended objects within 40 feet of the rift are drawn 15 feet toward it at the start of your turn, and they take damage as creatures if they come into contact with it.\n\nWhile concentrating on the spell, you take 2d6 necrotic damage at the end of each of your turns.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"8d10 necrotic","save":"str"},{"id":"deepm_void-strike","name":"Void Strike","level":3,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"With a short phrase of Void Speech, you gather writhing darkness around your hand. When you cast the spell, and as an action on subsequent turns while you maintain concentration, you can unleash a bolt of darkness at a creature within range. Make a ranged spell attack. If the target is in dim light or darkness, you have advantage on the roll. On a hit, the target takes 5d8 necrotic damage and is frightened of you until the start of your next turn.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast the spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd.","damage":"5d8 necrotic","attack":true},{"id":"deepm_volley-shield","name":"Volley Shield","level":7,"school":"Abjuration","time":"Action","range":"Touch","components":"S","duration":"1 minute","classes":[],"desc":"You touch a willing creature and create a shimmering shield of energy to protect it. The shield grants the target a +5 bonus to AC and gives it resistance against nonmagical bludgeoning, piercing, and slashing damage for the duration of the spell.\n\nIn addition, the shield can reflect hostile spells back at their casters. When the target makes a successful saving throw against a hostile spell, the caster of the spell immediately becomes the spell's new target. The caster is entitled to the appropriate saving throw against the returned spell, if any, and is affected by the spell as if it came from a spellcaster of the caster's level.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_vomit-tentacles","name":"Vomit Tentacles","level":2,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a piece of a tentacle)","duration":"5 rounds","classes":[],"desc":"Your jaws distend and dozens of thin, slimy tentacles emerge from your mouth to grasp and bind your opponents. Make a melee spell attack against a foe within 15 feet of you. On a hit, the target takes bludgeoning damage equal to 2d6 + your Strength modifier and is grappled (escape DC equal to your spell save DC). Until this grapple ends, the target is restrained and it takes the same damage at the start of each of your turns. You can grapple only one creature at a time.\n\nThe Armor Class of the tentacles is equal to yours. If they take slashing damage equal to 5 + your Constitution modifier from a single attack, enough tentacles are severed to enable a grappled creature to escape. Severed tentacles are replaced by new ones at the start of your turn. Damage dealt to the tentacles doesn't affect your hit points.\n\nWhile the spell is in effect, you are incapable of speech and can't cast spells that have verbal components.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","attack":true},{"id":"deepm_voorish-sign","name":"Voorish Sign","level":1,"school":"Divination","time":"Action","range":"Self","components":"S","duration":"10 minutes","classes":[],"desc":"For the duration, invisible creatures and objects within 20 feet of you become visible to you, and you have advantage on saving throws against effects that cause the frightened condition. The effect moves with you, remaining centered on you until the duration expires.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the radius increases by 5 feet for every two slot levels above 1st."},{"id":"deepm_waft","name":"Waft","level":1,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a topaz worth at least 10 gp)","duration":"1 round","classes":[],"desc":"This spell was first invented by dragon parents to assist their offspring when learning to fly. You gain a flying speed of 60 feet for 1 round. At the start of your next turn, you float rapidly down and land gently on a solid surface beneath you.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_walk-the-twisted-path","name":"Walk the Twisted Path","level":6,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a map)","duration":"Special","classes":[],"desc":"When you cast this spell, you and up to five creatures you can see within 20 feet of you enter a shifting landscape of endless walls and corridors that connect to many places throughout the world.\n\nYou can find your way to a destination within 100 miles, as long as you know for certain that your destination exists (though you don't need to have seen or visited it before), and you must make a successful DC 20 Intelligence check. If you have the ability to retrace a path you have previously taken without making a check (as a minotaur or a goristro can), this check automatically succeeds. On a failed check, you don't find your path this round, and you and your companions each take 4d6 psychic damage as the madness of the shifting maze exacts its toll. You must repeat the check at the start of each of your turns until you find your way to your destination or until you die. In either event, the spell ends.\n\nWhen the spell ends, you and those traveling with you appear in a safe location at your destination.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, you can bring along two additional creatures or travel an additional 100 miles for each slot level above 6th."},{"id":"deepm_walking-wall","name":"Walking Wall","level":7,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M (100 miniature axes)","duration":"10 minutes","classes":[],"desc":"This spell creates a wall of swinging axes from the pile of miniature axes you provide when casting the spell. The wall fills a rectangle 10 feet wide, 10 feet high, and 20 feet long. The wall has a base speed of 50 feet, but it can't take the Dash action. It can make up to four attacks per round on your turn, using your spell attack modifier to hit and with a reach of 10 feet. You direct the wall's movement and attacks as a bonus action. If you choose not to direct it, the wall continues trying to execute the last command you gave it. The wall can't use reactions. Each successful attack deals 4d6 slashing damage, and the damage is considered magical.\n\nThe wall has AC 12 and 200 hit points, and is immune to necrotic, poison, psychic, and piercing damage. If it is reduced to 0 hit points or when the spell's duration ends, the wall disappears and the miniature axes fall to the ground in a tidy heap.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_wall-of-time","name":"Wall of Time","level":5,"school":"Abjuration","time":"Action","range":"120 feet","components":"V, S, M (an hourglass)","duration":"1 minute","classes":[],"desc":"You create a wall of shimmering, transparent blocks on a solid surface within range. You can make a straight wall up to 60 feet long, 20 feet high, and 1 foot thick, or a cylindrical wall up to 20 feet high, 1 foot thick, and 20 feet in diameter. Nonmagical ranged attacks that cross the wall vanish into the time stream with no other effect. Ranged spell attacks and ranged weapon attacks made with magic weapons that pass through the wall are made with disadvantage. A creature that intentionally enters or passes through the wall is affected as if it had just failed its initial saving throw against a [slow](https://api.open5e.com/spells/slow) spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_warning-shout","name":"Warning Shout","level":2,"school":"Divination","time":"Reaction","range":"30 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"You sense danger before it happens and call out a warning to an ally. One creature you can see and that can hear you gains advantage on its initiative roll.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_warp-mind-and-matter","name":"Warp Mind and Matter","level":6,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M (root of deadly nightshade and a drop of the caster’s blood)","duration":"Until cured or dispelled","classes":[],"desc":"A creature you can see within range undergoes a baleful transmogrification. The target must make a successful Wisdom saving throw or suffer a flesh warp and be afflicted with a form of indefinite madness.","concentration":false,"ritual":true,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepm_weapon-of-blood","name":"Weapon of Blood","level":1,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M (a pinch of iron shavings)","duration":"1 hour","classes":[],"desc":"When you cast this spell, you inflict 1d4 slashing damage on yourself that can't be healed until after the blade created by this spell is destroyed or the spell ends. The trickling blood transforms into a dagger of red metal that functions as a **+1 dagger**.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd to 5th level, the self-inflicted wound deals 3d4 slashing damage and the spell produces a **+2 dagger**. When you cast this spell using a spell slot of 6th to 8th level, the self-inflicted wound deals 6d4 slashing damage and the spell produces a **+2 dagger of wounding**. When you cast this spell using a 9th-level spell slot, the self-inflicted wound deals 9d4 slashing damage and the spell produces a **+3 dagger of wounding**."},{"id":"deepm_weilers-ward","name":"Weiler’s Ward","level":2,"school":"Conjuration","time":"Bonus Action","range":"Self","components":"V, S, M (a lock of hair from a fey creature)","duration":"1 hour","classes":[],"desc":"You create four small orbs of faerie magic that float around your head and give off dim light out to a radius of 15 feet. Whenever a Large or smaller enemy enters that area of dim light, or starts its turn in the area, you can use your reaction to attack it with one or more of the orbs. The enemy creature makes a Charisma saving throw. On a failed save, the creature is pushed 20 feet directly away from you, and each orb you used in the attack explodes violently, dealing 1d6 force damage to the creature.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the number of orbs increases by one for each slot level above 2nd.","save":"cha"},{"id":"deepm_wild-shield","name":"Wild Shield","level":4,"school":"Abjuration","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"You surround yourself with the forces of chaos. Wild lights and strange sounds engulf you, making stealth impossible. While **wild shield** is active, you can use a reaction to repel a spell of 4th level or lower that targets you or whose area you are within. A repelled spell has no effect on you, but doing this causes the chance of a chaos magic surge as if you had cast a spell, with you considered the caster for any effect of the surge.\n\n**Wild shield** ends when the duration expires or when it absorbs 4 levels of spells. If you try to repel a spell whose level exceeds the number of levels remaining, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level – the number of levels **wild shield** can still repel. If the check succeeds, the spell is repelled; if the check fails, the spell has its full effect. The chance of a chaos magic surge exists regardless of whether the spell is repelled.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you can repel one additional spell level for each slot level above 4th."},{"id":"deepm_wind-lash","name":"Wind Lash","level":0,"school":"Evocation","time":"Action","range":"20 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Your swift gesture creates a solid lash of howling wind. Make a melee spell attack against the target. On a hit, the target takes 1d8 slashing damage from the shearing wind and is pushed 5 feet away from you.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"The spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","damage":"1d8 slashing","attack":true},{"id":"deepm_wind-of-the-hereafter","name":"Wind of the Hereafter","level":8,"school":"Conjuration","time":"Action","range":"120 feet","components":"V, S, M (a vial of air from a tomb)","duration":"10 minutes","classes":[],"desc":"You create a 30-foot-radius sphere of roiling wind that carries the choking stench of death. The sphere is centered on a point you choose within range. The wind blows around corners. When a creature starts its turn in the sphere, it takes 8d8 necrotic damage, or half as much damage if it makes a successful Constitution saving throw. Creatures are affected even if they hold their breath or don't need to breathe.\n\nThe sphere moves 10 feet away from you at the start of each of your turns, drifting along the surface of the ground. It is not heavier than air but drifts in a straight line for the duration of the spell, even if that carries it over a cliff or gully. If the sphere meets a wall or other impassable obstacle, it turns to the left or right (select randomly).","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","damage":"8d8 necrotic","save":"con"},{"id":"deepm_wind-tunnel","name":"Wind Tunnel","level":1,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M (a paper straw)","duration":"1 minute","classes":[],"desc":"You create a swirling tunnel of strong wind extending from yourself in a direction you choose. The tunnel is a line 60 feet long and 10 feet wide. The wind blows from you toward the end of the line, which is stationary once created. A creature in the line moving with the wind (away from you) adds 10 feet to its speed, and ranged weapon attacks launched with the wind don't have disadvantage because of long range. Creatures in the line moving against the wind (toward you) spend 2 feet of movement for every 1 foot they move, and ranged weapon attacks launched along the line against the wind are made with disadvantage.\n\nThe wind tunnel immediately disperses gas or vapor, and it extinguishes candles, torches, and similar unprotected flames in the line. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance of extinguishing them.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_winterdark","name":"Winterdark","level":6,"school":"Transmutation","time":"Action","range":"120 feet","components":"V, S","duration":"1 hour","classes":[],"desc":"This spell invokes the deepest part of night on the winter solstice. You target a 40-foot-radius, 60-foot-high cylinder centered on a point within range, which is plunged into darkness and unbearable cold. Each creature in the area when you cast the spell and at the start of its turn must make a successful Constitution saving throw or take 1d6 cold damage and gain one level of exhaustion. Creatures immune to cold damage are also immune to the exhaustion effect, as are creatures wearing cold weather gear or otherwise adapted for a cold environment.\n\nAs a bonus action, you can move the center of the effect 20 feet.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_winters-radiance","name":"Winter's Radiance","level":6,"school":"Evocation","time":"Action","range":"400 feet","components":"V, S, M (a piece of polished glass)","duration":"1 minute","classes":[],"desc":"When you cast this spell, the piercing rays of a day's worth of sunlight reflecting off fresh snow blankets the area. A creature caught in the spell's area must succeed on a Constitution saving throw or have disadvantage on ranged attacks and Wisdom (Perception) checks for the duration of the spell. In addition, an affected creature's vision is hampered such that foes it targets are treated as having three-quarters cover.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_wintry-glide","name":"Wintry Glide","level":4,"school":"Conjuration","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"Upon casting wintry glide, you can travel via ice or snow without crossing the intervening space. If you are adjacent to a mass of ice or snow, you can enter it by expending 5 feet of movement. By expending another 5 feet of movement, you can immediately exit from that mass at any point—within 500 feet—that's part of the contiguous mass of ice or snow. When you enter the ice or snow, you instantly know the extent of the material within 500 feet. You must have at least 10 feet of movement available when you cast the spell, or it fails.\n\nIf the mass of ice or snow is destroyed while you are transiting it, you must make a successful Constitution saving throw against your spell save DC to avoid taking 4d6 bludgeoning damage and falling prone at the midpoint of a line between your entrance point and your intended exit point.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"con"},{"id":"deepm_withered-sight","name":"Withered Sight","level":1,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S, M (a dried lizard's eye)","duration":"1 minute","classes":[],"desc":"You cause the eyes of a creature you can see within range to lose acuity. The target must make a Constitution saving throw. On a failed save, the creature has disadvantage on Wisdom (Perception) checks and all attack rolls for the duration of the spell. An affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. This spell has no effect on a creature that is blind or that doesn't use its eyes to see.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st.","save":"con"},{"id":"deepm_wolfsong","name":"Wolfsong","level":1,"school":"Transmutation","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You emit a howl that can be heard clearly from 300 feet away outdoors. The howl can convey a message of up to nine words, which can be understood by all dogs and wolves in that area, as well as (if you choose) one specific creature of any kind that you name when casting the spell.\n\nIf you cast the spell indoors and aboveground, the howl can be heard out to 200 feet from you. If you cast the spell underground, the howl can be heard from 100 feet away. A creature that understands the message is not compelled to act in a particular way, though the nature of the message might suggest or even dictate a course of action.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can name another specific recipient for each slot level above 2nd."},{"id":"deepm_word-of-misfortune","name":"Word of Misfortune","level":0,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You hiss a word of Void Speech. Choose one creature you can see within range. The next time the target makes a saving throw during the spell's duration, it must roll a d4 and subtract the result from the total of the saving throw. The spell then ends.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition"},{"id":"deepm_wresting-wind","name":"Wresting Wind","level":2,"school":"Evocation","time":"Action","range":"90 feet","components":"V, S, M (a handful of paper confetti)","duration":"Instantaneous","classes":[],"desc":"By blowing a pinch of confetti from your cupped hand, you create a burst of air that can rip weapons and other items out of the hands of your enemies. Each enemy in a 20-foot radius centered on a point you target within range must make a successful Strength saving throw or drop anything held in its hands. The objects land 10 feet away from the creatures that dropped them, in random directions.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"str"},{"id":"deepm_writhing-arms","name":"Writhing Arms","level":1,"school":"Transmutation","time":"Action","range":"10 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Your arms become constantly writhing tentacles. You can use your action to make a melee spell attack against any target within range. The target takes 1d10 necrotic damage and is grappled (escape DC is your spell save DC). If the target does not escape your grapple, you can use your action on each subsequent turn to deal 1d10 necrotic damage to the target automatically.\n\nAlthough you control the tentacles, they make it difficult to manipulate items. You cannot wield weapons or hold objects, including material components, while under the effects of this spell.","concentration":true,"ritual":false,"sourceName":"Deep Magic for 5th Edition","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the damage you deal with your tentacle attack increases by 1d10 for each slot level above 1st.","damage":"1d10 necrotic","attack":true},{"id":"deepm_yellow-sign","name":"Yellow Sign","level":4,"school":"Enchantment","time":"Action","range":"30 feet","components":"V, S","duration":"1d10 hours","classes":[],"desc":"You attempt to afflict a humanoid you can see within range with memories of distant, alien realms and their peculiar inhabitants. The target must make a successful Wisdom saving throw or be afflicted with a form of long-term madness and be charmed by you for the duration of the spell or until you or one of your allies harms it in any way. While charmed in this way, the creature regards you as a sacred monarch. If you or an ally of yours is fighting the creature, it has advantage on its saving throw.\n\nA successful [remove curse](https://api.open5e.com/spells/remove-curse) spell ends both effects.","concentration":false,"ritual":false,"sourceName":"Deep Magic for 5th Edition","save":"wis"},{"id":"deepmx_absolute-command","name":"Absolute Command","level":4,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M","duration":"10 minutes","classes":["wizard"],"desc":"Deep Magic: clockwork You can control a construct you have built with a challenge rating of 6 or less. You can manipulate objects with your construct as precisely as its construction allows, and you perceive its surroundings through its sensory inputs as if you inhabited its body. The construct uses the caster's Proficiency bonus (modified by the construct's Strength and Dexterity scores). You can use the manipulators of the construct to perform any number of skill-based tasks, using the construct's Strength and Dexterity modifiers when using skills based on those particular abilities. Your body remains immobile, as if paralyzed, for the duration of the spell. The construct must remain within 100 feet of you. If it moves beyond this distance, the spell immediately ends and the caster's mind returns to his or her body.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using higher-level spell slots, you may control a construct with a challenge rating 2 higher for each slot level you use above 4th. The construct's range also increases by 10 feet for each slot level."},{"id":"deepmx_amplify-ley-field","name":"Amplify Ley Field","level":5,"school":"Evocation","time":"Action","range":"Self","components":"V, S","duration":"10 minutes","classes":["druid","warlock","wizard"],"desc":"You create a faintly shimmering field of charged energy around yourself. Within that area, the intensity of ley lines you're able to draw on increases from weak to strong, or from strong to titanic. If no ley lines are near enough for you to draw on, you can treat the area of the spell itself as an unlocked, weak ley line.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_animate-construct","name":"Animate Construct","level":1,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M","duration":"10 minutes","classes":["wizard"],"desc":"Deep Magic: clockwork This spell animates a carefully prepared construct of Tiny size. The object acts immediately, on your turn, and can attack your opponents to the best of its ability. You can direct it not to attack, to attack particular enemies, or to perform other actions. You choose the object to animate, and you can change that choice each time you cast the spell. The cost of the body to be animated is 10 gp x its hit points. The body can be reused any number of times, provided it isn't severely damaged or destroyed. If no prepared construct body is available, you can animate a mass of loose metal or stone instead. Before casting, the loose objects must be arranged in a suitable shape (taking up to a minute), and the construct's hit points are halved. An animated construct has a Constitution of 10, Intelligence and Wisdom 3, and Charisma 1. Other characteristics are determined by the construct's size as follows. Size HP AC Attack STR DEX Spell Slot Tiny 15 12 +3, 1d4+4 4 16 1st Small 25 13 +4, 1d8+2 6 14 2nd Medium 40 14 +5, 2d6+1 10 12 3rd Large 50 15 +6, 2d10+2 14 10 4th Huge 80 16 +8, 2d12+4 18 8 5th Gargantuan 100 17 +10, 4d8+6 20 6 6th","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"Casting this spell using higher level spell slots allows you to increase the size of the construct animated, as shown on the table."},{"id":"deepmx_anomalous-object","name":"Anomalous Object","level":7,"school":"Conjuration","time":"Action","range":"Touch","components":"V, S, M","duration":"1 minute","classes":["wizard"],"desc":"Deep Magic: temporal By touching an object, you retrieve another version of the object from elsewhere in time. If the object is attended, you must succeed on a melee spell attack roll against the creature holding or controlling the object. Any effect that affects the original object also affects the duplicate (charges spent, damage taken, etc.) and any effect that affects the duplicate also affects the original object. If either object is destroyed, both are destroyed. This spell does not affect sentient items or unique artifacts.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_armored-heart","name":"Armored Heart","level":1,"school":"Conjuration","time":"Bonus Action","range":"Touch","components":"V, S, M","duration":"1 round","classes":["bard","warlock","wizard"],"desc":"Deep Magic: clockwork The targeted creature gains resistance to bludgeoning, slashing, and piercing damage. This resistance can be overcome with adamantine or magical weapons.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_armored-shell","name":"Armored Shell","level":1,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M","duration":"1 hour","classes":["warlock","wizard"],"desc":"Deep Magic: clockwork This spell creates a suit of magical studded leather armor (AC 12). It does not grant you proficiency in its use. Casters without the appropriate armor proficiency suffer disadvantage on any ability check, saving throw, or attack roll that involves Strength or Dexterity and cannot cast spells.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"Casting armored shell using a higher-level spell slot creates stronger armor: a chain shirt (AC 13) at level 2, scale mail (AC 14) at level 3, chain mail (AC 16) at level 4, and plate armor (AC 18) at level 5.","save":"str"},{"id":"deepmx_banshee-wail","name":"Banshee Wail","level":6,"school":"Necromancy","time":"Action","range":"Self","components":"V, S, M","duration":"Instantaneous","classes":["warlock","wizard"],"desc":"You emit a soul-shattering wail. Every creature within a 30-foot cone who hears the wail must make a Wisdom saving throw. Those that fail take 6d10 psychic damage and become frightened of you; a frightened creature repeats the saving throw at the end of its turn, ending the effect on itself on a success. Those that succeed take 3d10 psychic damage and aren't frightened. This spell has no effect on constructs and undead.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"wis"},{"id":"deepmx_beguiling-gift","name":"Beguiling Gift","level":1,"school":"Enchantment","time":"Action","range":"Touch","components":"S","duration":"Instantaneous","classes":["bard","cleric","druid","warlock","wizard"],"desc":"Deep Magic: hieroglyph You implant a powerful suggestion into an item as you hand it to someone. If the person you hand it to accepts it willingly, they must make a successful Wisdom saving throw or use the object as it's meant to be used at their first opportunity: writing with a pen, consuming food or drink, wearing clothing, drawing a weapon, etc. After the first use, they're under no compulsion to continue using the object or even to keep it.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"wis"},{"id":"deepmx_borrowing","name":"Borrowing","level":3,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M","duration":"1 minute","classes":[],"desc":"By touching a target, you gain one sense, movement type and speed, feat, language, immunity, or extraordinary ability of the target for the duration of the spell. The target also retains the use of the borrowed ability. An unwilling target prevents the effect with a successful Constitution saving throw. The target can be a living creature or one that's been dead no longer than 1 minute; a corpse makes no saving throw. You can possess only one borrowed power at a time.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 5th level, its duration increases to 1 hour. Additionally, the target loses the stolen power for the duration of the spell.","save":"con"},{"id":"deepmx_call-the-hunter","name":"Call the Hunter","level":8,"school":"Conjuration","time":"1 minute","range":"90 feet","components":"V, S","duration":"10 minutes","classes":["cleric"],"desc":"Deep Magic: clockwork You detach a portion of your soul to become the embodiment of justice in the form of a clockwork outsider known as a Zelekhut who will serve at your commands for the duration, so long as those commands are consistent with its desire to punish wrongdoers. You may give the creature commands as a bonus action; it acts either immediately before or after you.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_circle-of-devestation","name":"Circle of Devestation","level":9,"school":"Evocation","time":"Action","range":"1 mile","components":"V, S, M","duration":"1 minute","classes":["warlock","wizard"],"desc":"You create a 10-foot tall, 20-foot radius ring of destructive energy around a point you can see within range. The area inside the ring is difficult terrain. When you cast the spell and as a bonus action on each of your turns, you can choose one of the following damage types: cold, fire, lightning, necrotic, or radiant. Creatures and objects that touch the ring, that are inside it when it's created, or that end their turn inside the ring take 6d6 damage of the chosen type, or half damage with a successful Constitution saving throw. A creature or object reduced to 0 hit points by the spell is reduced to fine ash. At the start of each of your subsequent turns, the ring's radius expands by 20 feet. Any creatures or objects touched by the expanding ring are subject to its effects immediately.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"con"},{"id":"deepmx_cloying-darkness","name":"Cloying Darkness","level":1,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S","duration":"1 round","classes":["warlock","wizard"],"desc":"You reach out with a hand of decaying shadows. Make a ranged spell attack. If it hits, the target takes 2d8 necrotic damage and must make a Constitution saving throw. If it fails, its visual organs are enveloped in shadow until the start of your next turn, causing it to treat all lighting as if it's one step lower in intensity (it treats bright light as dim, dim light as darkness, and darkness as magical darkness).","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st.","damage":"2d8 necrotic","save":"con","attack":true},{"id":"deepmx_cosmic-alignment","name":"Cosmic Alignment","level":9,"school":"Conjuration","time":"1 hour","range":"Self","components":"V, S, M","duration":"24 hours","classes":["wizard"],"desc":"Deep Magic: illumination You arrange the forces of the cosmos to your benefit. Choose a cosmic event from the Comprehension of the Starry Sky ability that affects spellcasting (conjunction, eclipse, or nova; listed after the spell). You cast spells as if under the effect of the cosmic event until the next sunrise or 24 hours have passed. When the ability requires you to expend your insight, you expend your ritual focus instead. This spell must be cast outdoors, and the casting of this spell is obvious to everyone within 100 miles of its casting when an appropriate symbol, such as a flaming comet, appears in the sky above your location while you are casting the spell. Conjunction: Planetary conjunctions destabilize minds and emotions. You can give one creature you can see disadvantage on a saving throw against one enchantment or illusion spell cast by you. Eclipse: Eclipses plunge the world into darkness and strengthen connections to the shadow plane. When you cast a spell of 5th level or lower that causes necrotic damage, you can reroll a number of damage dice up to your Intelligence modifier (minimum of one). You must use the new rolls. Nova: The nova is a powerful aid to divination spells. You can treat one divination spell you cast as though you had used a spell slot one level higher than the slot actually used.","concentration":false,"ritual":true,"sourceName":"Deep Magic Extended","save":"int"},{"id":"deepmx_cruor-of-visions","name":"Cruor of Visions","level":5,"school":"Divination","time":"1 minute","range":"Self","components":"V, S, M","duration":"5 minutes","classes":["cleric","warlock","wizard"],"desc":"You prick your finger with a bone needle as you cast this spell, taking 1 necrotic damage. This drop of blood must be caught in a container such as a platter or a bowl, where it grows into a pool 1 foot in diameter. This pool acts as a crystal ball for the purpose of scrying. If you place a drop (or dried flakes) of another creature's blood in the cruor of visions, the creature has disadvantage on any Wisdom saving throw to resist scrying. Additionally, you can treat the pool of blood as a crystal ball of telepathy (see the crystal ball description in the Fifth Edition rules). I When you cast this spell using a spell slot of 7th level or higher, the pool of blood acts as either a crystal ball of mind reading or a crystal ball of true seeing (your choice when the spell is cast).","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"wis"},{"id":"deepmx_extract-foyson","name":"Extract Foyson","level":1,"school":"Transmutation","time":"1 minute","range":"30 feet","components":"V, S, M","duration":"Permanent","classes":["bard","druid","warlock","wizard"],"desc":"You extract the goodness in food, pulling all the nutrition out of three days' worth of meals and concentrating it into about a tablespoon of bland, flourlike powder. The flour can be mixed with liquid and drunk or baked into elven bread. Foyson used in this way still imparts all the nutritional value of the original food, for the amount consumed. The original food appears unchanged and though it's still filling, it has no nutritional value. Someone eating nothing but foyson-free food will eventually starve.","concentration":false,"ritual":true,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, an additional three meals' worth of food can be extracted for each slot level above 1st. Ritual Focus. If you expend your ritual focus, you can choose to have each day's worth of foyson take the form of a slice of delicious elven bread."},{"id":"deepmx_find-the-flaw","name":"Find the Flaw","level":1,"school":"Divination","time":"Action","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":["bard","warlock","wizard"],"desc":"Deep Magic: clockwork You touch one creature. The next attack roll that creature makes against a clockwork or metal construct, or any machine, is a critical hit.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_gear-shield","name":"Gear Shield","level":1,"school":"Abjuration","time":"Action","range":"60 feet","components":"V, S, M","duration":"10 minutes","classes":["warlock","wizard"],"desc":"Deep Magic: clockwork You cause a handful of gears to orbit the target's body. These shield the spell's target from incoming attacks, granting a +2 bonus to AC and to Dexterity and Constitution saving throws for the duration, without hindering the subject's movement, vision, or outgoing attacks.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"dex"},{"id":"deepmx_gift-of-azathoth","name":"Gift of Azathoth","level":2,"school":"Enchantment","time":"Action","range":"Touch","components":"V, S","duration":"24 hours or until the target attempts a third death saving throw","classes":["bard","cleric","druid","ranger","warlock","wizard"],"desc":"Deep Magic: void magic A willing creature you touch is imbued with the persistence of ultimate Chaos. Until the spell ends, the target has advantage on the first three death saving throws it attempts.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 5th, 6th, or 7th level, the duration increases to 48 hours. When you cast this spell using a spell slot of 8th or 9th level, the duration increases to 72 hours."},{"id":"deepmx_greater-ley-pulse","name":"Greater Ley Pulse","level":7,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":["druid","warlock","wizard"],"desc":"You set up ley energy vibrations in a 20-foot cube within range, and name one type of damage. Each creature in the area must succeed on a Wisdom saving throw or lose immunity to the chosen damage type for the duration.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a 9th-level spell slot, choose two damage types instead of one.","save":"wis"},{"id":"deepmx_gremlins","name":"Gremlins","level":4,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M","duration":"1 minute","classes":["warlock","wizard"],"desc":"Deep Magic: clockwork You target a construct and summon a plague of invisible spirits to harass it. The target resists the spell and negates its effect with a successful Wisdom saving throw. While the spell remains in effect, the construct has disadvantage on attack rolls, ability checks, and saving throws, and it takes 3d8 force damage at the start of each of its turns as it is magically disassembled by the spirits.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 5th or higher, the damage increases by 1d8 for each slot above 4th.","damage":"3d8 force","save":"wis"},{"id":"deepmx_grinding-gears","name":"Grinding Gears","level":4,"school":"Evocation","time":"Action","range":"120 feet","components":"V, S, M","duration":"1 minute","classes":["warlock","wizard"],"desc":"Deep Magic: clockwork You designate a spot within range, and massive gears emerge from the ground at that spot, creating difficult terrain in a 20-foot radius. Creatures that move in the area must make successful Dexterity saving throws after every 10 feet of movement or when they stand up. Failure indicates that the creature falls prone and takes 1d8 points of bludgeoning damage.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","damage":"1d8 bludgeoning","save":"dex"},{"id":"deepmx_hearth-charm","name":"Hearth Charm","level":1,"school":"Transmutation","time":"Action","range":"25 feet","components":"V, S","duration":"24 hours","classes":["druid","ranger","warlock"],"desc":"This spell makes flammable material burn twice as long as normal.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_hellforging","name":"Hellforging","level":7,"school":"Necromancy","time":"1 hour","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":["cleric","wizard"],"desc":"Deep Magic: clockwork You spend an hour calling forth a disembodied evil spirit. At the end of that time, the summoned spirit must make a Charisma saving throw. If the saving throw succeeds, you take 2d10 psychic damage plus 2d10 necrotic damage from waves of uncontrolled energy rippling out from the disembodied spirit. You can maintain the spell, forcing the subject to repeat the saving throw at the end of each of your turns, with the same consequence to you for each failure. If you choose not to maintain the spell or are unable to do so, the evil spirit returns to its place of torment and cannot be recalled. If the saving throw fails, the summoned spirit is transferred into the waiting soul gem and immediately animates the constructed body. The subject is now a hellforged; it loses all of its previous racial traits and gains gearforged traits except as follows: Vulnerability: Hellforged are vulnerable to radiant damage. Evil Mind: Hellforged have disadvantage on saving throws against spells and abilities of evil fiends or aberrations that effect the mind or behavior. Past Life: The hellforged retains only a vague sense of who it was in its former existence, but these memories are enough for it to gain proficiency in one skill. Languages: Hellforged speak Common, Machine Speech, and Infernal or Abyssal Up to four other spellcasters of at least 5th level can assist you in the ritual. Each assistant increases the DC of the Charisma saving throw by 1. In the event of a failed saving throw, the spellcaster and each assistant take damage. An assistant who drops out of the casting can't rejoin.","concentration":false,"ritual":true,"sourceName":"Deep Magic Extended","save":"cha"},{"id":"deepmx_hods-gift","name":"Hod's Gift","level":5,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M","duration":"1 hour","classes":["cleric","wizard"],"desc":"The target gains blindsight to a range of 60 feet.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the duration is increased by 1 hour for every slot above 5th level."},{"id":"deepmx_imbue-spell","name":"Imbue Spell","level":5,"school":"Transmutation","time":"1 hour","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":["cleric","wizard"],"desc":"Deep Magic: clockwork You imbue a spell of 1st thru 3rd level that has a casting time of instantaneous onto a gear worth 100 gp per level of spell you are imbuing. At the end of the ritual, the gear is placed into a piece of clockwork that includes a timer or trigger mechanism. When the timer or trigger goes off, the spell is cast. If the range of the spell was Touch, it effects only a target touching the device. If the spell had a range in feet, the spell is cast on the closest viable target within range, based on the nature of the spell. Spells with a range of Self or Sight can't be imbued. If the gear is placed with a timer, it activates when the time elapses regardless of whether a legitimate target is available.","concentration":false,"ritual":true,"sourceName":"Deep Magic Extended","higherLevel":"You can perform this ritual as a 7th-level spell to imbue a spell of 4th or 5th level."},{"id":"deepmx_jotuns-jest","name":"Jotun's Jest","level":4,"school":"Transmutation","time":"Action","range":"25 feet","components":"V, S","duration":"1 minute","classes":["bard","warlock","wizard"],"desc":"Giants never tire of having fun with this spell. It causes a weapon or other item to vastly increase in size, temporarily becoming sized for a Gargantuan creature. The item weighs 12 times its original weight and in most circumstances cannot be used effectively by creatures smaller than Gargantuan size. The item retains its usual qualities (including magical powers and effects) and returns to normal size when the spell ends.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_land-bond","name":"Land Bond","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M","duration":"1 hour","classes":["druid","warlock","wizard"],"desc":"You touch a willing creature and infuse it with ley energy, creating a bond between the creature and the land. For the duration of the spell, if the target is in contact with the ground, the target has advantage on saving throws and ability checks made to avoid being moved or knocked prone against its will. Additionally, the creature ignores nonmagical difficult terrain and is immune to effects from extreme environments such as heat, cold (but not cold or fire damage), and altitude.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_lesser-ley-pulse","name":"Lesser Ley Pulse","level":5,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":["druid","warlock","wizard"],"desc":"You set up ley energy vibrations in a 10-foot cube within range, and name one type of damage. Each creature in the area must make a successful Wisdom saving throw or lose resistance to the chosen damage type for the duration of the spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a 7th-level spell slot, choose two damage types instead of one.","save":"wis"},{"id":"deepmx_ley-disruption","name":"Ley Disruption","level":2,"school":"Evocation","time":"Action","range":"50 feet","components":"V, S, M","duration":"1 minute","classes":["druid","warlock","wizard"],"desc":"You create a 15-foot-radius sphere filled with disruptive ley energy. The sphere is centered around a point you can see within range. Surfaces inside the sphere shift erratically, becoming difficult terrain for the duration. Any creature in the area when it appears, that starts its turn in the area, or that enters the area for the first time on a turn must succeed on a Dexterity saving throw or fall prone. If you cast this spell in an area within the influence of a ley line, creatures have disadvantage on their saving throws against its effect. Special. A geomancer with a bound ley line is “within the influence of a ley line” for purposes of ley disruption as long as he or she is on the same plane as the bound line.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"dex"},{"id":"deepmx_ley-energy-bolt","name":"Ley Energy Bolt","level":3,"school":"Evocation","time":"Action","range":"Self","components":"S, M","duration":"Instantaneous","classes":["druid","warlock","wizard"],"desc":"You transform ambient ley power into a crackling bolt of energy 100 feet long and 5 feet wide. Each creature in the line takes 5d8 force damage, or half damage with a successful Dexterity saving throw. The bolt passes through the first inanimate object in its path, and creatures on the other side of the obstacle receive no bonus to their saving throw from cover. The bolt stops if it strikes a second object.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, the bolt's damage increases by 1d8 for each slot level above 3rd.","damage":"5d8 force","save":"dex"},{"id":"deepmx_ley-leech","name":"Ley Leech","level":5,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":["druid","warlock","wizard"],"desc":"You channel destructive ley energy through your touch. Make a melee spell attack against a creature within your reach. The target takes 8d10 necrotic damage and must succeed on a Constitution saving throw or have disadvantage on attack rolls, saving throws, and ability checks. An affected creature repeats the saving throw at the end of its turn, ending the effect on itself with a success. This spell has no effect against constructs or undead.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the spell's damage increases by 1d10 for each slot level above 5th.","damage":"8d10 necrotic","save":"con","attack":true},{"id":"deepmx_ley-sense","name":"Ley Sense","level":3,"school":"Divination","time":"Action","range":"Self","components":"V, S","duration":"10 minutes","classes":["druid","warlock","wizard"],"desc":"You tune your senses to the pulse of ambient ley energy flowing through the world. For the duration, you gain tremorsense with a range of 20 feet and you are instantly aware of the presence of any ley line within 5 miles. You know the distance and direction to every ley line within that range.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_ley-storm","name":"Ley Storm","level":9,"school":"Conjuration","time":"Action","range":"Special","components":"V, S","duration":"1 minute","classes":["druid","warlock","wizard"],"desc":"A roiling stormcloud of ley energy forms, centered around a point you can see and extending horizontally to a radius of 360 feet, with a thickness of 30 feet. Shifting color shoots through the writhing cloud, and thunder roars out of it. Each creature under the cloud at the moment when it's created (no more than 5,000 feet beneath it) takes 2d6 thunder damage and is disruptive aura spell. Rounds 5-10. Flashes of multicolored light burst through and out of the cloud, causing creatures to have disadvantage on Wisdom (Perception) checks that rely on sight while they are beneath the cloud. In addition, each round, you trigger a burst of energy that fills a 20-foot sphere centered on a point you can see beneath the cloud. Each creature in the sphere takes 4d8 force damage (no saving throw). Special. A geomancer who casts this spell regains 4d10 hit points.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","damage":"2d6 thunder","save":"wis"},{"id":"deepmx_ley-surge","name":"Ley Surge","level":9,"school":"Evocation","time":"Action","range":"150 feet","components":"V, S","duration":"Instantaneous","classes":["druid","warlock","wizard"],"desc":"You unleash the power of a ley line within 5 miles, releasing a spark that flares into a 30-foot sphere centered around a point within 150 feet of you. Each creature in the sphere takes 14d6 force damage and is stunned for 1 minute; a successful Constitution saving throw halves the damage and negates the stun. A stunned creature repeats the saving throw at the end of its turn, ending the effect on itself on a success. Special. A geomancer with a bound ley line can cast this spell as long as he or she is on the same plane as the bound line.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","damage":"14d6 force","save":"con"},{"id":"deepmx_ley-whip","name":"Ley Whip","level":6,"school":"Evocation","time":"Bonus Action","range":"Self","components":"V, S","duration":"1 minute","classes":["druid","warlock","wizard"],"desc":"You channel the power of a ley line within 1 mile into a crackling tendril of multicolored ley energy. The tendril extends from your hand but doesn't interfere with your ability to hold or manipulate objects. When you cast the spell and as a bonus action on subsequent turns, you can direct the tendril to strike a target within 50 feet of you. Make a melee spell attack; on a hit, the tendril does 3d8 force damage and the target must make a Strength saving throw. If the saving throw fails, you can push the target away or pull it closer, up to 10 feet in either direction. Special. A geomancer with a bound ley line can cast this spell as long as he or she is on the same plane as the bound line.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"str","attack":true},{"id":"deepmx_lokis-gift","name":"Loki's Gift","level":1,"school":"Enchantment","time":"Action","range":"Self","components":"V","duration":"1 minute","classes":["bard","cleric","warlock"],"desc":"Loki's gift makes even the most barefaced lie seem strangely plausible: you gain advantage to Charisma (Deception) checks for whatever you're currently saying. If your Deception check fails, the creature knows that you tried to manipulate it with magic. If you lie to a creature that has a friendly attitude toward you and it fails a Charisma saving throw, you can also coax him or her to reveal a potentially embarrassing secret. The secret can involve wrongdoing (adultery, cheating at tafl, a secret fear, etc.) but not something life-threatening or dishonorable enough to earn the subject repute as a nithling. The verbal component of this spell is the lie you are telling.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"cha"},{"id":"deepmx_machine-sacrifice","name":"Machine Sacrifice","level":8,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M","duration":"1 minute","classes":["wizard"],"desc":"Deep Magic: clockwork You sacrifice a willing construct you can see to imbue a willing target with construct traits. The target gains resistance to all nonmagical damage and gains immunity to the blinded, charmed, deafened, frightened, petrified, and poisoned conditions.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_machine-speech","name":"Machine Speech","level":1,"school":"Transmutation","time":"Bonus Action","range":"Self","components":"V, S","duration":"1 round","classes":["bard","cleric","wizard"],"desc":"Deep Magic: clockwork Your voice, and to a lesser extent your mind, changes to communicate only in the whirring clicks of machine speech. Until the end of your next turn, all clockwork spells you cast have advantage on their attack rolls or the targets have disadvantage on their saving throws.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_machines-load","name":"Machine's Load","level":1,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M","duration":"1 minute","classes":["cleric","warlock","wizard"],"desc":"Deep Magic: clockwork You touch a creature and give it the capacity to carry, lift, push, or drag weight as if it were one size category larger. If you're using the encumbrance rules, the target is not subject to penalties for weight. Furthermore, the subject can carry loads that would normally be unwieldy.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"When you cast this spell using a spell slot higher than 1st, you can touch one additional creature for each spell level."},{"id":"deepmx_mass-blade-ward","name":"Mass Blade Ward","level":2,"school":"Abjuration","time":"Action","range":"30 feet","components":"V, S","duration":"1 round","classes":["wizard"],"desc":"You make a protective gesture toward your allies. Choose three creatures that you can see within range. Until the end of your next turn, the targets have resistance against bludgeoning, piercing, and slashing damage from weapon attacks. If a target moves farther than 30 feet from you, the effect ends for that creature.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_mass-repair-metal","name":"Mass Repair Metal","level":5,"school":"Transmutation","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":["cleric","wizard"],"desc":"Deep Magic: clockwork As repair metal, but you can affect all metal within range. You repair 1d8 + 5 damage to a metal object or construct by sealing up rents and bending metal back into place.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"Casting mass repair metal as a 6th-level spell repairs 2d8 + 10 damage."},{"id":"deepmx_mechanical-union","name":"Mechanical Union","level":5,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M","duration":"1 hour","classes":["wizard"],"desc":"Deep Magic: clockwork You can take control of a construct by voice or mental commands. The construct makes a Wisdom saving throw to resist the spell, and it gets advantage on the saving throw if its CR equals or exceeds your level in the class used to cast this spell. Once a command is given, the construct does everything it can to complete the command. Giving a new command takes an action. Constructs will risk harm, even go into combat, on your orders but will not self-destruct; giving such an order ends the spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"wis"},{"id":"deepmx_molechs-blessing","name":"Molech's Blessing","level":7,"school":"Transmutation","time":"1 hour","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":["cleric"],"desc":"Deep Magic: clockwork ritual You call upon the dark blessings of the furnace god Molech. In an hour-long ritual begun at midnight, you dedicate a living being to Molech by branding the deity's symbol onto the victim's forehead. If the ritual is completed and the victim fails to make a successful Wisdom saving throw (or the victim chooses not to make one), the being is transformed into an avatar of Molech under your control. The avatar is 8 feet tall and appears to be made of black iron wreathed in flames. Its eyes, mouth, and a portion of its torso are cut away to show the churning fire inside that crackles with wailing voices. The avatar has all the statistics and abilities of an earth elemental, with the following differences: Alignment is Neutral Evil; Speed is 50 feet and it cannot burrow or use earth glide; it gains the fire form ability of a fire elemental, but it cannot squeeze through small spaces; its Slam does an additional 1d10 fire damage. This transformation lasts for 24 hours. At the end of that time, the subject returns to its normal state and takes 77 (14d10) fire damage, or half damage with a successful DC 15 Constitution saving throw.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","damage":"77 fire","save":"wis"},{"id":"deepmx_move-the-cosmic-wheel","name":"Move the Cosmic Wheel","level":8,"school":"Conjuration","time":"Action","range":"120 feet","components":"V, S, M","duration":"24 hours","classes":["cleric","wizard"],"desc":"Deep Magic: clockwork You wind your music box and call forth a piece of another plane of existence with which you are familiar, either through personal experience or intense study. The magic creates a bubble of space with a 30-foot radius within range of you and at a spot you designate. The portion of your plane that's inside the bubble swaps places with a corresponding portion of the plane your music box is attuned with. There is a 10% chance that the portion of the plane you summon arrives with native creatures on it. Inanimate objects and non-ambulatory life (like trees) are cut off at the edge of the bubble, while living creatures that don't fit inside the bubble are shunted outside of it before the swap occurs. Otherwise, creatures from both planes that are caught inside the bubble are sent along with their chunk of reality to the other plane for the duration of the spell unless they make a successful Charisma saving throw when the spell is cast; with a successful save, a creature can choose whether to shift planes with the bubble or leap outside of it a moment before the shift occurs. Any natural reaction between the two planes occurs normally (fire spreads, water flows, etc.) while energy (such as necrotic energy) leaks slowly across the edge of the sphere (no more than a foot or two per hour). Otherwise, creatures and effects can move freely across the boundary of the sphere; for the duration of the spell, it becomes a part of its new location to the fullest extent possible, given the natures of the two planes. The two displaced bubbles shift back to their original places automatically after 24 hours. Note that the amount of preparation involved (acquiring and attuning the music box) precludes this spell from being cast on the spur of the moment. Because of its unpredictable and potentially wide-ranging effect, it's also advisable to discuss your interest in this spell with your GM before adding it to your character's repertoire.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"cha"},{"id":"deepmx_overclock","name":"Overclock","level":3,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M","duration":"1 minute","classes":["bard","cleric","wizard"],"desc":"Deep Magic: clockwork You cause a targeted piece of clockwork to speed up past the point of control for the duration of the spell. The targeted clockwork can't cast spells with verbal components or even communicate effectively (all its utterances sound like grinding gears). At the start of each of its turns, the target must make a Wisdom saving throw. If the saving throw fails, the clockwork moves at three times its normal speed in a random direction and its turn ends; it can't perform any other actions. If the saving throw succeeds, then until the end of its turn, the clockwork's speed is doubled and it gains an additional action, which must be Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object. When the spell ends, the clockwork takes 2d8 force damage. It also must be rewound or refueled and it needs to have its daily maintenance performed immediately, if it relies on any of those things.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","damage":"2d8 force","save":"wis"},{"id":"deepmx_power-word-restore","name":"Power Word Restore","level":8,"school":"Evocation","time":"Action","range":"Touch","components":"V","duration":"Instantaneous","classes":["cleric","wizard"],"desc":"Deep Magic: clockwork You speak a word of power, and energy washes over a single construct you touch. The construct regains all of its lost hit points, all negative conditions on the construct end, and it can use a reaction to stand up, if it was prone.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_read-memory","name":"Read Memory","level":4,"school":"Divination","time":"10 minutes","range":"Self","components":"V, S, M","duration":"Instantaneous","classes":["bard","cleric","wizard"],"desc":"Deep Magic: clockwork You copy the memories of one memory gear into your own mind. You recall these memories as if you had experienced them but without any emotional attachment or context.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_repair-metal","name":"Repair Metal","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":["cleric","wizard"],"desc":"Deep Magic: clockwork A damaged construct or metal object regains 1d8 + 5 hit points when this spell is cast on it.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","higherLevel":"The spell restores 2d8 + 10 hit points at 4th level, 3d8 + 15 at 6th level, and 4d8 + 20 at 8th level."},{"id":"deepmx_risen-road","name":"Risen Road","level":4,"school":"Transmutation","time":"1 minute","range":"30 feet","components":"V, S, M","duration":"2-12 hours","classes":[],"desc":"When you cast this spell, you open a glowing portal into the plane of shadow. The portal remains open for 1 minute, until 10 creatures step through it, or until you collapse it (no action required). Stepping through the portal places you on a shadow road leading to a destination within 50 miles, or in a direction specified by you. The road is in ideal condition. You and your companions can travel it safely at a normal pace, but you can't rest on the road; if you stop for more than 10 minutes, the spell expires and dumps you back into the real world at a random spot within 10 miles of your starting point. The spell expires 2d6 hours after being cast. When that happens, travelers on the road are safely deposited near their specified destination or 50 miles from their starting point in the direction that was specified when the spell was cast. Travelers never incur exhaustion no matter how many hours they spent walking or riding on the shadow road. The temporary shadow road ceases to exist; anything left behind is lost in the shadow realm. Each casting of risen road creates a new shadow road. A small chance exists that a temporary shadow road might intersect with an existing shadow road, opening the possibility for meeting other travelers or monsters, or for choosing a different destination mid-journey. The likelihood is entirely up to the GM.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_robe-of-shards","name":"Robe of Shards","level":6,"school":"Abjuration","time":"Action","range":"Self","components":"V, S, M","duration":"1 minute","classes":["warlock","wizard"],"desc":"Deep Magic: clockwork You create a robe of metal shards, gears, and cogs that provides a base AC of 14 + your Dexterity modifier. As a bonus action while protected by a robe of shards, you can command bits of metal from a fallen foe to be absorbed by your robe; each infusion of metal increases your AC by 1, to a maximum of 18 + Dexterity modifier. You can also use a bonus action to dispel the robe, causing it to explode into a shower of flying metal that does 8d6 slashing damage, +1d6 per point of basic (non-Dexterity) AC above 14, to all creatures within 30 feet of you.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_shadow-realm-gateway","name":"Shadow Realm Gateway","level":5,"school":"Conjuration","time":"1 minute","range":"30 feet","components":"V, S, M","duration":"1 minute","classes":["warlock","wizard"],"desc":"By drawing a circle of black chalk up to 15 feet in diameter and chanting for one minute, you open a portal directly into the Shadow Realm. The portal fills the chalk circle and appears as a vortex of inky blackness; nothing can be seen through it. Any object or creature that passes through the portal instantly arrives safely in the Shadow Realm. The portal remains open for one minute or until you lose concentration on it, and it can be used to travel between the Shadow Realm and the chalk circle, in both directions, as many times as desired during the spell's duration. This spell can only be cast as a ritual.","concentration":false,"ritual":true,"sourceName":"Deep Magic Extended"},{"id":"deepmx_shield-of-star-and-shadow","name":"Shield of Star and Shadow","level":3,"school":"Abjuration","time":"Action","range":"Self","components":"V, S, M","duration":"10 minutes","classes":["wizard"],"desc":"You wrap yourself in a protective shroud of the night sky made from swirling shadows punctuated with twinkling motes of light. The shroud grants you resistance against either radiant or necrotic damage (choose when the spell is cast). You also shed dim light in a 10-foot radius. You can end the spell early by using an action to dismiss it.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_snowblind-stare","name":"Snowblind Stare","level":2,"school":"Necromancy","time":"Action","range":"Self","components":"V, S","duration":"2 rounds","classes":["cleric","druid","wizard"],"desc":"Your eyes burn with a bright, cold light that inflicts snow blindness on a creature you target within 30 feet of you. If the target fails a Constitution saving throw, it suffers the first stage of snow blindness (see [Conditions](https://api.open5e.com/sections/conditions)), or the second stage of snow blindness if it already has the first stage. The target recovers as described in [Conditions](https://api.open5e.com/sections/conditions).","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"con"},{"id":"deepmx_soothsayers-shield","name":"Soothsayer's Shield","level":2,"school":"Divination","time":"Reaction","range":"Self","components":"V, S","duration":"Instantaneous","classes":["bard","cleric","druid","ranger"],"desc":"This spell can be cast when you are hit by an enemy's attack. Until the start of your next turn, you have a +4 bonus to AC, including against the triggering attack.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_soul-of-the-machine","name":"Soul of the Machine","level":3,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S","duration":"1 hour","classes":["bard","cleric"],"desc":"Deep Magic: clockwork One willing creature you touch becomes immune to mind-altering effects and psychic damage for the spell's duration.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_sphere-of-order","name":"Sphere of Order","level":6,"school":"Evocation","time":"Action","range":"Self","components":"V, S","duration":"1 round","classes":["cleric"],"desc":"Deep Magic: clockwork You surround yourself with the perfect order of clockwork. Chaotic creatures that start their turn in the area or enter it on their turn take 5d8 psychic damage. The damage is 8d8 for Chaotic aberrations, celestials, elementals, and fiends. A successful Wisdom saving throw halves the damage, but Chaotic creatures (the only ones affected by the spell) make the saving throw with disadvantage.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"wis"},{"id":"deepmx_spire-of-stone","name":"Spire of Stone","level":2,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M","duration":"10 minutes","classes":["warlock","wizard"],"desc":"You cause a spire of rock to burst out of the ground, floor, or another surface beneath your feet. The spire is as wide as your space, and lifting you, it can rise up to 20 feet in height. When the spire appears, a creature within 5 feet of you must succeed on a Dexterity saving throw or fall prone. As a bonus action on your turn, you can cause the spire to rise or descend up to 20 feet to a maximum height of 40 feet. If you move off of the spire, it immediately collapses back into the ground. When the spire disappears, it leaves the surface from which it sprang unharmed. You can create a new spire as a bonus action for the duration of the spell.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended","save":"dex"},{"id":"deepmx_strength-of-the-underworld","name":"Strength of the Underworld","level":3,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S, M","duration":"1 minute","classes":[],"desc":"You call on the power of the dark gods of the afterlife to strengthen the target's undead energy. The spell's target has advantage on saving throws against Turn Undead while the spell lasts. If this spell is cast on a corpse that died from darakhul fever, the corpse gains a +5 bonus on its roll to determine whether it rises as a darakhul.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_summon-old-ones-avatar","name":"Summon Old One's Avatar","level":9,"school":"Conjuration","time":"10 minutes","range":"60 feet","components":"V, S, M","duration":"1 hour","classes":["bard","cleric","druid","warlock","wizard"],"desc":"Deep Magic: void magic You summon a worldly incarnation of a Great Old One, which appears in an unoccupied space you can see within range. This avatar manifests as a Void speaker (Creature Codex NPC) augmented by boons from the Void. Choose one of the following options for the type of avatar that appears (other options might be available if the GM allows): Avatar of Cthulhu. The Void speaker is a goat-man with the ability to cast black goat's blessing and unseen strangler at will. Avatar of Yog-Sothoth. The Void speaker is a human with 1d4 + 1 flesh warps and the ability to cast gift of Azathoth and thunderwave at will. When the avatar appears, you must make a Charisma saving throw. If it succeeds, the avatar is friendly to you and your allies. If it fails, the avatar is friendly to no one and attacks the nearest creature to it, pursuing and fighting for as long as possible. Roll initiative for the avatar, which takes its own turn. If friendly to you, it obeys verbal commands you issue to it (no action required by you). If the avatar has no command, it attacks the nearest creature. Each round you maintain concentration on the spell, you must make a successful DC 15 Wisdom saving throw or take 1d6 psychic damage. If the cumulative total of this damage exceeds your Wisdom score, you gain one point of Void taint and you are afflicted with a short-term madness. The same penalty recurs when the damage exceeds twice your Wisdom, three times your Wisdom, etc. The avatar disappears when it drops to 0 hit points or when the spell ends. If you stop concentrating on the spell before an hour has elapsed, the avatar becomes uncontrolled and hostile and doesn't disappear until 1d6 rounds later or it's killed.","concentration":false,"ritual":true,"sourceName":"Deep Magic Extended","save":"cha"},{"id":"deepmx_tick-stop","name":"Tick Stop","level":0,"school":"Transmutation","time":"Action","range":"30 feet","components":"V","duration":"1 round","classes":["wizard"],"desc":"Deep Magic: clockwork You speak a word and the target construct can take one action or bonus action on its next turn, but not both. The construct is immune to further tick stops from the same caster for 24 hours.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_timeless-engine","name":"Timeless Engine","level":7,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S","duration":"Until dispelled","classes":["bard","cleric","wizard"],"desc":"Deep Magic: clockwork You halt the normal processes of degradation and wear in a nonmagical clockwork device, making normal maintenance unnecessary and slowing fuel consumption to 1/10th of normal. For magical devices and constructs, the spell greatly reduces wear. A magical clockwork device, machine, or creature that normally needs daily maintenance only needs care once a year; if it previously needed monthly maintenance, it now requires attention only once a decade.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_winding-key","name":"Winding Key","level":2,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, M","duration":"1 minute","classes":["bard","cleric","wizard"],"desc":"Deep Magic: clockwork You target a construct, giving it an extra action or move on each of its turns.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"deepmx_wotans-rede","name":"Wotan's Rede","level":2,"school":"Divination","time":"Action","range":"Self","components":"V, S","duration":"Instantaneous","classes":["bard","cleric","warlock"],"desc":"You recite a poem in the Northern tongue, sent to your lips by Wotan himself, to gain supernatural insight or advice. Your next Intelligence or Charisma check within 1 minute is made with advantage, and you can include twice your proficiency bonus. At the GM's discretion, this spell can instead provide a piece of general advice equivalent to an contact other plane.","concentration":false,"ritual":true,"sourceName":"Deep Magic Extended"},{"id":"deepmx_write-memory","name":"Write Memory","level":4,"school":"Transmutation","time":"1 hour","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":["bard","cleric","wizard"],"desc":"Deep Magic: clockwork You copy your memories, or those learned from the spell read memory, onto an empty memory gear.","concentration":false,"ritual":false,"sourceName":"Deep Magic Extended"},{"id":"kp_ambush","name":"Ambush","level":1,"school":"Illusion","time":"Action","range":"Self","components":"S, M","duration":"1 hour","classes":[],"desc":"The forest floor swirls and shifts around you to welcome you into its embrace. While in a forest, you have advantage on Dexterity (Stealth) checks to Hide. While hidden in a forest, you have advantage on your next Initiative check. The spell ends if you attack or cast a spell.","concentration":true,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional creature for each slot level above 1st. The spell ends if you or any target of this spell attacks or casts a spell."},{"id":"kp_blood-strike","name":"Blood Strike","level":5,"school":"Necromancy","time":"10 minutes","range":"Self","components":"V, S, M","duration":"Special","classes":[],"desc":"By performing this ritual, you can cast a spell on one nearby creature and have it affect a different, more distant creature. Both targets must be related by blood (no more distantly than first cousins). Neither of them needs to be a willing target. The blood strike ritual is completed first, taking 10 minutes to cast on yourself. Then the spell to be transferred is immediately cast by you on the initial target, which must be close enough to touch no matter what the spell's normal range is. The secondary target must be within 1 mile and on the same plane of existence as you. If the second spell allows a saving throw, it's made by the secondary target, not the initial target. If the saving throw succeeds, any portion of the spell that's avoided or negated by the secondary target affects the initial target instead. A creature can be the secondary target of blood strike only once every 24 hours; subsequent attempts during that time take full effect against the initial target with no chance to affect the secondary target. Only spells that have a single target can be transferred via blood stike. For example, a lesser restoration) currently affecting the initial creature and transfer it to the secondary creature, which then makes any applicable saving throw against the effect. If the saving throw fails or there is no saving throw, the affliction transfers completely and no longer affects the initial target. If the saving throw succeeds, the initial creature is still afflicted and also suffers anew any damage or conditions associated with first exposure to the affliction.","concentration":false,"ritual":true,"sourceName":"Kobold Press Compilation"},{"id":"kp_conjure-manabane-swarm","name":"Conjure Manabane Swarm","level":4,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M","duration":"1 minute","classes":[],"desc":"Deep Magic: summoning You summon a swarm of manabane scarabs that has just 40 hit points. The swarm appears at a spot you choose within 60 feet and attacks the closest enemy. You can conjure the swarm to appear in an enemy's space. If you prefer, you can summon two full-strength, standard swarms of insects (including beetles, centipedes, spiders, or wasps) instead.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_curse-of-formlessness","name":"Curse of Formlessness","level":6,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M","duration":"Permanent","classes":[],"desc":"A creature you touch must make a successful Constitution saving throw or be cursed with a shifting, amorphous form. Spells that change the target creature's shape (such as polymorph) do not end the curse, but they do hold the creature in a stable form, temporarily mitigating it until the end of that particular spell's duration; shapechange and stoneskin have similar effects. While under the effect of the curse of formlessness, the target creature is resistant to slashing and piercing damage and ignores the additional damage done by critical hits, but it can neither hold nor use any item, nor can it cast spells or activate magic items. Its movement is halved, and winged flight becomes impossible. Any armor, clothing, helmet, or ring becomes useless. Large items that are carried or worn, such as armor, backpacks, or clothing, become hindrances, so the target has disadvantage on Dexterity checks and saving throws while such items are in place. A creature under the effect of a curse of formlessness can try to hold itself together through force of will. The afflicted creature uses its action to repeat the saving throw; if it succeeds, the afflicted creature negates the penalties from the spell until the start of its next turn.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","save":"con"},{"id":"kp_delay-passing","name":"Delay Passing","level":1,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You draw forth the ebbing life force of a creature and question it. Upon casting this spell, you must touch a creature that dropped to 0 hit points since your last turn. If it fails a Wisdom saving throw, you temporarily prevent its spirit from passing into the next realm. You are able to hear the spirit, though the spirit doesn't appear to any creature without the ability to see invisible creatures. The spirit communicates directly with your psyche and cannot see or hear anything but what you tell it. You can ask the spirit a number of questions equal to your proficiency bonus. Questions must be asked directly; a delay of more than 10 seconds between the spirit answering one question and you asking another allows the spirit to escape into the afterlife. The corpse's knowledge is limited to what it knew during life, including the languages it spoke. The spirit cannot lie to you, but it can refuse to answer a question that would harm its living family or friends, or truthfully answer that it doesn't know. Once the spirit answers your allotment of questions, it passes on.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","save":"wis"},{"id":"kp_doom-of-ancient-decrepitude","name":"Doom of Ancient Decrepitude","level":5,"school":"Necromancy","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"You generate an entropic field that rapidly ages every creature in the area of effect. The field covers a sphere with a 20-foot radius centered on you. Every creature inside the sphere when it's created, including you, must make a successful Constitution saving throw or gain 2 levels of exhaustion from sudden, traumatic aging. A creature that ends its turn in the field must repeat the saving throw, gaining 1 level of exhaustion per subsequent failure. You have advantage on these saving throws. An affected creature sheds 1 level of exhaustion at the end of its turn, if it started the turn outside the spell's area of effect (or the spell has ended). Only 1 level of exhaustion can be removed this way; all remaining levels are removed when the creature completes a short or long rest. A creature that died from gaining 6 levels of exhaustion, however, remains dead.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","save":"con"},{"id":"kp_doom-of-voracity","name":"Doom of Voracity","level":3,"school":"Conjuration","time":"Action","range":"120 feet","components":"V, S, M","duration":"1 minute","classes":[],"desc":"You create a ripple of dark energy that destroys everything it touches. You create a 10-foot-radius, 10-foot-deep cylindrical extra-dimensional hole on a horizontal surface of sufficient size. Since it extends into another dimension, the pit has no weight and does not otherwise displace the original underlying material. You can create the pit in the deck of a ship as easily as in a dungeon floor or the ground of a forest. Any creature standing in the original conjured space, or on an expanded space as it grows, must succeed on a Dexterity saving throw to avoid falling in. The sloped pit edges crumble continuously, and any creature adjacent to the pit when it expands must succeed on a Dexterity saving throw to avoid falling in. Creatures subjected to a successful pushing effect (such as by a spell like incapacitated for 2 rounds. When the spell ends, creatures within the pit must make a Constitution saving throw. Those who succeed rise up with the bottom of the pit until they are standing on the original surface. Those who fail also rise up but are stunned for 2 rounds.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, increase the depth of the pit by 10 feet for each slot level above 3rd.","save":"dex"},{"id":"kp_feed-the-worms","name":"Feed the Worms","level":1,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"Until destroyed","classes":[],"desc":"You draw forth the ebbing life force of a creature and use it to feed the worms. Upon casting this spell, you touch a creature that dropped to 0 hit points since your last turn. If it fails a Constitution saving throw, its body is completely consumed by worms in moments, leaving no remains. In its place is a swarm of worms (treat as a standard swarm of insects) that considers all other creatures except you as enemies. The swarm remains until it's killed.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","save":"con"},{"id":"kp_greater-ley-protection","name":"Greater Ley Protection","level":7,"school":"Abjuration","time":"Action","range":"60 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Deep Magic: forest-bound You create a 20-foot cube of antimagic within range that specifically protects against ley line magic. Ley line spells and magical effects up to level 7 that target a creature within the cube have no effect on that target. Any active ley line spells or magical effects up to level 7 on a creature or an object in the cube is suppressed while the creature or object is in it. The area of a ley line spell or magical effect up to level 7 can't extend into the cube. If the cube overlaps an area of ley line magic, such as greater ley pulse, the part of the area that is covered by the cube is suppressed. The cube has no effect on other types of magic or spells. You can exclude specific individuals within the cube from the protection.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 9th level or higher, its duration is concentration, up to 1 hour."},{"id":"kp_hirvsths-call","name":"Hirvsth's Call","level":4,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Deep Magic: Rothenian You summon a spectral herd of ponies to drag off a creature that you can see in range. The target must be no bigger than Large and must make a Dexterity saving throw. On a successful save, the spell has no effect. On a failed save, a spectral rope wraps around the target and pulls it 60 feet in a direction of your choosing as the herd races off. The ponies continue running in the chosen direction for the duration of the spell but will alter course to avoid impassable obstacles. Once you choose the direction, you cannot change it. The ponies ignore difficult terrain and are immune to damage. The target is prone and immobilized but can use its action to make a Strength or Dexterity check against your spell DC to escape the spectral bindings. The target takes 1d6 bludgeoning damage for every 20 feet it is dragged by the ponies. The herd moves 60 feet each round at the beginning of your turn.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, one additional creature can be targeted for each slot level above 4th.","damage":"1d6 bludgeoning","save":"dex"},{"id":"kp_incantation-of-lies-made-truth","name":"Incantation of Lies Made Truth","level":9,"school":"Enchantment","time":"9 hours","range":"1000 feet","components":"V, S, M","duration":"Permanent","classes":[],"desc":"This ritual must be cast during a solar eclipse. It can target a person, an organization (including a city), or a kingdom. If targeting an organization or a kingdom, the incantation requires an object epitomizing the entity as part of the material component, such as a crown, mayoral seal, standard, or primary relic. If targeting a person, the primary performer must hold a vial of the person's blood. Over the course of the incantation, the components are mixed and the primary caster inscribes a false history and a sum of knowledge concerning the target into the book using the mockingbird quills. When the incantation is completed, whatever the caster wrote in the book becomes known and accepted as truth by the target. The target can attempt a Wisdom saving throw to negate this effect. If the target was a city or a kingdom, the saving throw is made with advantage by its current leader or ruler. If the saving throw fails, all citizens or members of the target organization or kingdom believe the account written in the book to be fact. Any information contrary to what was written in the book is forgotten within an hour, but individuals who make a sustained study of such information can attempt a Wisdom saving throw to retain the contradictory knowledge. Books containing contradictory information are considered obsolete or purposely misleading. Permanent structures such as statues of heroes who've been written out of existence are believed to be purely artistic endeavors or so old that no one remembers their identities anymore. The effects of this ritual can be reversed by washing the written words from the book using universal solvent and then burning the book to ashes in a magical fire. Incantation of lies made truth is intended to be a villainous motivator in a campaign, with the player characters fighting to uncover the truth and reverse the spell's effect. The GM should take care not to remove too much player agency with this ritual. The creatures affected should be predominantly NPCs, with PCs and even select NPCs able to resist it. Reversing the effect of the ritual can be the entire basis of a campaign.","concentration":false,"ritual":true,"sourceName":"Kobold Press Compilation","save":"wis"},{"id":"kp_jeweled-fissure","name":"Jeweled Fissure","level":3,"school":"Conjuration","time":"Action","range":"100 feet","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"Deep Magic: dragon With a sweeping gesture, you cause jagged crystals to burst from the ground and hurtle directly upward. Choose an origin point within the spell's range that you can see. Starting from that point, the crystals burst out of the ground along a 30-foot line. All creatures in that line and up to 100 feet above it take 2d8 thunder damage plus 2d8 piercing damage; a successful Dexterity saving throw negates the piercing damage. A creature that fails the saving throw is impaled by a chunk of crystal that halves the creature's speed, prevents it from flying, and causes it to fall to the ground if it was flying. To remove a crystal, the creature or an ally within 5 feet of it must use an action and make a successful DC 13 Strength check. If the check succeeds, the impaled creature takes 1d8 piercing damage and its speed and flying ability are restored to normal.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","damage":"1d8 piercing","save":"dex"},{"id":"kp_lesser-ley-protection","name":"Lesser Ley Protection","level":5,"school":"Abjuration","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Deep Magic: forest-bound You create a 10-foot cube of antimagic within range that specifically protects against ley line magic. Ley line spells and magical effects up to level 5 that target a creature within the cube have no effect on that target. Any active ley line spells or magical effects up to level 5 on a creature or an object in the cube is suppressed while the creature or object is in it. The area of a ley line spell or magical effect up to level 5 can't extend into the cube. If the cube overlaps an area of ley line magic, such as lesser ley pulse, the part of the area that is covered by the cube is suppressed. The cube has no effect on other types of magic or spells. You can exclude specific individuals within the cube from the protection.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 7th level or higher, its duration is concentration, up to 1 hour."},{"id":"kp_ley-disturbance","name":"Ley Disturbance","level":3,"school":"Divination","time":"Action","range":"Self","components":"V, S","duration":"1 hour","classes":[],"desc":"Deep Magic: forest-bound While in your bound forest, you tune your senses to any disturbances of ley energy flowing through it. For the duration, you are aware of any ley line manipulation or ley spell casting within 5 miles of you. You know the approximate distance and general direction to each disturbance within that range, but you don't know its exact location. This doesn't allow you to locate the ley lines themselves, just any use or modification of them.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_locate-red-portal","name":"Locate Red Portal","level":3,"school":"Divination","time":"Action","range":"60 feet","components":"V, S","duration":"10 minutes","classes":[],"desc":"For the duration, you can sense the presence of any dimensional portals within range and whether they are one-way or two-way. If you sense a portal using this spell, you can use your action to peer through the portal to determine its destination. You gain a glimpse of the area at the other end of the shadow road. If the destination is not somewhere you have previously visited, you can make a DC 25 Intelligence (Arcana, History or Nature-whichever is most relevant) check to determine to where and when the portal leads.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_moons-respite","name":"Moon's Respite","level":5,"school":"Abjuration","time":"1 hour","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"You touch a creature who must be present for the entire casting. A beam of moonlight shines down from above, bathing the target in radiant light. The spell fails if you can't see the open sky. If the target has any levels of shadow corruption, the moonlight burns away some of the Shadow tainting it. The creature must make a Constitution saving throw against a DC of 10 + the number of shadow corruption levels it has. The creature takes 2d10 radiant damage per level of shadow corruption and removes 1 level of shadow corruption on a failed saving throw, or half as much damage and removes 2 levels of shadow corruption on a success.","concentration":false,"ritual":true,"sourceName":"Kobold Press Compilation","damage":"2d10 radiant","save":"con"},{"id":"kp_morphic-flux","name":"Morphic Flux","level":7,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M","duration":"1 minute","classes":[],"desc":"When you cast this spell, your body becomes highly mutable, your flesh constantly shifting and quivering, occasionally growing extra parts-limbs and eyes-only to reabsorb them soon afterward. While under the effect of this spell, you have resistance to slashing and piercing damage and ignore the additional damage done by critical hits. You can squeeze through Tiny spaces without penalty. In addition, once per round, as a bonus action, you can make an unarmed attack with a newly- grown limb. Treat it as a standard unarmed attack, but you choose whether it does bludgeoning, piercing, or slashing damage.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_open-red-portal","name":"Open Red Portal","level":9,"school":"Transmutation","time":"Action","range":"60 feet","components":"V, S, M","duration":"10 minutes","classes":[],"desc":"You must tap the power of a titanic or strong ley line to cast this spell (see the Ley Initiate feat). You open a new two-way Red Portal on the shadow road, leading to a precise location of your choosing on any plane of existence. If located on the Prime Material Plane, this destination can be in the present day or up to 1,000 years in the past. The portal lasts for the duration. Deities and other planar rulers can prevent portals from opening in their presence or anywhere within their domains.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_peruns-doom","name":"Perun's Doom","level":3,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"Deep Magic: Rothenian A powerful wind swirls from your outstretched hand toward a point you choose within range, where it explodes with a low roar into vortex of air. Each creature in a 20-foot-radius cylinder centered on that point must make a Strength saving throw. On a failed save, the creature takes 3d8 bludgeoning damage, is pulled to the center of the cylinder, and thrown 50 feet upward into the air. If a creature hits a solid obstruction, such as a stone ceiling, when it's thrown upward, it takes bludgeoning damage as if it had fallen (50 feet - the distance it's traveled upward). For example, if a creature hits the ceiling after rising only 10 feet, it takes bludgeoning damage as if it had fallen (50 feet - 10 feet =) 40 feet, or 4d6 bludgeoning damage.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, increase the distance affected creatures are thrown into the air by 10 feet for each slot above 3rd.","damage":"3d8 bludgeoning","save":"str"},{"id":"kp_reset-red-portal","name":"Reset Red Portal","level":5,"school":"Transmutation","time":"Action","range":"10 feet","components":"V, S, M","duration":"1 hour","classes":[],"desc":"When you cast this spell, you can reset the destination of a Red Portal within range, diverting the shadow road so it leads to a location of your choosing. This destination must be in the present day. You can specify the target destination in general terms such as the City of the Fire Snakes, Mammon's home, the Halls of Avarice, or in the Eleven Hells, and anyone stepping through the portal while the spell is in effect will appear in or near that destination. If you reset the destination to the City of the Fire Snakes, for example, the portal might now lead to the first inner courtyard inside the city, or to the marketplace just outside at the GM's discretion. Once the spell's duration expires, the Red Portal resets to its original destination (50% chance) or to a new random destination (roll on the Destinations table).","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, you can specify a destination up to 100 years in the past for each slot level beyond 5th."},{"id":"kp_sanguine-spear","name":"Sanguine Spear","level":2,"school":"Transmutation","time":"Action","range":"Touch","components":"V, S, M","duration":"1 minute","classes":[],"desc":"You draw blood from the corpse of a creature that has been dead for no more than 24 hours and magically fashion it into a spear of frozen blood. This functions as a +1 spear that does cold damage instead of piercing damage. If the spear leaves your hand for more than 1 round, it melts and the spell ends.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"If the spell is cast with a 4th-level spell slot, it creates a +2 spear. A 6th-level spell slot creates a +3 spear."},{"id":"kp_scattered-images","name":"Scattered Images","level":4,"school":"Illusion","time":"Action","range":"Self","components":"V, S","duration":"1 minute","classes":[],"desc":"When you cast this spell, you create illusory doubles that move when you move but in different directions, distracting and misdirecting your opponents. When scattered images is cast, 1d4 + 2 images are created. Images behave exactly as those created with mirror image, with the exceptions described here. These images remain in your space, acting as invisible or the attacker is blind, the spell has no effect.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_seal-red-portal","name":"Seal Red Portal","level":6,"school":"Abjuration","time":"Action","range":"60 feet","components":"V, S, M","duration":"Until dispelled","classes":[],"desc":"You seal a Red Portal or other dimensional gate within range, rendering it inoperable until this spell is dispelled. While the portal remains sealed in this way, it cannot be found with the locate Red Portal spell.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_selfish-wish","name":"Selfish Wish","level":9,"school":"Conjuration","time":"Action","range":"Self","components":"V, S, M (a pint of blood and a black sapphire worth at least 2,500 gp)","duration":"Instantaneous","classes":[],"desc":"The selfish wish grants the desires of a supplicant in exchange for power. Like a wish, it alters reality, but in doing so it grants the caster power, while the end result of the selfish wish is often a twisted or misinterpreted version of the actual desire.\n\nThe wish-maker must provide a pint of his or her blood and state their desire. The caster then completes the spell and provides whatever effect is asked for. However, unlike wish, the GM must pervert any casting of this spell. If the selfish wish is worded with great care, the negative effects may be less hideous than they would be otherwise, but they should still occur. A selfish wish is never granted without drawbacks.\n\nA selfish wish can produce any of the effects that a wish can. If greater effects than those are wished for, the drawbacks become even more dangerous (e.g., a wish for a great increase in Strength may come with an equal reduction in Intelligence).\n\nIn exchange for casting the selfish wish, the caster also receives an influx of power. The caster receives the following bonuses for 2 minutes:\n\n- Doubled speed\n- one extra action each round (as haste)\n- Armor class increases by 3","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_shadow-spawn","name":"Shadow Spawn","level":6,"school":"Illusion","time":"4 hours","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"Casting this spell consumes the corpse of a creature and creates a shadowy duplicate of it. The creature returns as a shadow beast. The shadow beast has dim memories of its former life and retains free will; casters are advised to be ready to make an attractive offer to the newly-risen shadow beast, to gain its cooperation.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_shadow-tree","name":"Shadow Tree","level":2,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M","duration":"10 minutes","classes":[],"desc":"This spell temporarily draws a willow tree from the Shadow Realm to the location you designate within range. The tree is 5 feet in diameter and 20 feet tall.\n  When you cast the spell, you can specify individuals who can interact with the tree. All other creatures see the tree as a shadow version of itself and can't grasp or climb it, passing through its shadowy substance. A creature that can interact with the tree and that has Sunlight Sensitivity or Sunlight Hypersensitivity is protected from sunlight while within 20 feet of the tree. A creature that can interact with the tree can climb into its branches, giving the creature half cover.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"kp_shadows-brand","name":"Shadow's Brand","level":2,"school":"Necromancy","time":"Action","range":"Touch","components":"S","duration":"Until dispelled","classes":[],"desc":"You draw a rune or inscription no larger than your hand on the target. The target must succeed on a Constitution saving throw or be branded with the mark on a location of your choosing. The brand appears as an unintelligible mark to most creatures. Those who understand the Umbral language recognize it as a mark indicating the target is an enemy of the shadow fey. Shadow fey who view the brand see it outlined in a faint glow. The brand can be hidden by mundane means, such as clothing, but it can be removed only by the remove curse spell.\n  While branded, the target has disadvantage on ability checks when interacting socially with shadow fey.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","save":"con"},{"id":"kp_stigmata-of-the-red-goddess","name":"Stigmata of the Red Goddess","level":2,"school":"Necromancy","time":"Action","range":"Self","components":"V, S, M","duration":"3 rounds","classes":[],"desc":"You cut yourself and bleed as tribute to Marena, gaining power as long as the blood continues flowing. The stigmata typically appears as blood running from the eyes or ears, or from wounds manifesting on the neck or chest. You take 1 piercing damage at the beginning of each turn and gain a +2 bonus on damage rolls. Any healing received by you, magical or otherwise, ends the spell.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage you take at the start of each of your turns and the bonus damage you do both increase by 1 for each slot level above 2nd, and the duration increases by 1 round for each slot level above 2nd."},{"id":"kp_the-black-gods-blessing","name":"The Black God's Blessing","level":9,"school":"Transmutation","time":"7 hours","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"Chernobog doesn't care that the Night Cauldron only focuses on one aspect of his dominion. After all, eternal night leads perfectly well to destruction and murder, especially by the desperate fools seeking to survive in the new, lightless world. Having devotees at the forefront of the mayhem suits him, so he allows a small measure of his power to infuse worthy souls. After contacting the Black God, the ritual caster makes a respectful yet forceful demand for him to deposit some of his power into the creature that is the target of the ritual. For Chernobog to comply with this demand, the caster must make a successful DC 20 spellcasting check. If the check fails, the spell fails and the caster and the spell's target become permanently vulnerable to fire; this vulnerability can be ended with remove curse or comparable magic. If the spell succeeds, the target creature gains darkvision (60 feet) and immunity to cold. Chernobog retains the privilege of revoking these gifts if the recipient ever wavers in devotion to him.","concentration":false,"ritual":true,"sourceName":"Kobold Press Compilation"},{"id":"kp_wield-soul","name":"Wield Soul","level":4,"school":"Necromancy","time":"Action","range":"Touch","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You draw forth the ebbing life force of a creature and use its arcane power. Upon casting this spell, you must touch a creature that dropped to 0 hit points since your last turn. If it fails a Wisdom saving throw, you gain knowledge of spells, innate spells, and similar abilities it could have used today were it still alive. Expended spells and abilities aren't revealed. Choose one of these spells or abilities with a casting time no longer than 1 action. Until you complete a long rest, you can use this spell or ability once, as a bonus action, using the creature's spell save DC or spellcasting ability bonus.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation","save":"wis"},{"id":"kp_winged-spies","name":"Winged Spies","level":4,"school":"Divination","time":"Action","range":"10 miles","components":"V, S","duration":"10 hours","classes":[],"desc":"This spell summons a swarm of ravens or other birds-or a swarm of bats if cast at night or underground-to serve you as spies. The swarm moves out as you direct, but it won't patrol farther away than the spell's range. Commands must be simple, such as “search the valley to the east for travelers” or “search everywhere for humans on horses.” The GM can judge how clear and effective your instructions are and use that estimation in determining what the spies report. You can recall the spies at any time by whispering into the air, but the spell ends when the swarm returns to you and reports. You must receive the swarm's report before the spell expires, or you gain nothing. The swarm doesn't fight for you; it avoids danger if possible but defends itself if it must. You know if the swarm is destroyed, and the spell ends.","concentration":false,"ritual":false,"sourceName":"Kobold Press Compilation"},{"id":"wz_abrupt-hug","name":"Abrupt Hug","level":1,"school":"Transmutation","time":"Reaction","range":"30 feet","components":"V","duration":"Instantaneous","classes":[],"desc":"You or the creature taking the Attack action can immediately make an unarmed strike. In addition to dealing damage with the unarmed strike, the target can grapple the creature it hit with the unarmed strike.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_avert-evil-eye","name":"Avert Evil Eye","level":1,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S, M","duration":"1 hour","classes":[],"desc":"The evil eye takes many forms. Any incident of bad luck can be blamed on it, especially if a character recently displayed arrogance or selfishness. When avert evil eye is cast, the recipient has a small degree of protection against the evil eye for up to 1 hour. While the spell lasts, the target of the spell has advantage on saving throws against being blinded, charmed, cursed, and frightened. During the spell's duration, the target can also cancel disadvantage on one d20 roll the target is about to make, but doing so ends the spell's effect.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_bardo","name":"Bardo","level":3,"school":"Necromancy","time":"Reaction","range":"30 feet","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"You capture some of the fading life essence of the triggering creature, drawing on the energy of the tenuous moment between life and death. You can then use this essence to immediately harm or help a different creature you can see within range. If you choose to harm, the target must make a Wisdom saving throw. The target takes psychic damage equal to 6d8 + your spellcasting ability modifier on a failed save, or half as much damage on a successful one. If you choose to help, the target regains hit points equal to 3d8 + your spellcasting ability modifier. This spell can't be triggered by the death of a construct or an undead creature, and it can't restore hit points to constructs or undead.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"wis"},{"id":"wz_battle-chant","name":"Battle Chant","level":2,"school":"Enchantment","time":"1 minute","range":"60 feet","components":"V, S, M","duration":"5 minutes","classes":[],"desc":"You bless up all allied creatures of your choice within range. Whenever a target lands a successful hit before the spell ends, the target can add 1 to the damage roll. When cast by multiple casters chanting in unison, the same increases to 2 points added to the damage roll.","concentration":false,"ritual":true,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can extend the range by 10 feet for each slot level above 2nd."},{"id":"wz_bombardment-of-stings","name":"Bombardment of Stings","level":2,"school":"Evocation","time":"Action","range":"Self","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"Each creature in a 30-foot cone must make a Dexterity saving throw. On a failed save, a creature takes 4d6 piercing damage and is poisoned for 1 minute. On a successful save, a creature takes half as much damage and isn't poisoned. At the end of each of its turns, a poisoned target can make a Constitution saving throw. On a success, the condition ends on the target.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd.","damage":"4d6 piercing","save":"dex"},{"id":"wz_charming-aesthetics","name":"Charming Aesthetics","level":3,"school":"Enchantment","time":"Action","range":"60 feet","components":"V, S, M","duration":"1 day","classes":[],"desc":"You affect a group of the same plants or animals within range, giving them a harmless and attractive appearance. If a creature studies one of the enchanted plants or animals, it must make a Wisdom saving throw. If it fails the saving throw, it is charmed by the plant or animal until the spell ends or until another creature other than one of its allies does anything harmful to it. While the creature is charmed and stays within sight of the enchanted plants or animals, it has disadvantage on Wisdom (Perception) checks as well as checks to notice signs of danger. If the charmed creature attempts to move out of sight of the spell's subject, it must make a second Wisdom saving throw. If it fails the saving throw, it refuses to move out of sight of the spell's subject. It can repeat this save once per minute. If it succeeds, it can move away, but it remains charmed.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional group of plants or animals for each slot level above 4th.","save":"wis"},{"id":"wz_child-of-light-and-darkness","name":"Child of Light and Darkness","level":8,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M","duration":"1 minute","classes":[],"desc":"Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 1-10, you take the form of a humanoid made of pure, searing light. On a roll of 11-20, you take the form of a humanoid made of bone-chilling darkness. In both forms, you have immunity to bludgeoning, piercing, and slashing damage from nonmagical attacks, and a creature that attacks you has disadvantage on the attack roll. You gain additional benefits while in each form: Light Form. You shed bright light in a 60-foot radius and dim light for an additional 60 feet, you are immune to fire damage, and you have resistance to radiant damage. Once per turn, as a bonus action, you can teleport to a space you can see within the light you shed. Darkness Form. You are immune to cold damage, and you have resistance to necrotic damage. Once per turn, as a bonus action, you can target up to three Large or smaller creatures within 30 feet of you. Each target must succeed on a Strength saving throw or be pulled or pushed (your choice) up to 20 feet straight toward or away from you.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"str"},{"id":"wz_commanders-pavilion","name":"Commander's Pavilion","level":3,"school":"Conjuration","time":"Action","range":"Touch","components":"V, S, M","duration":"24 hours","classes":[],"desc":"Creates a command tent 30 feet by 30 feet with a peak height of 20 feet. It is filled with items a military commander might require of a headquarters tent on a campaign, such as maps of the area, a spyglass, a sandglass, materials for correspondence, references for coding and decoding messages, books on history and strategy relevant to the area, banners, spare uniforms, and badges of rank. Such minor mundane items dissipate once the spell's effect ends. Recasting the spell on subsequent days maintains the existing tent for another 24 hours.","concentration":false,"ritual":true,"sourceName":"Warlock Zine"},{"id":"wz_devouring-darkness","name":"Devouring Darkness","level":9,"school":"Evocation","time":"Action","range":"300 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"Terrifying and nightmarish monsters exist within the unknown void of the in-between. Choose up to six points you can see within range. Voidlike, magical darkness spreads from each point to fill a 10-footradius sphere for the duration. The darkness spreads around corners. A creature with darkvision can't see through this darkness, and no light, magical or nonmagical, can illuminate it.\n  Each creature inside a sphere when this spell is cast must make a Dexterity saving throw. On a failed save, the creature takes 6d10 piercing damage and 5d6 psychic damage and is restrained until it breaks free as unseen entities bite and tear at it from the Void. Once a successful save, the creature takes half as much damage and isn't restrained. A restrained creature can use its action to make a Strength check against your spell save DC. If it succeeds, it is no longer restrained.\n  When a creature enters a sphere for the first time on a turn or starts its turn in a sphere, that creature must make an Intelligence saving throw. The creature takes 5d6 psychic damage on a failed save, or half as much damage on a successful one.\n  Once created, the spheres can't be moved. A creature in overlapping spheres doesn't suffer additional effects for being in more than one sphere at a time.","concentration":true,"ritual":false,"sourceName":"Warlock Zine","damage":"6d10 piercing","save":"dex"},{"id":"wz_door-of-the-far-traveler","name":"Door of the Far Traveler","level":8,"school":"Conjuration","time":"10 minutes","range":"10 feet","components":"V, S, M","duration":"6 hours","classes":[],"desc":"You conjure a door to the destination of your choice that lasts for the duration or until dispelled. You sketch the outline of the door with chalk on any hard surface (a wall, a cliffside, the deck of a ship, etc.) and scribe sigils of power around its outline. The doorway must be at least 1 foot wide by 2 feet tall and can be no larger than 5 feet wide by 10 feet tall. Once the door is drawn, place the knob appropriately; it attaches magically to the surface and your drawing becomes a real door to the spell's destination. The doorway remains functional for the spell's duration. During that time, anyone can open or close the door and pass through it in either direction.\n  The destination can be on any plane of existence. It must be familiar to you, and your level of familiarity with it determines the accuracy of the spell (determined by the GM). If it's a place you've visited, you can expect 100 percent accuracy. If it's been described to you by someone who was there, you might arrive in the wrong room or even the wrong structure, depending on how detailed their description was. If you've only heard about the destination third-hand, you may end up in a similar structure that's in a very different locale.\n  Door of the far traveler doesn't create a doorway at the destination. It connects to an existing, working door. It can't, for example, take you to an open field or a forest with no structures (unless someone built a doorframe with a door in that spot for this specific purpose!). While the spell is in effect, the pre-existing doorway connects only to the area you occupied while casting the spell. If you connected to an existing doorway between a home's parlor and library, for example, and your door leads into the library, then people can still walk through that doorway from the parlor into the library normally. Anyone trying to go the other direction, however, arrives wherever you came from instead of in the parlor.\n  Before casting the spell, you must spend one hour etching magical symbols onto the doorknob that will serve as the spell's material component to attune it to your desired destination. Once prepared, the knob remains attuned to that destination until it's used or you spend another hour attuning it to a different location.\n  The door of the far traveler is dispelled if you remove the knob from the door. You can do this as a bonus action from either side of the door, provided it's shut. If the spell's duration expires naturally, the knob falls to the ground on whichever side of the door you're on. Once the spell ends, the knob loses its attunement to any location and another hour must be spent attuning it before it can be used again.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"If you cast this spell using a 9thlevel slot, the duration increases to 12 hours."},{"id":"wz_eternal-echo","name":"Eternal Echo","level":3,"school":"Necromancy","time":"Action","range":"60 feet","components":"V","duration":"Special","classes":[],"desc":"You gain a portentous voice of compelling power, commanding all undead within 60 feet that fail a Wisdom saving throw. This overrides any prior loyalty to spellcasters such as necromancers or evil priests, and it can nullify the effect of a Turn Undead result from a cleric.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"wis"},{"id":"wz_ethereal-stairs","name":"Ethereal Stairs","level":5,"school":"Conjuration","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You create a staircase out of the nothingness of the air. A shimmering staircase 10 feet wide appears and remains for the duration. The staircase ascends at a 45-degree angle to a point as much as 60 feet above the ground. The staircase consists only of steps with no apparent support, unless you choose to have it resemble a stone or wooden structure. Even then, its magical nature is obvious, as it has no color and is translucent, and only the steps have solidity; the rest of it is no more solid than air. The staircase can support up to 10 tons of weight. It can be straight, spiral, or switchback. Its bottom must connect to solid ground, but its top need not connect to anything.","concentration":true,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 6th level or higher, the staircase extends an additional 20 feet for each slot level above 5th."},{"id":"wz_exchanged-knowledge","name":"Exchanged Knowledge","level":3,"school":"Divination","time":"Action","range":"Self","components":"V, S, M","duration":"1 hour","classes":[],"desc":"When you cast this spell, you open a conduit to the Castle Library, granting access to difficult-to-obtain information. For the spell's duration, you double your proficiency bonus whenever you make an Intelligence check to recall information about any subject. Additionally, you can gain advantage on an Intelligence check to recall information. To do so, you must either sacrifice another lore-filled book or succeed on a Charisma saving throw. On a failed save, the spell ends, and you have disadvantage on all Intelligence checks to recall information for 1 week. A wish spell ends this effect.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"int"},{"id":"wz_hedgehog-dozen","name":"Hedgehog Dozen","level":3,"school":"Illusion","time":"Action","range":"Touch","components":"V, S","duration":"1 minute","classes":[],"desc":"Eleven illusory duplicates of the touched creature appear in its space. A creature affected by hedgehog dozen seems to have a dozen arms, shields, and weapons-a swarm of partially overlapping, identical creatures. Until the spell ends, these duplicates move with the target and mimic its actions, shifting position so it's impossible to track which image is real. You can use your action to dismiss the illusory duplicates. While surrounded by duplicates, a creature gains advantage against any opponent because of the bewildering number of weapons and movements. Each time a creature targets you with an attack during the spell's duration, roll a d8 to determine whether the attack instead targets one of your duplicates. On a roll of 1, it strikes you. On any other roll it removes one of your duplicates; when you have only five duplicates remaining, the spell ends. A creature is unaffected by this spell if it can't see, if it relies on senses other than sight, such as blindsight, or if it can perceive illusions as false as with truesight.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_hypnagogia","name":"Hypnagogia","level":4,"school":"Enchantment","time":"Action","range":"90 feet","components":"S, M","duration":"1 minute","classes":[],"desc":"You alter the mental state of one creature you can see within range. The target must make an Intelligence saving throw. If it fails, choose one of the following effects. At the end of each of its turns, the target can make another Intelligence saving throw. On a success, the spell ends on the target. A creature with an Intelligence score of 4 or less isn't affected by this spell.\n  **Sleep Paralysis.** Overwhelming heaviness and fatigue overcome the creature, slowing it. The creature's speed is halved, and it has disadvantage on weapon attacks.\n  **Phantasmata.** The creature imagines vivid and terrifying hallucinations centered on a point of your choice within range. For the duration, the creature is frightened, and it must take the Dash action and move away from the point you chose by the safest available route on each of its turns, unless there is nowhere to move.\n  **False Awakening.** The creature enters a trancelike state of consciousness in which it's not fully aware of its surroundings. It can't take reactions, and it must roll a d4 at the beginning of its turn to determine its behavior. Each time the target takes damage, it makes a new Intelligence saving throw. On a success, the spell ends on the target.\n\nd4 | Behavior\n1 | The creature takes the Dash action and uses all of its movement to move in a random direction. To determine the direction, roll a d8 and assign a direction to each die face.\n2 | The creature uses its action to pantomime preparing for its day: brushing teeth and hair, bathing, eating, or similar activity.\n3 | The creature moves up to its speed toward a randomly determined creature and uses its action to make one melee attack against that creature. If there is no creature within range, the creature does nothing this turn.\n4 | The creature does nothing this turn.","concentration":true,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th. The creatures must be within 30 feet of each other when you target them.","save":"int"},{"id":"wz_hypnic-jerk","name":"Hypnic Jerk","level":0,"school":"Illusion","time":"Action","range":"60 feet","components":"S","duration":"Instantaneous","classes":[],"desc":"Strange things happen in the mind and body in that moment between waking and sleeping. One of the most common is being startled awake by a sudden feeling of falling. With a snap of your fingers, you trigger that sensation in a creature you can see within range. The target must succeed on a Wisdom saving throw or take 1d6 force damage. If the target fails the saving throw by 5 or more, it drops one object it is holding. A dropped object lands in the creature's space.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"The spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).","save":"wis"},{"id":"wz_inconspicuous-facade","name":"Inconspicuous Facade","level":4,"school":"Illusion","time":"1 minute","range":"100 feet","components":"V, S, M","duration":"Until dispelled","classes":[],"desc":"By means of this spell, you make a target building seem much less important or ostentatious than it is. You can give the target an unremarkable appearance or one that blends in with nearby buildings. By its nature, this spell does not allow you to specify features that would make the building stand out. You also cannot make a building look more opulent to match surrounding buildings. You can make the building appear smaller or larger that its actual size to better fit into its environs. However, these size changes are noticeable with cursory physical inspection as an object will pass through extra illusory space or bump into a seemingly smaller section of the building. A creature can use its action to inspect the building and make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware the building has been disguised. In addition to you dispelling inconspicuous facade, the spell ends if the target building is destroyed.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_march-of-the-dead","name":"March of the Dead","level":3,"school":"Necromancy","time":"1 minute","range":"50 feet","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"This spell animates the recently dead to remove them from a battlefield. Choose one corpse of a Medium or Small humanoid per level of the caster (within range). Your spell imbues the targets with an animating spirit, raising them as construct creatures similar in appearance to flesh golems, though with the strength and abilities of zombies. Dwarves use this to return the bodies of the fallen to clan tombs and to deny the corpses the foul attention of ghouls, necromancers, and similar foes. On each of your turns, you can use a bonus action to mentally command all the creatures you made with this spell if the creatures are within 60 feet of you. You decide what action the creatures will take and where they will move during the next day; you cannot command them to guard. If you issue no commands, the creatures only defend themselves against hostile creatures. Once given an order and direction of march, the creatures continue to follow it until they arrive at the destination you named or until 24 hours have elapsed when the spell ends and the corpses fall lifeless once more. To tell creatures to move for another 24 hours, you must cast this spell on the creatures again before the current 24-hour period ends. This use of the spell reasserts your control over up to 50 creatures you have animated with this spell rather than animating a new one.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 4th level or higher, you animate or reassert control over two additional construct creatures for each slot level above 3rd (two creatures/level at 4th, three creatures/level at 5th). Each of the creatures must come from a different corpse."},{"id":"wz_mind-maze","name":"Mind Maze","level":6,"school":"Evocation","time":"Action","range":"60 feet","components":"V, S, M","duration":"Up to 1 minute","classes":[],"desc":"Choose a creature you can see within range. It must succeed on an Intelligence saving throw or be mentally trapped in an imagined maze of mirrors for the duration. While trapped in this way, the creature is incapacitated, but it imagines itself alone and wandering through the maze. Externally, it appears dazed as it turns in place and reaches out at nonexistent barriers. Each time the target takes damage, it makes another Intelligence saving throw. On a success, the spell ends.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"int"},{"id":"wz_mirror-realm","name":"Mirror Realm","level":7,"school":"Conjuration","time":"Action","range":"90 feet","components":"S, M","duration":"24 hours","classes":[],"desc":"You transform a mirror into a magical doorway to an extradimensional realm. You and any creatures you designate when you cast the spell can move through the doorway into the realm beyond. For the spell's duration, the mirror remains anchored in the plane of origin, where it can't be broken or otherwise damaged by any mundane means. No creatures other than those you designate can pass through the mirror or see into the mirror realm.\n  The realm within the mirror is an exact reflection of the location you left. The temperature is comfortable, and any environmental threats (lava, poisonous gas, or similar) are inert, harmless facsimiles of the real thing. Likewise, magic items reflected in the mirror realm have no magical properties, but those carried into it work normally. Food, drink, and other beneficial items within the mirror realm (reflections of originals in the real world) function as normal, real items; food can be eaten, wine can be drunk, and so on. Only items that were reflected in the mirror at the moment the spell was cast exist inside the mirror realm. Items placed in front of the mirror afterward don't appear in the mirror realm, and creatures never do unless they are allowed in by you. Items found in the mirror realm dissolve into nothingness when they leave it, but the effects of food and drink remain.\n  Sound passes through the mirror in both directions. Creatures in the mirror realm can see what's happening in the world, but creatures in the world see only what the mirror reflects. Objects can cross the mirror boundary only while worn or carried by a creature, and spells can't cross it at all. You can't stand in the mirror realm and shoot arrows or cast spells at targets in the world or vice versa.\n  The boundaries of the mirror realm are the same as the room or location in the plane of origin, but the mirror realm can't exceed 50,000 square feet (for simplicity, imagine 50 cubes, each cube being 10 feet on a side). If the original space is larger than this, such as an open field or a forest, the boundary is demarcated with an impenetrable, gray fog.\n  Any creature still inside the mirror realm when the spell ends is expelled through the mirror into the nearest empty space.\n  If this spell is cast in the same spot every day for a year, it becomes permanent. Once permanent, the mirror can't be moved or destroyed through mundane means. You can allow new creatures into the mirror realm (and disallow previous creatures) by recasting the spell within range of the permanent mirror. Casting the spell elsewhere doesn't affect the creation or the existence of a permanent mirror realm; a determined spellcaster could have multiple permanent mirror realms to use as storage spaces, hiding spots, and spy vantages.","concentration":false,"ritual":true,"sourceName":"Warlock Zine"},{"id":"wz_obfuscate-object","name":"Obfuscate Object","level":0,"school":"Illusion","time":"Bonus Action","range":"10 feet","components":"S","duration":"1 minute","classes":[],"desc":"While you are in dim light, you cause an object in range to become unobtrusively obscured from the sight of other creatures. For the duration, you have advantage on Dexterity (Sleight of Hand) checks to hide the object. The object can't be larger than a shortsword, and it must be on your person, held in your hand, or otherwise unattended.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"You can affect two objects when you reach 5th level, three objects at 11th level, and four objects at 17th level."},{"id":"wz_order-of-revenge","name":"Order of Revenge","level":3,"school":"Enchantment","time":"Action","range":"Touch","components":"V, S, M","duration":"1 hour/caster level","classes":[],"desc":"You touch a weapon or a bundle of 30 ammunition, imbuing them with spell energy. Any creature damaged by a touched, affected weapon leaves an invisibly glowing trail of their path until the spell expires. The caster may see this trail by casting revenge's eye or see invisible. Any other caster may see the trail by casting see invisible. Casting dispel magic on an affected creature causes that creature to stop generating a trail, and the trail fades over the next hour.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast the spell using a slot of 4th level or higher, you can target one additional weapon or bundle of ammunition for each slot level above fourth."},{"id":"wz_pierce-the-veil","name":"Pierce the Veil","level":5,"school":"Divination","time":"1 minute","range":"30 feet","components":"V, S, M","duration":"10 minutes","classes":[],"desc":"By sketching a shimmering, ethereal doorway in the air and knocking three times, you call forth an otherworldly entity to provide insight or advice. The door swings open and the entity, wreathed in shadow or otherwise obscured, appears at the threshold. It answers up to five questions truthfully and to the best of its ability, but its answers aren't necessarily clear or direct. The entity can't pass through the doorway or interact with anything on your side of the doorway other than by speaking its responses.\n  Likewise, creatures on your side of the doorway can't pass through it to the other side or interact with the other side in any way other than asking questions. In addition, the spell allows you and the creature to understand each other's words even if you have no language in common, the same as if you were both under the effects of the comprehend languages spell.\n  When you cast this spell, you must request a specific, named entity, a specific type of creature, or a creature from a specific plane of existence. The target creature can't be native to the plane you are on when you cast the spell. After making this request, make an ability check using your spellcasting ability. The DC is 12 if you request a creature from a specific plane; 16 if you request a specific type of creature; or 20 if you request a specific entity. (The GM can choose to make this check for you secretly.) If the spellcasting check fails, the creature that responds to your summons is any entity of the GM's choosing, from any plane. No matter what, the creature is always of a type with an Intelligence of at least 8 and the ability to speak and to hear.","concentration":false,"ritual":true,"sourceName":"Warlock Zine"},{"id":"wz_pratfall","name":"Pratfall","level":1,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"You cause a small bit of bad luck to befall a creature, making it look humorously foolish. You create one of the following effects within range: A small, oily puddle appears under the feet of your target, causing it to lose balance. The target must succeed on a Dexterity saving throw or be unable use a bonus action on its next turn as it regains its footing. Tiny particles blow in your target's face, causing it to sneeze. The target must succeed on a Constitution saving throw or have disadvantage on its first attack roll on its next turn. Strobing lights flash briefly before your target's eyes, causing difficulties with its vision. The target must succeed on a Constitution saving throw or its passive Perception is halved until the end of its next turn. The target feels the sensation of a quick, mild clap against its ears, briefly disorienting it. The target must succeed on a Constitution saving throw to maintain its concentration. An invisible force sharply tugs on the target's trousers, causing the clothing to slip down. The target must make a Dexterity saving throw. On a failed save, the target has disadvantage on its next attack roll with a two-handed weapon or loses its shield bonus to its Armor Class until the end of its next turn as it uses one hand to gather its slipping clothing. Only one of these effects can be used on a single creature at a time.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"dex"},{"id":"wz_putrescent-faerie-circle","name":"Putrescent Faerie Circle","level":5,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M","duration":"1 minute","classes":[],"desc":"You create a 20-foot-diameter circle of loosely-packed toadstools that spew sickly white spores and ooze a tarry substance. At the start of each of your turns, each creature within the circle must make a Constitution saving throw. A creature takes 4d8 necrotic damage on a failed save, or half as much damage on a successful one. If a creature attempts to pass through the ring of toadstools, the toadstools release a cloud of spores, and the creature must make a Constitution saving throw. On a failure, the creature takes 8d8 poison damage and is poisoned for 1 minute. On a success, the creature takes half as much damage and isn't poisoned. While a creature is poisoned, it is paralyzed. It can attempt a new Constitution saving throw at the end of each of its turns to remove the paralyzed condition (but not the poisoned condition).","concentration":false,"ritual":false,"sourceName":"Warlock Zine","damage":"4d8 necrotic","save":"con"},{"id":"wz_reassemble","name":"Reassemble","level":5,"school":"Necromancy","time":"1 hour","range":"Touch","components":"V, S, M","duration":"Instantaneous","classes":[],"desc":"You touch an undead creature (dust and bones suffice) destroyed not more than 10 hours ago; the creature is surrounded by purple fire for 1 round and is returned to life with full hit points. This spell has no effect on any creatures except undead, and it cannot restore a lich whose phylactery has been destroyed, a vampire destroyed by sunlight, any undead whose remains are destroyed by fire, acid, or holy water, or any remains affected by a gentle repose spell. This spell doesn't remove magical effects. If they aren't removed prior to casting, they return when the undead creature comes back to life. This spell closes all mortal wounds but doesn't restore missing body parts. If the creature doesn't have body parts or organs necessary for survival, the spell fails. Sudden reassembly is an ordeal involving enormous expenditure of necrotic energy; ley line casters within 5 miles are aware that some great shift in life forces has occurred and a sense of its direction. The target takes a -4 penalty to all attacks, saves, and ability checks. Every time it finishes a long rest, the penalty is reduced by 1 until it disappears.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_reciprocating-portal","name":"Reciprocating Portal","level":3,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S","duration":"Instantaneous","classes":[],"desc":"With a gesture and a muttered word, you cause an inky black, circular portal to open on the ground beneath one or more creatures. You can create one 15-foot-diameter portal, two 10-foot-diameter portals, or six 5-foot-diameter portals. A creature that's standing where you create a portal must make a Dexterity saving throw. On a failed save, the creature falls through the portal, disappears into a demiplane where it is stunned as it falls endlessly, and the portal closes.\n  At the start of your next turn, the creatures that failed their saving throws fall through matching portals directly above their previous locations. A falling creature lands prone in the space it once occupied or the nearest unoccupied space and takes falling damage as if it fell 60 feet, regardless of the distance between the exit portal and the ground. Flying and levitating creatures can't be affected by this spell.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"dex"},{"id":"wz_remove-insulation","name":"Remove Insulation","level":4,"school":"Necromancy","time":"Action","range":"30 feet","components":"V, S","duration":"8 hours","classes":[],"desc":"You target a creature within range, and that creature must succeed on a Fortitude saving throw or become less resistant to lightning damage. A creature with immunity to lightning damage has advantage on this saving throw. On a failure, a creature with immunity to lightning damage instead has resistance to lightning damage for the spell's duration, and a creature with resistance to lightning damage loses its resistance for the duration. A creature without resistance to lightning damage that fails its saving throw takes double damage from lightning for the spell's duration. Remove curse or similar magic ends this spell.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"If you cast this spell using a spell slot of 6th level or higher, the duration is 24 hours. If you use a spell slot of 8th level or higher, a creature with immunity to lightning damage no longer has advantage on its saving throw. If you use a spell slot of 9th level or higher, the spell lasts until it is dispelled."},{"id":"wz_revenges-eye","name":"Revenge's Eye","level":2,"school":"Divination","time":"Action","range":"Touch","components":"V, S, M","duration":"1 hour","classes":[],"desc":"You touch a creature's visual organs and grant them the ability to see the trail left by creatures damaged by a weapon you cast invisible creatures; it only reveals trails left by those affected by order of revenge also cast by the spellcaster.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 3rd level or higher, you can target +1 creature for each slot level above second."},{"id":"wz_rise-of-the-green","name":"Rise of the Green","level":8,"school":"Evocation","time":"Action","range":"180 feet","components":"V, S, M","duration":"10 minutes","classes":[],"desc":"The spell gives life to existing plants in range. If there are no plants in range, the spell creates undergrowth and trees that persist for the duration. One of the trees becomes a treant friendly to you and your companions. Roll initiative for the treant, which has its own turn. It obeys any verbal commands that you issue to it. If you don't issue it any commands, it defends itself from hostile creatures but otherwise takes no actions. The animated undergrowth creates difficult terrain for your enemies. Additionally, at the beginning of each of your turns, all creatures that are on the ground in range must succeed on a Strength saving throw or become restrained until the spell ends. A restrained creature can use an action to make a Strength (Athletics) check against your spell save DC, ending the effect on itself on a success. If a creature is restrained by plants at the beginning of your turn, it takes 1d6 bludgeoning damage. Finally, the trees swing at each enemy in range, requiring each creature to make a Dexterity saving throw. A creature takes 6d6 bludgeoning damage on a failed save or half as much damage on a successful one. You can use a bonus action to recenter the spell on yourself. This does not grow additional trees in areas that previously had none.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a 9th-level slot, an additional tree becomes a treant, the undergrowth deals an additional 1d6 bludgeoning damage, and the trees inflict an additional 2d6 bludgeoning damage.","damage":"1d6 bludgeoning","save":"str"},{"id":"wz_rive","name":"Rive","level":4,"school":"Evocation","time":"Action","range":"60 feet","components":"S, M","duration":"Instantaneous","classes":[],"desc":"You pull on the filaments of transition and possibility to tear at your enemies. Choose a creature you can see within range and make a ranged spell attack. On a hit, the target takes 5d8 cold damage as strands of icy nothingness whip from your outstretched hand to envelop it. If the target isn't native to the plane you're on, it takes an extra 3d6 psychic damage and must succeed on a Constitution saving throw or be stunned until the end of its next turn.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","damage":"5d8 cold","save":"con","attack":true},{"id":"wz_shadow-adaptation","name":"Shadow Adaptation","level":2,"school":"Transmutation","time":"Action","range":"Self","components":"V, S, M","duration":"8 hours","classes":[],"desc":"Your flesh and clothing pale and become faded as your body takes on a tiny fragment of the Shadow Realm. For the duration of this spell, you are immune to shadow corruption and have resistance to necrotic damage. In addition, you have advantage on saving throws against effects that reduce your Strength score or hit point maximum, such as a shadow's Strength Drain or the harm spell.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"str"},{"id":"wz_skull-road","name":"Skull Road","level":5,"school":"Conjuration","time":"Action","range":"60 feet","components":"V, S, M","duration":"1 minute","classes":[],"desc":"You conjure a portal linking an unoccupied space you can see within range to an imprecise location on the plane of Evermaw. The portal is a circular opening, which you can make 5-20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration. If your casting is at 5th level, this opens a pathway to the River of Tears, to the Vitreous Mire, or to the Plains of Bone-travel to a settlement can take up to 7 days (1d6+1). If cast at 7th level, the skull road spell opens a portal to a small settlement of gnolls, ghouls, or shadows on the plane near the Eternal Palace of Mot or a similar settlement. Undead casters can use this spell in the reverse direction, opening a portal from Evermaw to the mortal world, though with similar restrictions. At 5th level, the portal opens in a dark forest, cavern, or ruins far from habitation. At 7th level, the skull road leads directly to a tomb, cemetery, or mass grave near a humanoid settlement of some kind.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_storm-of-axes","name":"Storm of Axes","level":4,"school":"Conjuration","time":"Action","range":"25 feet","components":"V, S, M","duration":"Concentration + 1 round","classes":[],"desc":"Deep Magic: battle You conjure up dozens of axes and direct them in a pattern in chopping, whirling mayhem. The blades fill eight 5-foot squares in a line 40 feet long or in a double-strength line 20 feet long and 10 deep. The axes cause 6d8 slashing damage to creatures in the area at the moment the spell is cast or half damage with a successful Dexterity saving throw. By maintaining concentration, you can move the swarm of axes up to 20 feet per round in any direction you wish. If the storm of axes moves into spaces containing creatures, they immediately must make another Dexterity saving throw or suffer damage again.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"dex"},{"id":"wz_subliminal-aversion","name":"Subliminal Aversion","level":1,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S","duration":"1 minute","classes":[],"desc":"You ward a creature within range against attacks by making the choice to hit them painful. When the warded creature is hit with a melee attack from within 5 feet of it, the attacker takes 1d4 psychic damage.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","damage":"1d4 psychic"},{"id":"wz_summon-clockwork-beast","name":"Summon Clockwork Beast","level":5,"school":"Conjuration","time":"10 minutes","range":"10 feet","components":"V, S, M","duration":"1 hour","classes":[],"desc":"Deep Magic: clockwork Once per day, you can cast this ritual to summon a Tiny clockwork beast doesn't require air, food, drink, or sleep. When its hit points are reduced to 0, it crumbles into a heap of gears and springs.","concentration":false,"ritual":true,"sourceName":"Warlock Zine"},{"id":"wz_suppress-regeneration","name":"Suppress Regeneration","level":1,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M","duration":"1 minute","classes":[],"desc":"You temporarily remove the ability to regenerate from a creature you can see within range. The target must make a Constitution saving throw. On a failed save, the target can't regain hit points from the Regeneration trait or similar spell or trait for the duration. The target can receive magical healing or regain hit points from other traits, spells, or actions, as normal. At the end of each of its turns, the target can make another Constitution saving throw. On a success, the spell ends on the target.","concentration":true,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them.","save":"con"},{"id":"wz_threshold-slip","name":"Threshold Slip","level":2,"school":"Conjuration","time":"Bonus Action","range":"Self","components":"V","duration":"Instantaneous","classes":[],"desc":"The threshold of a doorway, the sill of a window, the junction where the floor meets the wall, the intersection of two walls—these are all points of travel for you. When you cast this spell, you can step into the junction of two surfaces, slip through the boundary of the Material Plane, and reappear in an unoccupied space with another junction you can see within 60 feet.\n  You can take one willing creature of your size or smaller that you're touching with you. The target junction must have unoccupied spaces for both of you to enter when you reappear or the spell fails.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_toxic-pollen","name":"Toxic Pollen","level":2,"school":"Transmutation","time":"Action","range":"30 feet","components":"V, S, M","duration":"1 year","classes":[],"desc":"Upon casting this spell, one type of plant within range gains the ability to puff a cloud of pollen based on conditions you supply during casting. If the conditions are met, an affected plant sprays a pollen cloud in a 10-foot-radius sphere centered on it. Creatures in the area must succeed on a Constitution saving throw or become poisoned for 1 minute. At the end of a poisoned creature's turn, it can make a Constitution saving throw. On a success, it is no longer poisoned. A plant can only release this pollen once within the duration.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","save":"con"},{"id":"wz_vagrants-nondescript-cloak","name":"Vagrant's Nondescript Cloak","level":2,"school":"Abjuration","time":"Action","range":"Touch","components":"V, S, M","duration":"1 hour","classes":[],"desc":"You touch a creature. The creature is warded against the effects of locate creature, the caster may determine if the affected creature is within 1,000 feet but cannot determine the direction to the target of vagrant's nondescript cloak. If the creature is already affected by one of the warded spells, then both the effect and vagrant's nondescript cloak end immediately.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When you cast this spell using a spell slot of third level or higher, you can target +1 creature for each slot level above second."},{"id":"wz_vengeful-panopy-of-the-ley-line-ignited","name":"Vengeful Panopy of the Ley Line Ignited","level":6,"school":"Evocation","time":"Action","range":"Self","components":"V, S","duration":"10 minutes","classes":[],"desc":"Deep Magic: ley line While bound to a ley line, you draw directly from its power, becoming cloaked in a magical heliotropic fire that sheds dim light in a 10-foot radius. Additionally, each round, including the round it is cast, you may make a ranged spell attack as an action. On a hit, the target takes 6d6 force damage. Every 3 minutes the effect is active, your bond with the ley line is reduced by one step; a bond to a Titanic ley line becomes effectively a Strong, then a Weak, and after 10 minutes, the bond is broken. The strength of the bond is only restored after a long rest; if the bond was broken, it can only be restored at the next weakest level for a week. A bond broken from a Weak ley line cannot be restored for two weeks. Some believe this spell damages ley lines, and there is some evidence to support this claim. Additionally, whenever a creature within 5 feet hits you with a melee attack, the cloak erupts with a heliotropic flare. The attacker takes 3d6 force damage.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","higherLevel":"When casting this spell using a spell slot of 6th level, the damage from all effects of the spell increase by 1d6 for each slot level above 6th.","damage":"6d6 force","attack":true},{"id":"wz_who-goes-there","name":"Who Goes There?","level":5,"school":"Conjuration","time":"10 minutes","range":"60 feet","components":"V, S, M","duration":"10 minutes","classes":[],"desc":"You sift the surrounding air for sound wave remnants of recent conversations to discern passwords or other important information gleaned from a conversation, such as by guards on a picket line. The spell creates a cloud of words in the caster's mind, assigning relevance to them. Selecting the correct word or phrase is not foolproof, but you can make an educated guess. You make a Wisdom (Perception) check against the target person's Wisdom score (DC 10, if not specified) to successfully pick the key word or phrase.","concentration":false,"ritual":false,"sourceName":"Warlock Zine"},{"id":"wz_zymurgic-aura","name":"Zymurgic Aura","level":7,"school":"Necromancy","time":"Action","range":"Self","components":"V, M","duration":"Instantaneous","classes":[],"desc":"A wave of putrefaction surges from you, targeting creatures of your choice within a 30-foot radius around you, speeding the rate of decay in those it touches. The target must make a Constitution saving throw. It takes 10d6 necrotic damage on a failed save or half as much on a successful save. Its hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the creature takes a long rest.","concentration":false,"ritual":false,"sourceName":"Warlock Zine","damage":"10d6 necrotic","save":"con"}]}};
